window.STUDY={"meta":{"built":"2026-10-26","exam":{"date":"2026-10-27T16:00:00-04:00","label":"Exam 1","where":"STC 0010, in class","count":45,"minutes":60}},"figSlots":{"sem":["innate","behaviour","networks","living","broad"],"lalonde":["biology","environment","lifestyle","care"],"prevention":["primordial","primary","secondary","tertiary"],"transitions":["t1","t2","t3","t4"],"ttm":["pre","contemp","prep","action","maint","term"],"smart":["s","m","a","r","t"],"designs":["exp","obs","rct","nonrand","desc","anal","cohort","cc","cross"],"pyramid":["meta","sr","guide","rct","cohort","cc","case"],"maslow":["physio","safety","love","esteem","self"],"dual":["flourish","symptomatic","vulnerable","languish"],"hpa":["hyp","crh","pit","acth","adr","cort"],"gas":["alarm","resist","exhaust"],"yerkes":["under","optimum","over","burnout"]},"units":[{"id":"W1","n":1,"added":"2026-10-26","title":"Perspectives on Health and the Rise of Public Health","short":"Perspectives & history","blurb":"How health, wellness, disease and its determinants are defined, and how public health developed from ancient times to modern Canada.","topics":["Definitions of health and wellness","Disease, illness, sickness and the biomedical model","Risk factors, determinants and the social-ecological model","From Hippocrates to germ theory and sanitary reform","Public health in Canada: Lalonde, Ottawa Charter, PHAC","Omran's epidemiologic transitions"],"lectures":["Week 1 Part 1: Different Perspectives on Health","Week 1 Part 2: Major Historical Developments Relevant to Public Health"],"terms":[{"id":"W1-T-biomedical-definition-of-health","term":"Biomedical definition of health","def":"Health is a \"state of normal function that can be disrupted from time to time by disease\". It is the predominant model in health care.","ex":"A doctor calls you healthy because your tests are normal.","src":"W1 Part 1, slide 2","ch":"W1-C1","added":"2026-10-26"},{"id":"W1-T-who-1948-definition-of-health","term":"WHO definition of health (1948)","def":"Health is a state of \"physical, mental, and social wellbeing, and not merely the absence of disease and infirmity\". Its weakness: it is hard to measure.","src":"W1 Part 1, slide 3","ch":"W1-C1","added":"2026-10-26"},{"id":"W1-T-health-as-a-resource-for-living","term":"Health as a resource for living (WHO, 1984)","def":"From the WHO health promotion movement of the 1980s: health is the extent to which a person or group can realize aspirations, satisfy needs, and change or cope with the environment. Health is a resource for everyday life, not the objective of living. It is not a static state but resiliency.","ex":"A person with a managed chronic condition who copes well with school and work.","src":"W1 Part 1, slide 4","ch":"W1-C1","added":"2026-10-26"},{"id":"W1-T-wellness","term":"Wellness","def":"Optimal health and vitality. Health can be influenced by non-modifiable risk factors, while wellness is largely determined by modifiable risk factors.","ex":"Choosing to exercise and sleep well changes wellness; your age does not.","src":"W1 Part 1, slide 5","ch":"W1-C1","added":"2026-10-26"},{"id":"W1-T-dimensions-of-wellness","term":"Dimensions of wellness","def":"Nine dimensions that continuously influence and are influenced by one another: physical, emotional, intellectual, interpersonal, cultural, spiritual, environmental, financial and occupational. Cultural, financial and occupational were added in the 4th edition. The older figure showed six dimensions on a continuum from low level of wellness (malaise) to high level of wellness (vital, meaningful life).","ex":"Financial wellness: living within your means and saving for emergencies.","src":"W1 Part 1, slides 6-7","ch":"W1-C1","added":"2026-10-26"},{"id":"W1-T-disease","term":"Disease","def":"The underlying pathology, biologically defined. The practitioner's perspective: the illness seen in terms of a theory of disorder.","ex":"A biopsy shows a tumour.","src":"W1 Part 1, slide 8","ch":"W1-C2","added":"2026-10-26"},{"id":"W1-T-illness","term":"Illness","def":"A person's subjective experience of their symptoms. What the patient brings to the doctor.","ex":"\"I have felt exhausted and achy for weeks.\"","src":"W1 Part 1, slide 8","ch":"W1-C2","added":"2026-10-26"},{"id":"W1-T-sickness","term":"Sickness","def":"The social and cultural conceptions of a condition: cultural beliefs and reactions such as fear or rejection, which affect how the patient reacts. Also covers what is considered a disorder suitable for medical treatment.","ex":"Coworkers avoid someone after hearing their diagnosis.","src":"W1 Part 1, slide 8","ch":"W1-C2","added":"2026-10-26"},{"id":"W1-T-biomedical-model","term":"Biomedical model of disease","def":"Focuses on pathological processes: understanding, diagnosing and treating the physical or biological aspect of disease. Illness results from disease, so removal of the disease means no illness and restored health.","ex":"A stent, a wire mesh tube, is inserted into a narrowed coronary artery.","src":"W1 Part 1, slide 9","ch":"W1-C2","added":"2026-10-26"},{"id":"W1-T-reductionist","term":"Reductionist","def":"Describes the biomedical model: it explains disease as abnormal structure or function of cells, organs and systems.","src":"W1 Part 1, slide 9","ch":"W1-C2","added":"2026-10-26"},{"id":"W1-T-clinical-course-of-disease","term":"Clinical course of a disease","def":"From the biomedical perspective: exposure to a pathogen (or another pathophysiological event), biological onset of disease, symptoms appear, diagnosis, therapy begun, outcomes (cured, living with the disease, deteriorated, died). Onset to symptoms is the preclinical phase; from symptoms onward is the clinical phase. Relapse can loop back to diagnosis.","ex":"Plaque building up in arteries before any chest pain is preclinical.","src":"W1 Part 1, slide 10","ch":"W1-C2","added":"2026-10-26"},{"id":"W1-T-etiological-phase","term":"Etiological phase","def":"The stage before disease in the extended clinical course: social and environmental determinants (conditions in society, community circumstances, living environment) lead to risk and protective factors (lifestyle, genetics, education, occupation, social supports).","src":"W1 Part 1, slide 15","ch":"W1-C2","added":"2026-10-26"},{"id":"W1-T-post-clinical-phase","term":"Post-clinical phase","def":"The stage after the clinical phase: longer-term outcomes such as impact on family and work, and economic impact. The figure also shows a sequence from impairment to disability to handicap.","ex":"After a stroke, a person cannot return to work and the family loses income.","src":"W1 Part 1, slide 15","ch":"W1-C2","added":"2026-10-26"},{"id":"W1-T-epidemiology","term":"Epidemiology","def":"\"The study of the distribution and determinants of health-related states or events in specified populations, and the application of this study to the control of health problems.\"","src":"W1 Part 1, slide 11","ch":"W1-C3","added":"2026-10-26"},{"id":"W1-T-epidemiologic-triad","term":"Interacting triad of causal factors","def":"Agent (virulence, infectivity, addictive qualities), host (genetic susceptibility, resiliency, nutritional status, motivation) and environment (public health sanitation, social context, availability of health care). Like the fireman's mantra: a fire needs air, fuel and heat.","ex":"Tobacco's addictive qualities belong to the agent corner.","src":"W1 Part 1, slides 11-13","ch":"W1-C3","added":"2026-10-26"},{"id":"W1-T-risk-factor","term":"Risk factor","def":"A variable associated with an increased statistical probability of contracting a disease, injury, or infection. Risk factors tend to be proximal to the individual. Correlational, not causal.","ex":"Smoking a cigarette.","src":"W1 Part 1, slide 14","ch":"W1-C3","added":"2026-10-26"},{"id":"W1-T-determinants","term":"Determinants","def":"Upstream factors that correlate with increased risk. They tend to be distal and occur at the population level. Correlational, not causal. \"Determinant\" does not imply determinism (inevitability); it comes from the Latin for \"from the end\", the origin of the causal chain or web.","ex":"An open drainage ditch running through a slum.","src":"W1 Part 1, slides 14 and 17","ch":"W1-C3","added":"2026-10-26"},{"id":"W1-T-social-determinants-of-health","term":"Social determinants of health","def":"The Canadian Public Health Association lists 14 key social determinants: income and income distribution, education, unemployment and job security, early childhood development, food insecurity, housing, gender, social safety network, employment and working conditions, social exclusion, Aboriginal and Indigenous status, race, health services and disability. The instructor adds racism. Individual factors are separate: age, sex, biological and hereditary factors, and lifestyle or behaviours.","src":"W1 Part 1, slide 16","ch":"W1-C3","added":"2026-10-26"},{"id":"W1-T-intersectionality","term":"Intersectionality","def":"Social determinants interact and intersect with each other, even though they are listed one by one.","ex":"Experiencing discrimination based on both race and gender.","src":"W1 Part 1, slide 16","ch":"W1-C3","added":"2026-10-26"},{"id":"W1-T-social-ecological-model","term":"Social-ecological model","def":"The model of multiple determinants this course uses. Concentric rings from the centre out: innate individual traits (proximal), individual behaviour, social, family and community networks, living and working conditions (intermediate), and broad social, economic, cultural, health and environmental conditions and policies (distal). It applies over the life span.","src":"W1 Part 1, slides 17-18","ch":"W1-C3","added":"2026-10-26"},{"id":"W1-T-integrated-life-course-model","term":"Integrated Life Course and Social Determinants Model of Indigenous Health","def":"A holistic view with mental, physical, emotional and spiritual aspects. The child sits at the centre and develops through youth into adulthood, within First Nations, Metis and Inuit contexts, all surrounded by social determinants of health.","src":"W1 Part 1, slide 19","ch":"W1-C3","added":"2026-10-26"},{"id":"W1-T-agricultural-revolution","term":"Agricultural Revolution","def":"The shift from nomadic hunting and gathering to settled farming. It gave a more secure food supply and population growth, but also more infectious disease: zoonoses from living near animals, close quarters, less varied diets, and garbage that attracted rodents and insect vectors.","src":"W1 Part 2, slides 3-4","ch":"W1-C4","added":"2026-10-26"},{"id":"W1-T-zoonoses","term":"Zoonoses","def":"Infectious diseases that the slides link to humans living near animals after the Agricultural Revolution.","src":"W1 Part 2, slide 4","ch":"W1-C4","added":"2026-10-26"},{"id":"W1-T-hippocrates","term":"Hippocrates (460 BC)","def":"\"Father\" of Western medicine (Hippocratic Corpus). Said disease is caused by an imbalance of man with the environment, and linked disease to climate, water, lifestyle and nutrition. Also an imbalance in the humours: melancholy, phlegm, bile and blood.","src":"W1 Part 2, slide 5","ch":"W1-C4","added":"2026-10-26"},{"id":"W1-T-black-death","term":"Black Death (1348)","def":"Plague in two forms: bubonic, transmitted by fleas from rats to humans, and pneumonic, spread by sneezing. Death in 60% of cases. Killed 1/3 of the European population, 60 million worldwide. Caused by the bacterium Yersinia pestis.","src":"W1 Part 2, slides 6-7","ch":"W1-C4","added":"2026-10-26"},{"id":"W1-T-miasma","term":"Miasma","def":"A theory of the cause of the plague: disease came from vapours from swamps or cesspools.","src":"W1 Part 2, slide 7","ch":"W1-C4","added":"2026-10-26"},{"id":"W1-T-reservoir-and-vector","term":"Reservoir and vector","def":"In the plague, rats were the reservoir for the bacteria and fleas were the vector that transmitted it by biting.","src":"W1 Part 2, slide 7","ch":"W1-C4","added":"2026-10-26"},{"id":"W1-T-john-snow","term":"John Snow (1813-1858)","def":"London physician, the father of epidemiology. He systematically studied cholera outbreaks, and his data supported his theory of their source. In 1853 he removed the handle of the Broad Street Pump: the first public health intervention.","src":"W1 Part 2, slides 9-10","ch":"W1-C4","added":"2026-10-26"},{"id":"W1-T-william-harvey","term":"William Harvey (1578-1657)","def":"English physician who did animal dissections. Published \"An Anatomical Study of the Motion of the Heart and of the Blood in Animals\" (1628). First to hypothesize that mammals reproduce by fertilization of an egg by sperm.","src":"W1 Part 2, slide 11","ch":"W1-C4","added":"2026-10-26"},{"id":"W1-T-edward-jenner","term":"Edward Jenner (1796)","def":"English physician. His 1796 cowpox experiment showed that inoculation with cowpox (material from pustules) gave immunity against smallpox, a virus. He was not the first: smallpox inoculation was practised in China and India as early as 1000 CE using ground-up smallpox scabs.","src":"W1 Part 2, slide 12","ch":"W1-C4","added":"2026-10-26"},{"id":"W1-T-louis-pasteur","term":"Louis Pasteur (1822-1895)","def":"In 1862 disproved the theory of spontaneous generation and published his germ theory. Pasteurization saved the wine industry. Made vaccines against anthrax and rabies and coined the term \"vaccine\" in honour of Jenner. Head of the Pasteur Institute in Paris (1888).","src":"W1 Part 2, slide 13","ch":"W1-C4","added":"2026-10-26"},{"id":"W1-T-robert-koch","term":"Robert Koch (1843-1910)","def":"Discovered the tuberculosis bacterium (1882) and identified the bacterium that causes cholera (1883). Koch's postulates are his rules for proving that a specific microbe causes a specific disease.","src":"W1 Part 2, slide 13","ch":"W1-C4","added":"2026-10-26"},{"id":"W1-T-jeremy-bentham","term":"Jeremy Bentham","def":"Industrial-era thinker: \"It is the greatest happiness of the greatest number that is the measure of right and wrong.\" Linked to the ideas that reducing mortality and improving health is better for the economy, and that good government and health and social policies matter.","src":"W1 Part 2, slide 14","ch":"W1-C5","added":"2026-10-26"},{"id":"W1-T-edwin-chadwick","term":"Edwin Chadwick (1842)","def":"English social reformer. His 1842 report, \"Survey into the Sanitary Condition of the Labouring Classes in Great Britain\", described how filth in the environment spread disease in urban areas and exposed child labour: half of child labourers died before their 5th birthday. It led to reforms in sanitation and in treatment of the poor and working class.","src":"W1 Part 2, slide 16","ch":"W1-C5","added":"2026-10-26"},{"id":"W1-T-great-sanitary-awakening","term":"Great Sanitary Awakening (1800 to 1900s)","def":"Period of more scientific knowledge of disease causes, greater humanitarian ideals and recognition of the link between poverty and disease. Brought clean water, sewage removal, garbage collection, public works departments, monitoring of community health status, and public health departments, regulation and inspection.","src":"W1 Part 2, slide 17","ch":"W1-C5","added":"2026-10-26"},{"id":"W1-T-grosse-ile","term":"Grosse Ile","def":"A tiny island in the St. Lawrence in Quebec where many Irish immigrants arrived during the Great Irish famine of 1847. An example of early 19th century quarantine and isolation of immigrants carrying cholera and typhus.","src":"W1 Part 2, slide 18","ch":"W1-C6","added":"2026-10-26"},{"id":"W1-T-lalonde-report","term":"Lalonde Report (1974)","def":"Report by former federal health minister Marc Lalonde. Looked beyond the individual to improving the health of the population and started the Population Health Movement. Argued that equating health with the availability of physicians and hospitals is inadequate; future gains lie in improving the environment, moderating self-imposed risks and adding to knowledge of human biology.","src":"W1 Part 2, slides 19-20","ch":"W1-C6","added":"2026-10-26"},{"id":"W1-T-health-field-concept","term":"Health field concept","def":"Lalonde's model with 4 fields that each have a two-way link with health: human biology, environment, lifestyle and health care organization.","ex":"A provincial anti-smoking campaign works on the lifestyle field.","src":"W1 Part 2, slides 19-20","ch":"W1-C6","added":"2026-10-26"},{"id":"W1-T-ottawa-charter","term":"Ottawa Charter for Health Promotion (1986)","def":"Result of the first international conference on health promotion, held in Ottawa. Aims: reduce inequities, ramp up prevention, empower individuals. Five action areas: build healthy public policy, create supportive environments, strengthen community action, develop personal skills, reorient health services. Seven prerequisites for health: peace, shelter, education, food, income, a stable eco-system and sustainable resources.","src":"W1 Part 2, slides 19, 21-22","ch":"W1-C6","added":"2026-10-26"},{"id":"W1-T-phac-act-2006","term":"Public Health Agency of Canada Act (2006)","def":"Established the Public Health Agency of Canada and a Chief Public Health Officer, whose mandate is to advocate for disease prevention and health promotion, provide science-based policy advice to the federal health minister, lead special health initiatives and improve public health practice. Followed outbreaks in the early 2000s (Walkerton 2000, North Battlefield 2001, SARS 2002) that revealed cracks in public health. Dr. Joss Reimer became CPHO on April 1, 2026.","src":"W1 Part 2, slides 23-24","ch":"W1-C6","added":"2026-10-26"},{"id":"W1-T-epidemiologic-transition","term":"Epidemiologic transition","def":"Theory first proposed by Abdel Omran in 1971: dramatic shifts in the patterns of mortality and disease as countries develop economically. Four transitions or stages.","src":"W1 Part 2, slide 25","ch":"W1-C7","added":"2026-10-26"},{"id":"W1-T-age-of-pestilence-and-famine","term":"Age of Pestilence and Famine (stage 1)","def":"Most of human history. Life expectancy 20 to 40 years, high infant mortality, deaths mainly from malnutrition or infectious disease, no sustained population growth. CVD about 5 to 10% of deaths. Example: Sub-Saharan Africa.","src":"W1 Part 2, slide 26","ch":"W1-C7","added":"2026-10-26"},{"id":"W1-T-age-of-receding-pandemics","term":"Age of Receding Pandemics (stage 2)","def":"Late 1800s to early 1900s in developed countries. Safer, more available food, sanitation, better prenatal and postnatal care, immunization and antibiotics drove down deaths from infection and malnutrition. Life expectancy about 50, infant mortality falls. CVD 15 to 35% of deaths. Example: some parts of Latin America and Southeast Asia.","src":"W1 Part 2, slide 27","ch":"W1-C7","added":"2026-10-26"},{"id":"W1-T-age-of-degenerative-and-man-made-diseases","term":"Age of Degenerative and Man-Made Diseases (stage 3)","def":"Mid 20th century. Deaths from chronic diseases overtake deaths from infectious diseases. Life expectancy about 60. Peak in CVD and cancer; over 50% of deaths due to CVD. Example: some parts of Central Asia, Middle East, North Africa and urban India.","src":"W1 Part 2, slide 28","ch":"W1-C7","added":"2026-10-26"},{"id":"W1-T-age-of-delayed-degenerative-disease","term":"Age of Delayed Degenerative Disease (stage 4)","def":"Mid-1960s to today. CVD mortality declines, though CVD is still a top 3 cause of death, thanks to prevention (smoking cessation, tobacco control), technology (blood pressure medications, coronary artery bypass surgery) and public health education. Life expectancy in Canada is about 82.","src":"W1 Part 2, slide 29","ch":"W1-C7","added":"2026-10-26"}],"chapters":[{"id":"W1-C1","title":"Defining health and wellness","src":"W1 Part 1, slides 2-7","blurb":"Three definitions of health, and the nine dimensions of wellness.","learn":"The slides give three definitions of health. The <b>biomedical definition</b> calls health a \"state of normal function that can be disrupted from time to time by disease\". It is the predominant model in health care. The <b>1948 WHO definition</b> widens this to \"physical, mental, and social wellbeing, and not merely the absence of disease and infirmity\", but it is hard to measure. In the 1980s the WHO health promotion movement called health <b>a resource for everyday life, not the objective of living</b>: the ability to realize aspirations, satisfy needs, and change or cope with the environment. Health here is resiliency, not a static state.<br><br><b>Wellness</b> is optimal health and vitality. Health can be influenced by non-modifiable risk factors. Wellness is largely determined by modifiable ones. The 4th Canadian edition lists <b>nine dimensions</b> of wellness that keep influencing each other. Cultural, financial and occupational are the three that were added.","steps":[{"id":"W1-C1-S1","type":"sort","src":"W1 Part 1, slides 2-4","prompt":"Sort each statement under the definition of health it belongs to.","bins":["Biomedical","WHO 1948","WHO 1980s health promotion"],"items":[["State of normal function, disrupted from time to time by disease",0,"This is the biomedical quote on slide 2."],["Predominant model in health care",0,"Slide 2 says the biomedical definition dominates health care."],["Physical, mental, and social wellbeing",1,"The three parts of wellbeing in the 1948 WHO wording."],["Not merely the absence of disease and infirmity",1,"Also part of the 1948 WHO definition."],["Hard to measure",1,"Slide 3 gives this as the weakness of the 1948 definition."],["A resource for everyday life, not the objective of living",2,"From the 1984 WHO health promotion document."],["Able to realize aspirations, satisfy needs, and change or cope with the environment",2,"The 1984 WHO wording."],["Health is resiliency, not a static state",2,"Slide 4 heading for the health promotion view."]]},{"id":"W1-C1-S2","type":"match","src":"W1 Part 1, slide 7","prompt":"Match each dimension of wellness to an example from Fig 1.1.","pairs":[["Physical","Getting regular checkups"],["Intellectual","Ability to think critically"],["Interpersonal","Cultivating a support system of friends and family"],["Cultural","Maintaining and valuing your own cultural identity"],["Spiritual","Sense of meaning and purpose"],["Financial","Living within one's means"],["Occupational","Feeling valued by your manager"]]},{"id":"W1-C1-S3","type":"mcq","src":"W1 Part 1, slide 5","ch":"W1-C1","added":"2026-10-26","case":"Two students compare notes. Ana has a family history of heart disease. Ben stays up until 3 a.m. most nights and skips meals.","q":"Using the slides' distinction between health and wellness, which statement is correct?","opts":[["Ana's family history is a non-modifiable factor that can influence her health; Ben's habits are modifiable factors that largely shape his wellness.",true,"Slide 5: health can be influenced by non-modifiable risk factors, wellness is largely determined by modifiable ones."],["Ana's family history mainly shapes her wellness, while Ben's habits only affect his health.",false,"This reverses the slide. Wellness is tied to modifiable factors."],["Neither student's situation matters, since wellness is defined as the absence of disease.",false,"Wellness is optimal health and vitality, not the absence of disease."],["Both situations are determinants, since they occur at the population level.",false,"These are individual factors. Determinants are upstream, population-level factors."]]}],"summary":"Health has a biomedical, a 1948 WHO and a 1980s WHO resource-for-living definition. Wellness is optimal health and vitality across nine interacting dimensions, shaped mostly by modifiable factors."},{"id":"W1-C2","title":"Disease, illness, sickness and the biomedical model","src":"W1 Part 1, slides 8-10, 15","blurb":"Three perspectives on a condition, the biomedical model, and the clinical course of disease.","learn":"One condition can be seen three ways. <b>Disease</b> is the underlying pathology, biologically defined: the practitioner's view. <b>Illness</b> is the person's subjective experience of symptoms: what the patient brings to the doctor. <b>Sickness</b> is the social and cultural view of the condition, such as fear or rejection, and what counts as a disorder fit for medical treatment.<br><br>The <b>biomedical model</b> focuses on pathological processes. Illness results from disease, so removing the disease (for example, a stent in a narrowed coronary artery) restores health. It is <b>reductionist</b>: disease is abnormal structure or function of cells, organs and systems.<br><br>The <b>clinical course</b> runs from exposure, to biological onset, symptoms, diagnosis, therapy and outcomes. Onset to symptoms is the <b>preclinical phase</b>; after that is the <b>clinical phase</b>. An extended version adds an <b>etiological phase</b> before (determinants, then risk and protective factors) and a <b>post-clinical phase</b> after (impact on family, work and income).","steps":[{"id":"W1-C2-S1","type":"sort","src":"W1 Part 1, slide 8","prompt":"Is each example about disease, illness or sickness?","bins":["Disease","Illness","Sickness"],"items":[["A biopsy shows abnormal cell growth in the lung",0,"Biologically defined pathology, the practitioner's view."],["Blood tests confirm high glucose",0,"A measured biological abnormality."],["Plaque narrowing a coronary artery",0,"Underlying pathology."],["A patient says she has felt exhausted and achy for weeks",1,"Her subjective experience of symptoms."],["\"My chest feels tight when I climb stairs\"",1,"What the patient brings to the doctor."],["Neighbours avoid a man after hearing his diagnosis",2,"Cultural reactions such as fear or rejection."],["A society debates whether a condition should be treated as a medical disorder",2,"Sickness covers what is considered a disorder suitable for treatment."]]},{"id":"W1-C2-S2","type":"order","src":"W1 Part 1, slide 10","prompt":"Put the clinical course of a disease (biomedical view) in order.","items":["Exposure to pathogen","Biological onset of disease","Symptoms appear","Diagnosis","Therapy begun","Outcomes: cured, living with the disease, deteriorated, or died"],"why":"Onset to symptoms is the preclinical phase. From symptoms on is the clinical phase. A relapse loops back to diagnosis and a change in therapy."},{"id":"W1-C2-S3","type":"sort","src":"W1 Part 1, slide 15","prompt":"Place each item in the phase of the extended clinical course where the figure shows it.","bins":["Etiological phase","Preclinical and clinical phases","Post-clinical phase"],"items":[["Conditions in society, such as economic stability",0,"A social and environmental determinant, at the start of the etiological phase."],["Community circumstances, such as services available",0,"Also a social and environmental determinant."],["Personal factors: lifestyle, genetics, education, occupation",0,"Risk and protective factors, the second part of the etiological phase."],["Biological onset of disease",1,"Starts the preclinical phase."],["Diagnosis and therapy",1,"Clinical phase events."],["Impairment",1,"Shown under the clinical phase in the bottom row."],["Longer-term impact on family, work and income",2,"The longer-term outcome of the post-clinical phase."],["Handicap",2,"The last box in the impairment, disability, handicap row, under the post-clinical phase."]]},{"id":"W1-C2-S4","type":"mcq","src":"W1 Part 1, slide 9","ch":"W1-C2","added":"2026-10-26","case":"An oncologist explains a patient's lung tumour entirely as lung cells dividing in an uncontrolled way. The plan targets only the tumour cells.","q":"Which feature of the biomedical model does this explanation show most directly?","opts":[["It treats illness as the patient's subjective experience.",false,"That is the illness perspective, not the biomedical focus on pathology."],["It focuses on distal, population-level determinants.",false,"The biomedical model looks at pathology in the individual, not upstream determinants."],["It is reductionist: disease is explained as abnormal structure or function of cells, organs and systems.",true,"Slide 9 calls the biomedical model reductionist for exactly this reason."],["It views health as a resource for everyday life.",false,"That is the 1980s WHO health promotion view."]]}],"summary":"Disease is pathology, illness is experience, sickness is the social view. The biomedical model is reductionist and equates removing disease with restored health; the clinical course can be extended to include etiological and post-clinical phases."},{"id":"W1-C3","title":"Risk factors, determinants and the social-ecological model","src":"W1 Part 1, slides 11-19","blurb":"Epidemiology, the causal triad, risk factors versus determinants, and models of determinants.","learn":"<b>Epidemiology</b> is the study of the distribution and determinants of health-related states or events in specified populations, applied to control health problems. Causes form an interacting triad: <b>agent</b> (virulence, infectivity, addictive qualities), <b>host</b> (genetic susceptibility, resiliency, nutrition, motivation) and <b>environment</b> (sanitation, social context, access to care). A fire needs air, fuel and heat.<br><br>A <b>risk factor</b> is a variable linked to a higher statistical probability of disease, injury or infection. It is proximal to the individual, like smoking. A <b>determinant</b> is an upstream factor linked to higher risk. It is distal and works at the population level, like poor sanitation. Both are correlational, not causal. Determinant does not mean determinism.<br><br>The <b>social-ecological model</b> puts innate traits at the centre (proximal), then individual behaviour, social and community networks, living and working conditions (intermediate), and broad conditions and policies (distal). The Indigenous life course model adds mental, physical, emotional and spiritual health.","steps":[{"id":"W1-C3-S1","type":"compare","src":"W1 Part 1, slides 14 and 17","prompt":"Risk factor or determinant?","a":{"name":"Risk factor","points":["Variable associated with increased probability of disease, injury or infection","Proximal to the individual","Correlational, not causal"]},"b":{"name":"Determinant","points":["Upstream factor that correlates with increased risk","Distal, occurs at the population level","Correlational, not causal; not determinism"]},"scenarios":[["A student smokes a pack of cigarettes a day",0,"Slide 14 shows smoking as a proximal risk factor."],["An open drainage ditch runs through a low-income neighbourhood",1,"Slide 14 shows poor sanitation as a distal, population-level determinant."],["A country's income distribution is very unequal",1,"Income distribution is an upstream social determinant."],["A man rarely does any physical activity",0,"An individual behaviour close to the person."],["A city has a shortage of affordable housing",1,"Housing is a social determinant at the population level."]]},{"id":"W1-C3-S2","type":"label","fig":"sem","src":"W1 Part 1, slide 18","prompt":"Drag each level onto the social-ecological model, from the proximal centre to the distal outer ring."},{"id":"W1-C3-S3","type":"sort","src":"W1 Part 1, slide 16","prompt":"Is each item a social determinant of health (CPHA list) or an individual factor?","bins":["Social determinant","Individual factor"],"items":[["Income and income distribution",0,"First item on the CPHA list."],["Housing",0,"On the CPHA list."],["Social exclusion",0,"On the CPHA list."],["Racism",0,"Added to the list by the instructor."],["Early childhood development",0,"On the CPHA list."],["Age",1,"Listed in the separate Individual Factors box."],["Biological and hereditary factors",1,"Individual Factors box."],["Lifestyle and behaviours",1,"Individual Factors box."]]},{"id":"W1-C3-S4","type":"mcq","src":"W1 Part 1, slides 11-12","ch":"W1-C3","added":"2026-10-26","case":"A class fills in the agent, host and environment triad for lung cancer.","q":"Where does the addictive quality of tobacco belong?","opts":[["Host",false,"Host covers the person: genetic susceptibility, resiliency, nutritional status, motivation."],["Agent",true,"Slide 11 lists addictive qualities under the agent, with virulence and infectivity."],["Environment",false,"Environment covers sanitation, social context and availability of health care."],["Vector",false,"Vector is not a corner of the triad; the slides use it for fleas in the plague."]]}],"summary":"Risk factors are proximal and individual; determinants are distal and population-level; both are correlational. The social-ecological model arranges determinants from innate traits out to broad policies."},{"id":"W1-C4","title":"From ancient health to germ theory","src":"W1 Part 2, slides 2-13","blurb":"Hunter-gatherers, farming, Hippocrates, the plague, and the scientists who built epidemiology.","learn":"Hunter-gatherers (10,000 years ago) followed tribal rules for survival, like avoiding stagnant water and keeping waste away from shelters. The <b>Agricultural Revolution</b> gave a secure food supply and population growth, but also zoonoses from living near animals, crowding, less varied diets, and garbage that drew rodents and insect vectors.<br><br><b>Hippocrates</b> (460 BC) said disease came from an imbalance between people and their environment, and an imbalance of humours. During the <b>Black Death</b> (1348), people blamed miasmas. The real cause was <i>Yersinia pestis</i>, with rats as reservoir and fleas as vector. Without a systematic way to test links between exposures and outcomes, there was little progress. Science and epidemiology filled that gap. Harvey published on the heart and blood (1628). Jenner used cowpox against smallpox (1796). <b>John Snow</b> removed the Broad Street Pump handle (1853). Pasteur published germ theory (1862). Koch found the tuberculosis (1882) and cholera (1883) bacteria.","steps":[{"id":"W1-C4-S1","type":"order","src":"W1 Part 2, slides 5-13","prompt":"Put these events in historical order, earliest first.","items":["Hippocrates links disease to imbalance with the environment (460 BC)","The Black Death reaches Europe (1348)","Harvey publishes his study of the motion of the heart and blood (1628)","Jenner's cowpox experiment (1796)","Snow removes the Broad Street Pump handle (1853)","Pasteur disproves spontaneous generation and publishes germ theory (1862)","Koch discovers the tuberculosis bacterium (1882)"],"why":"Ancient medicine, then the medieval plague, then the Age of Reason (Harvey, Jenner), then the 1800s rise of epidemiology and germ theory (Snow, Pasteur, Koch)."},{"id":"W1-C4-S2","type":"match","src":"W1 Part 2, slides 5, 9-13","prompt":"Match each person to their contribution.","pairs":[["Hippocrates","Disease as an imbalance of humours and of man with the environment"],["William Harvey","Animal dissections and a study of the heart and blood"],["Edward Jenner","Cowpox inoculation conferred immunity to smallpox"],["John Snow","Systematically studied cholera outbreaks in London"],["Louis Pasteur","Disproved spontaneous generation; coined the term vaccine"],["Robert Koch","Postulates for proving a specific microbe causes a specific disease"]]},{"id":"W1-C4-S3","type":"mcq","src":"W1 Part 2, slide 7","ch":"W1-C4","added":"2026-10-26","case":"During the plague, a town council orders swamps drained and cesspools covered, convinced that bad vapours spread the disease.","q":"Which theory guided the council?","opts":[["Germ theory",false,"Germ theory came from Pasteur in 1862, centuries later."],["Imbalance of the humours",false,"That was Hippocrates' idea about body fluids, not vapours."],["Koch's postulates",false,"Koch's postulates are rules for proving a microbe causes a disease (1880s)."],["Miasma theory",true,"Slide 7: one theory blamed miasmas, vapours from swamps or cesspools."]]},{"id":"W1-C4-S4","type":"mcq","src":"W1 Part 2, slide 13","ch":"W1-C4","added":"2026-10-26","case":"Winemakers in the 1800s keep losing batches to spoilage.","q":"Which of Pasteur's contributions is credited on the slides with saving the wine industry?","opts":[["Vaccination against rabies",false,"A Pasteur vaccine, but not linked to wine."],["Identifying the cholera bacterium",false,"Koch identified the cholera bacterium in 1883."],["Cowpox inoculation",false,"That was Jenner in 1796."],["Pasteurization",true,"Slide 13: pasteurization saved the wine industry."]]}],"summary":"Ideas about disease moved from imbalance and miasma to systematic study. Snow, Harvey, Jenner, Pasteur and Koch built the science that showed specific causes for specific diseases."},{"id":"W1-C5","title":"Industrial era and sanitary reform","src":"W1 Part 2, slides 14-17","blurb":"Urban slums, Bentham, Chadwick's report and the Great Sanitary Awakening.","learn":"The Industrial Revolution brought ideals of democracy, reason and citizenship. <b>Jeremy Bentham</b> wrote that \"the greatest happiness of the greatest number\" is the measure of right and wrong. Reducing mortality was seen as good for the economy, and good government and social policy mattered.<br><br>Cities also brought slums, poverty, no indoor plumbing or sewage removal, fast spread of infection and dangerous work. Life expectancy took a nosedive. <b>Edwin Chadwick</b>'s 1842 report on the sanitary condition of the labouring classes showed how filth spread disease in cities. It exposed child labour: half of child labourers died before their 5th birthday. It led to sanitary reform.<br><br>The <b>Great Sanitary Awakening</b> (1800 to 1900s) joined scientific knowledge with humanitarian ideals. It linked poverty and disease and brought clean water, sewage removal, garbage collection, public works departments, health departments, regulation, inspection and monitoring of community health.","steps":[{"id":"W1-C5-S1","type":"sort","src":"W1 Part 2, slides 15 and 17","prompt":"Was each item a problem of industrial cities or a response during the Great Sanitary Awakening?","bins":["Industrial-era problem","Sanitary Awakening response"],"items":[["Slums and poverty",0,"Slide 15."],["Lack of indoor plumbing and sewage removal",0,"Slide 15."],["Dangerous working conditions",0,"Slide 15."],["Life expectancy takes a nosedive",0,"Slide 15."],["Public works departments",1,"Slide 17."],["Monitoring community health status",1,"Slide 17."],["Public health departments, regulation and inspection",1,"Slide 17."],["Clean water supply and garbage collection",1,"Slide 17."]]},{"id":"W1-C5-S2","type":"match","src":"W1 Part 2, slides 14-17","prompt":"Match each item to what the slides say about it.","pairs":[["Jeremy Bentham","Greatest happiness of the greatest number"],["Edwin Chadwick","1842 report on the sanitary condition of the labouring classes"],["Child labourers in Chadwick's report","Half died before their 5th birthday"],["Great Sanitary Awakening","Recognized the connection between poverty and disease"],["Industrial cities","Rapid spread of infectious diseases"]]},{"id":"W1-C5-S3","type":"mcq","src":"W1 Part 2, slide 15","ch":"W1-C5","added":"2026-10-26","case":"A historian notes that life expectancy fell in fast-growing industrial cities during the 1800s.","q":"Which explanation fits the slides?","opts":[["Humans began living near farm animals, causing zoonoses",false,"That is the Agricultural Revolution, thousands of years earlier."],["Slums, poverty, no proper sewage removal, rapid spread of infection and dangerous work",true,"These are the conditions listed on slide 15 before the line about life expectancy."],["Chronic disease deaths overtook infectious disease deaths",false,"That describes Omran's stage 3, in the mid 20th century."],["Pasteurization and vaccines were not yet invented anywhere",false,"Not the explanation given; Jenner's smallpox inoculation already existed (1796)."]]}],"summary":"Industrial cities spread disease and cut life expectancy. Chadwick's 1842 report and the Great Sanitary Awakening tied poverty to disease and built public works and health departments."},{"id":"W1-C6","title":"Public health in Canada","src":"W1 Part 2, slides 18-24","blurb":"From quarantine at Grosse Ile to Lalonde, the Ottawa Charter and the Public Health Agency of Canada.","learn":"In the early to mid 19th century, Canada focused on water, sanitation, and quarantine and isolation of immigrants carrying cholera and typhus, as at <b>Grosse Ile</b> during the Irish famine of 1847. The early 20th century brought water chlorination, milk pasteurization and vaccines for smallpox and diphtheria. The WHO was set up in 1948.<br><br>The 1974 <b>Lalonde Report</b> looked beyond the individual to population health and started the Population Health Movement. Its <b>health field concept</b> has four fields: human biology, environment, lifestyle and health care organization. Equating health with doctors and hospitals is inadequate.<br><br>The 1986 <b>Ottawa Charter</b> came from the first international health promotion conference. It has five action areas and seven prerequisites for health.<br><br>Outbreaks in the early 2000s (Walkerton 2000, North Battlefield 2001, SARS in Toronto 2002 with 44 deaths) showed cracks in public health. The 2006 Act created the <b>Public Health Agency of Canada</b> and a Chief Public Health Officer.","steps":[{"id":"W1-C6-S1","type":"order","src":"W1 Part 2, slides 18-24","prompt":"Put these Canadian and global public health events in order.","items":["Irish famine immigrants quarantined at Grosse Ile (1847)","World Health Organization established within the UN (1948)","Lalonde Report (1974)","Ottawa Charter for Health Promotion (1986)","E. coli outbreak in Walkerton, ON (2000)","SARS in Toronto (2002)","Public Health Agency of Canada Act (2006)"],"why":"Quarantine came first, then the WHO, then the population health and health promotion era, then the early-2000s outbreaks that led to PHAC."},{"id":"W1-C6-S2","type":"label","fig":"lalonde","src":"W1 Part 2, slide 20","prompt":"Drag the four fields of Lalonde's health field concept onto the figure."},{"id":"W1-C6-S3","type":"sort","src":"W1 Part 2, slides 21-22","prompt":"Ottawa Charter: is each item an action area or a prerequisite for health?","bins":["Action area","Prerequisite for health"],"items":[["Building healthy public policy",0,"One of the five action areas."],["Creating supportive environments",0,"Action area."],["Strengthening community action",0,"Action area."],["Reorienting health services",0,"Action area."],["Peace",1,"One of the seven prerequisites."],["Shelter",1,"Prerequisite."],["Income",1,"Prerequisite."],["A stable eco-system",1,"Prerequisite."]]},{"id":"W1-C6-S4","type":"mcq","src":"W1 Part 2, slides 19, 21","ch":"W1-C6","added":"2026-10-26","case":"A regional health authority moves part of its hospital budget into prevention programs run by its own clinics.","q":"Which Ottawa Charter action area does this match best?","opts":[["Developing personal skills",false,"That is about building individuals' abilities, not changing how services are run."],["Strengthening community action",false,"That is about communities acting together, not a health authority changing its services."],["Reorienting health services",true,"The health services themselves change direction, in line with the Charter's aim to ramp up prevention."],["Creating supportive environments",false,"That is about the settings people live in, not the health system's priorities."]]}],"summary":"Canada moved from quarantine and sanitation to population health (Lalonde, 1974) and health promotion (Ottawa Charter, 1986). Early-2000s outbreaks led to the Public Health Agency of Canada in 2006."},{"id":"W1-C7","title":"Epidemiologic transitions","src":"W1 Part 2, slides 25-30","blurb":"Omran's four stages and the rise in Canadian life expectancy.","learn":"Abdel Omran proposed the <b>epidemiologic transition</b> in 1971: patterns of death and disease shift as countries develop economically. There are four stages.<ul><li><b>Pestilence and Famine</b>: most of human history. Life expectancy 20 to 40, high infant mortality, deaths from malnutrition and infection. CVD about 5 to 10% of deaths.</li><li><b>Receding Pandemics</b>: late 1800s to early 1900s in developed countries. Safer food, sanitation, immunization and antibiotics. Life expectancy about 50. CVD 15 to 35%.</li><li><b>Degenerative and Man-Made Diseases</b>: mid 20th century. Chronic disease deaths overtake infectious ones. Life expectancy about 60. CVD over 50%.</li><li><b>Delayed Degenerative Disease</b>: mid-1960s to today. CVD deaths fall through tobacco control, blood pressure drugs, bypass surgery and health education. Life expectancy in Canada is about 82.</li></ul>","steps":[{"id":"W1-C7-S1","type":"label","fig":"transitions","src":"W1 Part 2, slides 26-29","prompt":"Drag Omran's four stages into order."},{"id":"W1-C7-S2","type":"sort","src":"W1 Part 2, slides 26-29","prompt":"Which stage does each feature belong to?","bins":["1. Pestilence and Famine","2. Receding Pandemics","3. Degenerative and Man-Made Diseases","4. Delayed Degenerative Disease"],"items":[["Life expectancy between 20 and 40 years",0,"Slide 26."],["CVD about 5 to 10% of deaths",0,"Slide 26."],["Immunization programs and antibiotics introduced",1,"Slide 27."],["CVD 15 to 35% of deaths; life expectancy about 50",1,"Slide 27."],["Chronic disease deaths overtake infectious disease deaths",2,"Slide 28."],["Peak in CVD and cancer; over 50% of deaths from CVD",2,"Slide 28."],["Coronary artery bypass surgery and blood pressure medications",3,"Slide 29, technological advances."],["Life expectancy in Canada about 82",3,"Slide 29."]]},{"id":"W1-C7-S3","type":"table","src":"W1 Part 2, slide 30","prompt":"Read Fig 1.2, life expectancy in Canada over time.","caption":"Fig 1.2 Public Health Achievements of the Twentieth and Twenty-First Centuries: life expectancy (years)","head":["Year","Life expectancy"],"rows":[["1900","47.3"],["1910","50.0"],["1920","57.1"],["1930","59.8"],["1940","64.3"],["1950","68.1"],["1960","70.8"],["1970","72.5"],["1980","75.2"],["1990","77.5"],["2000","79.2"],["2010","81.5"],["2019","82.05"],["2022","81.3"]],"qs":[{"id":"W1-C7-S3-Q1","type":"mcq","src":"W1 Part 2, slide 30","ch":"W1-C7","added":"2026-10-26","q":"In which listed year did life expectancy first pass 70 years?","opts":[["1960",true,"70.8 in 1960; 1950 was 68.1."],["1950",false,"1950 was 68.1, still below 70."],["1970",false,"1970 was 72.5, but it had already passed 70 in 1960."],["1940",false,"1940 was 64.3."]]},{"id":"W1-C7-S3-Q2","type":"mcq","src":"W1 Part 2, slide 30","ch":"W1-C7","added":"2026-10-26","q":"Life expectancy fell from 82.05 to 81.3. Which period was this, and what does the figure place there?","opts":[["2019 to 2022, the COVID-19 pandemic",true,"The only drop on the chart, marked with the COVID-19 icon."],["2010 to 2019, the decline in heart disease deaths",false,"Life expectancy rose from 81.5 to 82.05 in that period."],["1990 to 2000, healthier mothers and babies",false,"It rose from 77.5 to 79.2."],["1960 to 1970, recognition of tobacco as a health hazard",false,"It rose from 70.8 to 72.5."]]}]},{"id":"W1-C7-S4","type":"mcq","src":"W1 Part 2, slide 26","ch":"W1-C7","added":"2026-10-26","case":"In a region, most people die of malnutrition or infectious disease, infant mortality is high, and the population cannot sustain growth. Only about 5 to 10% of deaths are from CVD.","q":"Which epidemiologic transition stage is this?","opts":[["Age of Receding Pandemics",false,"In stage 2 infectious and malnutrition deaths are being driven down, and CVD is 15 to 35%."],["Age of Degenerative and Man-Made Diseases",false,"Stage 3 has chronic disease deaths overtaking infectious ones."],["Age of Pestilence and Famine",true,"Every feature matches slide 26; the slide gives Sub-Saharan Africa as an example."],["Age of Delayed Degenerative Disease",false,"Stage 4 is the modern stage with life expectancy around 82 in Canada."]]}],"summary":"Omran (1971) described four stages, from pestilence and famine to delayed degenerative disease. Canadian life expectancy rose from 47.3 in 1900 to 82.05 in 2019, then dipped during COVID-19."}],"questions":[{"id":"W1-Q01","type":"mcq","ch":"W1-C1","src":"W1 Part 1, slide 2","added":"2026-10-26","q":"Which definition of health is described as the predominant model in health care?","opts":[["Physical, mental, and social wellbeing, and not merely the absence of disease and infirmity",false,"The 1948 WHO definition. It is broad but hard to measure."],["A state of normal function that can be disrupted from time to time by disease",true,"This is the biomedical definition, which slide 2 calls predominant in health care."],["A resource for everyday life, not the objective of living",false,"The 1980s WHO health promotion view."],["Optimal health and vitality",false,"That is the definition of wellness."]]},{"id":"W1-Q02","type":"mcq","ch":"W1-C1","src":"W1 Part 1, slide 3","added":"2026-10-26","case":"A health ministry tries to track how many citizens are healthy using the 1948 WHO definition.","q":"Which problem from the slides is the ministry most likely to face?","opts":[["The definition ignores physical health.",false,"It explicitly includes physical wellbeing."],["The definition treats health as only the absence of disease.",false,"It says health is not merely the absence of disease."],["The definition applies only to people with a diagnosed disease.",false,"Nothing on the slide limits it this way."],["The definition is hard to measure.",true,"Slide 3 names this as the weakness of the 1948 definition."]]},{"id":"W1-Q03","type":"mcq","ch":"W1-C1","src":"W1 Part 1, slide 4","added":"2026-10-26","case":"Priya has type 1 diabetes. She manages her blood sugar, leads a campus club, and says she can meet her goals and cope with the stress of first year.","q":"Which view of health best supports calling Priya healthy?","opts":[["The biomedical definition: a state of normal function disrupted by disease",false,"Under this view her disease disrupts normal function."],["Health determined mainly by non-modifiable risk factors",false,"This is not a definition of health on the slides; slide 5 says health can be influenced by such factors."],["The sickness perspective",false,"Sickness is the social and cultural view of a condition, not a definition of health."],["Health as a resource for everyday life: the ability to realize aspirations, satisfy needs and cope with the environment",true,"The 1980s WHO view focuses on coping and meeting needs, not on the absence of disease."]]},{"id":"W1-Q04","type":"mcq","ch":"W1-C1","src":"W1 Part 1, slides 6-7","added":"2026-10-26","q":"According to the 4th Canadian edition, how many dimensions of wellness are there, and which three were added?","opts":[["Six; cultural, financial and occupational",false,"Six was the older count, before these three were added."],["Nine; cultural, financial and occupational",true,"Slide 6: six was struck out for nine, and these three were added in the 4th edition."],["Nine; spiritual, environmental and intellectual",false,"These three were already in the six-dimension figure."],["Nine; interpersonal, emotional and physical",false,"These were already present; interpersonal is the new name for social."]]},{"id":"W1-Q05","type":"mcq","ch":"W1-C1","src":"W1 Part 1, slide 7","added":"2026-10-26","case":"Jordan makes a monthly budget, stops buying things he does not need on credit, and starts an emergency fund.","q":"Which dimension of wellness is Jordan working on?","opts":[["Occupational",false,"Occupational is about enjoying your work and relationships at work."],["Emotional",false,"Emotional covers optimism, self-esteem and sharing feelings."],["Financial",true,"Fig 1.1: living within one's means, avoiding debt, saving for the future and emergencies."],["Environmental",false,"Environmental covers clean resources, recycling and reducing pollution."]]},{"id":"W1-Q06","type":"mcq","ch":"W1-C1","src":"W1 Part 1, slide 7","added":"2026-10-26","case":"Mei joins a multicultural student association to build friendships with people from backgrounds unlike hers, while keeping up her own family's traditions.","q":"Which dimension of wellness does this best match?","opts":[["Cultural",true,"Fig 1.1: creating relationships with those different from you, and valuing your own cultural identity."],["Interpersonal",false,"Interpersonal is about relationships and support systems in general, not cultural identity or difference."],["Spiritual",false,"Spiritual covers meaning, purpose, compassion and belonging to something greater."],["Intellectual",false,"Intellectual covers openness to ideas, critical thinking and curiosity."]]},{"id":"W1-Q07","type":"mcq","ch":"W1-C2","src":"W1 Part 1, slide 8","added":"2026-10-26","q":"Which perspective is defined as a person's subjective experience of their symptoms?","opts":[["Illness",true,"Illness is what the patient brings to the doctor."],["Disease",false,"Disease is the underlying pathology, the practitioner's view."],["Sickness",false,"Sickness is the social and cultural conception of the condition."],["Impairment",false,"Impairment is a box in the extended clinical course figure, not one of the three perspectives."]]},{"id":"W1-Q08","type":"mcq","ch":"W1-C2","src":"W1 Part 1, slide 8","added":"2026-10-26","case":"After his diagnosis becomes known, a man's neighbours stop visiting out of fear, and he begins hiding his condition.","q":"Which perspective describes the neighbours' reaction and its effect on him?","opts":[["Illness",false,"Illness is his own experience of symptoms, not others' reactions."],["Disease",false,"Disease is the biological pathology."],["Sickness",true,"Sickness covers cultural reactions such as fear or rejection, which affect how the patient reacts."],["Etiological phase",false,"That is the pre-disease stage of the extended clinical course."]]},{"id":"W1-Q09","type":"mcq","ch":"W1-C2","src":"W1 Part 1, slide 9","added":"2026-10-26","case":"A cardiologist inserts a stent into a narrowed coronary artery. Once blood flow is restored, she tells the patient he is healthy again.","q":"Which model is she applying?","opts":[["The social-ecological model",false,"That model looks at layers of determinants around the person, not only the artery."],["The biomedical model: removal of pathology results in restored health",true,"Slide 9 uses a stent as its example."],["Lalonde's health field concept",false,"That model adds environment, lifestyle and health care organization to biology."],["The 1980s WHO resource-for-living view",false,"That view defines health by coping and meeting needs, not by removal of pathology."]]},{"id":"W1-Q10","type":"mcq","ch":"W1-C2","src":"W1 Part 1, slide 10","added":"2026-10-26","case":"A 50-year-old feels fine, but plaque is building up in his arteries. He has had no symptoms and no diagnosis.","q":"Which phase of the clinical course is he in?","opts":[["Clinical phase",false,"The clinical phase begins when symptoms appear."],["Post-clinical phase",false,"That comes after the clinical phase, with longer-term outcomes."],["Etiological phase",false,"The etiological phase is before biological onset: determinants and risk factors."],["Preclinical phase",true,"Biological onset has occurred but symptoms have not appeared."]]},{"id":"W1-Q11","type":"mcq","ch":"W1-C2","src":"W1 Part 1, slide 15","added":"2026-10-26","case":"Two years after a stroke, a woman cannot return to her job, and her family's income has dropped.","q":"In the extended clinical course of disease, where do these effects belong?","opts":[["Etiological phase: risk and protective factors",false,"Those come before the disease."],["Preclinical phase",false,"That is before symptoms."],["Social and environmental determinants",false,"Those are the upstream causes in the etiological phase."],["Post-clinical phase: longer-term outcome",true,"Slide 15 lists impact on family, work and economic impact as the longer-term outcome."]]},{"id":"W1-Q12","type":"mcq","ch":"W1-C3","src":"W1 Part 1, slide 11","added":"2026-10-26","q":"Which is the definition of epidemiology given in the course?","opts":[["The study of pathological processes in cells, organs and systems",false,"That describes the reductionist biomedical model."],["The study of the distribution and determinants of health-related states or events in specified populations, and the application of this study to the control of health problems",true,"This is the quoted definition on slide 11."],["The study of a person's subjective experience of symptoms",false,"That describes illness."],["The study of how countries' disease patterns shift as they develop economically",false,"That is the epidemiologic transition, one topic within epidemiology."]]},{"id":"W1-Q13","type":"mcq","ch":"W1-C3","src":"W1 Part 1, slides 11 and 13","added":"2026-10-26","case":"Mapping COVID-19 onto the triad of causal factors, a student lists public health sanitation and availability of health care in one region.","q":"Which corner of the triad do these belong to?","opts":[["Host",false,"Host is the person: genetic susceptibility, resiliency, nutritional status, motivation."],["Agent",false,"Agent covers virulence, infectivity and addictive qualities."],["Environment",true,"Slide 11 lists sanitation, social context and availability of health care under environment."],["Reservoir",false,"Reservoir is not part of the triad; it was used for rats in the plague."]]},{"id":"W1-Q14","type":"mcq","ch":"W1-C3","src":"W1 Part 1, slide 14","added":"2026-10-26","case":"In one city, low-income neighbourhoods have open drainage ditches of polluted water running between homes.","q":"How do the slides classify this?","opts":[["A determinant: distal, upstream, at the population level",true,"Slide 14 uses this exact kind of photo to show a determinant."],["A risk factor: proximal to the individual",false,"Risk factors are closer to the person, like smoking."],["A proven cause of every disease in the area",false,"Determinants are correlational, not causal."],["An innate individual trait",false,"Innate traits are age, sex, race and biology."]]},{"id":"W1-Q15","type":"mcq","ch":"W1-C3","src":"W1 Part 1, slides 14 and 17","added":"2026-10-26","q":"Which statement about risk factors and determinants is NOT true?","opts":[["Risk factors are causal, while determinants are only correlational.",true,"This is false: slide 14 says both are correlational, not causal."],["Determinants tend to be distal and occur at the population level.",false,"True, from slide 14."],["Risk factors tend to be proximal to the individual.",false,"True, from slide 14."],["A determinant does not imply that an outcome is inevitable.",false,"True: slide 17 says determinant does not imply determinism."]]},{"id":"W1-Q16","type":"mcq","ch":"W1-C3","src":"W1 Part 1, slide 18","added":"2026-10-26","case":"A factory worker has rotating night shifts, little job security and daily exposure to fumes.","q":"In the social-ecological model, which level do these conditions fall under?","opts":[["Individual behaviour",false,"These are conditions of his job, not his own choices."],["Social, family and community networks",false,"That level is about relationships and support."],["Living and working conditions",true,"The slide 18 callout lists employment status and occupational factors here."],["Innate individual traits",false,"That level is age, sex, race and biological factors."]]},{"id":"W1-Q17","type":"mcq","ch":"W1-C3","src":"W1 Part 1, slide 18","added":"2026-10-26","case":"The federal government changes national tax and income support policy, which shifts income distribution for millions of people.","q":"Which level of the social-ecological model does this act on, and how is it labelled?","opts":[["Living and working conditions; proximal",false,"Living and working conditions are labelled intermediate, and national policy sits further out."],["Broad social, economic, cultural, health and environmental conditions and policies; distal",true,"The outer ring covers policies at the global, national, state and local levels and is labelled distal."],["Social, family and community networks; intermediate",false,"Networks are relationships, not national policy."],["Individual behaviour; proximal",false,"Tax policy is not an individual's behaviour."]]},{"id":"W1-Q18","type":"mcq","ch":"W1-C3","src":"W1 Part 1, slide 16","added":"2026-10-26","case":"A Black woman reports being passed over at work in ways she links to both her race and her gender together.","q":"Which concept from the slides describes this?","opts":[["Determinism",false,"Slide 17 says determinants do not imply determinism, or inevitability."],["Reductionism",false,"Reductionism describes the biomedical model."],["Sickness",false,"Sickness is the social view of a health condition, not overlapping determinants."],["Intersectionality",true,"Slide 16 gives discrimination based on both race and gender as its example."]]},{"id":"W1-Q19","type":"mcq","ch":"W1-C3","src":"W1 Part 1, slide 19","added":"2026-10-26","q":"Which description fits the Integrated Life Course and Social Determinants Model of Indigenous Health?","opts":[["Four fields of human biology, environment, lifestyle and health care organization linked to health",false,"That is Lalonde's health field concept."],["Agent, host and environment interacting to cause disease",false,"That is the triad of causal factors."],["Nine interacting dimensions on a continuum from malaise to a vital life",false,"That describes the dimensions of wellness."],["The child is at the centre, developing to adulthood, with mental, physical, emotional and spiritual aspects, surrounded by social determinants",true,"This matches the slide 19 figure and text."]]},{"id":"W1-Q20","type":"mcq","ch":"W1-C4","src":"W1 Part 2, slide 4","added":"2026-10-26","case":"Early farmers keep cattle and pigs right beside their homes and begin catching diseases from them.","q":"Which term from the Agricultural Revolution slides fits this?","opts":[["Miasma",false,"Miasma was a plague-era theory about vapours from swamps."],["Zoonoses",true,"Slide 4: humans living near animals led to zoonoses."],["Pandemics receding",false,"That is Omran's stage 2, thousands of years later."],["Spontaneous generation",false,"A theory Pasteur disproved in 1862."]]},{"id":"W1-Q21","type":"mcq","ch":"W1-C4","src":"W1 Part 2, slide 5","added":"2026-10-26","q":"Which idea is linked to Hippocrates on the slides?","opts":[["Specific microbes cause specific diseases",false,"That is germ theory and Koch's postulates."],["Rats are the reservoir and fleas are the vector",false,"That describes the plague."],["Disease is caused by an imbalance of man with the environment and of the humours",true,"Slide 5, with links to climate, water, lifestyle and nutrition."],["Mammals reproduce by fertilization of an egg by sperm",false,"Harvey was first to hypothesize this."]]},{"id":"W1-Q22","type":"mcq","ch":"W1-C4","src":"W1 Part 2, slide 7","added":"2026-10-26","q":"In the bubonic plague, what roles did rats and fleas play?","opts":[["Rats were the reservoir; fleas were the vector",true,"Slide 7 states this directly; the bacterium was Yersinia pestis."],["Fleas were the reservoir; rats were the vector",false,"This reverses the roles."],["Rats were the agent; fleas were the host",false,"The agent was the bacterium Yersinia pestis."],["Both were sources of miasma",false,"Miasma was the mistaken vapour theory."]]},{"id":"W1-Q23","type":"mcq","ch":"W1-C4","src":"W1 Part 2, slide 8","added":"2026-10-26","q":"According to the slides, what was the major factor that held back understanding of the causes of disease?","opts":[["The lack of a systematic way to test associations between exposures and outcomes",true,"Slide 8, which leads to the need for science and epidemiology."],["The lack of hospitals and physicians",false,"Not given as the reason; Lalonde later argued doctors and hospitals are not the whole story."],["The belief that disease came from imbalanced humours",false,"This was one early idea, but slide 8 names the lack of systematic testing."],["The lack of vaccines",false,"Not the reason given on slide 8."]]},{"id":"W1-Q24","type":"mcq","ch":"W1-C4","src":"W1 Part 2, slides 9-10","added":"2026-10-26","q":"Why is John Snow's removal of the Broad Street Pump handle in 1853 significant?","opts":[["It was the first time the cholera bacterium was seen under a microscope",false,"Koch identified the cholera bacterium in 1883."],["It was the first vaccine trial",false,"Jenner's cowpox experiment was in 1796."],["It is called the first public health intervention, based on systematic study of outbreak data",true,"Slides 9 and 10."],["It disproved spontaneous generation",false,"That was Pasteur in 1862."]]},{"id":"W1-Q25","type":"mcq","ch":"W1-C4","src":"W1 Part 2, slides 12-13","added":"2026-10-26","q":"Which statement about smallpox inoculation is true according to the slides?","opts":[["Jenner coined the term vaccine",false,"Pasteur coined it, in honour of Jenner."],["Inoculation against smallpox was practised in China and India as early as 1000 CE, before Jenner",true,"Slide 12: Jenner was not the first; ground-up smallpox scabs were used."],["Jenner inoculated people with ground-up smallpox scabs",false,"Jenner used material from cowpox pustules."],["Smallpox is caused by a bacterium",false,"The slide says smallpox is caused by a virus."]]},{"id":"W1-Q26","type":"mcq","ch":"W1-C4","src":"W1 Part 2, slide 13","added":"2026-10-26","case":"A researcher suspects a newly found microbe causes a lung disease and wants a formal set of rules to prove it.","q":"What would the researcher use?","opts":[["The health field concept",false,"Lalonde's model of four influences on health."],["The miasma theory",false,"A discredited theory about vapours."],["The Ottawa Charter",false,"A health promotion framework."],["Koch's postulates",true,"Slide 13: Koch's postulates prove that a specific microbe causes a specific disease."]]},{"id":"W1-Q27","type":"mcq","ch":"W1-C5","src":"W1 Part 2, slide 16","added":"2026-10-26","case":"An 1842 report shows that filth in the environment spreads disease in cities and that half of child labourers die before age 5.","q":"Who wrote this report?","opts":[["Jeremy Bentham",false,"Bentham is quoted for the greatest happiness principle, not this report."],["John Snow",false,"Snow studied cholera outbreaks in the 1850s."],["Marc Lalonde",false,"Lalonde wrote the 1974 Canadian report."],["Edwin Chadwick",true,"His Survey into the Sanitary Condition of the Labouring Classes in Great Britain (1842)."]]},{"id":"W1-Q28","type":"mcq","ch":"W1-C5","src":"W1 Part 2, slide 14","added":"2026-10-26","case":"A 19th-century official argues for funding city sewers because healthier workers help the economy and benefit the most people.","q":"Which idea from the slides does this argument reflect?","opts":[["Hippocrates' balance of the humours",false,"That is about body fluids, not economics or policy."],["Bentham's \"greatest happiness of the greatest number\", and that lower mortality is better for the economy",true,"Slide 14 links these industrial-era ideals."],["Koch's postulates",false,"Rules for linking microbes to disease."],["Omran's epidemiologic transition",false,"A 1971 theory of shifting disease patterns."]]},{"id":"W1-Q29","type":"mcq","ch":"W1-C5","src":"W1 Part 2, slide 17","added":"2026-10-26","q":"Which was NOT a feature of the Great Sanitary Awakening (1800 to 1900s)?","opts":[["Recognition of the connection between poverty and disease",false,"Listed on slide 17."],["Public works departments",false,"Listed on slide 17."],["Establishment of a national public health agency with a Chief Public Health Officer",true,"That is the 2006 Public Health Agency of Canada Act."],["Monitoring community health status",false,"Listed on slide 17."]]},{"id":"W1-Q30","type":"mcq","ch":"W1-C6","src":"W1 Part 2, slide 20","added":"2026-10-26","case":"A province launches a campaign to cut smoking and get people more active.","q":"Which field of Lalonde's health field concept does it target?","opts":[["Lifestyle",true,"Lalonde's report speaks of moderating self-imposed risks."],["Human biology",false,"Human biology is about the body and genetics, not habits."],["Environment",false,"Environment is about surroundings, not personal habits."],["Health care organization",false,"That field is about the health care system."]]},{"id":"W1-Q31","type":"mcq","ch":"W1-C6","src":"W1 Part 2, slides 19-20","added":"2026-10-26","q":"What did the 1974 Lalonde Report argue?","opts":[["Equating the level of health with the availability of physicians and hospitals is inadequate; look beyond the individual to the population",true,"Slides 19 and 20. It started the Population Health Movement."],["Health is the absence of disease and is best restored by treatment",false,"That is the biomedical view."],["The main threats to Canadians are infectious diseases arriving with immigrants",false,"That was the early 19th century focus on quarantine."],["Canada needed a Chief Public Health Officer",false,"That came with the 2006 PHAC Act."]]},{"id":"W1-Q32","type":"mcq","ch":"W1-C6","src":"W1 Part 2, slide 21","added":"2026-10-26","case":"A community health centre runs cooking and budgeting workshops so residents can make healthier choices on their own.","q":"Which Ottawa Charter action area does this match?","opts":[["Building healthy public policy",false,"That would be laws or policies, not workshops."],["Reorienting health services",false,"That is about changing how health services are run."],["Developing personal skills",true,"The workshops build individuals' abilities."],["Strengthening community action",false,"That is about communities organizing to act together."]]},{"id":"W1-Q33","type":"mcq","ch":"W1-C6","src":"W1 Part 2, slide 22","added":"2026-10-26","q":"Which is NOT one of the Ottawa Charter's seven prerequisites for health?","opts":[["Peace",false,"On the list."],["Access to physicians",true,"Not on the list."],["A stable eco-system",false,"On the list."],["Income",false,"On the list."]]},{"id":"W1-Q34","type":"mcq","ch":"W1-C6","src":"W1 Part 2, slides 23-24","added":"2026-10-26","q":"The 2000 Walkerton E. coli outbreak, the 2001 North Battlefield cryptosporidium outbreak and SARS in Toronto in 2002 are presented as evidence of what?","opts":[["Canada's entry into the Age of Pestilence and Famine",false,"Stage 1 is most of human history, with life expectancy 20 to 40."],["The success of the Great Sanitary Awakening",false,"These outbreaks showed gaps, not success."],["The start of the Population Health Movement",false,"That started with the 1974 Lalonde Report."],["Cracks in the public health infrastructure, followed by the 2006 Public Health Agency of Canada Act",true,"Slides 23 and 24."]]},{"id":"W1-Q35","type":"mcq","ch":"W1-C6","src":"W1 Part 2, slide 24","added":"2026-10-26","q":"Which is part of the mandate of Canada's Chief Public Health Officer?","opts":[["Run hospitals in each province",false,"Not part of the mandate."],["Approve each physician's licence",false,"Not part of the mandate."],["Write the Ottawa Charter",false,"The Charter came from a 1986 international conference."],["Provide science-based health policy analysis and advice to the federal minister for health",true,"One of the four mandate points on slide 24."]]},{"id":"W1-Q36","type":"mcq","ch":"W1-C7","src":"W1 Part 2, slide 25","added":"2026-10-26","q":"Who first proposed the epidemiologic transition, and when?","opts":[["Marc Lalonde, 1974",false,"Lalonde wrote the health field concept report."],["Abdel Omran, 1971",true,"Slide 25."],["Edwin Chadwick, 1842",false,"Chadwick wrote the sanitary report."],["John Snow, 1853",false,"Snow is the father of epidemiology, not of the transition theory."]]},{"id":"W1-Q37","type":"mcq","ch":"W1-C7","src":"W1 Part 2, slide 27","added":"2026-10-26","case":"A country introduces immunization programs and antibiotics, improves sanitation and prenatal care, and life expectancy rises to about 50. CVD causes 15 to 35% of deaths.","q":"Which stage is this country in?","opts":[["Age of Pestilence and Famine",false,"Stage 1 has life expectancy of 20 to 40 and CVD at 5 to 10%."],["Age of Degenerative and Man-Made Diseases",false,"Stage 3 has life expectancy about 60 and CVD over 50%."],["Age of Receding Pandemics",true,"Every feature matches slide 27."],["Age of Delayed Degenerative Disease",false,"Stage 4 has falling CVD deaths and life expectancy near 82 in Canada."]]},{"id":"W1-Q38","type":"mcq","ch":"W1-C7","src":"W1 Part 2, slide 28","added":"2026-10-26","case":"In a region, deaths from chronic disease have just overtaken deaths from infection. Life expectancy is about 60, and over half of deaths are from CVD.","q":"Which stage is this?","opts":[["Age of Degenerative and Man-Made Diseases",true,"Slide 28: chronic overtakes infectious, about 60 years, over 50% CVD."],["Age of Receding Pandemics",false,"In stage 2, CVD is only 15 to 35% of deaths."],["Age of Delayed Degenerative Disease",false,"In stage 4, CVD deaths are declining."],["Age of Pestilence and Famine",false,"In stage 1, people mainly die of malnutrition or infection."]]},{"id":"W1-Q39","type":"mcq","ch":"W1-C7","src":"W1 Part 2, slide 29","added":"2026-10-26","q":"In the Age of Delayed Degenerative Disease, which factors does the slide credit for the decline in CVD mortality?","opts":[["Smoking cessation and tobacco control, blood pressure medications and bypass surgery, and public health education",true,"Slide 29 lists prevention, technology and education."],["Draining swamps and covering cesspools",false,"That follows the old miasma theory."],["Quarantine of immigrants",false,"An early 19th century Canadian measure against cholera and typhus."],["The first introduction of antibiotics and immunization",false,"Slide 27 puts these in stage 2."]]},{"id":"W1-Q40","type":"mcq","ch":"W1-C7","src":"W1 Part 2, slides 26-29","added":"2026-10-26","q":"Which statement about Omran's stages is NOT true?","opts":[["The Age of Pestilence and Famine covers most of human history.",false,"True, slide 26."],["In the Age of Delayed Degenerative Disease, CVD is still a top 3 cause of death.",false,"True, slide 29."],["In the Age of Degenerative and Man-Made Diseases, life expectancy is about 82 years.",true,"False: stage 3 is about 60. About 82 is today's Canada, in stage 4."],["The Age of Receding Pandemics was in the late 1800s to early 1900s in developed countries.",false,"True, slide 27."]]}],"review":[{"id":"W1-R01","ch":"W1-C1","src":"W1 Part 1, slides 2-4","added":"2026-10-26","q":"Compare the three definitions of health on the slides. Give one strength or weakness of each.","answer":"The biomedical definition calls health a state of normal function that is disrupted from time to time by disease. It is the predominant model in health care, but it reduces health to the absence of disease. The 1948 WHO definition adds mental and social wellbeing and says health is not merely the absence of disease, but it is hard to measure. The 1980s WHO health promotion view calls health a resource for everyday life, not the objective of living: the ability to realize aspirations, satisfy needs, and change or cope with the environment. It treats health as resiliency rather than a fixed state.","points":["Biomedical: normal function disrupted by disease; predominant in health care","WHO 1948: physical, mental and social wellbeing, not merely absence of disease","WHO 1948 weakness: hard to measure","WHO 1980s: resource for everyday life; realize aspirations, satisfy needs, cope with environment","Health as resiliency, not a static state"]},{"id":"W1-R02","ch":"W1-C2","src":"W1 Part 1, slides 8-9","added":"2026-10-26","q":"Explain the difference between disease, illness and sickness, using one condition as an example.","answer":"Disease is the underlying pathology, defined biologically from the practitioner's perspective. For heart disease, it is plaque narrowing a coronary artery. Illness is the person's subjective experience of symptoms, such as chest tightness and fatigue that the patient brings to the doctor. Sickness is the social and cultural conception of the condition, such as how others react with fear or rejection and whether it is seen as something needing medical treatment. The biomedical model focuses on disease and assumes that removing it ends the illness.","points":["Disease: underlying pathology, practitioner's view","Illness: subjective experience of symptoms","Sickness: social and cultural reactions and conceptions","A worked example for each","Biomedical model focuses on disease"]},{"id":"W1-R03","ch":"W1-C3","src":"W1 Part 1, slides 14, 17-18","added":"2026-10-26","q":"Distinguish risk factors from determinants and place each in the social-ecological model.","answer":"A risk factor is a variable associated with an increased statistical probability of disease, injury or infection. It is proximal to the individual, like smoking, and fits the individual behaviour ring. A determinant is an upstream factor that correlates with increased risk. It is distal and works at the population level, like poor sanitation in a slum, and sits in the outer rings such as living and working conditions or broad conditions and policies. Both are correlational, not causal, and a determinant does not imply that an outcome is inevitable.","points":["Risk factor definition; proximal, individual","Determinant definition; distal, upstream, population level","Both correlational, not causal","Determinant is not determinism","Correct placement in the social-ecological rings"]},{"id":"W1-R04","ch":"W1-C4","src":"W1 Part 2, slides 7-10","added":"2026-10-26","q":"Why is John Snow called the father of epidemiology? Connect his work to the problem described in the slide 8 concept.","answer":"Before Snow, ideas like miasma blamed disease on vapours from swamps or cesspools. Slide 8 says the lack of a systematic way to test associations between exposures and outcomes was the major factor holding back understanding of disease causes. Snow, a London physician, systematically studied cholera outbreaks, and his data supported his theory of the source. In 1853 he removed the handle from the Broad Street Pump, called the first public health intervention. His work showed how systematic study of exposures and outcomes could guide prevention.","points":["Earlier theories such as miasma","Lack of systematic testing of exposure and outcome links","Snow systematically studied cholera outbreaks in London","Broad Street Pump handle removed in 1853","First public health intervention"]},{"id":"W1-R05","ch":"W1-C6","src":"W1 Part 2, slides 19-22","added":"2026-10-26","q":"Describe how the Lalonde Report (1974) and the Ottawa Charter (1986) changed the approach to health in Canada.","answer":"The Lalonde Report, by former federal health minister Marc Lalonde, looked beyond the individual to the health of the population and started the Population Health Movement. Its health field concept has four fields: human biology, environment, lifestyle and health care organization. It argued that equating health with the availability of physicians and hospitals is inadequate. The Ottawa Charter came from the first international conference on health promotion. It aimed to reduce inequities, ramp up prevention and empower individuals through five action areas, and named seven prerequisites for health such as peace, shelter, food and income.","points":["Lalonde: population health, Population Health Movement","Four fields of the health field concept","Doctors and hospitals alone are inadequate","Ottawa Charter: first international health promotion conference","Five action areas and seven prerequisites"]},{"id":"W1-R06","ch":"W1-C7","src":"W1 Part 2, slides 25-29","added":"2026-10-26","q":"Outline Omran's four epidemiologic transitions, with life expectancy and share of deaths from CVD where the slides give them.","answer":"Omran proposed the theory in 1971: patterns of mortality and disease shift as countries develop economically. In the Age of Pestilence and Famine, life expectancy is 20 to 40 years, people die of malnutrition and infection, and CVD is about 5 to 10% of deaths. In the Age of Receding Pandemics, sanitation, safer food, immunization and antibiotics raise life expectancy to about 50, and CVD is 15 to 35%. In the Age of Degenerative and Man-Made Diseases, chronic disease deaths overtake infectious ones, life expectancy is about 60 and over 50% of deaths are from CVD. In the Age of Delayed Degenerative Disease, CVD deaths fall through tobacco control, medications, surgery and education, and Canadian life expectancy is about 82.","points":["Omran, 1971, linked to economic development","Stage 1: 20 to 40 years, CVD 5 to 10%","Stage 2: about 50 years, CVD 15 to 35%","Stage 3: about 60 years, CVD over 50%, chronic overtakes infectious","Stage 4: CVD deaths decline, Canada about 82"]}],"explore":[{"fig":"sem","title":"Social-ecological model","caption":"Levels of influence on health, from proximal at the centre to distal at the edge, over the life span.","items":{"innate":{"label":"Innate individual traits","text":"Age, sex, race and biological factors: the biology of disease. The instructor labels the centre proximal.","src":"W1 Part 1, slide 18"},"behaviour":{"label":"Individual behaviour","text":"What the person does. Risk factors such as smoking are proximal to the individual.","src":"W1 Part 1, slides 14 and 18"},"networks":{"label":"Social, family and community networks","text":"The people and communities around the person. This ring and the next are labelled intermediate.","src":"W1 Part 1, slide 18"},"living":{"label":"Living and working conditions","text":"Psychosocial factors, employment and occupational factors, socioeconomic status, the natural and built environments, public health services and health care services.","src":"W1 Part 1, slide 18"},"broad":{"label":"Broad social, economic, cultural, health and environmental conditions and policies","text":"Conditions and policies at the global, national, state and local levels. Labelled distal. Determinants tend to sit out here, upstream and at the population level.","src":"W1 Part 1, slides 14 and 18"}}},{"fig":"transitions","title":"Omran's epidemiologic transitions","caption":"Patterns of mortality and disease shift as countries develop economically (Omran, 1971).","items":{"t1":{"label":"Age of Pestilence and Famine","text":"Most of human history. Life expectancy 20 to 40 years, deaths mainly from malnutrition and infection, CVD about 5 to 10% of deaths.","src":"W1 Part 2, slide 26"},"t2":{"label":"Age of Receding Pandemics","text":"Late 1800s to early 1900s in developed countries. Sanitation, safer food, immunization and antibiotics; life expectancy about 50; CVD 15 to 35%.","src":"W1 Part 2, slide 27"},"t3":{"label":"Age of Degenerative and Man-Made Diseases","text":"Mid 20th century. Chronic disease deaths overtake infectious ones; life expectancy about 60; over 50% of deaths from CVD.","src":"W1 Part 2, slide 28"},"t4":{"label":"Age of Delayed Degenerative Disease","text":"Mid-1960s to today. CVD deaths decline through tobacco control, blood pressure medications, bypass surgery and education. Life expectancy in Canada is about 82.","src":"W1 Part 2, slide 29"}}}]},{"id":"W2","n":2,"added":"2026-10-26","title":"Current Health Challenges and How We Meet Them","short":"Challenges & change","blurb":"Leading causes of death, health inequities, public and population health strategies, levels of prevention, and the models and steps of personal behaviour change.","topics":["Leading causes of death: Canada 2022, ages 15 to 24, WHO 2021","Health inequality, disparity, inequity; levels of racism","PHAC mandate; public vs population health","Levels of prevention; protection, promotion, surveillance","Ottawa Charter and the Pan-Canadian Healthy Living Strategy","Stages of change, Health Belief Model, Theory of Planned Behaviour, SMART goals"],"lectures":["Week 2 Part 1: Current Health Challenges in Canada and the World","Week 2 Part 2: Meeting the Challenges: Population and Public Health Approaches","Week 2 Part 3: Meeting the Challenges: Personal Wellness"],"terms":[{"id":"W2-T-canada-leading-causes-2022","term":"Ten leading causes of death in Canada, 2022","def":"Of 334,081 deaths in 2022, the ten leading causes made up 227,712 (68.3%). Ranked: cancer (82,412; 24.7%), heart disease, COVID-19, unintentional injuries, stroke, chronic lower respiratory diseases, diabetes, influenza and pneumonia, Alzheimer's disease, chronic liver disease and cirrhosis. Lifestyle codes: D diet, I inactive lifestyle, S smoking, A excessive alcohol, O obesity.","ex":"Chronic lower respiratory diseases are coded S and O: smoking and obesity play a part.","src":"W2 Part 1, slide 2","ch":"W2-C1","added":"2026-10-26"},{"id":"W2-T-youth-leading-causes-2023","term":"Leading causes of death, Canadians aged 15 to 24, 2023","def":"Of 2,326 deaths: 1. accidents (unintentional injuries) 694 (29.8%); 2. intentional self-harm (death by suicide) 391 (16.8%); 3. cancer 131 (5.6%); 4. assault (homicide) 68 (2.9%); 5. heart disease 37 (1.6%).","src":"W2 Part 1, slide 3","ch":"W2-C1","added":"2026-10-26"},{"id":"W2-T-who-global-top-10-2021","term":"Top 10 global causes of death, 2021 (WHO)","def":"The top 10 causes accounted for 39 million deaths, or 57% of the 68 million deaths worldwide. Ischaemic heart disease ranked first, COVID-19 second and stroke third.","src":"W2 Part 1, slide 4","ch":"W2-C1","added":"2026-10-26"},{"id":"W2-T-high-vs-low-income-deaths","term":"High-income vs low-income country death patterns","def":"High-income countries: deaths mostly from noncommunicable chronic diseases (cancers, cardiovascular diseases, chronic obstructive lung disease, dementia, kidney diseases); the only leading communicable causes are COVID-19 and lower respiratory infections. Low-income countries: deaths mostly from communicable (infectious) diseases (lower respiratory infections, COVID-19, diarrhoeal diseases, HIV/AIDS, malaria, TB), plus many deaths from complications in childbirth.","src":"W2 Part 1, slides 5-7","ch":"W2-C1","added":"2026-10-26"},{"id":"W2-T-who-13-urgent-challenges","term":"WHO 13 urgent health challenges (2020)","def":"WHO list for the next decade: climate crisis; health in conflict and crisis; access to medicines; stopping infectious diseases; preparing for epidemics/pandemics; lack of food, unsafe food, unhealthy diets and dangerous products; under-investment in health care workers; keeping adolescents safe; earning public trust; ethical and social implications of new technologies; antimicrobial resistance; lack of water, sanitation and hygiene in health facilities; health inequities.","src":"W2 Part 1, slides 8, 11","ch":"W2-C1","added":"2026-10-26"},{"id":"W2-T-environmental-health","term":"Environmental health","def":"Grew out of efforts to control communicable diseases: clean water, sanitary waste disposal, safe food, insect and rodent control, and responding to natural or human-made disasters. Its focus has expanded and become more complex over the last few decades.","ex":"Burning fossil fuels releases greenhouse gases that contribute to global warming, with more severe weather, rising sea levels, flooding, drought and insect vectors moving into new regions.","src":"W2 Part 1, slides 9-10","ch":"W2-C1","added":"2026-10-26"},{"id":"W2-T-health-inequality","term":"Health inequality","def":"A systematic difference in health between groups of people due to biological differences and/or lifestyle, socio-economic status, or differential access to health care.","src":"W2 Part 1, slide 15","ch":"W2-C2","added":"2026-10-26"},{"id":"W2-T-health-disparity","term":"Health disparity","def":"Systematic inequalities in health due mainly to social disadvantages.","src":"W2 Part 1, slide 15","ch":"W2-C2","added":"2026-10-26"},{"id":"W2-T-health-inequity","term":"Health inequity","def":"A health disparity that is deemed unfair, which creates a moral imperative to try to correct it.","ex":"Systematic health disparities for Indigenous Canadians.","src":"W2 Part 1, slide 15","ch":"W2-C2","added":"2026-10-26"},{"id":"W2-T-sex","term":"Sex","def":"The different biological and physiological characteristics of females, males and intersex persons, such as chromosomes, hormones and reproductive organs.","src":"W2 Part 1, slide 17","ch":"W2-C2","added":"2026-10-26"},{"id":"W2-T-gender","term":"Gender","def":"The socially constructed characteristics of women, men, girls and boys, including norms, behaviours, roles and relationships with each other. It varies from society to society and can change over time.","src":"W2 Part 1, slide 17","ch":"W2-C2","added":"2026-10-26"},{"id":"W2-T-gender-identity","term":"Gender identity","def":"A person's deeply felt, internal and individual experience of gender, which may or may not correspond to the person's physiology or designated sex at birth.","src":"W2 Part 1, slide 17","ch":"W2-C2","added":"2026-10-26"},{"id":"W2-T-social-gradient","term":"Social gradient in health","def":"The steady rise in longevity across income levels. Gradients also exist in rates of disability and ill-health, and between certain racial or ethnic groups.","ex":"Remaining life expectancy at age 25 in Canada rises with each income quintile, for both men and women (Figure 2.1, 1991 to 2006).","src":"W2 Part 1, slide 19","ch":"W2-C2","added":"2026-10-26"},{"id":"W2-T-institutionalized-racism","term":"Institutionalized (structural) racism","def":"Racism built into systems, seen in differences in material conditions and in access to power.","ex":"A racialized neighbourhood that has worse housing and fewer services, and little say in decisions about them.","src":"W2 Part 1, slide 21","ch":"W2-C2","added":"2026-10-26"},{"id":"W2-T-personally-mediated-racism","term":"Personally-mediated racism","def":"Racism carried out between people, as prejudice and discrimination.","ex":"A clinic receptionist treats a patient differently because of their race.","src":"W2 Part 1, slide 21","ch":"W2-C2","added":"2026-10-26"},{"id":"W2-T-internalized-racism","term":"Internalized racism","def":"Acceptance by members of the stigmatized races of negative messages about their own abilities and intrinsic worth.","src":"W2 Part 1, slide 21","ch":"W2-C2","added":"2026-10-26"},{"id":"W2-T-camara-jones","term":"Camara Jones (2000)","def":"Published 'Levels of racism: a theoretic framework and a gardener's tale' (American Journal of Public Health, 2000), which sets out three levels of racism: institutionalized, personally-mediated, and internalized.","src":"W2 Part 1, slide 21","ch":"W2-C2","added":"2026-10-26"},{"id":"W2-T-indigenous-health-inequities","term":"Health inequities among Indigenous Peoples of Canada","def":"Compared with non-Indigenous populations: higher infant mortality, shorter life expectancy, 1.5x higher rate of heart disease, 2 to 5x higher rate of type 2 diabetes, 40x higher rate of tuberculosis, and higher food insecurity (inadequate nutritional intake from less access to both quality and quantity of nutritious food, such as fresh fruits and vegetables). Contributing factors include diet, physical activity, substance use, trauma and colonization. Indigenous people are 4x more likely to be unemployed, and people living on reserves earn half the income.","src":"W2 Part 1, slide 25","ch":"W2-C2","added":"2026-10-26"},{"id":"W2-T-phac-mandate","term":"Mandate of the Public Health Agency of Canada (PHAC)","def":"Promote health; prevent and control chronic diseases and injuries; prevent and control infectious diseases; prepare for and respond to public health emergencies; share Canada's expertise with the world; apply international research to Canada's public health programs; strengthen intergovernmental collaboration and national approaches to public health policy and planning.","src":"W2 Part 2, slide 4","ch":"W2-C3","added":"2026-10-26"},{"id":"W2-T-public-vs-population-health","term":"Public health and population health","def":"Both look at patterns of health and illness in groups rather than individuals, monitor health trends, examine their determinants, and propose population-level interventions to protect and promote health. The population model takes a broader view and often looks at underlying social determinants, such as poverty or lack of access to care, with the aim of reducing health inequities.","src":"W2 Part 2, slide 5","ch":"W2-C3","added":"2026-10-26"},{"id":"W2-T-primordial-prevention","term":"Primordial prevention","def":"Actions to minimize future hazards to health by addressing broad health determinants. Targets the whole population, mainly through government legislation and fiscal measures and community agencies' social programs.","ex":"Legislation that raises income supports for low-income families.","src":"W2 Part 2, slides 6-7","ch":"W2-C3","added":"2026-10-26"},{"id":"W2-T-primary-prevention","term":"Primary prevention","def":"Prevents the onset of specific diseases through risk reduction, by limiting exposures that lead to disease. Targets at-risk groups through public health community action and family physician counselling.","ex":"A family physician counsels a healthy patient who smokes to quit.","src":"W2 Part 2, slides 6-7","ch":"W2-C3","added":"2026-10-26"},{"id":"W2-T-secondary-prevention","term":"Secondary prevention","def":"Procedures to detect and treat pathological changes early, when intervention can be more effective. Aimed at patients with disease in the preclinical phase, for example through public health screening.","ex":"A screening test finds an early change that is then treated.","src":"W2 Part 2, slides 6-7","ch":"W2-C3","added":"2026-10-26"},{"id":"W2-T-tertiary-prevention","term":"Tertiary prevention","def":"After a disease has been treated in the clinical phase, actions to prevent relapse or decrease its impact on the patient. Aimed at recovering individuals through clinicians' counselling, follow-up care and rehabilitation.","ex":"Rehabilitation after a heart attack.","src":"W2 Part 2, slides 6-7","ch":"W2-C3","added":"2026-10-26"},{"id":"W2-T-health-protection","term":"Health protection","def":"Reducing threats to population health through primordial and primary prevention activities, such as the safety of food and water, addressing environmental threats and controlling infectious diseases. One of the roles of PHAC and other government agencies.","src":"W2 Part 2, slide 8","ch":"W2-C4","added":"2026-10-26"},{"id":"W2-T-surveillance","term":"Surveillance","def":"The ongoing, systematic collection and analysis of population-level health information to guide the design of public health and preventive interventions. May include long-term, passive monitoring of general health trends, or active, short-term checking for emergent diseases or outbreaks.","src":"W2 Part 2, slide 9","ch":"W2-C4","added":"2026-10-26"},{"id":"W2-T-health-promotion","term":"Health promotion","def":"Aims to enhance health through education, developing healthy public policy, preventing disease, organizational, economic and political interventions that support healthy behaviour change, and strengthening the skills and resiliency of individuals and community groups. Differs from health protection, which focuses on removing negative threats.","src":"W2 Part 2, slide 11","ch":"W2-C4","added":"2026-10-26"},{"id":"W2-T-ottawa-charter","term":"Ottawa Charter for Health Promotion","def":"Five action areas: building healthy public policy, creating supportive environments, strengthening community action, developing personal skills, and reorienting health services. At its centre are three strategies: enable, mediate, advocate.","src":"W2 Part 2, slide 10","ch":"W2-C4","added":"2026-10-26"},{"id":"W2-T-pan-canadian-healthy-living-strategy","term":"Integrated Pan-Canadian Healthy Living Strategy","def":"Created in 2002 by the federal, provincial and territorial ministers of health. Goals (by 2015): improve health outcomes by focusing on modifiable risk factors for non-communicable diseases (physical inactivity, unhealthy diets, tobacco use) and reduce health disparities. Strengthened in 2010 by two initiatives: making prevention of disease, disability and injury and health promotion priorities, and decreasing childhood obesity.","ex":"Alberta's target: raise physical activity by 10 percentage points, from 52% to 62%.","src":"W2 Part 2, slides 12-15","ch":"W2-C4","added":"2026-10-26"},{"id":"W2-T-behaviour-change","term":"Behaviour change","def":"An approach to lifestyle management: moving toward wellness by cultivating healthy behaviours and working to overcome unhealthy ones. Getting serious means examining your current habits, choosing a target behaviour, learning about it, and finding help.","src":"W2 Part 3, slide 3","ch":"W2-C5","added":"2026-10-26"},{"id":"W2-T-self-efficacy","term":"Self-efficacy","def":"Belief in your ability to make a change. Ways to boost it: an internal locus of control, visualization and self-talk, role models and other supportive people, and identifying and overcoming barriers to change.","src":"W2 Part 3, slide 6","ch":"W2-C5","added":"2026-10-26"},{"id":"W2-T-locus-of-control","term":"Locus of control","def":"The figurative place a person designates as the source of responsibility for the events in their life. Internal: the person sees themselves as responsible. External: the person sees outside forces as responsible.","ex":"'I failed because I did not study' is internal; 'I failed because the test was unfair' is external.","src":"W2 Part 3, slide 6","ch":"W2-C5","added":"2026-10-26"},{"id":"W2-T-transtheoretical-model","term":"Transtheoretical model (stages of change)","def":"A model of a person's readiness to change: to change a target behaviour you move through distinct stages (precontemplation, contemplation, preparation, action, maintenance, termination). Knowing your current stage helps you choose strategies to progress. Relapse, slipping back to a previous stage, is a common part of the cycle (Fig 1.7).","src":"W2 Part 3, slides 7-9","ch":"W2-C5","added":"2026-10-26"},{"id":"W2-T-precontemplation","term":"Precontemplation","def":"Stage of change: the person has no intention to change and sees no reason to.","ex":"'I do not see why I should stop vaping.'","src":"W2 Part 3, slide 9","ch":"W2-C5","added":"2026-10-26"},{"id":"W2-T-contemplation","term":"Contemplation","def":"Stage of change: the person intends to change the target behaviour within 6 months.","src":"W2 Part 3, slide 9","ch":"W2-C5","added":"2026-10-26"},{"id":"W2-T-preparation","term":"Preparation","def":"Stage of change: the person plans to take action within a month or is already taking small steps to change.","src":"W2 Part 3, slide 9","ch":"W2-C5","added":"2026-10-26"},{"id":"W2-T-action-stage","term":"Action","def":"Stage of change: the person is already making changes to the behaviour, which requires time and energy.","src":"W2 Part 3, slide 9","ch":"W2-C5","added":"2026-10-26"},{"id":"W2-T-maintenance","term":"Maintenance","def":"Stage of change: the person has maintained the new, healthier lifestyle for at least 6 months.","src":"W2 Part 3, slide 9","ch":"W2-C5","added":"2026-10-26"},{"id":"W2-T-termination","term":"Termination","def":"Stage of change: the new behaviour is adopted.","src":"W2 Part 3, slide 9","ch":"W2-C5","added":"2026-10-26"},{"id":"W2-T-health-belief-model","term":"Health Belief Model (HBM)","def":"Decisions depend on a pattern of beliefs. People are most likely to take preventive action if they see the threat as serious, see themselves as susceptible, and believe the benefits of acting outweigh not acting; a strong enough belief triggers action. Perceived susceptibility and severity form the perceived threat.","ex":"A student gets a flu shot.","src":"W2 Part 3, slides 7, 11-12","ch":"W2-C5","added":"2026-10-26"},{"id":"W2-T-cues-to-action","term":"Cues to action (HBM)","def":"Triggers in the Health Belief Model that raise perceived threat: raised awareness (mass media campaign, newspaper article), personal advice (reminder from a health professional), personal symptoms, or illness of a family member or friend.","src":"W2 Part 3, slide 12","ch":"W2-C5","added":"2026-10-26"},{"id":"W2-T-theory-of-planned-behaviour","term":"Theory of Planned Behaviour (TPB)","def":"Assumes rational planning by the person. An extension of the HBM that adds subjective norms and self-efficacy. Attitude, subjective norms and perceived behavioural control (from control beliefs, self-efficacy) shape intention to act, and intention leads to behaviour; perceived behavioural control also has a direct path to behaviour.","src":"W2 Part 3, slides 7, 13","ch":"W2-C5","added":"2026-10-26"},{"id":"W2-T-subjective-norms","term":"Subjective norms (TPB)","def":"Felt social pressure to act (perceived social pressure to change), built from normative beliefs about how others view the behaviour.","src":"W2 Part 3, slides 7, 13","ch":"W2-C5","added":"2026-10-26"},{"id":"W2-T-personalized-plan-steps","term":"Five steps of a personalized plan","def":"1. Monitor your behaviour and gather data. 2. Analyze the data and identify patterns. 3. Be SMART about setting goals. 4. Devise a plan of action. 5. Make a personal contract.","src":"W2 Part 3, slide 14","ch":"W2-C6","added":"2026-10-26"},{"id":"W2-T-health-journal","term":"Health journal","def":"A record of the target behaviour on each occurrence: what the activity was, when and where it happened, what you were doing, and how you felt at the time.","ex":"Fig 1.8 logs time, meal or snack, food, hunger rating, place, who influenced you, and emotions.","src":"W2 Part 3, slides 15-16","ch":"W2-C6","added":"2026-10-26"},{"id":"W2-T-smart-goals","term":"SMART goals","def":"Specific (do not be vague), Measurable (give your goal a number), Attainable (recognize your limits), Realistic (manage your expectations), Time frame specific (how long will it take?).","ex":"Walk 2 km, 3 days a week, for 15 to 20 minutes, in week 2 (Fig 1.9).","src":"W2 Part 3, slide 18","ch":"W2-C6","added":"2026-10-26"},{"id":"W2-T-personal-contract","term":"Personal contract","def":"A signed statement of your goal and your commitment to it: when you will start, how you will measure progress, which strategies you will use, and the date you expect to succeed. It can list mini-goals with rewards and a helper who witnesses it.","src":"W2 Part 3, slide 20","ch":"W2-C6","added":"2026-10-26"},{"id":"W2-T-tb-health","term":"Health (textbook definition)","def":"The overall condition of body or mind and the presence or absence of illness or injury. Some aspects of health can be determined or influenced by factors beyond your control, such as your genes, age, the health care system and the care you received as a young child.","ex":"A 60-year-old man with a strong family history of prostate cancer and limited access to screening has a higher-than-average risk.","src":"Textbook Ch 1, p. 4","ch":"W2-C7","added":"2026-10-26"},{"id":"W2-T-tb-wellness-decisions","term":"Wellness as a product of decisions","def":"Wellness is optimal health and vitality, encompassing all the dimensions of well-being. Unlike health, it is largely determined by the decisions you make about how you live.","ex":"The same 60-year-old man can lower his cancer risk by eating sensibly, exercising and getting screened, and can still live a rich life if he becomes ill.","src":"Textbook Ch 1, p. 4","ch":"W2-C7","added":"2026-10-26"},{"id":"W2-T-tb-modifiable-nonmodifiable","term":"Modifiable vs nonmodifiable risk factors","def":"Nonmodifiable risk factors, such as age and family history, cannot be controlled. Modifiable risk factors are behaviours you can change, such as smoking, exercising and eating a healthy diet. Enhanced wellness means making conscious decisions to control the modifiable ones.","src":"Textbook Ch 1, p. 4","ch":"W2-C7","added":"2026-10-26"},{"id":"W2-T-tb-wellness-continuum","term":"Wellness continuum (Fig 1.1)","def":"Wellness runs from a low level of wellness (physical, mental and emotional symptoms) to a high level of wellness, through change and growth. Wellness is constant and dynamic, not static, and ignoring any dimension can harm your life.","src":"Textbook Ch 1, pp. 4-5","ch":"W2-C7","added":"2026-10-26"},{"id":"W2-T-tb-physical-wellness","term":"Physical wellness","def":"Your body's overall condition and the absence of disease, plus your fitness level and your ability to care for yourself. The higher your fitness level and self-care ability, the higher your physical wellness.","ex":"Eating well, exercising, getting regular checkups, avoiding injuries.","src":"Textbook Ch 1, p. 5","ch":"W2-C7","added":"2026-10-26"},{"id":"W2-T-tb-emotional-wellness","term":"Emotional wellness","def":"Your ability to understand and deal with your feelings: attending to your thoughts and feelings, monitoring your reactions, identifying obstacles to emotional stability, and finding solutions to emotional problems, with professional help if necessary.","ex":"Self-esteem, self-acceptance, self-confidence.","src":"Textbook Ch 1, p. 5","ch":"W2-C7","added":"2026-10-26"},{"id":"W2-T-tb-intellectual-wellness","term":"Intellectual wellness","def":"Constantly challenging your mind. An active mind detects problems, finds solutions and directs behaviour. People with intellectual wellness never stop learning and seek out new experiences and challenges.","ex":"Openness to new ideas, critical thinking, curiosity, lifelong learning.","src":"Textbook Ch 1, p. 5","ch":"W2-C7","added":"2026-10-26"},{"id":"W2-T-tb-interpersonal-wellness","term":"Interpersonal (social) wellness","def":"Your ability to develop and maintain satisfying and supportive relationships, which are essential to physical and emotional health. It also requires participating in and contributing to your community and society.","ex":"Communication skills, capacity for intimacy, a support system of friends and family.","src":"Textbook Ch 1, p. 5","ch":"W2-C7","added":"2026-10-26"},{"id":"W2-T-tb-spiritual-wellness","term":"Spiritual wellness","def":"Having a set of guiding beliefs, principles or values that give meaning and purpose to your life, especially in difficult times. Organized religion is one source, but not the only one: people also find meaning through nature, art, meditation, good works or loved ones.","src":"Textbook Ch 1, pp. 5-6","ch":"W2-C7","added":"2026-10-26"},{"id":"W2-T-tb-environmental-wellness","term":"Environmental wellness","def":"Defined by the livability of your surroundings. Personal health depends on the health of the planet, from the safety of the food supply to the degree of violence in society. You improve it by protecting yourself from hazards and working to make your world cleaner and safer.","ex":"Recycling, reducing pollution and waste.","src":"Textbook Ch 1, p. 6","ch":"W2-C7","added":"2026-10-26"},{"id":"W2-T-tb-occupational-wellness","term":"Occupational wellness","def":"The level of happiness and fulfillment you gain through your work. High salaries and prestigious titles alone generally do not bring it. Aspects: enjoyable work, job satisfaction, feelings of achievement, opportunities to learn and grow, and recognition from managers and colleagues.","src":"Textbook Ch 1, p. 6","ch":"W2-C7","added":"2026-10-26"},{"id":"W2-T-tb-financial-wellness","term":"Financial wellness","def":"Being comfortable with your financial situation, not necessarily rich. Financially well people understand the limits of their income, live within their means, can manage a bank account and try to save for the future.","src":"Textbook Ch 1, p. 6","ch":"W2-C7","added":"2026-10-26"},{"id":"W2-T-tb-biological-cultural","term":"Biological vs cultural health differences","def":"Health-related differences among people can be biological (determined genetically) or cultural (patterns of behaviour learned through daily interactions with family, community and society). Many conditions combine both: a person with a genetic predisposition may not develop a disease unless lifestyle factors such as stress or a poor diet are present.","src":"Textbook Ch 1, p. 9","ch":"W2-C7","added":"2026-10-26"},{"id":"W2-T-tb-stereotyping-overgeneralizing","term":"Stereotyping and overgeneralizing","def":"The two dangers in talking about health for diverse populations. Stereotyping: talking about people as groups rather than as individuals. Overgeneralizing: ignoring the large biological and cultural diversity among peoples who are grouped together.","ex":"The label Aboriginal peoples includes First Nations, Metis and Inuit, each with its own genetic and cultural heritage.","src":"Textbook Ch 1, pp. 9-10","ch":"W2-C7","added":"2026-10-26"},{"id":"W2-T-tb-diversity-dimensions","term":"Dimensions for describing health differences","def":"Health-related differences among groups can be described in the context of gender, ethnicity, income and education, disability, geographic location and sexual orientation. Poverty and low educational attainment are far more important predictors of poor health than any ethnic factor.","src":"Textbook Ch 1, pp. 10, 12-13","ch":"W2-C7","added":"2026-10-26"},{"id":"W2-T-tb-factors-wellness","term":"Factors that influence wellness","def":"Behaviour (health habits), heredity and family history, environment, and access to health care. These vary for individuals and groups and can interact to produce either health or disease. Behaviour can often tip the balance toward good health even when heredity or environment is a negative factor.","src":"Textbook Ch 1, pp. 14-16","ch":"W2-C7","added":"2026-10-26"},{"id":"W2-T-tb-genome-gene","term":"Genome and gene","def":"Genome: the complete set of genetic material in an individual's cells (about 25,000 genes, half from each parent). Gene: the basic unit of heredity, a section of genetic material containing chemical instructions for making a particular protein.","src":"Textbook Ch 1, p. 15","ch":"W2-C7","added":"2026-10-26"},{"id":"W2-T-tb-target-behaviour","term":"Target behaviour","def":"An isolated behaviour selected as the subject of a behaviour change program. Start small with one behaviour and a simple first goal, work on it until you succeed, then make the next goal a little more significant.","ex":"Resisting the urge to snack between classes.","src":"Textbook Ch 1, pp. 18-19","ch":"W2-C8","added":"2026-10-26"},{"id":"W2-T-tb-pros-cons","term":"Pros and cons of change (cost-benefit analysis)","def":"Health behaviours have short-term and long-term benefits and costs. To change, you must believe the benefits of change outweigh the costs. Most people are moved more by short-term, personal benefits (feeling better, looking better, doing better in school, less stress) than by long-term goals.","src":"Textbook Ch 1, p. 21","ch":"W2-C8","added":"2026-10-26"},{"id":"W2-T-tb-visualization","term":"Visualization","def":"Imagining yourself successfully doing the new, healthier behaviour and enjoying its short-term and long-term benefits, and creating a new self-image. One of the best ways to boost confidence and self-efficacy.","src":"Textbook Ch 1, pp. 21-22","ch":"W2-C8","added":"2026-10-26"},{"id":"W2-T-tb-self-talk","term":"Self-talk","def":"The internal dialogue you carry on with yourself. To build self-efficacy, counter self-defeating thoughts with more positive or realistic ones.","ex":"\"I am a strong, capable person, and I can maintain my commitment to change.\"","src":"Textbook Ch 1, p. 22","ch":"W2-C8","added":"2026-10-26"},{"id":"W2-T-tb-lapse","term":"Lapse","def":"A single slip back to the old behaviour. People in maintenance may have lapses but quickly re-establish the desired behaviour.","src":"Textbook Ch 1, pp. 22-23","ch":"W2-C8","added":"2026-10-26"},{"id":"W2-T-tb-relapse","term":"Relapse vs failure","def":"Relapse is a return to old habits. It can be demoralizing but is not failure. Failure means stopping before you reach your goal and never changing the target behaviour. Plan for relapse early so you can avoid guilt and self-blame.","src":"Textbook Ch 1, pp. 23-24","ch":"W2-C8","added":"2026-10-26"},{"id":"W2-T-tb-spiral-model","term":"Spiral model of change (Fig 1.6)","def":"People seldom move through the stages of change in a straight line. They cycle back through earlier stages but are further along each time they renew their commitment. Most people make several attempts before they succeed.","src":"Textbook Ch 1, pp. 23-24","ch":"W2-C8","added":"2026-10-26"},{"id":"W2-T-tb-relapse-steps","term":"Three steps for dealing with relapse","def":"1. Forgive yourself: one setback is not the end of the world. 2. Give yourself credit for the progress you have made, and use it as motivation. 3. Move on: learn from the relapse to handle future setbacks. If relapses keep happening, return to an earlier stage and re-evaluate your goals and strategy.","src":"Textbook Ch 1, p. 24","ch":"W2-C8","added":"2026-10-26"},{"id":"W2-T-tb-plan-of-action","term":"Plan of action strategies","def":"Get what you need (resources, equipment, right away); modify your environment (control cues that trigger the behaviour); control related habits; reward yourself (planned, instant, real rewards tied to goals, preferably not food or alcohol); involve the people around you (give them a list of dos and don'ts); plan for challenges.","src":"Textbook Ch 1, pp. 25-26","ch":"W2-C8","added":"2026-10-26"},{"id":"W2-T-tb-habit-goals","term":"Habit goals vs outcome goals","def":"For some situations it makes more sense to focus on something other than the outcome goal. Early in change, the goal may be to learn about the risks or do a cost-benefit analysis. For long-term lifestyle change, such as reaching a healthy weight, focus on developing healthy habits rather than a specific weight loss.","ex":"Exercise 30 minutes a day, reduce portion sizes, cut late-night snacks.","src":"Textbook Ch 1, p. 25","ch":"W2-C8","added":"2026-10-26"},{"id":"W2-T-tb-procrastinating","term":"Procrastinating","def":"Putting off the start of your plan. Fix: break the plan into smaller steps you can do one day at a time.","ex":"\"It's Friday already; I might as well wait until Monday to start.\"","src":"Textbook Ch 1, p. 27","ch":"W2-C8","added":"2026-10-26"},{"id":"W2-T-tb-rationalizing","term":"Rationalizing","def":"Making excuses for not following your plan. When you win by deceiving yourself, it is not much of a victory.","ex":"\"I wanted to go swimming today but wouldn't have had time to wash my hair afterward.\"","src":"Textbook Ch 1, p. 27","ch":"W2-C8","added":"2026-10-26"},{"id":"W2-T-tb-blaming","term":"Blaming","def":"Blaming others for your own failure to follow through. It takes your focus off the real problem and denies responsibility for your own actions.","ex":"\"I couldn't exercise because Dave was hogging the elliptical trainer.\"","src":"Textbook Ch 1, p. 27","ch":"W2-C8","added":"2026-10-26"}],"chapters":[{"id":"W2-C1","title":"Leading causes of death and global challenges","src":"W2 Part 1, slides 2-11","blurb":"What Canadians and people worldwide die of, and the WHO's 13 urgent challenges.","learn":"In <b>Canada in 2022</b> there were 334,081 deaths. The ten leading causes made up 68.3% of them. <b>Cancer</b> ranked first (24.7%), then heart disease, COVID-19 and unintentional injuries. Most causes carry lifestyle codes: <b>D</b> diet, <b>I</b> inactive lifestyle, <b>S</b> smoking, <b>A</b> excessive alcohol, <b>O</b> obesity.<br><br>For Canadians <b>aged 15 to 24 (2023)</b>, accidents came first (29.8%), then suicide (16.8%).<br><br><b>Worldwide in 2021</b>, the top 10 causes made up 39 million of 68 million deaths (57%). Ischaemic heart disease ranked first. In <b>high-income</b> countries deaths are mostly from noncommunicable chronic diseases. In <b>low-income</b> countries they are mostly from communicable diseases, plus complications in childbirth.<br><br>In 2020 the WHO named <b>13 urgent health challenges</b>, from the climate crisis to health inequities. Environmental health grew out of efforts to control communicable diseases.","steps":[{"id":"W2-C1-S1","type":"table","src":"W2 Part 1, slide 2","added":"2026-10-26","prompt":"Read Table 1.2, then answer the questions.","caption":"Table 1.2 Ten Leading Causes of Death in Canada, 2022 (Statistics Canada, 2023). Lifestyle factors: D diet, I inactive lifestyle, S smoking, A excessive alcohol use, O obesity. (C is not defined on the slide.)","head":["Rank","Cause of death","Number of deaths","% of total deaths","Lifestyle factors"],"rows":[["","All causes","334,081","100.0",""],["","Total, ten leading causes","227,712","68.3",""],["1","Cancer","82,412","24.7","DISAOC"],["2","Heart disease","53,704","17.2","DISAOC"],["3","COVID-19","19,716","5.9","C"],["4","Unintentional injuries (accidents)","18,365","5.5","ISAC"],["5","Cerebrovascular diseases (stroke)","13,915","4.2","DISAOC"],["6","Chronic lower respiratory diseases","12,462","3.7","SOC"],["7","Diabetes mellitus","7,557","2.3","DISOC"],["8","Influenza and pneumonia","5,985","1.8","DISAC"],["9","Alzheimer's disease","5,413","1.6","C"],["10","Chronic liver disease and cirrhosis","4,530","1.4","DSAOC"]],"qs":[{"id":"W2-C1-S1-Q1","type":"mcq","src":"W2 Part 1, slide 2","ch":"W2-C1","added":"2026-10-26","q":"Which leading cause of death lists inactive lifestyle (I) but NOT diet (D) as a lifestyle factor?","opts":[["Chronic lower respiratory diseases",false,"Coded SOC: neither diet nor inactive lifestyle is listed."],["Unintentional injuries (accidents)",true,"Coded ISAC: inactive lifestyle, smoking and alcohol play a part, but diet does not."],["Diabetes mellitus",false,"Coded DISOC, so diet does play a part."],["Chronic liver disease and cirrhosis",false,"Coded DSAOC: diet is listed, and inactive lifestyle is not."]]},{"id":"W2-C1-S1-Q2","type":"mcq","src":"W2 Part 1, slide 2","ch":"W2-C1","added":"2026-10-26","q":"A public health campaign targets excessive alcohol use (A). Based on the table, which ranked cause would it NOT be expected to affect?","opts":[["Cancer",false,"Cancer is coded DISAOC, which includes A."],["Chronic liver disease and cirrhosis",false,"Coded DSAOC, which includes A."],["Influenza and pneumonia",false,"Coded DISAC, which includes A."],["Diabetes mellitus",true,"Diabetes is coded DISOC, with no A."]]}]},{"id":"W2-C1-S2","type":"table","src":"W2 Part 1, slide 3","added":"2026-10-26","prompt":"Read Table 1.3, then answer the question.","caption":"Table 1.3 Five Leading Causes of Death among Canadians Aged 15 to 24, 2023 (Statistics Canada, 2023).","head":["Rank","Cause of death","Number of deaths","% of total deaths"],"rows":[["","All causes","2,326",""],["1","Accidents (unintentional injuries)","694","29.8"],["2","Intentional self-harm (death by suicide)","391","16.8"],["3","Cancer","131","5.6"],["4","Assault (homicide)","68","2.9"],["5","Heart disease","37","1.6"]],"qs":[{"id":"W2-C1-S2-Q1","type":"mcq","src":"W2 Part 1, slides 2-3","ch":"W2-C1","added":"2026-10-26","q":"Which statement correctly compares Table 1.3 (ages 15 to 24, 2023) with Table 1.2 (all ages, 2022)?","opts":[["Accidents rank first in both tables.",false,"Accidents are first for ages 15 to 24 but fourth for all ages."],["Suicide appears in both top-ten lists.",false,"Intentional self-harm is second for ages 15 to 24 but is not in the all-ages top ten."],["Cancer ranks first for all ages but third for ages 15 to 24.",true,"Cancer is rank 1 in Table 1.2 (24.7%) and rank 3 in Table 1.3 (5.6%)."],["Heart disease ranks second in both tables.",false,"Heart disease is second for all ages but fifth (1.6%) for ages 15 to 24."]]}]},{"id":"W2-C1-S3","type":"table","src":"W2 Part 1, slides 4-7","added":"2026-10-26","prompt":"Compare the WHO top 10 causes of death in 2021 for the world, high-income countries and low-income countries.","caption":"WHO (2024), top 10 causes of death, 2021. Rank order from the slide charts. NCD = noncommunicable disease; Comm = communicable, maternal, perinatal or nutritional condition. Worldwide, the top 10 caused 39 million of 68 million deaths (57%).","head":["Rank","World","High-income countries","Low-income countries"],"rows":[["1","Ischaemic heart disease (NCD)","Ischaemic heart disease (NCD)","Lower respiratory infections (Comm)"],["2","COVID-19 (Comm)","COVID-19 (Comm)","Stroke (NCD)"],["3","Stroke (NCD)","Stroke (NCD)","Ischaemic heart disease (NCD)"],["4","Chronic obstructive pulmonary disease (NCD)","Alzheimer disease and other dementias (NCD)","Malaria (Comm)"],["5","Lower respiratory infections (Comm)","Trachea, bronchus, lung cancers (NCD)","Preterm birth complications (Comm)"],["6","Trachea, bronchus, lung cancers (NCD)","Chronic obstructive pulmonary disease (NCD)","COVID-19 (Comm)"],["7","Alzheimer disease and other dementias (NCD)","Colon and rectum cancers (NCD)","Diarrhoeal diseases (Comm)"],["8","Diabetes mellitus (NCD)","Lower respiratory infections (Comm)","Tuberculosis (Comm)"],["9","Kidney diseases (NCD)","Kidney diseases (NCD)","Birth asphyxia and birth trauma (Comm)"],["10","Tuberculosis (Comm)","Hypertensive heart disease (NCD)","HIV/AIDS (Comm)"]],"qs":[{"id":"W2-C1-S3-Q1","type":"mcq","src":"W2 Part 1, slides 5-7","ch":"W2-C1","added":"2026-10-26","q":"Which statement about 2021 is supported by the WHO data?","opts":[["Malaria, HIV/AIDS and tuberculosis are in the top 10 for low-income countries but not for high-income countries.",true,"All three appear only in the low-income list; high-income communicable causes are only COVID-19 and lower respiratory infections."],["Noncommunicable diseases are absent from the low-income top 10.",false,"Stroke (2nd) and ischaemic heart disease (3rd) are NCDs in the low-income list."],["Lower respiratory infections rank first in high-income countries.",false,"They rank 8th in high-income countries; they rank first in low-income countries."],["Dementia ranks higher in low-income countries than in high-income countries.",false,"Alzheimer disease and other dementias rank 4th in high-income countries and do not appear in the low-income top 10."]]},{"id":"W2-C1-S3-Q2","type":"mcq","src":"W2 Part 1, slide 7","ch":"W2-C1","added":"2026-10-26","q":"Besides communicable diseases, what other source of many deaths in low-income countries does the lecture name?","opts":[["Hypertensive heart disease",false,"This appears only in the high-income top 10."],["Road injuries",false,"No injury category appears in the low-income top 10."],["Complications in childbirth",true,"Slide 7 lists 'many deaths from complications in child birth' for low-income countries; preterm birth complications and birth asphyxia appear in the top 10."],["Colon and rectum cancers",false,"This appears only in the high-income top 10."]]}]},{"id":"W2-C1-S4","type":"mcq","src":"W2 Part 1, slides 8-11","ch":"W2-C1","added":"2026-10-26","case":"A WHO briefing describes a growing movement that spreads false claims about vaccines online, and falling trust in health advice.","q":"Which of the WHO's 13 urgent health challenges (2020) does this fit best?","opts":[["Anti-microbial resistance",false,"This challenge concerns drugs losing effect, with tuberculosis and STIs as examples."],["Earning public trust",true,"Challenge 9 is earning public trust, with misinformation and the anti-vaccine movement as its examples."],["Ethical and social implications of new technologies",false,"This challenge covers genome editing, synthetic biology, digital health and artificial intelligence."],["Stopping infectious diseases",false,"Related, but the problem described is trust and misinformation, which is its own challenge."]]}],"summary":"Cancer and heart disease lead deaths in Canada; accidents and suicide lead for ages 15 to 24. High-income countries die mostly of chronic noncommunicable disease, low-income countries mostly of communicable disease."},{"id":"W2-C2","title":"Health differences across populations","src":"W2 Part 1, slides 12-26","blurb":"Inequality, disparity and inequity; sex and gender; the social gradient; racism; Indigenous health.","learn":"Some people are genetically predisposed to health problems, but blaming lifestyle alone is too simple. Many conditions come from interactions between biology, culture and higher-level determinants that create structural disadvantage. Do not stereotype or overgeneralize.<ul><li><b>Health inequality</b>: a systematic difference in health between groups, due to biology and/or lifestyle, socio-economic status or access to care.</li><li><b>Health disparity</b>: inequalities due mainly to social disadvantages.</li><li><b>Health inequity</b>: a disparity deemed unfair, so there is a moral imperative to correct it.</li></ul><b>Sex</b> is biological; <b>gender</b> is socially constructed; <b>gender identity</b> is a person's internal experience of gender. Longevity rises steadily across income levels: the <b>social gradient in health</b>. Jones (2000) describes three levels of racism: <b>institutionalized</b>, <b>personally-mediated</b> and <b>internalized</b>. Indigenous Peoples face 1.5x the heart disease, 2 to 5x the type 2 diabetes and 40x the tuberculosis of non-Indigenous people, plus higher food insecurity.","steps":[{"id":"W2-C2-S1","type":"match","src":"W2 Part 1, slides 15, 17, 19","added":"2026-10-26","prompt":"Match each term to its definition from the slides.","pairs":[["Health inequality","Systematic difference in health between groups due to biology and/or lifestyle, SES or access to care"],["Health disparity","Systematic inequalities due mainly to social disadvantages"],["Health inequity","A disparity deemed unfair, with a moral imperative to correct it"],["Sex","Biological and physiological characteristics such as chromosomes, hormones and reproductive organs"],["Gender","Socially constructed norms, behaviours and roles that vary between societies and over time"],["Gender identity","A person's deeply felt, internal and individual experience of gender"],["Social gradient in health","Steady rise in longevity across income levels"]]},{"id":"W2-C2-S2","type":"sort","src":"W2 Part 1, slide 21","added":"2026-10-26","prompt":"Sort each example into the level of racism it shows (Jones, 2000).","bins":["Institutionalized (structural)","Personally-mediated","Internalized"],"items":[["Racialized neighbourhoods receive fewer clinics and worse housing",0,"Differences in material conditions built into systems."],["A racialized community has almost no representation on the board that sets local health budgets",0,"Differences in access to power are institutionalized racism."],["A landlord refuses to rent to an applicant because of their ethnicity",1,"Discrimination by one person toward another."],["A nurse assumes a patient is exaggerating pain because of the patient's race",1,"Prejudice acted out between individuals."],["A teenager comes to believe people of her race are not smart enough for university",2,"Acceptance of negative messages about one's own abilities."],["A man feels his community is worth less than others because of messages he grew up with",2,"Acceptance of negative messages about one's intrinsic worth."]]},{"id":"W2-C2-S3","type":"table","src":"W2 Part 1, slide 24","added":"2026-10-26","prompt":"Read Fig 1.9, then answer the questions.","caption":"Fig 1.9 Prevalence of Diabetes Among Adults in Canada Aged 18+, % (Public Health Agency of Canada, Framework for Diabetes in Canada, 2022).","head":["Grouping","Category","Prevalence (%)"],"rows":[["Household income","Lowest","10.5"],["Household income","2nd","8.1"],["Household income","3rd","7.2"],["Household income","4th","6.5"],["Household income","Highest","5.2"],["Education","Less than high school","11.0"],["Education","High school graduate","7.8"],["Education","Community college/technical","7.6"],["Education","University graduate","5.7"],["Indigenous identity","First Nations living off-reserve","12.2"],["Indigenous identity","Inuit","9.0"],["Indigenous identity","Metis","8.9"],["Indigenous identity","Non-Indigenous","7.4"],["Cultural/racial background","South Asian","15.3"],["Cultural/racial background","Black","12.9"],["Cultural/racial background","Arab/West Asian","12.4"],["Cultural/racial background","East/Southeast Asian","8.4"],["Cultural/racial background","White","6.8"]],"qs":[{"id":"W2-C2-S3-Q1","type":"mcq","src":"W2 Part 1, slides 19, 24","ch":"W2-C2","added":"2026-10-26","q":"Diabetes prevalence falls step by step from the lowest income group (10.5%) to the highest (5.2%). What does this pattern show?","opts":[["Internalized racism",false,"The pattern is by income, not about accepting negative messages about one's own race."],["Primordial prevention",false,"That is a level of prevention, not a pattern in data."],["A health inequality caused only by biology",false,"Income differences reflect socio-economic status, not biology alone."],["A social gradient in health",true,"Health improves steadily with each step up in income, as on the social gradient slide."]]},{"id":"W2-C2-S3-Q2","type":"mcq","src":"W2 Part 1, slide 24","ch":"W2-C2","added":"2026-10-26","q":"Which group has the highest diabetes prevalence in Fig 1.9?","opts":[["South Asian adults (15.3%)",true,"15.3% is the highest value in the figure."],["Black adults (12.9%)",false,"Second highest in the cultural/racial group, below South Asian."],["First Nations adults living off-reserve (12.2%)",false,"Highest in the Indigenous identity group, but below South Asian and Black."],["Adults with less than high school (11.0%)",false,"Highest in the education group, but lower than South Asian."]]}]},{"id":"W2-C2-S4","type":"mcq","src":"W2 Part 1, slide 15","ch":"W2-C2","added":"2026-10-26","case":"Indigenous Canadians have a 40x higher rate of tuberculosis than non-Indigenous Canadians. The gap is linked to social disadvantage and the effects of colonization, and a health agency states it must work to close it.","q":"Which term best describes this difference?","opts":[["Internalized racism",false,"That is acceptance of negative messages about one's own worth, not a population difference in disease."],["Health inequity",true,"A disparity judged unfair, with a moral imperative to correct it. The slide gives Indigenous health disparities as the example."],["Health inequality due to biological differences",false,"The case links the gap to social disadvantage and colonization, and calls for correction."],["Gender difference",false,"The case is about Indigenous identity, not socially constructed gender roles."]]}],"summary":"An inequality is any systematic difference; a disparity comes mainly from social disadvantage; an inequity is a disparity judged unfair. Income, racism and colonization all shape who gets sick."},{"id":"W2-C3","title":"PHAC, public vs population health, and levels of prevention","src":"W2 Part 2, slides 2-7","blurb":"Who leads public health in Canada, and the four levels of prevention.","learn":"The <b>Public Health Agency of Canada (PHAC)</b> promotes health, prevents and controls chronic and infectious diseases and injuries, prepares for emergencies, shares expertise worldwide, and strengthens intergovernmental collaboration.<br><br><b>Public and population health</b> both study patterns of health in groups, monitor trends and propose population-level interventions. The <b>population</b> model is broader: it looks at underlying social determinants such as poverty or lack of access to care, to reduce health inequities.<br><br><b>Prevention</b> includes stopping disease from starting and limiting its progress and consequences.<ul><li><b>Primordial</b>: modify social determinants; whole population; government legislation, fiscal measures, social programs.</li><li><b>Primary</b>: limit exposures through risk reduction; at-risk groups.</li><li><b>Secondary</b>: detect and treat early, as in screening; patients with disease.</li><li><b>Tertiary</b>: prevent relapse after clinical treatment; recovering individuals; rehabilitation.</li></ul>","steps":[{"id":"W2-C3-S1","type":"label","fig":"prevention","src":"W2 Part 2, slide 7","added":"2026-10-26","prompt":"Place each level of prevention at the right point along the course of disease, from underlying health determinants to the post-clinical phase."},{"id":"W2-C3-S2","type":"sort","src":"W2 Part 2, slides 6-7","added":"2026-10-26","prompt":"Sort each action into its level of prevention.","bins":["Primordial","Primary","Secondary","Tertiary"],"items":[["The federal government passes legislation that raises income supports for low-income families",0,"Government legislation that modifies a broad social determinant for the whole population."],["A community agency runs a social program that improves housing across a city",0,"Community social programs that address underlying determinants are primordial."],["A family physician counsels a healthy patient who smokes to quit",1,"Risk reduction before any disease is present."],["Public health offers a vaccine to students before flu season",1,"Prevents the onset of a specific disease by limiting exposure risk."],["A public health program screens adults for early signs of cancer",2,"Screening detects pathological changes early, in the preclinical phase."],["A blood test finds early kidney changes in a patient with no symptoms, and treatment starts",2,"Detecting and treating a disease process early."],["A heart attack survivor attends a rehabilitation program",3,"After clinical treatment, rehabilitation reduces impact and prevents relapse."],["A clinician provides follow-up care to a cancer survivor to prevent recurrence",3,"Follow-up care for recovering individuals is tertiary."]]},{"id":"W2-C3-S3","type":"mcq","src":"W2 Part 2, slide 5","ch":"W2-C3","added":"2026-10-26","case":"A health unit notices that diabetes rates are highest in neighbourhoods with high poverty and few clinics. It decides its main goal will be to reduce the poverty and access barriers that drive the gap.","q":"Which approach is this most typical of?","opts":[["Personal behaviour change",false,"The focus is on social conditions in neighbourhoods, not on individual habits."],["Secondary prevention",false,"Secondary prevention is early detection and treatment, such as screening."],["A population health approach",true,"The population model takes a broader view of underlying social determinants such as poverty and access to care, to reduce inequities."],["Tertiary prevention",false,"Tertiary prevention targets recovering individuals after clinical treatment."]]},{"id":"W2-C3-S4","type":"mcq","src":"W2 Part 2, slide 7","ch":"W2-C3","added":"2026-10-26","case":"A program targets people who already have high blood pressure but no symptoms yet, by offering checks in pharmacies and referring anyone with a high reading for early treatment.","q":"Which level of prevention, and which target population, does this match on the prevention figure?","opts":[["Tertiary prevention; recovering individuals",false,"Tertiary prevention follows clinical treatment to avoid relapse."],["Secondary prevention; patients with disease",true,"Detect and treat the pathological process early, in the preclinical phase, through screening."],["Primary prevention; at-risk groups",false,"Primary prevention limits exposures before disease starts; here the disease process is already present."],["Primordial prevention; whole population",false,"Primordial prevention modifies social determinants through legislation and social programs."]]}],"summary":"PHAC leads public health federally. Primordial addresses social determinants, primary reduces risk, secondary detects early, tertiary limits relapse and impact."},{"id":"W2-C4","title":"Protection, surveillance, promotion, and national strategy","src":"W2 Part 2, slides 8-15","blurb":"How public health removes threats, watches trends, enhances health, and sets national targets.","learn":"<b>Health protection</b> reduces threats to population health. It uses primordial and primary prevention: safe food and water, addressing environmental threats, controlling infectious diseases. It is one of PHAC's roles.<br><br><b>Surveillance</b> is the ongoing, systematic collection and analysis of population health information to guide interventions. It can be long-term passive monitoring of trends or active short-term checking for outbreaks.<br><br><b>Health promotion</b> aims to enhance health, not just remove threats: education, healthy public policy, disease prevention, interventions that support behaviour change, and building skills and resiliency. The <b>Ottawa Charter</b> names five action areas: healthy public policy, supportive environments, community action, personal skills, reorienting health services.<br><br>The <b>Integrated Pan-Canadian Healthy Living Strategy</b> (2002) targeted physical inactivity, unhealthy diets and tobacco use, and aimed to reduce health disparities. In 2010 it added prevention and health promotion priorities and childhood obesity.","steps":[{"id":"W2-C4-S1","type":"compare","src":"W2 Part 2, slides 8, 11","added":"2026-10-26","prompt":"Decide whether each activity is mainly health protection or health promotion.","a":{"name":"Health protection","points":["Reduces or removes threats to population health","Uses primordial and primary prevention","Food and water safety, environmental threats, infectious disease control"]},"b":{"name":"Health promotion","points":["Aims to enhance health","Education and healthy public policy","Builds skills and resiliency of individuals and communities"]},"scenarios":[["Inspectors test a town's drinking water after a flood",0,"Removing a threat through water safety."],["A university runs workshops teaching students to cook healthy meals on a budget",1,"Education that builds personal skills enhances health."],["Public health isolates cases and traces contacts during a measles outbreak",0,"Controlling an infectious disease is protection."],["A province funds community programs that strengthen resiliency in youth groups",1,"Strengthening skills and resiliency of community groups is promotion."],["Restaurants are inspected for safe food handling",0,"Food safety removes a threat."]]},{"id":"W2-C4-S2","type":"match","src":"W2 Part 2, slide 10","added":"2026-10-26","prompt":"Match each Ottawa Charter action area to the example that fits it best.","pairs":[["Build healthy public policy","A city passes a bylaw banning smoking on restaurant patios"],["Create supportive environments","A campus adds safe bike lanes and water refill stations"],["Strengthen community action","Neighbours organize together to start a community garden"],["Develop personal skills","A clinic teaches teens how to read nutrition labels"],["Reorient health services","A hospital shifts funding toward prevention and health promotion, not only treatment"]]},{"id":"W2-C4-S3","type":"table","src":"W2 Part 2, slide 13","added":"2026-10-26","prompt":"Read Table 1.4, then answer the questions.","caption":"Table 1.4 Eating Habits and Physical Activity and Smoking Levels among People in Canada, by province, % (Statistics Canada, 2023). Territories (Yukon, Northwest Territories, Nunavut) have no data shown.","head":["Province","Smoking 2019, daily or occasional","Smoking 2019, daily","Vaping 2017, ever used","Vaping 2017, past 30 days","Healthy eating habits","Physically active"],"rows":[["British Columbia","8.9","6.3","18.7","6.4","21.2","62.4"],["Alberta","11.4","9.1","20.2","6.8","19.4","58.0"],["Saskatchewan","14.9","10.8","22.3","6.8","21.9","52.2"],["Manitoba","11.7","10.4","19.8","6.2","19.7","52.8"],["Ontario","10.8","8.4","17.2","5.2","19.9","51.5"],["Quebec","13.2","10.3","19.2","5.5","28.6","51.7"],["New Brunswick","13.2","11.8","20.2","5.0","15.9","50.6"],["Nova Scotia","15.1","12.7","20.2","6.2","17.7","55.4"],["Prince Edward Island","15.5","13.1","21.5","7.2","16.6","51.3"],["Newfoundland and Labrador","16.3","13.0","20.2","6.0","11.9","50.3"]],"qs":[{"id":"W2-C4-S3-Q1","type":"mcq","src":"W2 Part 2, slide 13","ch":"W2-C4","added":"2026-10-26","q":"Which province has the highest percentage with healthy eating habits AND which has the lowest?","opts":[["Highest British Columbia (21.2); lowest New Brunswick (15.9)",false,"Both values exist, but Quebec is higher than 21.2 and NL is lower than 15.9."],["Highest Saskatchewan (21.9); lowest Prince Edward Island (16.6)",false,"Quebec (28.6) is higher and NL (11.9) is lower."],["Highest Quebec (28.6); lowest Nova Scotia (17.7)",false,"Quebec is right, but NL at 11.9 is lower than Nova Scotia."],["Highest Quebec (28.6); lowest Newfoundland and Labrador (11.9)",true,"28.6 is the top value in the column and 11.9 is the bottom."]]},{"id":"W2-C4-S3-Q2","type":"mcq","src":"W2 Part 2, slide 13","ch":"W2-C4","added":"2026-10-26","q":"British Columbia has the lowest smoking rate (8.9% daily or occasional). Which other measure does BC lead?","opts":[["Lowest vaping, ever used",false,"Ontario is lowest (17.2); BC is 18.7."],["Lowest vaping, past 30 days",false,"New Brunswick has the lowest past-30-day vaping (5.0); BC is 6.4."],["Highest physically active (62.4%)",true,"62.4 is the highest value in the physically active column."],["Highest healthy eating habits",false,"Quebec leads at 28.6; BC is 21.2."]]}]},{"id":"W2-C4-S4","type":"mcq","src":"W2 Part 2, slide 9","ch":"W2-C4","added":"2026-10-26","case":"After reports of a new respiratory illness, a public health team spends three weeks actively contacting hospitals each day to count new cases and look for an outbreak.","q":"What is this?","opts":[["Active, short-term surveillance",true,"Checking actively over a short period for emergent diseases or outbreaks is one form of surveillance."],["Long-term, passive surveillance",false,"Passive surveillance is long-term monitoring of general health trends, not daily active checking."],["Health promotion",false,"Promotion enhances health through education, policy and skill building; this is data collection."],["Tertiary prevention",false,"Tertiary prevention helps recovering patients avoid relapse."]]}],"summary":"Protection removes threats, promotion enhances health, and surveillance collects the data that guide both. The Ottawa Charter and the Pan-Canadian strategy frame health promotion in Canada."},{"id":"W2-C5","title":"Personal wellness: motivation and models of behaviour","src":"W2 Part 3, slides 2-13","blurb":"Self-efficacy, locus of control, the stages of change, the Health Belief Model and the Theory of Planned Behaviour.","learn":"Wellness depends on health habits, heredity, environment and access to care, but behaviour can make a difference. <b>Behaviour change</b> means building healthy behaviours and overcoming unhealthy ones. Start by examining your habits and choosing one <b>target behaviour</b>.<br><br>To build motivation, weigh the pros and cons and boost <b>self-efficacy</b>: an internal <b>locus of control</b>, visualization and self-talk, role models, and overcoming barriers.<br><br>The <b>transtheoretical model</b> says you move through stages: precontemplation (no intention), contemplation (within 6 months), preparation (within a month, or small steps), action, maintenance (6 months or more), termination. Relapse is common.<br><br>The <b>Health Belief Model</b>: people act when they see a threat as serious, see themselves as susceptible, and believe benefits outweigh barriers; cues to action trigger them. The <b>Theory of Planned Behaviour</b> extends it with subjective norms and self-efficacy (perceived behavioural control).","steps":[{"id":"W2-C5-S1","type":"label","fig":"ttm","src":"W2 Part 3, slides 9-10","added":"2026-10-26","prompt":"Place the six stages of change in order, from no intention to change through to the new behaviour being adopted."},{"id":"W2-C5-S2","type":"sort","src":"W2 Part 3, slide 9","added":"2026-10-26","prompt":"Sort each student into their stage of change.","bins":["Precontemplation","Contemplation","Preparation","Action","Maintenance"],"items":[["Ali vapes daily and says he sees no reason to stop",0,"No intention to change and no reason seen."],["Bea knows her sleep schedule is hurting her grades and plans to fix it sometime this term, within 6 months",1,"Intends to change within 6 months but has not started."],["Chen bought a reusable water bottle and will cut out pop starting next week",2,"Plans to act within a month and is taking small steps."],["Dana has cooked dinner instead of ordering takeout for the past 6 weeks",3,"Already making changes, but for less than 6 months."],["Eli has walked to campus every day for the past 10 months",4,"Has kept the new behaviour for at least 6 months."],["Farah already goes to bed 15 minutes earlier and plans a full schedule change in two weeks",2,"Small steps now and action planned within a month."],["Gus started limiting energy drinks 2 months ago and is sticking to it",3,"Making the change, but not yet for 6 months."]]},{"id":"W2-C5-S3","type":"compare","src":"W2 Part 3, slides 7, 11-13","added":"2026-10-26","prompt":"Which model's component is each statement describing?","a":{"name":"Health Belief Model","points":["Perceived susceptibility and severity form perceived threat","Perceived benefits minus barriers","Cues to action trigger behaviour"]},"b":{"name":"Theory of Planned Behaviour","points":["Assumes rational planning","Attitude, subjective norms and perceived behavioural control shape intention","Extension of the HBM adding subjective norms and self-efficacy"]},"scenarios":[["A student gets a flu shot after a reminder email from campus health services",0,"A reminder from a health professional is a cue to action in the HBM."],["A student plans to stop vaping because her friends now think vaping is uncool",1,"Felt social pressure from others is a subjective norm."],["A man books a skin check because his brother was just diagnosed with skin cancer and he feels at risk",0,"Illness of a family member is a cue to action and raises perceived susceptibility."],["A student intends to exercise and believes she can fit it into her schedule, which makes her follow through",1,"Perceived behavioural control (self-efficacy) feeds intention and behaviour."]]},{"id":"W2-C5-S4","type":"mcq","src":"W2 Part 3, slide 6","ch":"W2-C5","added":"2026-10-26","case":"Jordan wants to sleep more but says, 'There's no point trying. My roommate is loud and my profs assign too much. It's out of my hands.'","q":"What does this show, and what would the lecture suggest?","opts":[["The maintenance stage; he should focus on preventing relapse",false,"Maintenance means the new behaviour has lasted 6 months or more."],["High self-efficacy; no motivation strategies are needed",false,"Saying change is out of his hands shows low belief in his own ability."],["An external locus of control; boost self-efficacy, for example by identifying and overcoming barriers",true,"Jordan places responsibility outside himself. Boosting self-efficacy includes moving toward an internal locus of control and tackling barriers."],["An internal locus of control; he should move straight to a personal contract",false,"An internal locus would mean he sees himself as responsible."]]}],"summary":"Know your stage of change and build self-efficacy. The HBM explains action through perceived threat, benefits and cues; the TPB adds social norms and perceived control."},{"id":"W2-C6","title":"Creating a personalized plan","src":"W2 Part 3, slides 14-22","blurb":"The five steps of a behaviour change plan, SMART goals, and staying with it.","learn":"A personalized plan has <b>five steps</b>:<ul><li><b>Monitor</b> your behaviour and gather data. Record each occurrence in a health journal: what, when and where, what you were doing, how you felt.</li><li><b>Analyze</b> the data and identify patterns: triggers, links between feelings and cues such as time of day, place, or other people.</li><li><b>Set SMART goals</b>: Specific, Measurable, Attainable, Realistic, Time frame specific.</li><li><b>Devise a plan of action</b>: get what you need, modify your environment, control related habits, reward yourself, involve others, plan for challenges.</li><li><b>Make a personal contract</b>: your goal, start date, how you will measure progress, strategies, and target date.</li></ul>Putting the plan into action takes commitment; keep your environment change-friendly and congratulate yourself. Barriers to staying with it: social influences, motivation and commitment, choice of techniques and effort, stress, and procrastinating, rationalizing and blaming.","steps":[{"id":"W2-C6-S1","type":"order","src":"W2 Part 3, slide 14","added":"2026-10-26","prompt":"Put the steps for creating a personalized behaviour change plan in order.","items":["Monitor your behaviour and gather data","Analyze the data and identify patterns","Be SMART about setting goals","Devise a plan of action","Make a personal contract"],"why":"You need baseline data before you can find patterns, patterns before you can set fitting goals, goals before a plan, and the contract records the whole plan as a commitment."},{"id":"W2-C6-S2","type":"label","fig":"smart","src":"W2 Part 3, slide 18","added":"2026-10-26","prompt":"Label each letter of a SMART goal."},{"id":"W2-C6-S3","type":"sort","src":"W2 Part 3, slides 15-20","added":"2026-10-26","prompt":"Sort each task into the step of the personalized plan it belongs to.","bins":["1. Monitor and gather data","2. Analyze patterns","3. SMART goals","4. Plan of action","5. Personal contract"],"items":[["Write down each time you snack, where you were and how you felt",0,"Recording each occurrence is monitoring."],["Notice that you snack most when studying alone late at night",1,"Finding a trigger in the journal is analysis."],["Change 'eat better' to 'eat one serving of fruit at lunch, 5 days a week, for 4 weeks'",2,"Making the goal specific, measurable and time-bound."],["Stop keeping chips in your residence room",3,"Modifying your environment is part of the plan of action."],["Plan a small reward for each week you meet your goal",3,"Reward yourself is a plan-of-action strategy."],["Sign a statement with your start date and target date, witnessed by a friend",4,"That is the personal contract."]]},{"id":"W2-C6-S4","type":"mcq","src":"W2 Part 3, slide 18","ch":"W2-C6","added":"2026-10-26","case":"Sam writes the goal: 'I will run 4 to 5 km, 4 days a week.'","q":"Which SMART element is clearly missing?","opts":[["Attainable",false,"Nothing in the goal shows it is beyond Sam's limits; the clear gap is the time frame."],["Time frame specific",true,"The goal does not say how long it will take or by when."],["Specific",false,"Running 4 to 5 km is a specific activity."],["Measurable",false,"Distance and days per week are numbers."]]}],"summary":"Monitor, analyze, set SMART goals, plan, and sign a contract. Then expect barriers and plan for them."},{"id":"W2-C7","title":"Reading: Wellness, its dimensions and what shapes it","src":"Textbook Ch 1, pp. 3-16","added":"2026-10-26","blurb":"Textbook Ch 1, first half: health vs wellness, the dimensions, diverse populations and the factors that influence wellness.","learn":"The textbook separates two ideas. <b>Health</b> is the overall condition of body or mind and the presence or absence of illness or injury. Parts of it are shaped by things you cannot control: genes, age, the health care system. <b>Wellness</b> is optimal health and vitality, and it is largely determined by your decisions.<br><br>Wellness is dynamic: it moves along a <b>continuum</b> from symptoms to a high level of wellness. The textbook describes physical, emotional, intellectual, interpersonal, spiritual and environmental wellness, plus occupational and financial wellness in a box. (The slides list nine dimensions; use the slide list on the exam.)<br><br>Health differences can be <b>biological</b> or <b>cultural</b>. Avoid two dangers: <b>stereotyping</b> and <b>overgeneralizing</b>. Poverty and low education predict poor health more than any ethnic factor.<br><br>Four factors influence wellness: <b>health habits, heredity, environment and access to health care</b>. Behaviour can often tip the balance even when heredity is a negative factor.","summary":"Health can be shaped by things you cannot control; wellness is mostly your choices. Behaviour can tip the balance even against family history.","steps":[{"id":"W2-C7-S1","type":"sort","src":"Textbook Ch 1, p. 5 (Table 1.2)","prompt":"Table 1.2: sort each quality or behaviour into its dimension of wellness.","bins":["Physical","Emotional","Intellectual","Interpersonal","Spiritual","Environmental"],"items":[["Getting regular checkups",0,"Table 1.2 lists checkups under physical wellness, along with eating well and exercising."],["Avoiding injuries",0,"Physical wellness includes making choices that help you avoid illness and injury."],["Self-acceptance",1,"Emotional wellness qualities include self-esteem, self-acceptance and self-confidence."],["Capacity to question and think critically",2,"An active, questioning mind is intellectual wellness."],["Lifelong learning",2,"People with intellectual wellness never stop learning."],["Ability to cultivate a support system of friends and family",3,"Interpersonal wellness is the ability to build satisfying, supportive relationships."],["Sense of meaning and purpose",4,"Spiritual wellness means guiding beliefs or values that give life meaning and purpose."],["Sense of belonging to something greater than yourself",4,"Table 1.2 lists this under spiritual wellness."],["Recycling whenever possible",5,"Environmental wellness includes recycling and reducing pollution and waste."]]},{"id":"W2-C7-S2","type":"compare","src":"Textbook Ch 1, p. 4","prompt":"Health or wellness? Decide which idea each detail about a 60-year-old man best illustrates.","a":{"name":"Health","points":["Overall condition of body or mind; presence or absence of illness or injury","Can be shaped by factors beyond your control: genes, age, health care system, early childhood care"]},"b":{"name":"Wellness","points":["Optimal health and vitality; living life to its fullest","Largely determined by the decisions you make about how you live"]},"scenarios":[["He has a strong family history of prostate cancer.",0,"Family history is beyond his control, so it shapes his health, not his wellness choices."],["His rural community has limited access to cancer screening.",0,"The health care system around him is a factor beyond his control."],["He starts eating sensibly, exercising and booking screening tests when available.",1,"These are decisions about how he lives, which is what wellness is built from."],["After a diagnosis, he keeps up his friendships and challenges himself intellectually.",1,"The textbook says he can still rise above the disease to live a rich, meaningful life: a wellness choice."]]},{"id":"W2-C7-S3","type":"mcq","src":"Textbook Ch 1, p. 16","case":"Hana's mother and aunt both had breast cancer. Hana says, \"It runs in my family, so it doesn't matter what I do.\"","q":"What does the textbook say about her situation?","opts":[["Behaviour can tip the balance: controlling her weight, eating well, exercising and having regular mammograms make her less likely to develop and die from the disease.",true,"The textbook uses this exact example under 'Behaviour can make a difference'."],["Her genes determine the outcome, so only screening is worth her effort.",false,"The textbook says breast cancer is also linked to controllable factors such as being overweight, poor nutrition and inactivity."],["Family history is a modifiable risk factor, so she can change it.",false,"Family history is nonmodifiable. What she can change is her behaviour."],["She is right, because genetic alterations cause common diseases on their own.",false,"In common, complex disorders, altered genes only increase risk; the disease comes from many genes interacting with other factors."]]},{"id":"W2-C7-S4","type":"mcq","src":"Textbook Ch 1, pp. 9-10","case":"A health report describes \"Aboriginal peoples\" as one group with one set of health risks, without separating First Nations, Metis and Inuit.","q":"Which danger in talking about health for diverse populations does this show?","opts":[["Overgeneralizing",true,"Overgeneralizing ignores the biological and cultural diversity among peoples grouped together. The textbook uses this same label as its example."],["Rationalizing",false,"Rationalizing is making excuses in a behaviour change plan."],["Internalized racism",false,"That is the acceptance of negative messages by members of stigmatized groups (Jones, W2 slides)."],["External locus of control",false,"Locus of control is about who a person sees as responsible for events in their life."]]}]},{"id":"W2-C8","title":"Reading: Lifestyle management and behaviour change","src":"Textbook Ch 1, pp. 16-29","added":"2026-10-26","blurb":"Textbook Ch 1, second half: getting serious, motivation, stages of change, relapse, the personalized plan and staying with it.","learn":"<b>Getting serious</b>: examine your habits, choose one <b>target behaviour</b>, learn its risks, and find help if it is too serious for self-management. Knowledge alone is usually not enough; you need motivation.<br><br><b>Motivation</b>: weigh pros and cons (short-term, personal benefits move most people), boost <b>self-efficacy</b> (internal locus of control, <b>visualization</b>, <b>self-talk</b>, role models, a buddy), and plan around barriers.<br><br><b>Readiness</b>: the stages of change are best seen as a <b>spiral</b>. A <b>lapse</b> is one slip; a <b>relapse</b> is a return to old habits; <b>failure</b> is quitting for good. After a relapse: forgive yourself, give yourself credit, move on.<br><br><b>The plan</b>: monitor in a journal, analyze patterns, set SMART goals with smaller intermediate goals, devise a plan of action, sign a contract with a witness.<br><br><b>Staying with it</b>: watch for social influences, low commitment, the wrong technique, stress, and the games of procrastinating, rationalizing and blaming.","summary":"Pick one behaviour, build motivation, know your stage, plan for relapse, write a SMART plan and contract, and watch for the games you play with yourself.","steps":[{"id":"W2-C8-S1","type":"match","src":"Textbook Ch 1, pp. 22-23","prompt":"Match each stage of change to the textbook detail that describes it.","pairs":[["Precontemplation","May deny the risks, blame others, or think the situation is hopeless after past failures"],["Contemplation","Knows there is a problem and weighs costs, but does not know how to proceed"],["Preparation","Doing the new behaviour now and then, not yet regularly; may be worried about failing"],["Action","Outwardly changes behaviour and environment; needs the greatest commitment of time and energy"],["Maintenance","Lapses may happen but the behaviour is quickly re-established; can last months or years"],["Termination","No longer tempted to lapse; a new self-image and total self-efficacy"]]},{"id":"W2-C8-S2","type":"sort","src":"Textbook Ch 1, p. 23","prompt":"'Tips for Moving Forward in the Cycle of Behaviour Change': which stage is each tip listed under?","bins":["Precontemplation","Contemplation","Preparation","Action","Maintenance"],"items":[["Raise your awareness: research your target behaviour and its effects",0,"People in precontemplation may be unaware of the risks, so awareness comes first."],["Be self-aware: look at how you resist change, such as denial or rationalization",0,"Denial is typical of precontemplation."],["Keep a journal of your target behaviour and what triggers it",1,"A record helps a contemplator plan a change program."],["Do a cost-benefit analysis of keeping vs changing the behaviour",1,"Contemplators are weighing benefits against costs."],["Create a plan with a start date, goals and rewards",2,"Preparation is when you plan to act within a month."],["Take short steps: practise the new behaviour for even a single day",2,"Small early successes build confidence in preparation."],["Change your environment, for example get rid of snack foods",3,"In action, people outwardly modify their behaviour and environment."],["Find alternatives to your target behaviour",3,"Listed under action, alongside monitoring progress and rewarding yourself."],["Be a role model: help someone else make the same change",4,"Once you have changed and kept it up, you can help others."]]},{"id":"W2-C8-S3","type":"mcq","src":"Textbook Ch 1, p. 27","case":"Devon's contract says he starts running on Wednesday. On Wednesday he thinks, \"It's already midweek; I might as well start fresh on Monday.\"","q":"Which game is Devon playing, and what does the textbook suggest?","opts":[["Procrastinating; break the plan into smaller steps he can do one day at a time.",true,"The textbook's own example is 'It's Friday already; I might as well wait until Monday'."],["Rationalizing; sign a new contract with a later start date.",false,"Rationalizing is making excuses like the hair-washing example. Moving the date feeds the delay."],["Blaming; tell his helper to stop pressuring him.",false,"He is not blaming anyone else."],["Relapse; forgive himself and give himself credit.",false,"He has not started yet, so there is nothing to relapse from."]]},{"id":"W2-C8-S4","type":"mcq","src":"Textbook Ch 1, p. 25","case":"Luis is sedentary. His long-term goal is to run 5 km in 30 minutes within six months.","q":"Which approach follows the textbook?","opts":[["Set smaller intermediate goals, such as walking under 2 km for 10 to 15 minutes, 3 days a week, in week 1, and adjust them as he goes.",true,"The textbook builds this exact goal from walking up to running, and says to make goals harder or easier as needed to stay motivated."],["Run 5 km every day from week 1 so he reaches the goal sooner.",false,"Too challenging goals make steady progress hard and make giving up more likely."],["Keep the short-term goals fixed even if he progresses faster than expected.",false,"The textbook says it may be reasonable to make goals more challenging if you progress faster."],["Skip the time frame so he does not feel pressure.",false,"Time-frame specific is one of the SMART criteria."]]}]}],"questions":[{"id":"W2-Q01","type":"mcq","ch":"W2-C1","src":"W2 Part 1, slide 2","added":"2026-10-26","q":"According to Table 1.2, what was the leading cause of death in Canada in 2022?","opts":[["Heart disease",false,"Heart disease ranked second."],["COVID-19",false,"COVID-19 ranked third (5.9%)."],["Unintentional injuries",false,"Unintentional injuries ranked fourth (5.5%)."],["Cancer",true,"Cancer ranked first with 82,412 deaths (24.7%)."]]},{"id":"W2-Q02","type":"mcq","ch":"W2-C1","src":"W2 Part 1, slide 3","added":"2026-10-26","case":"A campus health office wants to focus on the single largest cause of death among students aged 18 to 24.","q":"Based on Canadian data for ages 15 to 24 (2023), what should it focus on?","opts":[["Accidents (unintentional injuries)",true,"Ranked first with 694 of 2,326 deaths (29.8%)."],["Intentional self-harm (suicide)",false,"Ranked second (16.8%)."],["Cancer",false,"Ranked third (5.6%)."],["Assault (homicide)",false,"Ranked fourth (2.9%)."]]},{"id":"W2-Q03","type":"mcq","ch":"W2-C1","src":"W2 Part 1, slide 2","added":"2026-10-26","q":"In Table 1.2, which cause of death lists smoking (S) and obesity (O) but NOT diet (D) as lifestyle factors?","opts":[["Unintentional injuries",false,"Coded ISAC: smoking but no obesity."],["Chronic lower respiratory diseases",true,"Coded SOC: smoking and obesity, no diet."],["Diabetes mellitus",false,"Coded DISOC, which includes diet."],["Cerebrovascular diseases (stroke)",false,"Coded DISAOC, which includes diet."]]},{"id":"W2-Q04","type":"mcq","ch":"W2-C1","src":"W2 Part 1, slide 4","added":"2026-10-26","q":"In 2021, what share of the world's 68 million deaths did the top 10 causes account for?","opts":[["39%",false,"39 is the number of deaths in millions, not the percentage."],["24.7%",false,"24.7% is cancer's share of deaths in Canada in 2022."],["57% (39 million deaths)",true,"Slide 4: 39 million deaths, or 57% of 68 million."],["68.3%",false,"68.3% is the share of Canada's 2022 deaths from its ten leading causes."]]},{"id":"W2-Q05","type":"mcq","ch":"W2-C1","src":"W2 Part 1, slides 5-7","added":"2026-10-26","case":"Country X's top causes of death in 2021 include lower respiratory infections, malaria, diarrhoeal diseases, tuberculosis, HIV/AIDS and preterm birth complications.","q":"Which description of Country X fits the lecture?","opts":[["A country with no noncommunicable deaths in its top 10",false,"Even low-income countries have stroke and ischaemic heart disease in the top 10."],["A low-income country, where deaths are mostly from communicable diseases",true,"These causes match the WHO low-income top 10."],["A high-income country, where deaths are mostly from noncommunicable chronic diseases",false,"High-income lists are dominated by heart disease, stroke, dementia and cancers."],["A high-income country, since lower respiratory infections are its top cause",false,"Lower respiratory infections rank 8th in high-income countries."]]},{"id":"W2-Q06","type":"mcq","ch":"W2-C1","src":"W2 Part 1, slides 8, 11","added":"2026-10-26","q":"Which of these is NOT one of the WHO's 13 urgent health challenges for the next decade (2020)?","opts":[["Climate crisis",false,"Challenge 1."],["Under-investment in health care workers",false,"Challenge 7."],["Lack of basic water, sanitation and hygiene in health facilities",false,"Challenge 12."],["Reducing surgical wait times in high-income countries",true,"This is not on the WHO list."]]},{"id":"W2-Q07","type":"mcq","ch":"W2-C1","src":"W2 Part 1, slides 9-10","added":"2026-10-26","q":"According to the lecture, environmental health originally grew out of efforts to:","opts":[["Slow global warming",false,"Global warming is a newer, more complex concern."],["Reduce health inequities among Indigenous Peoples",false,"Health inequities are a separate topic in this lecture."],["Control communicable diseases",true,"Through clean water, sanitary waste disposal, safe food, and insect and rodent control."],["Reduce chronic diseases such as cancer",false,"Not stated; its roots are in communicable disease control."]]},{"id":"W2-Q08","type":"mcq","ch":"W2-C2","src":"W2 Part 1, slide 15","added":"2026-10-26","q":"Which term means a health disparity that is deemed unfair, creating a moral imperative to correct it?","opts":[["Health inequity",true,"Slide 15 definition."],["Health inequality",false,"A systematic difference that can be due to biology and/or social factors; not defined by unfairness."],["Health disparity",false,"Systematic inequalities due mainly to social disadvantage; inequity adds the judgment of unfairness."],["Social gradient in health",false,"The steady rise in longevity across income levels."]]},{"id":"W2-Q09","type":"mcq","ch":"W2-C2","src":"W2 Part 1, slide 15","added":"2026-10-26","case":"Researchers find a systematic difference in a health outcome between two groups and trace it to biological differences between them.","q":"Which term from the lecture fits this difference?","opts":[["Health inequity",false,"An inequity is a disparity deemed unfair."],["Internalized racism",false,"That is a level of racism, not a biological difference."],["Health inequality",true,"A systematic difference in health between groups can be due to biological differences."],["Health disparity",false,"A disparity is due mainly to social disadvantages."]]},{"id":"W2-Q10","type":"mcq","ch":"W2-C2","src":"W2 Part 1, slide 17","added":"2026-10-26","case":"In one society, men are expected to 'tough it out' and avoid seeing a doctor. Over the past generation this expectation has weakened.","q":"Which concept does this describe?","opts":[["Social gradient",false,"The social gradient is about health rising with income."],["Gender",true,"Socially constructed norms and roles that vary between societies and change over time."],["Sex",false,"Sex refers to biological characteristics such as chromosomes and hormones."],["Gender identity",false,"Gender identity is a person's internal experience of gender, not a social expectation."]]},{"id":"W2-Q11","type":"mcq","ch":"W2-C2","src":"W2 Part 1, slide 18","added":"2026-10-26","q":"According to the sex and gender differences slide, how do heart disease symptoms tend to differ?","opts":[["Women often have chest pain; men's symptoms are more subtle",false,"This reverses the slide."],["Both sexes show the same symptoms",false,"The slide lists heart disease as a sex and gender difference."],["Women rarely develop heart disease",false,"The slide makes no such claim."],["Men often have chest pain; women's symptoms are more subtle, such as fatigue and general malaise",true,"This is what the slide states."]]},{"id":"W2-Q12","type":"mcq","ch":"W2-C2","src":"W2 Part 1, slide 21","added":"2026-10-26","case":"A hospital's policies mean that patients from a racialized community wait longer for referrals, and no one from that community sits on the hospital's board.","q":"Which level of racism (Jones, 2000) does this show?","opts":[["Institutionalized (structural) racism",true,"Differences in material conditions (access to care) and in access to power are built into the system."],["Personally-mediated racism",false,"That is prejudice and discrimination by individuals."],["Internalized racism",false,"That is acceptance of negative messages about one's own abilities and worth."],["Gender identity",false,"Not a level of racism."]]},{"id":"W2-Q13","type":"mcq","ch":"W2-C2","src":"W2 Part 1, slide 25","added":"2026-10-26","q":"Which statement about Indigenous Peoples of Canada, compared with non-Indigenous populations, is NOT on the slides?","opts":[["They are 4x more likely to be unemployed",false,"Stated on slide 25."],["They have a lower infant mortality rate",true,"The slide says a higher infant mortality rate."],["They have a 40x higher rate of tuberculosis",false,"Stated on slide 25."],["They have a 2 to 5x higher rate of type 2 diabetes",false,"Stated on slide 25."]]},{"id":"W2-Q14","type":"mcq","ch":"W2-C2","src":"W2 Part 1, slide 22","added":"2026-10-26","case":"Chart 2 (Canada, 2020) shows age-standardized COVID-19 deaths per 100,000. Black, in low income: 103; Black, not in low income: 36. Non-racialized, in low income: 30; not in low income: 21.","q":"Which conclusion does the chart support?","opts":[["Non-racialized Canadians in low income had the highest rate",false,"Their rate was 30, far below 103."],["The gap was caused by biology alone",false,"The chart groups by income and race, which point to social factors."],["Within each group, people in low income had higher COVID-19 mortality, and the gap was largest for Black Canadians",true,"Low income is higher in every group; 103 vs 36 is the widest gap."],["Income made no difference to COVID-19 mortality",false,"Every group shows a higher rate in low income."]]},{"id":"W2-Q15","type":"mcq","ch":"W2-C3","src":"W2 Part 2, slide 4","added":"2026-10-26","q":"Which of these is NOT part of the mandate of the Public Health Agency of Canada?","opts":[["Prevent and control chronic diseases and injuries",false,"Part of the mandate."],["Run hospitals and deliver surgical care",true,"Not on the PHAC mandate slide."],["Prepare for and respond to public health emergencies",false,"Part of the mandate."],["Serve as a central point for sharing Canada's expertise with the world",false,"Part of the mandate."]]},{"id":"W2-Q16","type":"mcq","ch":"W2-C3","src":"W2 Part 2, slide 5","added":"2026-10-26","q":"Which statement about public health and population health is true?","opts":[["Public health focuses on individuals, while population health focuses on groups",false,"Both are concerned with patterns in groups, not individuals."],["Only population health monitors health trends",false,"Both monitor health trends and examine their determinants."],["Population health does not propose interventions",false,"Both propose population-level interventions."],["The population model takes a broader view and often looks at underlying social determinants, aiming to reduce health inequities",true,"Slide 5."]]},{"id":"W2-Q17","type":"mcq","ch":"W2-C3","src":"W2 Part 2, slides 6-7","added":"2026-10-26","case":"A province passes a law and new tax measures to reduce child poverty across the whole population.","q":"Which level of prevention is this?","opts":[["Secondary",false,"Secondary prevention detects and treats disease early."],["Tertiary",false,"Tertiary prevention follows clinical treatment."],["Primordial",true,"Government legislation and fiscal measures that modify social determinants for the whole population."],["Primary",false,"Primary prevention limits exposures to specific disease risks in at-risk groups."]]},{"id":"W2-Q18","type":"mcq","ch":"W2-C3","src":"W2 Part 2, slides 6-7","added":"2026-10-26","case":"A public health nurse gives the HPV vaccine to grade 7 students, who do not have the infection.","q":"Which level of prevention is this?","opts":[["Primary",true,"It prevents the onset of a specific disease through risk reduction."],["Primordial",false,"Primordial prevention addresses broad social determinants, not a specific disease."],["Secondary",false,"Secondary prevention detects disease that has already started."],["Tertiary",false,"Tertiary prevention applies after clinical treatment."]]},{"id":"W2-Q19","type":"mcq","ch":"W2-C3","src":"W2 Part 2, slides 6-7","added":"2026-10-26","case":"A woman with no symptoms has a routine Pap test. Abnormal cells are found and removed before they become cancer.","q":"Which level of prevention does the Pap test represent?","opts":[["Tertiary",false,"Tertiary prevention is after clinical treatment of established disease."],["Primordial",false,"Primordial prevention modifies social determinants."],["Secondary",true,"Screening detects and treats pathological changes early, in the preclinical phase."],["Primary",false,"Primary prevention acts before any pathological change exists."]]},{"id":"W2-Q20","type":"mcq","ch":"W2-C3","src":"W2 Part 2, slides 6-7","added":"2026-10-26","case":"After surgery and treatment for a stroke, a man attends physiotherapy and receives follow-up care so he can regain function and avoid another stroke.","q":"Which level of prevention is this?","opts":[["Primordial",false,"Primordial prevention targets broad determinants in the whole population."],["Tertiary",true,"After clinical treatment: rehabilitation and follow-up to prevent relapse and reduce impact."],["Secondary",false,"Secondary prevention catches disease early, before the clinical phase."],["Primary",false,"Primary prevention stops disease from starting."]]},{"id":"W2-Q21","type":"mcq","ch":"W2-C3","src":"W2 Part 2, slide 7","added":"2026-10-26","q":"On the levels of prevention figure, which target population matches primary prevention?","opts":[["Whole population",false,"That is primordial prevention."],["Patients with disease",false,"That is secondary prevention."],["Recovering individuals",false,"That is tertiary prevention."],["At-risk groups",true,"Primary prevention sits under risk and protective factors and targets at-risk groups."]]},{"id":"W2-Q22","type":"mcq","ch":"W2-C3","src":"W2 Part 2, slides 6-7","added":"2026-10-26","case":"A family physician sees a patient with a strong family history of heart disease but no disease yet, and counsels him on diet and exercise.","q":"Which level of prevention is the physician practising?","opts":[["Primary",true,"Counselling for risk factor change before disease starts; family physicians work at the primary level through counselling."],["Secondary",false,"There is no pathological change to detect yet."],["Tertiary",false,"There has been no clinical disease or treatment."],["Primordial",false,"Primordial prevention works through legislation and social programs, not individual counselling."]]},{"id":"W2-Q23","type":"mcq","ch":"W2-C4","src":"W2 Part 2, slides 8, 11","added":"2026-10-26","q":"How does health promotion differ from health protection?","opts":[["They are the same thing",false,"Slide 11 says promotion differs from protection."],["Promotion aims to enhance health; protection focuses on removing negative threats",true,"Slide 11."],["Promotion removes threats; protection builds skills",false,"This reverses the two."],["Promotion is only for individuals; protection is only for governments",false,"Promotion includes policy and community work, not only individuals."]]},{"id":"W2-Q24","type":"mcq","ch":"W2-C4","src":"W2 Part 2, slide 8","added":"2026-10-26","case":"After a storm, the city tests well water for contamination and issues a boil-water advisory.","q":"Which public health strategy is this?","opts":[["Tertiary prevention",false,"Tertiary prevention is for recovering patients."],["Strengthening community action",false,"That is an Ottawa Charter action area led by communities."],["Health protection",true,"Ensuring water safety reduces a threat to population health."],["Health promotion",false,"Promotion enhances health through education, policy and skill building."]]},{"id":"W2-Q25","type":"mcq","ch":"W2-C4","src":"W2 Part 2, slide 9","added":"2026-10-26","q":"Which activity is an example of long-term, passive surveillance?","opts":[["Teaching high school students to read food labels",false,"That is health promotion."],["Yearly reports that track obesity rates across Canada",true,"Ongoing, long-term monitoring of general health trends."],["Calling every clinic daily during a suspected outbreak",false,"That is active, short-term surveillance."],["Vaccinating students before flu season",false,"That is primary prevention."]]},{"id":"W2-Q26","type":"mcq","ch":"W2-C4","src":"W2 Part 2, slide 10","added":"2026-10-26","case":"A family health team changes its focus from treating illness to also running prevention and health promotion programs.","q":"Which Ottawa Charter action area fits best?","opts":[["Building healthy public policy",false,"That involves laws and policies, such as bylaws or taxes."],["Strengthening community action",false,"That involves communities organizing themselves."],["Developing personal skills",false,"That involves teaching individuals skills."],["Reorienting health services",true,"Shifting the role of health services toward prevention and promotion."]]},{"id":"W2-Q27","type":"mcq","ch":"W2-C4","src":"W2 Part 2, slide 12","added":"2026-10-26","q":"Which modifiable risk factor was NOT named as a focus of the Integrated Pan-Canadian Healthy Living Strategy (2002)?","opts":[["Unhealthy diets",false,"Named on slide 12."],["Tobacco use",false,"Named on slide 12."],["Excessive alcohol use",true,"The strategy named physical inactivity, unhealthy diets and tobacco use."],["Physical inactivity",false,"Named on slide 12."]]},{"id":"W2-Q28","type":"mcq","ch":"W2-C4","src":"W2 Part 2, slides 12, 15","added":"2026-10-26","q":"British Columbia's healthy living target was to raise physical activity from 58% to 69.6%. By how many percentage points is that?","opts":[["11.6",true,"69.6 minus 58 is 11.6 percentage points, as slide 15 states."],["10",false,"Most provinces chose 10 points; BC's target was larger."],["8.4",false,"8.4 points is BC's target for reducing obesity and overweight."],["20",false,"Not a value on the slide."]]},{"id":"W2-Q29","type":"mcq","ch":"W2-C5","src":"W2 Part 3, slide 5","added":"2026-10-26","q":"In the 2022 National College Health Assessment of Canadian students, which health issue affected the most students?","opts":[["Anxiety (43.4%)",false,"Third."],["Sleep difficulties (31.9%)",false,"Fourth."],["Procrastination (61.0%)",true,"The top entry in the table."],["Stress (51.5%)",false,"Second."]]},{"id":"W2-Q30","type":"mcq","ch":"W2-C5","src":"W2 Part 3, slide 6","added":"2026-10-26","q":"What is locus of control?","opts":[["The stage at which a person has kept a new behaviour for 6 months",false,"That is maintenance."],["The figurative place a person designates as the source of responsibility for the events in their life",true,"Slide 6 definition."],["A person's belief that a health threat is serious",false,"That is perceived severity in the Health Belief Model."],["Felt social pressure to act",false,"That is subjective norms in the Theory of Planned Behaviour."]]},{"id":"W2-Q31","type":"mcq","ch":"W2-C5","src":"W2 Part 3, slide 9","added":"2026-10-26","case":"Priya says, 'I know I should cut back on caffeine. I'm going to do it sometime in the next few months, but not yet.'","q":"Which stage of change is Priya in?","opts":[["Precontemplation",false,"She does see a reason to change."],["Preparation",false,"Preparation means acting within a month or already taking small steps."],["Action",false,"She has not started changing."],["Contemplation",true,"She intends to change within 6 months but has not started."]]},{"id":"W2-Q32","type":"mcq","ch":"W2-C5","src":"W2 Part 3, slide 9","added":"2026-10-26","case":"Marcus has swapped energy drinks for water every day for the last 8 months.","q":"Which stage of change is Marcus in?","opts":[["Maintenance",true,"He has kept the new behaviour for at least 6 months."],["Action",false,"Action is making the change, before the 6-month mark."],["Preparation",false,"He is past planning and small steps."],["Contemplation",false,"He has already changed."]]},{"id":"W2-Q33","type":"mcq","ch":"W2-C5","src":"W2 Part 3, slides 9-10","added":"2026-10-26","case":"After 3 months of regular workouts, Lena stops exercising during exam season and goes back to only thinking about restarting.","q":"How does the lecture describe what happened?","opts":[["Maintenance, because she exercised for 3 months",false,"Maintenance requires at least 6 months."],["Relapse, slipping back to a previous stage, which is a common part of the cycle of change",true,"Fig 1.7 notes that relapse is common in the spiral model."],["Termination, because she ended the behaviour",false,"Termination means the new behaviour is fully adopted."],["Proof that the stages of change model does not apply to her",false,"The model expects relapse."]]},{"id":"W2-Q34","type":"mcq","ch":"W2-C5","src":"W2 Part 3, slides 11-12","added":"2026-10-26","case":"A student had not planned to get a flu shot. Then his roommate got very sick with the flu, and he booked a shot the next day.","q":"In the Health Belief Model, what role did the roommate's illness play?","opts":[["A perceived barrier",false,"A barrier would discourage the action."],["A modifying factor",false,"Modifying factors are demographics, sociopsychological and structural variables."],["A cue to action",true,"Illness of a family member or friend is listed as a cue to action that raises perceived threat."],["A subjective norm",false,"Subjective norms belong to the Theory of Planned Behaviour."]]},{"id":"W2-Q35","type":"mcq","ch":"W2-C5","src":"W2 Part 3, slides 7, 13","added":"2026-10-26","q":"What does the Theory of Planned Behaviour add to the Health Belief Model?","opts":[["Cues to action",false,"Cues to action are part of the HBM."],["Subjective norms (perceived social pressure) and self-efficacy",true,"Slide 7: an extension of the HBM that incorporates subjective norms and self-efficacy."],["Perceived susceptibility and perceived severity",false,"These are already part of the HBM."],["Stages of readiness to change",false,"That is the transtheoretical model."]]},{"id":"W2-Q36","type":"mcq","ch":"W2-C5","src":"W2 Part 3, slide 13","added":"2026-10-26","q":"In the Theory of Planned Behaviour diagram, which component has a direct arrow to behaviour as well as an arrow to intention?","opts":[["Attitude toward the behaviour",false,"Attitude only feeds intention."],["Subjective norms",false,"Subjective norms only feed intention."],["Normative beliefs",false,"Normative beliefs feed subjective norms."],["Perceived behavioural control",true,"It feeds intention and also points directly to behaviour."]]},{"id":"W2-Q37","type":"mcq","ch":"W2-C6","src":"W2 Part 3, slide 18","added":"2026-10-26","q":"Which goal best meets all the SMART criteria?","opts":[["Run 10 km every day starting tomorrow, after not exercising for a year",false,"Not attainable or realistic for a beginner."],["Exercise more often",false,"Not specific, measurable or time-bound."],["Walk 2 km, 3 days a week, for 15 to 20 minutes, for the next 4 weeks",true,"Specific activity, numbers to measure, a modest level, and a time frame."],["Get healthier this year",false,"Vague and not measurable."]]},{"id":"W2-Q38","type":"mcq","ch":"W2-C6","src":"W2 Part 3, slides 14-17","added":"2026-10-26","case":"After a week of logging, Noor sees that she scrolls on her phone mostly after 11 p.m., when alone and feeling anxious about deadlines.","q":"Which step of the personalized plan is Noor doing now?","opts":[["Analyze the data and identify patterns",true,"Finding triggers and links between feelings and cues such as time of day."],["Monitor your behaviour and gather data",false,"She already did that by logging for a week."],["Make a personal contract",false,"The contract comes after goals and a plan."],["Devise a plan of action",false,"She has not chosen strategies yet."]]},{"id":"W2-Q39","type":"mcq","ch":"W2-C6","src":"W2 Part 3, slide 19","added":"2026-10-26","case":"To cut back on junk food, Omar stops buying chips for his residence room and keeps cut fruit in his mini-fridge.","q":"Which plan-of-action strategy is he using?","opts":[["Involve the people around you",false,"He is acting alone."],["Make a personal contract",false,"That is step 5, not a plan-of-action strategy."],["Modify your environment",true,"He is changing what is around him to support the new behaviour."],["Reward yourself",false,"No reward is described."]]},{"id":"W2-Q40","type":"mcq","ch":"W2-C6","src":"W2 Part 3, slides 20, 22","added":"2026-10-26","case":"Kai's friends keep inviting him to late-night fast food runs, and he keeps going even though his goal is to eat out less.","q":"Which barrier to staying with a plan is this?","opts":[["Procrastinating, rationalizing and blaming",false,"He is not delaying or making excuses in the case."],["Social influences",true,"Pressure from friends is listed as a social influence."],["Stress barrier",false,"No stress is described."],["Choice of techniques and level of effort",false,"The issue is the friends, not his technique."]]},{"id":"W2-TQ01","ch":"W2-C7","src":"Textbook Ch 1, p. 4","added":"2026-10-26","q":"According to the textbook, how does wellness differ from health?","opts":[["Health can be shaped by factors beyond your control, while wellness is largely determined by the decisions you make about how you live.",true,"These are the two differences the textbook names."],["They mean exactly the same thing, so there is no difference.",false,"The textbook uses the words interchangeably but says two important differences exist."],["Wellness means only the absence of disease or injury.",false,"That is closer to the traditional view of health. Wellness goes beyond it to optimal health and vitality."],["Health is mostly decided by lifestyle, while wellness is mostly genetic.",false,"This reverses the textbook."]]},{"id":"W2-TQ02","ch":"W2-C7","src":"Textbook Ch 1, p. 4","added":"2026-10-26","q":"Ravi, 45, is worried about type 2 diabetes. Which of his risk factors is nonmodifiable?","opts":[["His father and grandfather both had type 2 diabetes.",true,"Family history, like age, is a nonmodifiable risk factor."],["He rarely exercises.",false,"Physical activity is a modifiable behaviour."],["He drinks two cans of pop a day.",false,"Diet is modifiable."],["He smokes.",false,"Smoking is a modifiable behaviour the textbook names."]]},{"id":"W2-TQ03","ch":"W2-C7","src":"Textbook Ch 1, p. 5","added":"2026-10-26","q":"Jamal joins a debate club, reads widely outside his program and keeps trying to master new skills. Which dimension of wellness is he building most directly?","opts":[["Intellectual",true,"Intellectual wellness means constantly challenging your mind and never stopping learning."],["Emotional",false,"Emotional wellness is about understanding and dealing with your feelings."],["Spiritual",false,"Spiritual wellness is about guiding beliefs and values that give meaning and purpose."],["Occupational",false,"Occupational wellness is fulfillment gained through work."]]},{"id":"W2-TQ04","ch":"W2-C7","src":"Textbook Ch 1, pp. 5-6","added":"2026-10-26","q":"Sofia is not religious. She draws meaning and purpose from meditation and time in nature, and these values help her through hard times. What does the textbook say?","opts":[["This is spiritual wellness; religion is one source of it but not the only one.",true,"Many people find meaning on their own, through nature, art, meditation or good works."],["This cannot be spiritual wellness because it does not involve organized religion.",false,"The textbook says religion is not the only source or form of spiritual wellness."],["This is environmental wellness, because it involves nature.",false,"Environmental wellness is about the livability of your surroundings, not personal meaning."],["This is emotional wellness, because spirituality is a feeling.",false,"Guiding beliefs that give meaning and purpose define spiritual wellness."]]},{"id":"W2-TQ05","ch":"W2-C7","src":"Textbook Ch 1, p. 6","added":"2026-10-26","q":"Marco earns a high salary and has an impressive title, but he dislikes his work, feels no connection to co-workers and has no chance to learn. How does the textbook view his occupational wellness?","opts":[["It is low, because salary and title alone generally do not bring occupational wellness.",true,"An occupationally well person likes the work, feels connected to others there, and can learn and be challenged."],["It is high, because income is the main part of occupational wellness.",false,"High salaries and prestigious titles alone generally do not bring it."],["It is high, because financial wellness and occupational wellness are the same thing.",false,"Financial wellness is a related facet, not the same thing."],["It cannot be judged, since occupational wellness is not discussed in the textbook.",false,"The textbook has a box on occupational wellness."]]},{"id":"W2-TQ06","ch":"W2-C7","src":"Textbook Ch 1, p. 6","added":"2026-10-26","q":"Which student best shows financial wellness as the textbook describes it?","opts":[["Mia earns little, but she knows the limits of her income, keeps expenses in check and saves a small amount each month.",true,"Financial wellness means being comfortable with your situation and living within your means, not being rich."],["Owen has a large allowance but overspends and worries about bills every week.",false,"Money problems are a source of stress; wealth alone does not make you financially well."],["Lea avoids looking at her bank statements so money does not stress her.",false,"Financially well people can interpret their bank statements."],["Ben believes more possessions will make him happy, so he buys on credit.",false,"Money and possessions in themselves will not necessarily make you happy."]]},{"id":"W2-TQ07","ch":"W2-C7","src":"Textbook Ch 1, pp. 9-10","added":"2026-10-26","q":"The textbook names two dangers when talking about health issues for diverse populations. What are they?","opts":[["Stereotyping and overgeneralizing",true,"Stereotyping treats people as groups rather than individuals; overgeneralizing ignores diversity within a group."],["Rationalizing and blaming",false,"These are games that undermine a behaviour change plan."],["Medicalizing and individualizing",false,"These are not the two dangers named."],["Stigma and discrimination",false,"Discrimination is discussed as a cause of disparities, but it is not one of the two dangers."]]},{"id":"W2-TQ08","ch":"W2-C7","src":"Textbook Ch 1, pp. 9-10","added":"2026-10-26","q":"Which health difference is cultural rather than biological, as the textbook uses those terms?","opts":[["A traditional diet learned from family and community",true,"Cultural differences are patterns of behaviour acquired through daily interactions with family, community and society."],["Higher rates of sickle-cell disease among people of African ancestry",false,"This is a genetic (biological) difference concentrated in a gene pool."],["Tay-Sachs disease among people of Eastern European Jewish and French-Canadian heritage",false,"This is a genetic (biological) difference."],["Higher rates of cystic fibrosis among people of Northern European descent",false,"This is a genetic (biological) difference."]]},{"id":"W2-TQ09","ch":"W2-C7","src":"Textbook Ch 1, pp. 12-13","added":"2026-10-26","q":"According to the textbook, which factors are far more important predictors of poor health than any ethnic factor?","opts":[["Poverty and low educational attainment",true,"Income and education are closely related, and the groups with the highest poverty and least education have the worst health."],["Genetic predisposition and family history",false,"Heredity matters, but the textbook names poverty and education as the strongest predictors of disparities."],["Geographic location and climate",false,"Location matters, but it is not what the textbook ranks highest."],["Sex and age",false,"These are not named as the strongest predictors."]]},{"id":"W2-TQ10","ch":"W2-C7","src":"Textbook Ch 1, p. 16","added":"2026-10-26","q":"Diabetes has risen sharply among Canadians in recent years. How does the textbook explain the rise?","opts":[["Rising obesity from poor dietary choices and lack of physical activity, not a change in genes",true,"The textbook uses this as an example of the power of behaviour and environment."],["A sudden change in the Canadian gene pool",false,"The textbook says the rise is not due to any sudden change in our genes."],["Better screening that finds cases that were always there",false,"The textbook does not give this explanation."],["An increase in infectious causes of diabetes",false,"Not the textbook's explanation."]]},{"id":"W2-TQ11","ch":"W2-C7","src":"Textbook Ch 1, pp. 14-16","added":"2026-10-26","q":"Which statement about the factors that influence wellness is NOT true, according to the textbook?","opts":[["Once a person has a genetic predisposition to a common disease such as heart disease, behaviour cannot change the outcome.",true,"This is false. In common, complex disorders, altered genes only increase risk, and behaviour can tip the balance."],["Vaccinations and screening tests show how access to health care improves quality and quantity of life.",false,"This is true; the textbook gives these examples."],["Environment includes conditions in your home, workplace and community, not only air and water.",false,"This is true."],["Behaviour, family history, environment and access to health care can interact to produce health or disease.",false,"This is true; these are the four factors named."]]},{"id":"W2-TQ12","ch":"W2-C8","src":"Textbook Ch 1, pp. 18-19","added":"2026-10-26","q":"Leila wants to start exercising, quit vaping, sleep eight hours a night and cut out sugar, all starting this Monday. What does the textbook advise?","opts":[["Choose one target behaviour, start with a simple goal, and build on success before taking on the next.",true,"Changing any behaviour is demanding, so start small with one target behaviour."],["Change everything at once while motivation is high.",false,"The textbook recommends one behaviour at a time."],["Start with the hardest behaviour first to prove her commitment.",false,"Success is more likely if the first goal is simple; later goals can be a little more significant."],["Wait until she reaches the termination stage for all four behaviours.",false,"Termination is the end of a cycle of change, not a starting condition."]]},{"id":"W2-TQ13","ch":"W2-C8","src":"Textbook Ch 1, p. 21","added":"2026-10-26","q":"According to the textbook, what kind of benefit moves most people to change a health behaviour?","opts":[["Shorter-term, personal benefits, such as feeling better, doing better in school or reducing stress",true,"Some people are moved by long-term goals, but most respond more to short-term, personal ones."],["Avoiding a disease that may develop 30 years from now",false,"The textbook says this moves some people, but most respond more to short-term goals."],["Knowing the facts about the behaviour's risks",false,"Knowledge is necessary but usually not enough to make people act."],["Pressure from family members to change",false,"Asking family about the effects of your behaviour helps the analysis, but it is not what the textbook says moves most people."]]},{"id":"W2-TQ14","ch":"W2-C8","src":"Textbook Ch 1, p. 21","added":"2026-10-26","q":"Dana says, \"My mother died of breast cancer, so I will too. Self-exams and checkups are a waste of time.\" What does her thinking show?","opts":[["An external locus of control, which can sabotage efforts to change",true,"This is the textbook's own example of an external locus of control."],["An internal locus of control",false,"An internal locus would mean believing she can act to reduce her risk."],["High self-efficacy",false,"Self-efficacy is belief in your ability to act; Dana believes action is pointless."],["The termination stage of change",false,"Termination means total self-efficacy for a behaviour already changed."]]},{"id":"W2-TQ15","ch":"W2-C8","src":"Textbook Ch 1, pp. 21-22","added":"2026-10-26","q":"Before a party, Omar repeats to himself, \"I am a strong, capable person, and I can keep my commitment not to drink tonight.\" Which self-efficacy strategy is he using?","opts":[["Self-talk",true,"Self-talk is the internal dialogue you use to counter self-defeating thoughts with positive or realistic ones."],["Visualization",false,"Visualization means picturing yourself doing the new behaviour and enjoying its benefits."],["Cost-benefit analysis",false,"That is weighing the pros and cons of change."],["Rationalizing",false,"Rationalizing is making excuses, which works against change."]]},{"id":"W2-TQ16","ch":"W2-C8","src":"Textbook Ch 1, p. 22","added":"2026-10-26","q":"Kai has started walking after class, but only once or twice a week so far. He has written a plan and plans to walk daily within a month, but he worries he will fail. Which stage is he in?","opts":[["Preparation",true,"Preparation: plans to act within a month or has begun small changes, not yet regularly, and may fear failing."],["Contemplation",false,"Contemplators intend to act within six months and do not yet know how to proceed."],["Action",false,"In action, the behaviour change is outward and consistent and takes the most time and energy."],["Maintenance",false,"Maintenance requires at least six months of the new behaviour."]]},{"id":"W2-TQ17","ch":"W2-C8","src":"Textbook Ch 1, p. 22","added":"2026-10-26","q":"Theo tried to cut back on drinking last year and failed. Now he says it's hopeless, blames his roommates for his habits, and has no plan to change. Which stage is he in?","opts":[["Precontemplation",true,"People in precontemplation may think change is hopeless after past failures and may blame others or external factors."],["Contemplation",false,"Contemplators know they have a problem and intend to act within six months."],["Relapse in the maintenance stage",false,"He is not maintaining any change, and he does not intend to change."],["Termination",false,"Termination means he is no longer tempted by the old behaviour."]]},{"id":"W2-TQ18","ch":"W2-C8","src":"Textbook Ch 1, p. 23","added":"2026-10-26","q":"How does the textbook describe the termination stage?","opts":[["The person has exited the cycle, is no longer tempted to lapse, and has total self-efficacy for the behaviour; it is reached for some behaviours.",true,"This is the textbook's description of the sixth and final stage."],["The person has kept the new behaviour for at least six months but still has occasional lapses.",false,"That describes maintenance."],["The person outwardly changes behaviour and environment with great effort.",false,"That describes action."],["The person decides to stop trying to change.",false,"Stopping before reaching the goal is what the textbook calls failure."]]},{"id":"W2-TQ19","ch":"W2-C8","src":"Textbook Ch 1, pp. 23-24","added":"2026-10-26","q":"In the textbook, what is the difference between a relapse and failure?","opts":[["A relapse is a return to old habits; failure is stopping before you reach your goal and never changing the behaviour.",true,"Relapse can be demoralizing, but it is not the same as failure."],["A relapse is a single slip; failure is any return to old habits.",false,"A single slip is a lapse. A return to old habits is a relapse."],["They are the same thing.",false,"The textbook separates them."],["Failure happens only in the action stage; relapse only in maintenance.",false,"The textbook does not tie them to stages this way."]]},{"id":"W2-TQ20","ch":"W2-C8","src":"Textbook Ch 1, p. 24","added":"2026-10-26","q":"Mei went three weeks without late-night snacking, then snacked every night of exam week. Which response follows the textbook's steps for dealing with relapse?","opts":[["Forgive herself, give herself credit for the three good weeks, learn what triggered the slip and move on.",true,"Forgive yourself, give yourself credit, move on."],["Decide the plan has failed and drop it until next term.",false,"Abandoning the effort is what turns a relapse into failure."],["Punish herself with a stricter goal of no snacks at all for a month.",false,"The textbook aims to avoid guilt and self-blame. A harder goal makes giving up more likely."],["Keep the slip to herself so her helper does not lose faith in her.",false,"The textbook stresses support from others and learning from the relapse."]]},{"id":"W2-TQ21","ch":"W2-C8","src":"Textbook Ch 1, p. 24","added":"2026-10-26","q":"Akira has smoked for 15 years. Her goal is to quit cold turkey tomorrow with no other support. Which SMART criterion does the textbook say this kind of goal is most likely to miss?","opts":[["Realistic",true,"The textbook's Realistic example: a long-time smoker may not be able to quit cold turkey; a more realistic plan uses nicotine replacement and a support group."],["Specific",false,"Her goal is specific: quit, starting tomorrow."],["Measurable",false,"Smoking zero cigarettes is measurable."],["Attainable",false,"In the textbook, Attainable is about physical limits, like a poor swimmer choosing walking instead of laps."]]},{"id":"W2-TQ22","ch":"W2-C8","src":"Textbook Ch 1, p. 25","added":"2026-10-26","q":"Jordan's long-term aim is to reach a healthy weight. What kind of goal does the textbook suggest he focus on?","opts":[["Healthy habits, such as exercising 30 minutes a day or cutting late-night snacks",true,"For long-term lifestyle change, focus on habits rather than a specific weight loss."],["A specific number of kilograms to lose by a set date",false,"The textbook says it is better to focus on habits than a specific weight loss."],["Whatever his friends are aiming for, so they can do it together",false,"The textbook says to make choices that are right for you."],["No goal at all until he reaches the action stage",false,"Even early in change, a goal such as learning about the risks is useful."]]},{"id":"W2-TQ23","ch":"W2-C8","src":"Textbook Ch 1, p. 26","added":"2026-10-26","q":"Sam always buys chips from the same vending machine on his way to class, so he changes his route to avoid it. Which plan-of-action strategy is this?","opts":[["Modify your environment",true,"If cues in your environment trigger the behaviour, control them. The textbook gives this vending machine example."],["Control related habits",false,"That means changing a linked habit, like putting an exercise bike in front of the TV."],["Reward yourself",false,"Rewards reinforce progress; changing his route removes a cue."],["Involve the people around you",false,"That means telling friends and family and giving them a list of dos and don'ts."]]},{"id":"W2-TQ24","ch":"W2-C8","src":"Textbook Ch 1, p. 26","added":"2026-10-26","q":"Which reward plan best fits the textbook's guidance?","opts":[["Deciding in advance to see a movie after one week of avoiding unhealthy snacks",true,"Rewards should be planned, instant and real, tied to specific goals or subgoals, and preferably not food or alcohol."],["A large dessert after every workout",false,"Rewards should preferably be unrelated to food or alcohol."],["Picking a treat on the spot whenever she feels she deserves one",false,"The textbook says to decide in advance what each reward will be and how you will earn it."],["One reward only, after the final goal is reached in six months",false,"The textbook ties rewards to subgoals too, so you get regular reinforcement."]]},{"id":"W2-TQ25","ch":"W2-C8","src":"Textbook Ch 1, p. 26","added":"2026-10-26","q":"According to the textbook, why make a serious personal contract, and who should sign it as a witness?","opts":[["It leads to more follow-through than a casual promise and helps prevent procrastination by setting dates; ideally someone actively helping with your program signs it.",true,"Both points are in the textbook's description of the contract."],["It is legally binding, so it protects you if you break your plan; a lawyer or notary should sign it as the witness.",false,"It is a personal commitment, not a legal document."],["It replaces the need for a health journal, and it works best when kept private so no one else signs it.",false,"The contract lists the tools you will use to monitor progress, such as a journal, and should be witnessed."],["It lets you skip goal-setting; your doctor should sign it.",false,"The contract states your goal, and the witness is ideally someone helping with the program."]]},{"id":"W2-TQ26","ch":"W2-C8","src":"Textbook Ch 1, p. 27","added":"2026-10-26","q":"Nadia skips her planned run and tells herself, \"It might rain later, and I'd hate to get my new shoes muddy.\" Which game is she playing?","opts":[["Rationalizing",true,"Rationalizing is making excuses. When you win by deceiving yourself, it is not much of a victory."],["Procrastinating",false,"Procrastinating is putting off the start, like waiting until Monday."],["Blaming",false,"Blaming puts the fault on another person."],["Visualization",false,"Visualization is a positive strategy for picturing success."]]},{"id":"W2-TQ27","ch":"W2-C8","src":"Textbook Ch 1, p. 27","added":"2026-10-26","q":"Priya has quit smoking and keeps pushing her roommate to quit too. Her own plan is stalling. What does the textbook say?","opts":[["Trying to change others is a trap; she can offer facts or support tactfully, but should focus on herself and may become a role model.",true,"The decision to make a major change comes only after intensive self-examination."],["She should keep pushing, since social influences are the strongest tool for change.",false,"The textbook calls trying to change friends or family a trap."],["She should drop her own plan until her roommate is ready.",false,"The textbook says to focus on yourself."],["She should end the friendship right away.",false,"The textbook says to connect with others who are more supportive, not to cut people off."]]},{"id":"W2-TQ28","ch":"W2-C8","src":"Textbook Ch 1, p. 27","added":"2026-10-26","q":"Halfway through her exercise plan, Grace catches a cold during the week a term paper is due. What does the textbook suggest for this stress barrier?","opts":[["Because the stress is temporary, she may wait until it passes before strengthening her efforts.",true,"For temporary stress, waiting can make sense. For ongoing stress, find healthy ways to manage it."],["She should drop the plan, since stress means she is not ready to change.",false,"The textbook does not say to quit."],["She should double her workouts to make up for lost time.",false,"The textbook suggests waiting out temporary stress."],["She should make stress management her new target behaviour right away.",false,"The textbook suggests this for ongoing stress, not a temporary cold and deadline."]]},{"id":"W2-TQ29","ch":"W2-C8","src":"Textbook Ch 1, p. 20","added":"2026-10-26","q":"A news story says that drinking coffee is \"associated with\" a longer life. Which response follows the textbook's advice on evaluating health information?","opts":[["Remember that 'associated with' does not prove cause and effect, check the original study, and do not change your behaviour on the basis of a single report.",true,"All three are textbook guidelines for judging health information."],["Start drinking more coffee, since the study was reported in the news and a published finding is enough to act on.",false,"Do not change behaviour based on a single report or study."],["Trust it if a friend says coffee helped him.",false,"Anecdotes are not facts."],["Trust it if the article calls it a breakthrough, since strong wording means the evidence is strong.",false,"Words like 'breakthrough' and 'dramatic proof' are probably hype."]]}],"review":[{"id":"W2-R01","ch":"W2-C2","src":"W2 Part 1, slide 15","added":"2026-10-26","q":"Define health inequality, health disparity and health inequity, and give the example from the slides of an inequity.","answer":"A health inequality is a systematic difference in health between groups, due to biological differences and/or lifestyle, socio-economic status or differential access to care. A health disparity is a systematic inequality due mainly to social disadvantages. A health inequity is a disparity that is deemed unfair, which creates a moral imperative to correct it. The slides give systematic health disparities for Indigenous Canadians as the example of an inequity.","points":["Inequality: systematic difference; biology and/or social causes","Disparity: due mainly to social disadvantage","Inequity: disparity judged unfair, moral imperative to correct","Example: Indigenous Canadians"]},{"id":"W2-R02","ch":"W2-C3","src":"W2 Part 2, slides 6-7","added":"2026-10-26","q":"Describe the four levels of prevention. For each, name its target population and give one example.","answer":"Primordial prevention addresses broad health determinants to minimize future hazards; it targets the whole population, for example through government legislation and fiscal measures or community social programs. Primary prevention prevents the onset of specific diseases through risk reduction; it targets at-risk groups, for example a physician counselling a smoker to quit. Secondary prevention detects and treats pathological changes early; it targets patients with disease in the preclinical phase, for example public health screening. Tertiary prevention prevents relapse or reduces impact after clinical treatment; it targets recovering individuals, for example rehabilitation and follow-up care.","points":["Primordial: social determinants, whole population","Primary: risk reduction before onset, at-risk groups","Secondary: early detection and treatment, screening","Tertiary: after treatment, prevent relapse, rehabilitation","One fitting example for each level"]},{"id":"W2-R03","ch":"W2-C4","src":"W2 Part 2, slides 8-11","added":"2026-10-26","q":"Compare health protection, surveillance and health promotion. Give one example of each.","answer":"Health protection reduces threats to population health using primordial and primary prevention, for example food and water safety or controlling infectious diseases. Surveillance is the ongoing, systematic collection and analysis of population-level health information to guide interventions; it can be long-term passive monitoring of trends or active short-term checking for outbreaks. Health promotion differs from protection because it aims to enhance health rather than remove threats, through education, healthy public policy, supportive interventions and building skills and resiliency. An example is teaching cooking skills, which fits the Ottawa Charter area of developing personal skills.","points":["Protection removes threats (water, food, infectious disease)","Surveillance collects and analyzes data to guide interventions","Passive long-term vs active short-term surveillance","Promotion enhances health (education, policy, skills)","An example for each"]},{"id":"W2-R04","ch":"W2-C5","src":"W2 Part 3, slides 8-10","added":"2026-10-26","q":"Describe the stages of the transtheoretical model and explain why knowing your current stage matters.","answer":"In precontemplation the person has no intention to change and sees no reason to. In contemplation they intend to change within 6 months. In preparation they plan to act within a month or are taking small steps. In action they are already changing, which takes time and energy. In maintenance they have kept the new lifestyle for at least 6 months, and in termination the new behaviour is adopted. Knowing your stage lets you choose strategies that fit it so you can progress, and relapse to an earlier stage is a common part of the cycle.","points":["All six stages in order","Time markers: 6 months, 1 month, at least 6 months","Knowing your stage guides strategy choice","Relapse is common"]},{"id":"W2-R05","ch":"W2-C5","src":"W2 Part 3, slides 7, 11-13","added":"2026-10-26","q":"Compare the Health Belief Model and the Theory of Planned Behaviour, using a student getting a flu shot as an example.","answer":"The Health Belief Model says people take preventive action when they believe the threat is serious, believe they are susceptible, and believe the benefits of acting outweigh the barriers; a strong enough belief or a cue to action triggers them. A student might get a flu shot after a reminder from campus health services. The Theory of Planned Behaviour assumes rational planning and extends the HBM by adding subjective norms and self-efficacy. Attitude, subjective norms and perceived behavioural control shape intention, which leads to behaviour. In TPB terms, the student gets the shot because friends expect it and the student feels able to book it.","points":["HBM: perceived severity, susceptibility, benefits vs barriers","HBM: cues to action","TPB: rational planning, extension of HBM","TPB: subjective norms and self-efficacy (perceived behavioural control) shape intention","Applies both to the flu shot"]},{"id":"W2-R06","ch":"W2-C6","src":"W2 Part 3, slides 14-20","added":"2026-10-26","q":"Outline the five steps of a personalized behaviour change plan and write one SMART goal for a target behaviour of your choice.","answer":"First, monitor your behaviour and gather data in a health journal: what, when and where, what you were doing and how you felt. Second, analyze the data to find triggers and patterns. Third, set SMART goals: specific, measurable, attainable, realistic and time frame specific. Fourth, devise a plan of action, such as modifying your environment, rewarding yourself and planning for challenges. Fifth, sign a personal contract stating your goal, start date, how you will measure progress, your strategies and your target date. A SMART goal: 'I will be in bed by 11:30 p.m. at least 5 nights a week for the next 4 weeks.'","points":["Five steps in order","Health journal contents","SMART letters explained","Plan-of-action strategies and contract contents","A goal with a number and a time frame"]},{"id":"W2-TR01","ch":"W2-C7","src":"Textbook Ch 1, pp. 4, 16","added":"2026-10-26","q":"Explain the two differences the textbook draws between health and wellness, and use the example of a person with a family history of disease to show why behaviour still matters.","answer":"Health is the overall condition of body or mind and the presence or absence of illness or injury, and some of it is shaped by factors beyond your control, such as genes, age and the health care system. Wellness is optimal health and vitality, and it is largely determined by the decisions you make about how you live. A woman with a family history of breast cancer has a nonmodifiable risk factor. She can still lower her chance of developing and dying from the disease by controlling her weight, eating well, exercising and having regular mammograms. In common diseases, genes only raise risk, so behaviour can tip the balance.","points":["Health: condition of body or mind; partly beyond your control","Wellness: optimal health and vitality; largely your decisions","Family history is nonmodifiable","Behaviour can tip the balance (weight, diet, exercise, screening)"]},{"id":"W2-TR02","ch":"W2-C8","src":"Textbook Ch 1, pp. 22-24","added":"2026-10-26","q":"Define a lapse, a relapse and failure. Explain why the stages of change are drawn as a spiral, and describe the three steps for dealing with relapse.","answer":"A lapse is a single slip, and a relapse is a return to old habits. Failure is different: it means stopping before you reach your goal and never changing the target behaviour. People seldom move through the stages in a straight line; they slip back to earlier stages but are further along each time they renew their commitment, so the model is a spiral. To deal with a relapse, forgive yourself, give yourself credit for the progress you have made, and move on by learning from it. If relapses keep happening, go back to an earlier stage and re-evaluate your goals and strategy.","points":["Lapse = single slip; relapse = return to old habits","Failure = stopping and never changing","Spiral: cycle back but further along each time","Forgive yourself, give yourself credit, move on","Repeated relapse: return to an earlier stage and re-evaluate"]},{"id":"W2-TR03","ch":"W2-C8","src":"Textbook Ch 1, p. 27","added":"2026-10-26","q":"Your behaviour change program is grinding to a halt. Describe the sources of obstacles the textbook lists under 'Staying with it' and what to do about each.","answer":"First check social influences: if the people you counted on are not supportive, connect with others who are, and do not try to change other people. If motivation and commitment are low, you may need to wait until the behaviour bothers you more, or change your goal. If the technique is wrong, change it, for example an aerobics class instead of running, or push harder. If stress is temporary, wait until it passes; if it is ongoing, manage it and perhaps make it your target. Finally, stop the games: procrastinating (break the plan into small daily steps), rationalizing (making excuses) and blaming (taking your focus off the real problem).","points":["Social influences: find supportive people; focus on yourself","Motivation and commitment: wait or change the goal","Technique and effort: switch method or push harder","Stress: wait out temporary stress; manage ongoing stress","Procrastinating, rationalizing, blaming"]}],"explore":[{"fig":"prevention","title":"Levels of prevention","caption":"Figure 4.1 (AFMC Primer): each level of prevention acts at a different point along the course of disease, with a different target population.","items":{"primordial":{"label":"Primordial","text":"Modify social determinants. Targets the whole population through government legislation and fiscal measures, and community agencies' social programs.","src":"W2 Part 2, slides 6-7"},"primary":{"label":"Primary","text":"Limit exposures that lead to disease, through risk reduction. Targets at-risk groups through public health community action and family physician counselling.","src":"W2 Part 2, slides 6-7"},"secondary":{"label":"Secondary","text":"Detect and treat the pathological process early, when intervention can be more effective. Targets patients with disease, for example through public health screening.","src":"W2 Part 2, slides 6-7"},"tertiary":{"label":"Tertiary","text":"After treatment in the clinical phase, modify risk factors to avoid relapse and further deterioration. Targets recovering individuals through counselling, follow-up care and rehabilitation.","src":"W2 Part 2, slides 6-7"}}},{"fig":"ttm","title":"Stages of change","caption":"The transtheoretical model: to change a target behaviour you move through distinct stages. Relapse to a previous stage is a common part of the cycle (Fig 1.7).","items":{"pre":{"label":"Precontemplation","text":"No intention to change and no reason seen to make a change.","src":"W2 Part 3, slide 9"},"contemp":{"label":"Contemplation","text":"Intends to change the target behaviour within 6 months.","src":"W2 Part 3, slide 9"},"prep":{"label":"Preparation","text":"Plans to take action within a month, or is already taking small steps.","src":"W2 Part 3, slide 9"},"action":{"label":"Action","text":"Already making changes to the behaviour, which requires time and energy.","src":"W2 Part 3, slide 9"},"maint":{"label":"Maintenance","text":"Has kept the new, healthier lifestyle for at least 6 months.","src":"W2 Part 3, slide 9"},"term":{"label":"Termination","text":"The new behaviour is adopted.","src":"W2 Part 3, slide 9"}}}]},{"id":"W3","n":3,"added":"2026-10-26","title":"Health Research: Study Designs and Population Health Measures","short":"Study designs & measures","blurb":"How health research is designed, which designs give the strongest evidence, and how population health is measured.","topics":["Qualitative vs quantitative research, epidemiology, Bradford Hill","Observational designs and confounding","Cohort vs case-control: relative risk and odds ratio","RCTs, clinical trial phases, evidence pyramid","Mortality, morbidity, prevalence, incidence","PYLL, QALY, DALY, HALE"],"lectures":["Week 3 Part 1: Introduction to Health Research: Study Designs","Week 3 Part 2: Observational Studies","Week 3 Part 3: Experimental Studies & Evidence Pyramid","Week 3 Part 4: Population Health Measures"],"terms":[{"id":"W3-T-qualitative-research","term":"Qualitative research","def":"Research that studies particular instances, generates hypotheses and is generally inductive (works from the particular instance to the general conclusion). It answers 'why?' and 'what does it mean?' questions and captures rich, contextual, detailed information from a small number of participants. Sampling gives representative coverage of ideas or concepts.","ex":"Study question: What is the experience of being treated for breast cancer?","src":"W3 Part 1, slide 2","ch":"W3-C1","added":"2026-10-26"},{"id":"W3-T-quantitative-research","term":"Quantitative research","def":"Research that identifies general principles, tests hypotheses and is generally deductive (works from the general theory to the particular explanation). It answers 'what?', 'how much?' and 'how many?' and gives numeric estimates of frequency, severity and associations from a large number of participants. It uses counting, rigorous study designs and statistical analysis to minimize the role of human judgment.","ex":"Study question: Does treatment for breast cancer reduce mortality and improve quality of life?","src":"W3 Part 1, slides 2-3","ch":"W3-C1","added":"2026-10-26"},{"id":"W3-T-epidemiology","term":"Epidemiology","def":"The study of the occurrence of disease in populations, from the Greek 'epi' (upon) and 'demos' (people). It operates within public health and emphasizes prevention through reducing risk factors. It is a comparative discipline: it compares the risk of disease in people exposed to an agent with those not exposed. The ultimate goal is to establish whether a relationship is causal.","src":"W3 Part 1, slide 4","ch":"W3-C1","added":"2026-10-26"},{"id":"W3-T-austin-bradford-hill","term":"Austin Bradford Hill (1965) criteria","def":"In 1965 Austin Bradford Hill proposed criteria for assessing whether an epidemiological relationship is causal: strength of association (high relative risk), a graded response to a graded dose, consistency, a temporal relationship, and a plausible mechanism.","ex":"If people who smoke more cigarettes per day get more disease, that is a graded response to a graded dose.","src":"W3 Part 1, slide 5","ch":"W3-C1","added":"2026-10-26"},{"id":"W3-T-observational-study","term":"Observational study","def":"A study where the researcher observes what happens to people under exposure conditions outside the researcher's control. It is a non-randomized design, so confounders can make it hard to infer causation. Two types: descriptive and analytical.","src":"W3 Part 2, slides 3, 6","ch":"W3-C2","added":"2026-10-26"},{"id":"W3-T-confounding","term":"Confounding (confounder)","def":"Occurs when a third variable is associated with BOTH the exposure and the outcome being studied. If it is not taken into account, the relationship between the other two variables may be misinterpreted. Exposed and unexposed groups may differ on such factors, which may be the true cause of the outcome. The slides contrast a risk marker with a risk (or causal) factor.","ex":"Birth order 4th or higher seemed linked to Down syndrome. Maternal age over 35 is linked to both. Adjusting for maternal age made the birth order association disappear.","src":"W3 Part 2, slides 3-5","ch":"W3-C2","added":"2026-10-26"},{"id":"W3-T-descriptive-study","term":"Descriptive study","def":"An observational study that does NOT test hypotheses. It describes how things are and is useful for public health agencies and health care planning. Case studies and case series are also descriptive.","ex":"The National College Health Assessment survey of the health habits of post-secondary students.","src":"W3 Part 2, slides 6, 8","ch":"W3-C2","added":"2026-10-26"},{"id":"W3-T-analytical-study","term":"Analytical study","def":"An observational study that tests a hypothesis. It looks at an outcome variable (like CVD) in relation to an exposure variable (like smoking or obesity) to test a predicted association. Types: cross-sectional, cohort and case-control.","src":"W3 Part 2, slides 6, 12","ch":"W3-C2","added":"2026-10-26"},{"id":"W3-T-case-study","term":"Case study","def":"A descriptive study of one diseased individual, giving a detailed description of an uncommon disease. It provides timely or rare information, does not test a hypothesis and has no comparison or control group.","src":"W3 Part 2, slide 8","ch":"W3-C2","added":"2026-10-26"},{"id":"W3-T-case-series","term":"Case series","def":"A descriptive study of multiple occurrences of unusual cases that have similar characteristics. Investigators can calculate the frequency of symptoms or characteristics of people with the disease. Results may generate causal hypotheses but do NOT test one. Usually carried out by clinicians and published in medical journals. No comparison or control group.","ex":"Hymes et al. (1981): eight cases of Kaposi's sarcoma.","src":"W3 Part 2, slides 8-10","ch":"W3-C2","added":"2026-10-26"},{"id":"W3-T-hymes-1981","term":"Hymes et al. (1981)","def":"Case series published in the Lancet in 1981: 'Kaposi's sarcoma in homosexual men: a report of eight cases'. The lecture's example of a case series; the slide asks students to consider its historical relevance.","src":"W3 Part 2, slide 9","ch":"W3-C2","added":"2026-10-26"},{"id":"W3-T-wakefield-1998","term":"Wakefield et al. (1998) MMR case series","def":"Lancet case series of 12 children with neuropsychiatric diagnoses (mostly autism) where parents or a pediatrician named the MMR vaccine as the cause, with symptoms appearing from 24 hours to weeks later. The slide calls it one of the most infamous case series published.","ex":"Like every case series, it had no control group and could not test whether MMR causes autism.","src":"W3 Part 2, slides 8, 10","ch":"W3-C2","added":"2026-10-26"},{"id":"W3-T-cross-sectional-study","term":"Cross-sectional study","def":"An analytical observational survey in which the purpose of the analysis is to record associations between variables, rather than merely to report how often they occur (that would be descriptive). On the design tree, sampling is based on neither exposure nor outcome.","ex":"Bobak et al. (2003), beer and obesity: in men, waist-to-hip ratio was related to beer intake, but the association became insignificant when other risk factors were controlled.","src":"W3 Part 2, slides 11-13","ch":"W3-C2","added":"2026-10-26"},{"id":"W3-T-ecological-study","term":"Ecological study","def":"A study that measures variables at the level of populations rather than individuals. Advantages: can give powerful clues when comparing large populations, and can use data already available, like government statistics. Disadvantage: cannot prove cause and effect, because the two factors must be studied in individuals.","ex":"Colli and Colli (2006): prostate cancer mortality vs per-capita sugar consumption in 71 countries. Also the diet-cancer correlation, and following migrating populations to compare cancer rates.","src":"W3 Part 2, slides 27-28","ch":"W3-C2","added":"2026-10-26"},{"id":"W3-T-cohort-study","term":"Cohort study","def":"An analytical observational study, also called longitudinal or prospective. It selects a population without the disease of interest, groups people by exposure (e.g. smokers vs non-smokers) and follows them over time, sometimes years. The number of new (incident) cases is recorded and compared between exposure groups. Sampling is based on exposure.","ex":"The Framingham Heart Study.","src":"W3 Part 2, slides 15-16","ch":"W3-C3","added":"2026-10-26"},{"id":"W3-T-framingham-heart-study","term":"Framingham Heart Study","def":"A famous cohort study started in 1948 in Framingham, Massachusetts, on risk factors for coronary heart disease (exercise, tobacco, blood pressure, cholesterol, obesity, etc.). Data include two generations after the initial families studied, with over 1000 publications.","ex":"Hubert et al. (1983) followed 5209 men and women of the original cohort for 26 years and found obesity was an independent risk factor for cardiovascular disease.","src":"W3 Part 2, slides 19-20","ch":"W3-C3","added":"2026-10-26"},{"id":"W3-T-relative-risk","term":"Relative risk (RR)","def":"Also called the risk ratio; used in cohort studies. Risk in the exposed group is a/(a+b) (the incidence); risk in the unexposed is c/(c+d). RR = [a/(a+b)] / [c/(c+d)]. An RR greater than 1.0 means a person who was exposed has a greater chance of becoming diseased than a person who was not.","ex":"Exposed: 40 of 400 get the disease (0.10). Unexposed: 15 of 600 (0.025). RR = 0.10 / 0.025 = 4.0.","src":"W3 Part 2, slide 17","ch":"W3-C3","added":"2026-10-26"},{"id":"W3-T-case-control-study","term":"Case-control study","def":"An analytical observational study, also called retrospective. The health profiles of a 'case' group (has the disease or outcome) are compared with a control group (without it) selected to be as similar as possible to the cases (similar spread of ages, sex, etc.). Researchers review records back in time for exposure. Sampling is based on outcome.","ex":"Pan et al. (2004): 21,022 cancer cases and 5,039 controls in Canada, looking at obesity.","src":"W3 Part 2, slides 21-22, 25","ch":"W3-C3","added":"2026-10-26"},{"id":"W3-T-odds-ratio","term":"Odds ratio (OR)","def":"Used in case-control studies. Odds that a case was exposed = a/c; odds that a control was exposed = b/d. OR = (a/c)/(b/d) = ad/bc. An OR greater than 1.0 means diseased people had a greater chance of having been exposed to the risk factor than controls. The OR can approximate the RR when the disease is rare.","ex":"Pan et al. (2004): obese people had an odds ratio of 1.34 for overall cancer and 2.74 for kidney cancer, compared with BMI under 25.","src":"W3 Part 2, slides 23, 25","ch":"W3-C3","added":"2026-10-26"},{"id":"W3-T-recall-bias","term":"Memory and recall bias","def":"A data quality problem of retrospective (case-control) studies: they rely on past information, so they have more problems with data quality, including memory and recall bias.","src":"W3 Part 2, slide 24","ch":"W3-C3","added":"2026-10-26"},{"id":"W3-T-experimental-study","term":"Experimental (interventional) study","def":"A study that tests the effects of a treatment (medical or surgical procedure, new drug, lifestyle change, dietary change) where the researcher controls the intervention: its timing, dose and intensity. The test question: is the investigator controlling the primary exposure?","ex":"A study in which your diet is prescribed and provided and you keep a food diary is experimental. If you choose what you eat and only your weight is monitored, it is observational.","src":"W3 Part 3, slides 3-4","ch":"W3-C4","added":"2026-10-26"},{"id":"W3-T-randomized-controlled-trial","term":"Randomized controlled trial (RCT)","def":"The 'gold standard' for evaluation. State the hypothesis; assemble participants as similar as possible (with free and informed consent); randomly assign them to the experimental group or a control group, which may get no treatment, the conventional treatment or a placebo; give the intervention, preferably double-blind; and monitor outcomes at a pre-determined time (e.g. mortality, functional health status, physiological or biochemical measures).","ex":"Sacher et al. (2010): 116 obese children randomly assigned to the MEND program or a waiting list control.","src":"W3 Part 3, slides 6-8, 12","ch":"W3-C4","added":"2026-10-26"},{"id":"W3-T-randomization","term":"Randomization","def":"Random assignment of participants to study groups. Its advantage is that confounding factors, like genetic characteristics, are likely equally represented in each group. Assuming no systematic error or bias, the only thing that should differ between two randomly assigned groups is the intervention.","src":"W3 Part 3, slide 9","ch":"W3-C4","added":"2026-10-26"},{"id":"W3-T-null-hypothesis","term":"Null hypothesis","def":"The hypothesis that the experimental treatment had no effect. If the probability (p) that the observed difference is due to chance alone is less than 1 in 20 (p ≤ 0.05), the null hypothesis is disproved and the observed difference is significant.","src":"W3 Part 3, slide 10","ch":"W3-C4","added":"2026-10-26"},{"id":"W3-T-rct-ethics","term":"Ethics of RCTs","def":"Tension between two principles: it is unethical to deny a patient access to an effective treatment, and it is unethical to adopt a new treatment without rigorous testing to prove efficacy. An RCT should only be used when there is 'genuine uncertainty' about whether the treatment is superior. It is also unethical to continue a trial once the treatment is found to be obviously effective or obviously dangerous.","src":"W3 Part 3, slide 11","ch":"W3-C4","added":"2026-10-26"},{"id":"W3-T-clinical-trial-phases","term":"Clinical trial phases (I to IV)","def":"Medications and vaccines are tested in phases before approval by regulators (Health Products and Food Branch (HPFB) of Health Canada; FDA in the US). Phase I: small group, side effects and safe dosage. Phase II: larger groups, efficacy and safety (usually not randomized). Phase III: series of RCTs to confirm efficacy, monitor side effects and compare to other common treatments. Phase IV: after approval and public use, post-marketing surveillance of efficacy and side effects (not RCTs).","src":"W3 Part 3, slide 13","ch":"W3-C4","added":"2026-10-26"},{"id":"W3-T-evidence-pyramid","term":"Evidence (study design) pyramid","def":"Ranks study designs by strength of evidence, which increases toward the top. Top to bottom: meta-analysis, systematic review, practice guideline, randomized control trial, cohort study, case control study, case reports/series.","src":"W3 Part 3, slides 14, 21","ch":"W3-C5","added":"2026-10-26"},{"id":"W3-T-practice-guideline","term":"Practice guideline","def":"Also called an evidence-based or clinical guideline. A statement by a panel of experts after an extensive review of the literature, created by professional associations, government agencies or public/private organizations. It gives guidance for integrating information into clinical practice.","ex":"Canadian Task Force on Preventive Health Care (CTFPHC) guideline on prevention and management of overweight and obesity in children and youth in primary health care.","src":"W3 Part 3, slides 15-16","ch":"W3-C5","added":"2026-10-26"},{"id":"W3-T-systematic-review","term":"Systematic review","def":"A document written by a panel that gives a comprehensive review of all relevant studies on a particular health topic or question, with stringent selection criteria for including studies. Cochrane Database systematic reviews include a plain language summary.","ex":"Kothandan (2014): school-based vs family-based interventions for childhood obesity; study quality was appraised with the CASP tool.","src":"W3 Part 3, slides 17-18","ch":"W3-C5","added":"2026-10-26"},{"id":"W3-T-meta-analysis","term":"Meta-analysis","def":"A method to systematically combine data from different studies to develop a single conclusion. It can establish statistical significance when studies have conflicting results. Combining data from several RCTs is the highest level of evidence. Cochrane databases also contain meta-analyses.","ex":"Ho et al. (2012) pooled studies comparing lifestyle interventions with no-treatment or wait-list controls for child obesity.","src":"W3 Part 3, slides 19-20","ch":"W3-C5","added":"2026-10-26"},{"id":"W3-T-five-ds","term":"The five Ds","def":"The scope of health measures: death, disease, disability, discomfort and distress. Measures range from objective and numerical to subjective and qualitative.","src":"W3 Part 4, slide 2","ch":"W3-C6","added":"2026-10-26"},{"id":"W3-T-aggregate-measures","term":"Aggregate measures","def":"Population-level indicators made of combined data from individual people, summarized at regional or national levels.","ex":"Prevalence of obesity.","src":"W3 Part 4, slide 3","ch":"W3-C6","added":"2026-10-26"},{"id":"W3-T-environmental-indicators","term":"Environmental indicators","def":"Population-level indicators of factors external to the individual, such as air or water quality. They can also be social characteristics, and may have analogues at the individual level.","src":"W3 Part 4, slide 3","ch":"W3-C6","added":"2026-10-26"},{"id":"W3-T-global-indicators","term":"Global indicators","def":"Population-level indicators with no analogues at the individual level.","ex":"Healthy public policy; social equity in access to health care.","src":"W3 Part 4, slide 3","ch":"W3-C6","added":"2026-10-26"},{"id":"W3-T-mortality","term":"Mortality and mortality rate","def":"Mortality is the state of being mortal, or the incidence of death (number of deaths) in a population. The mortality rate is the rate at which members of a population die during a specific period: numerator = number of people dying during the period; denominator = size of the population at the middle of the period. International agencies use mortality (e.g. death rates per 1000) to compare countries.","ex":"Canada, 2020: malignant neoplasms caused 26.4% of all deaths and diseases of the heart 17.5%.","src":"W3 Part 4, slides 2, 5-6","ch":"W3-C6","added":"2026-10-26"},{"id":"W3-T-morbidity","term":"Morbidity","def":"The disease state of an individual, or the incidence of illness in a population. Measured with prevalence and incidence.","src":"W3 Part 4, slide 5","ch":"W3-C6","added":"2026-10-26"},{"id":"W3-T-infant-mortality-rate","term":"Infant mortality rate","def":"Deaths among children under 1 year old divided by the number of live births in the same year, times 1,000.","ex":"In Canada from 1971 to 1996, infant mortality fell in every income quintile, but the poorest quintile stayed highest and the richest lowest (Wilkins, Statistics Canada, 2003).","src":"W3 Part 4, slide 7","ch":"W3-C6","added":"2026-10-26"},{"id":"W3-T-life-expectancy","term":"Life expectancy","def":"An estimate of the expected number of years to be lived by a newborn, based on age-specific mortality rates. A summary indicator of health that can be compared across countries.","src":"W3 Part 4, slide 8","ch":"W3-C6","added":"2026-10-26"},{"id":"W3-T-prevalence","term":"Prevalence","def":"A measure of disease state: the number of people with a given characteristic (commonly a disease or risk factor) at a given time, divided by the population at risk of having that condition. Good for assessing the burden of chronic disease. It answers: how many people are sick?","ex":"1,500 of 10,000 adults have asthma on a given day: prevalence = 15%.","src":"W3 Part 4, slide 9","ch":"W3-C6","added":"2026-10-26"},{"id":"W3-T-incidence","term":"Incidence","def":"A measure of the speed at which new cases of disease (or deaths) arise in a population during a fixed time: the number of new cases in a specified time divided by the number of people in the population at risk. Useful for communicating risk. It can be measured in a cohort study and used to calculate a relative risk. It answers: how many people get sick?","ex":"400 new cases in one year among 8,000 people at risk: incidence = 5% per year.","src":"W3 Part 4, slide 10","ch":"W3-C6","added":"2026-10-26"},{"id":"W3-T-health-measurement-scales","term":"Health measurement scales","def":"More subjective indicators of health. They are used because morbidity and mortality measures only apply to serious conditions, give no indication of positive aspects of health, and do not show level of function.","ex":"Short-form 36 Survey (SF-36); Canadian Index of Wellbeing.","src":"W3 Part 4, slide 11","ch":"W3-C6","added":"2026-10-26"},{"id":"W3-T-pyll","term":"Potential years of life lost (PYLL)","def":"One way to judge diseases by their impact on society: rank them by the total potential years of life lost due to each. Priorities based on PYLL will differ from priorities based on simple mortality rates.","ex":"Canada, 2004 to 2007: cancer ranked first on both measures, but unintentional injury and suicide had PYLL bars longer than their mortality-rate bars.","src":"W3 Part 4, slides 12-13","ch":"W3-C6","added":"2026-10-26"},{"id":"W3-T-qaly","term":"Quality-Adjusted Life Years (QALYs)","def":"A measure that combines morbidity and mortality outcomes by adjusting years of life for their quality. Example from the slides: one year after a disabling stroke might be worth 0.8 normal years.","ex":"Twins Bob and Bill both die at 65. Bob had a stroke at 55. Quality-adjusting his last 10 years: 10 - (10 x 0.8) = 2 years lost.","src":"W3 Part 4, slides 12, 15","ch":"W3-C6","added":"2026-10-26"},{"id":"W3-T-daly","term":"Disability-Adjusted Life Years (DALYs)","def":"Listed with QALYs and HALE as a disease impact measure that combines morbidity and mortality outcomes.","src":"W3 Part 4, slides 12, 14","ch":"W3-C6","added":"2026-10-26"},{"id":"W3-T-hale","term":"Health-Adjusted Life Expectancy (HALE)","def":"An indicator of the average number of years an individual is expected to live in a healthy state, so it reflects both quality and quantity of life. HALE in Canada (2012) was reported by SES, by chronic disease (diabetes and cancer) and by chronic conditions (hypertension).","src":"W3 Part 4, slide 16","ch":"W3-C6","added":"2026-10-26"}],"chapters":[{"id":"W3-C1","title":"Research basics and causation","src":"W3 Part 1, slides 2-6","blurb":"Qualitative vs quantitative research, epidemiology, Bradford Hill criteria and the design tree.","learn":"Health research is <b>qualitative</b> or <b>quantitative</b>. Qualitative research studies particular instances, generates hypotheses, works inductively and answers 'why?' with rich detail from a few people. Quantitative research looks for general principles, tests hypotheses, works deductively and gives numbers (frequency, severity, associations) from many people, using counting, rigorous designs and statistics.<br><br><b>Epidemiology</b> is the study of the occurrence of disease in populations ('epi' upon, 'demos' people). It compares the risk of disease in people exposed to an agent with people not exposed, and tries to establish whether the relationship is causal.<br><br><b>Austin Bradford Hill (1965)</b> listed criteria for causation: strength of association (high relative risk), a graded response to a graded dose, consistency, a temporal relationship and a plausible mechanism.<br><br>The design tree starts with one question: did the investigator assign the exposure? Yes: experimental. No: observational.","steps":[{"id":"W3-C1-S1","type":"compare","src":"W3 Part 1, slide 2","added":"2026-10-26","prompt":"Decide whether each study is qualitative or quantitative.","a":{"name":"Qualitative research","points":["Studies particular instances","Generates hypotheses","Inductive: particular to general","Answers 'why?' and 'what does it mean?'","Rich detail from a small number of participants"]},"b":{"name":"Quantitative research","points":["Identifies general principles","Tests hypotheses","Deductive: general theory to particular explanation","Answers 'what?', 'how much?', 'how many?'","Numeric estimates from a large number of participants"]},"scenarios":[["In-depth interviews with 12 women about what it is like to be treated for breast cancer.",0,"Studies particular experiences and asks what they mean: qualitative."],["A survey of 5,000 adults to estimate how many smoke daily.",1,"Asks 'how many?' with a large sample: quantitative."],["A trial testing whether a breast cancer treatment reduces mortality.",1,"Tests a hypothesis and measures 'how much': quantitative."],["Focus groups exploring why students skip breakfast, used to come up with new hypotheses.",0,"Generates hypotheses from rich detail: qualitative."],["Statistical analysis of the association between obesity and heart disease in 5,000 people.",1,"Looks for statistical associations between variables: quantitative."]]},{"id":"W3-C1-S2","type":"match","src":"W3 Part 1, slide 5","added":"2026-10-26","prompt":"Match each Bradford Hill criterion to an example of it.","pairs":[["Strength of association","Smokers have a relative risk of lung disease far above 1.0"],["Graded response to a graded dose","The more cigarettes per day, the more disease"],["Consistency","The same link shows up across different studies"],["Temporal relationship","The exposure comes before the disease"],["Plausible mechanism","There is a believable biological explanation for how exposure causes disease"]]},{"id":"W3-C1-S3","type":"label","fig":"designs","src":"W3 Part 1, slide 6","added":"2026-10-26","prompt":"Drag each study design onto the decision tree. Start at the top: did the investigator assign exposures?"},{"id":"W3-C1-S4","type":"mcq","src":"W3 Part 1, slide 6","ch":"W3-C1","added":"2026-10-26","case":"Researchers want to know if a new exercise program lowers blood pressure. They decide who joins the program and who does not, and they set how often and how hard each person exercises.","q":"Where does this study start on the design tree?","opts":[["Experimental study, because the investigator assigned the exposure",true,"The first question is whether the investigator assigned exposures. Here they did, so it is experimental."],["Observational study, because blood pressure is only measured",false,"Measuring an outcome does not make a study observational. The question is who controls the exposure."],["Descriptive study, because no hypothesis is stated",false,"A hypothesis is being tested (does the program lower blood pressure?), and the exposure is assigned."],["Cohort study, because participants are followed over time",false,"Cohorts are observational: people are grouped by exposures they chose, not ones the researcher assigned."]]}],"summary":"Qualitative research generates hypotheses; quantitative research tests them. Epidemiology compares exposed and unexposed groups, and the Bradford Hill criteria help judge causation."},{"id":"W3-C2","title":"Observational studies and confounding","src":"W3 Part 2, slides 2-14, 27-28","blurb":"Confounding, descriptive vs analytical designs, case studies and series, cross-sectional and ecological studies.","learn":"In an <b>observational study</b> the researcher watches what happens under exposures they do not control. Groups are not randomized, so exposed and unexposed people may differ on other factors that are the true cause. A <b>confounder</b> is a third variable linked to both the exposure and the outcome. Example: birth order 4th or higher seemed linked to Down syndrome, but higher birth order goes with maternal age over 35. After adjusting for maternal age, the link disappeared.<br><br><b>Descriptive</b> studies do not test hypotheses; they describe how things are. A <b>case study</b> looks at one patient; a <b>case series</b> at several similar unusual cases (Hymes 1981; Wakefield 1998). Neither has a control group, so they can only generate hypotheses.<br><br><b>Analytical</b> studies test a hypothesis about an exposure and an outcome. A <b>cross-sectional</b> study records associations between variables. An <b>ecological</b> study measures whole populations, not individuals, so it cannot prove cause and effect.","steps":[{"id":"W3-C2-S1","type":"mcq","src":"W3 Part 2, slides 4-5","ch":"W3-C2","added":"2026-10-26","case":"A study finds that people who carry matches or lighters have more lung cancer. People who smoke are more likely to carry matches, and smoking is linked to lung cancer.","q":"In this study, what is smoking?","opts":[["The outcome being studied",false,"The outcome is lung cancer."],["A confounder",true,"Smoking is associated with both the exposure (carrying matches) and the outcome (lung cancer). Ignoring it would make carrying matches look like a cause."],["The exposure being studied",false,"The exposure under study is carrying matches. Smoking is the third variable."],["A temporal relationship",false,"A temporal relationship is a Bradford Hill criterion about timing, not a variable."]]},{"id":"W3-C2-S2","type":"sort","src":"W3 Part 2, slides 6, 8, 12","added":"2026-10-26","prompt":"Sort each study into descriptive (no hypothesis tested) or analytical (tests a hypothesis).","bins":["Descriptive","Analytical"],"items":[["A detailed report of one patient with a rare disease",0,"A case study describes one individual and tests nothing."],["The National College Health Assessment survey of students' health habits",0,"The slides use it as the descriptive example: it describes how things are."],["A report of eight men with Kaposi's sarcoma",0,"A case series. It may generate hypotheses but does not test one."],["A survey testing whether beer intake is associated with waist-to-hip ratio",1,"A cross-sectional study recording an association between variables."],["Following smokers and non-smokers for 20 years to compare heart disease",1,"A cohort study testing an exposure-outcome hypothesis."],["Comparing past exposures of people with and without a cancer",1,"A case-control study testing an association."],["Counting how often each symptom appears in 12 unusual cases",0,"Case series can calculate the frequency of symptoms but still do not test a hypothesis."]]},{"id":"W3-C2-S3","type":"table","src":"W3 Part 2, slide 10","added":"2026-10-26","prompt":"This table is from one of the most infamous case series ever published.","caption":"Table 1: Neuropsychiatric diagnosis and interval post MMR vaccination. Adapted from Table 2 in Wakefield et al. (1998), Lancet 351:637-641.","head":["Child","Behavioral Diagnosis","Causal agent (identified by parents or pediatrician)","Interval from exposure to symptoms"],"rows":[["1","Autism","MMR","1 week"],["2","Autism","MMR","2 weeks"],["3","Autism","MMR","48 hours"],["4","Autism? Disintegrative disorder?","MMR","Dramatic deterioration immediately after MMR booster at 4.5 years"],["5","Autism","None, but MMR at 16 months","Self-injurious behavior started at 18 months"],["6","Autism","MMR","1 week"],["7","Autism","MMR","24 hours"],["8","Post-vaccinial encephalitis?","MMR","2 weeks"],["9","Autistic spectrum disorder","Recurrent inner-ear infections","1 week (MMR 2 months previously)"],["10","Post-viral encephalitis?","Measles (previously vaccinated with MMR)","24 hours"],["11","Autism","MMR","1 week"],["12","Autism","None, but MMR at 15 months","Developmental deterioration noted at 16 months"]],"qs":[{"id":"W3-C2-S3-Q1","type":"mcq","src":"W3 Part 2, slides 8, 10","ch":"W3-C2","added":"2026-10-26","q":"What is the main reason this study cannot show that MMR causes autism?","opts":[["It has no comparison or control group of children",true,"Case series do not include a control group, so there is nothing to compare these 12 children with. They can generate a hypothesis but not test it."],["It used a sample that was too large",false,"Twelve children is a small sample. Size is not the main design problem named on the slides."],["It measured variables at the population level",false,"That describes an ecological study. This table reports individual children."],["Participants were randomized to receive MMR",false,"No one was randomized. The children were described after the fact."]]},{"id":"W3-C2-S3-Q2","type":"mcq","src":"W3 Part 2, slide 8","ch":"W3-C2","added":"2026-10-26","q":"Who identified the 'causal agent' in the table?","opts":[["Parents or a pediatrician",true,"The column heading says the causal agent was identified by parents or pediatrician, not tested by the researchers."],["A randomized trial",false,"No trial was done. The table only reports what was believed about each child."],["A meta-analysis of earlier studies",false,"Nothing was pooled. This is a single case series."],["A matched control group",false,"There was no control group."]]}]},{"id":"W3-C2-S4","type":"mcq","src":"W3 Part 2, slides 27-28","ch":"W3-C2","added":"2026-10-26","case":"Researchers plot per-capita sugar consumption against age-adjusted prostate cancer mortality for 71 countries. Countries with higher sugar intake tend to have higher prostate cancer mortality.","q":"Which design is this, and what is its main limit?","opts":[["Cross-sectional study; it cannot show associations",false,"Cross-sectional studies do record associations, and they use data on individuals, not country averages."],["Ecological study; it cannot prove cause and effect in individuals",true,"Each data point is a country, so variables are measured at the population level. Cause and effect needs the two factors studied in individuals."],["Cohort study; it is expensive to follow countries over time",false,"No group of disease-free people is followed. Country-level data are compared at once."],["Case series; it has no control group",false,"A case series describes individual patients, not country averages."]]}],"summary":"Observational studies can be confounded because groups are not randomized. Descriptive studies (including case studies and series) describe; analytical studies test hypotheses."},{"id":"W3-C3","title":"Cohort and case-control studies","src":"W3 Part 2, slides 15-26","blurb":"Prospective vs retrospective designs, relative risk and odds ratio with 2x2 tables.","learn":"A <b>cohort study</b> (longitudinal, prospective) starts with people free of the disease, groups them by exposure and follows them over time, counting new (incident) cases in each group. Cohorts use the <b>relative risk</b>: RR = [a/(a+b)] / [c/(c+d)]. RR above 1.0 means the exposed have a greater chance of disease.<br><br>A <b>case-control study</b> (retrospective) starts with the outcome: cases with the disease and similar controls without it. It looks back at past exposure and uses the <b>odds ratio</b>: OR = (a/c)/(b/d) = ad/bc. OR above 1.0 means cases were more likely to have been exposed. OR approximates RR when the disease is rare.<br><br>In the 2x2 table, a = exposed with disease, b = exposed without, c = unexposed with disease, d = unexposed without.<br><br>Cohort: clear time order, fewer confounding problems, many diseases from one cohort, but long and expensive. Case-control: faster, good for rare diseases, but has memory and recall bias.","steps":[{"id":"W3-C3-S1","type":"compare","src":"W3 Part 2, slides 15-26","added":"2026-10-26","prompt":"Which design fits each situation?","a":{"name":"Cohort (prospective)","points":["Groups classified by exposure","Starts with people without the disease","Follows forward in time","Measures incidence and relative risk","Clear temporal relationship; expensive"]},"b":{"name":"Case-control (retrospective)","points":["Groups identified by outcome","Starts with cases and similar controls","Looks back at past exposure","Uses the odds ratio","Good for rare diseases; recall bias"]},"scenarios":[["300 people with lung cancer and 300 similar people without it are asked about past smoking.",1,"Groups are chosen by outcome and exposure is recalled: case-control."],["5,000 disease-free adults record their smoking status and are followed for 20 years.",0,"Groups are defined by exposure and followed forward: cohort."],["A team needs quick results on a very rare cancer.",1,"Case-control studies are good for rare diseases and take less time."],["Researchers must show clearly that the exposure came before the disease.",0,"Cohort studies can clearly establish the temporal relationship."],["One group of people will be used to study heart disease, stroke and diabetes.",0,"Many different diseases can be studied using the same cohort."]]},{"id":"W3-C3-S2","type":"mcq","src":"W3 Part 2, slide 17","ch":"W3-C3","added":"2026-10-26","case":"A cohort study follows 400 factory workers exposed to a solvent and 600 unexposed workers for 10 years. 40 exposed workers and 15 unexposed workers develop liver disease.","q":"What is the relative risk of liver disease for exposed workers?","opts":[["2.7",false,"This is 40/15, the ratio of case counts. RR compares risks, so divide each count by its group size first."],["0.25",false,"This is the inverse (0.025/0.10). The exposed risk goes on top."],["4.0",true,"Risk exposed = 40/400 = 0.10. Risk unexposed = 15/600 = 0.025. RR = 0.10 / 0.025 = 4.0."],["0.075",false,"This is the difference in risk (0.10 - 0.025), not the ratio."]]},{"id":"W3-C3-S3","type":"mcq","src":"W3 Part 2, slide 23","ch":"W3-C3","added":"2026-10-26","case":"A case-control study has 80 cases with a disease and 120 controls without it. 48 cases and 36 controls were exposed. So a = 48, b = 36, c = 32, d = 84.","q":"What is the odds ratio?","opts":[["3.5",true,"OR = ad/bc = (48 x 84) / (36 x 32) = 4032 / 1152 = 3.5."],["1.3",false,"This is 48/36, cases exposed over controls exposed. The OR needs the cross-products ad/bc."],["0.29",false,"This is bc/ad, the inverse. The OR is ad/bc."],["2.0",false,"This is (48/80)/(36/120) = 0.6/0.3, a ratio of proportions exposed, not the odds ratio."]]},{"id":"W3-C3-S4","type":"table","src":"W3 Part 2, slide 25","added":"2026-10-26","prompt":"Read the odds ratios from Pan et al. (2004).","caption":"Pan et al. (2004), Association of obesity and cancer risk in Canada: obese (BMI 30 or more) vs BMI under 25, multivariable adjusted odds ratios. 21,022 incident cases of 19 cancer types and 5,039 controls aged 20 to 76, 1994 to 1997.","head":["Cancer","Odds ratio","95% CI"],"rows":[["Overall cancer","1.34","1.22, 1.48"],["Non-Hodgkin's lymphoma","1.46","1.24, 1.72"],["Leukemia","1.61","1.32, 1.96"],["Multiple myeloma","2.06","1.46, 2.89"],["Kidney","2.74","2.30, 3.25"],["Colon","1.93","1.61, 2.31"],["Rectum","1.65","1.36, 2.00"],["Pancreas","1.51","1.19, 1.92"],["Breast (postmenopausal women)","1.66","1.33, 2.06"],["Ovary","1.95","1.44, 2.64"],["Prostate","1.27","1.09, 1.47"]],"qs":[{"id":"W3-C3-S4-Q1","type":"mcq","src":"W3 Part 2, slide 25","ch":"W3-C3","added":"2026-10-26","q":"Which cancer had the strongest association with obesity in this study?","opts":[["Multiple myeloma",false,"OR 2.06 is high, but kidney is higher."],["Kidney",true,"Kidney cancer has the highest odds ratio, 2.74."],["Overall cancer",false,"OR 1.34 is one of the lowest in the table."],["Ovary",false,"OR 1.95 is lower than kidney's 2.74."]]},{"id":"W3-C3-S4-Q2","type":"mcq","src":"W3 Part 2, slides 21-23","ch":"W3-C3","added":"2026-10-26","q":"Why does this study report odds ratios instead of relative risks?","opts":[["It is a case-control study, which starts from people with and without cancer",true,"Groups were chosen by outcome (cancer cases vs controls), so the odds of past exposure are compared with an odds ratio."],["It is a cohort study that followed obese people forward",false,"A cohort would report relative risk. This study started with incident cancer cases."],["It is an RCT, and RCTs always use odds ratios",false,"No one was randomly assigned to be obese."],["It is an ecological study of provinces",false,"Data are on individual cases and controls, not population averages."]]}]}],"summary":"Cohort studies sample on exposure, follow forward and give relative risk. Case-control studies sample on outcome, look back and give the odds ratio."},{"id":"W3-C4","title":"Experimental studies and RCTs","src":"W3 Part 3, slides 2-13","blurb":"Who controls the exposure, randomization, blinding, the null hypothesis, ethics and trial phases.","learn":"In an <b>experimental (interventional)</b> study the researcher controls the exposure: its timing, dose and intensity. Ask: is the investigator controlling the primary exposure?<br><br>The <b>randomized controlled trial (RCT)</b> is the 'gold standard'. State the hypothesis; recruit similar participants with free and informed consent; randomly assign them to the experimental group or a control group (no treatment, conventional treatment or placebo); give the intervention, preferably double-blind; measure outcomes at a set time. Randomization makes it likely that confounders, like genetic traits, are spread equally between groups.<br><br>The <b>null hypothesis</b> says the treatment had no effect. If p ≤ 0.05 (less than 1 in 20), the null is disproved and the difference is significant. An RCT is ethical only when there is real uncertainty about which treatment is better, and must stop if the treatment is obviously effective or dangerous.<br><br>Drugs and vaccines go through Phases I to IV, with approval by Health Canada's HPFB or the US FDA.","steps":[{"id":"W3-C4-S1","type":"sort","src":"W3 Part 3, slides 3-4","added":"2026-10-26","prompt":"Is the investigator controlling the primary exposure? Sort each study.","bins":["Experimental","Observational"],"items":[["Your diet is prescribed and provided, and you keep a food diary",0,"The slides' own example: the researcher controls the diet."],["You choose what you eat and your weight is monitored",1,"The slides' own example: you choose the exposure, so it is observational."],["Patients are randomly assigned to a new drug or a placebo",0,"The researcher assigns the drug: an RCT."],["116 obese children are randomly assigned to the MEND program or a waiting list",0,"Sacher et al. (2010) is the lecture's RCT example."],["Framingham residents' blood pressure is recorded and they are followed for decades",1,"The researchers do not set anyone's blood pressure: a cohort study."],["People with and without cancer are asked about their past diets",1,"A case-control study: exposure is recalled, not assigned."],["A researcher sets the dose and timing of a walking program, without random allocation",0,"The investigator assigns the exposure, so it is experimental: a non-randomized design."]]},{"id":"W3-C4-S2","type":"order","src":"W3 Part 3, slide 13","added":"2026-10-26","prompt":"Put the clinical trial phases for a new drug in order.","items":["Tested in a small group of people to examine side effects and safe dosage","Tested on larger groups with a focus on efficacy and safety, usually not randomized","Series of RCTs to confirm efficacy, monitor side effects and compare with other common treatments","After approval and public use, continued monitoring for efficacy and side effects (post-marketing surveillance)"],"why":"Phase I: small group, safety and dose. Phase II: larger groups, efficacy and safety. Phase III: series of RCTs. Phase IV: post-marketing surveillance after approval by HPFB (Health Canada) or the FDA."},{"id":"W3-C4-S3","type":"mcq","src":"W3 Part 3, slide 10","ch":"W3-C4","added":"2026-10-26","case":"In an RCT of a new blood pressure drug, the drug group's blood pressure fell more than the placebo group's. The probability that a difference this large is due to chance alone is p = 0.03.","q":"What should the researchers conclude?","opts":[["The null hypothesis is supported, because p is small",false,"A small p means the result is unlikely under the null hypothesis, so the null is disproved, not supported."],["The null hypothesis is disproved and the difference is significant",true,"p = 0.03 is below 0.05 (less than 1 in 20), so the difference is significant."],["The result is not significant, because p must be below 0.01",false,"The cut-off on the slides is p ≤ 0.05."],["The trial must be stopped for ethical reasons",false,"A trial stops if the treatment is obviously effective or dangerous. A single significant result does not say that."]]},{"id":"W3-C4-S4","type":"mcq","src":"W3 Part 3, slide 11","ch":"W3-C4","added":"2026-10-26","case":"Halfway through an RCT, the data show that patients on the new treatment are having far more serious harms than the control group.","q":"What do the ethics of RCTs require?","opts":[["Finish the trial so the results are complete",false,"The slides say it is unethical to continue once a treatment is obviously dangerous."],["Switch the control group to the new treatment",false,"That would expose more people to a treatment shown to be harmful."],["Stop the trial, because the treatment is obviously dangerous",true,"It is unethical to continue a trial when the treatment is found to be obviously effective or obviously dangerous."],["Remove blinding but keep going",false,"Unblinding does not fix the harm. The trial should stop."]]}],"summary":"Experimental studies assign the exposure. RCTs use randomization so the intervention is the only systematic difference, and test the null hypothesis at p ≤ 0.05."},{"id":"W3-C5","title":"The evidence pyramid","src":"W3 Part 3, slides 14-21","blurb":"Ranking designs by strength of evidence; practice guidelines, systematic reviews and meta-analyses.","learn":"The <b>evidence pyramid</b> ranks study designs. Evidence gets stronger toward the top. From the base up: case reports/series, case control study, cohort study, randomized control trial, practice guideline, systematic review, and meta-analysis at the top.<br><br>A <b>practice guideline</b> (evidence-based or clinical guideline) is a statement by an expert panel, after an extensive literature review, that guides clinical practice. Example: the Canadian Task Force on Preventive Health Care guideline on overweight and obesity in children and youth.<br><br>A <b>systematic review</b> is a panel's comprehensive review of all relevant studies on one question, with stringent selection criteria. A <b>meta-analysis</b> statistically combines data from different studies into one conclusion and can settle studies that conflict. Combining several RCTs is the highest level of evidence.<br><br>One study climbed the pyramid in this lecture: the MEND RCT (Sacher 2010) appears in Kothandan's systematic review (2014) and Ho's meta-analysis (2012).","steps":[{"id":"W3-C5-S1","type":"label","fig":"pyramid","src":"W3 Part 3, slide 14","added":"2026-10-26","prompt":"Place each design on the evidence pyramid, strongest evidence at the top."},{"id":"W3-C5-S2","type":"match","src":"W3 Part 2, slides 8, 15; W3 Part 3, slides 6, 15, 17, 19","added":"2026-10-26","prompt":"Match each level of the pyramid to its description.","pairs":[["Meta-analysis","Statistically combines data from different studies into a single conclusion"],["Systematic review","A panel's comprehensive review of all relevant studies, with stringent selection criteria"],["Practice guideline","Expert panel statement on how to integrate evidence into clinical practice"],["Randomized control trial","Participants randomly assigned to an experimental or control group"],["Cohort study","People without the disease grouped by exposure and followed over time"],["Case reports/series","Unusual cases described in detail, with no control group"]]},{"id":"W3-C5-S3","type":"mcq","src":"W3 Part 3, slides 18-20","ch":"W3-C5","added":"2026-10-26","case":"Ho et al. (2012) took the results of many trials of child obesity lifestyle programs, including the MEND trial, and pooled the numbers to get one overall estimate: a BMI change of -1.25 kg/m² compared with no-treatment or wait-list controls.","q":"What did Ho et al. carry out?","opts":[["A practice guideline",false,"A guideline is an expert panel's guidance for clinical practice. It does not pool numbers into one estimate."],["A randomized controlled trial",false,"Ho et al. did not assign anyone to groups. They combined data from trials others ran."],["A case series",false,"A case series describes individual patients and has no pooled analysis."],["A meta-analysis",true,"Systematically combining data from different studies into a single conclusion is a meta-analysis. Pooling RCTs is the highest level of evidence."]]}],"summary":"Meta-analyses and systematic reviews sit at the top of the pyramid; case reports and series sit at the base."},{"id":"W3-C6","title":"Population health measures","src":"W3 Part 4, slides 2-16","blurb":"The five Ds, indicator types, mortality and morbidity, prevalence and incidence, PYLL, QALY, DALY, HALE.","learn":"Health measures cover <b>the five Ds</b>: death, disease, disability, discomfort and distress. Population indicators come in three kinds: <b>aggregate</b> (individual data summarized for a region, e.g. prevalence of obesity), <b>environmental</b> (factors outside the person, like air or water quality, or social traits) and <b>global</b> (no individual analogue, e.g. healthy public policy).<br><br><b>Mortality</b> is the incidence of death; <b>morbidity</b> is disease in a person or illness in a population. Morbidity is measured by <b>prevalence</b> (people with the condition at a given time: how many are sick?) and <b>incidence</b> (new cases in a fixed time: how many get sick?). <b>Life expectancy</b> estimates years a newborn will live, from age-specific mortality rates.<br><br>These measures only cover serious conditions. <b>PYLL</b> ranks diseases by years of life lost. <b>QALYs</b>, <b>DALYs</b> and <b>HALE</b> combine morbidity and mortality. If a year after a stroke is worth 0.8, then 10 such years count as 8, so 2 years are lost.","steps":[{"id":"W3-C6-S1","type":"sort","src":"W3 Part 4, slide 3","added":"2026-10-26","prompt":"Sort each population-level indicator into its class.","bins":["Aggregate","Environmental","Global"],"items":[["Prevalence of obesity in Ontario",0,"Individual data combined and summarized at a regional level."],["Average blood pressure of adults in a region",0,"Built from individual measurements: aggregate."],["Air quality in a city",1,"A factor external to the individual."],["Water quality in a town",1,"A factor external to the individual."],["Social characteristics of a neighbourhood",1,"The slides say environmental indicators can also be social characteristics."],["Healthy public policy",2,"Has no analogue at the individual level."],["Social equity in access to health care",2,"Has no analogue at the individual level."]]},{"id":"W3-C6-S2","type":"sort","src":"W3 Part 4, slides 9-10","added":"2026-10-26","prompt":"Prevalence or incidence?","bins":["Prevalence","Incidence"],"items":[["How many people are sick?",0,"Prevalence counts everyone with the condition at a given time."],["How many people get sick?",1,"Incidence counts new cases in a fixed time."],["Good for assessing the burden of chronic disease",0,"Stated on the prevalence slide."],["Useful for communicating the idea of risk",1,"Stated on the incidence slide."],["Measured in a cohort study and used to calculate relative risk",1,"a/(a+b) in a cohort is the incidence in the exposed."],["Number of Canadians living with diabetes on January 1",0,"Everyone with the condition at one point in time."],["New flu cases in a school during March",1,"New cases during a fixed period."]]},{"id":"W3-C6-S3","type":"table","src":"W3 Part 4, slide 6","added":"2026-10-26","prompt":"Read the leading causes of death chart from the mortality rates slide.","caption":"Ten leading causes of death, Canada, 2020 (sexes combined, all ages). Percentage of all deaths, as printed. Source: Statistics Canada.","head":["Cause of death","Percentage of all deaths"],"rows":[["Malignant neoplasms","26.4%"],["Diseases of the heart","17.5%"],["COVID-19","5.25%"],["Unintentional injuries (accidents)","4.4%"],["Cerebrovascular disease","4.5%"],["Chronic lower respiratory disease","4.2%"],["Diabetes mellitus","2.5%"],["Influenza & pneumonia","1.9%"],["Alzheimer's disease","1.9%"],["Chronic liver disease & Cirrhosis","1.4%"],["All other causes","42%"]],"qs":[{"id":"W3-C6-S3-Q1","type":"mcq","src":"W3 Part 4, slide 6","ch":"W3-C6","added":"2026-10-26","q":"Together, what share of all 2020 deaths in Canada did the top two causes account for?","opts":[["17.5%",false,"That is diseases of the heart alone."],["31.65%",false,"That is malignant neoplasms plus COVID-19 (26.4 + 5.25)."],["43.9%",true,"Malignant neoplasms 26.4% + diseases of the heart 17.5% = 43.9%."],["42%",false,"That is the share for all other causes outside the top ten."]]},{"id":"W3-C6-S3-Q2","type":"mcq","src":"W3 Part 4, slides 5-6","ch":"W3-C6","added":"2026-10-26","q":"This chart is an example of which kind of measure?","opts":[["A mortality measure",true,"It shows deaths by cause, which is mortality: the incidence of death in a population."],["A morbidity measure",false,"Morbidity is about illness (prevalence, incidence of disease), not deaths."],["A health measurement scale",false,"Scales like the SF-36 are subjective indicators of health and function."],["A HALE estimate",false,"HALE estimates years lived in a healthy state."]]}]},{"id":"W3-C6-S4","type":"mcq","src":"W3 Part 4, slide 15","ch":"W3-C6","added":"2026-10-26","case":"Priya has a heart attack at 50 and lives to 70. Assume each year she lives after the heart attack is worth 0.75 of a normal year. Her twin sister, with no heart attack, also dies at 70.","q":"Using the QALY method from the Bob and Bill example, how many years did the heart attack cost Priya?","opts":[["15 years",false,"15 is the quality-adjusted years she lived (20 x 0.75), not the years lost."],["20 years",false,"20 is the number of years she lived after the heart attack. They are not all lost, only adjusted."],["0 years",false,"Both twins died at 70, so no years of life were lost, but quality-adjusted years were."],["5 years",true,"20 years x 0.75 = 15 quality-adjusted years. 20 - 15 = 5 years lost."]]}],"summary":"Mortality counts deaths; morbidity is measured by prevalence and incidence. PYLL, QALYs, DALYs and HALE add years of life and quality into the picture."}],"questions":[{"id":"W3-Q01","type":"mcq","ch":"W3-C1","src":"W3 Part 1, slide 2","added":"2026-10-26","q":"Which statement describes qualitative research?","opts":[["It tests hypotheses and is generally deductive",false,"That describes quantitative research."],["It provides numeric estimates of frequency and severity from many participants",false,"That describes quantitative research."],["It generates hypotheses and is generally inductive",true,"Qualitative research works from particular instances to general conclusions and generates hypotheses."],["Its sampling gives representative coverage of people in the population",false,"Quantitative research samples people; qualitative research samples to cover the range of ideas."]]},{"id":"W3-Q02","type":"mcq","ch":"W3-C1","src":"W3 Part 1, slides 2-3","added":"2026-10-26","case":"A researcher asks: 'Does a new smoking cessation drug reduce the number of cigarettes smoked per day?' She plans to enrol 2,000 smokers.","q":"Which type of research is this, and why?","opts":[["Qualitative, because it studies the experience of quitting",false,"The question asks 'how much?', not what the experience means."],["Quantitative, because it tests a hypothesis and asks 'how much?'",true,"Testing a hypothesis with numbers from a large sample is quantitative."],["Qualitative, because it is inductive",false,"This study starts with a hypothesis to test, which is deductive."],["Quantitative, because it captures rich detail from a few participants",false,"Rich detail from a few people is a feature of qualitative research."]]},{"id":"W3-Q03","type":"mcq","ch":"W3-C1","src":"W3 Part 1, slide 4","added":"2026-10-26","q":"Epidemiology is described as a 'comparative discipline'. What does it compare?","opts":[["The risk of disease in people exposed to an agent with those not exposed",true,"Epidemiology compares disease risk between exposed and unexposed people to judge whether the relationship is causal."],["The experiences of patients treated in different hospitals",false,"That is closer to a qualitative question about experience."],["The cost of treatment between countries",false,"Cost is not part of the slide's definition."],["Health measurement scale scores between individuals",false,"Epidemiology studies disease occurrence in populations."]]},{"id":"W3-Q04","type":"mcq","ch":"W3-C1","src":"W3 Part 1, slide 5","added":"2026-10-26","case":"In a study of air pollution, people living in areas with low, medium and high pollution have progressively higher rates of asthma.","q":"Which Bradford Hill criterion does this finding support?","opts":[["Consistency",false,"Consistency is about the same result across studies, not across levels of exposure in one study."],["Temporal relationship",false,"That is about the exposure coming before the outcome."],["A graded response to a graded dose",true,"More exposure (pollution) goes with more of the outcome (asthma)."],["Plausible mechanism",false,"That is about a believable explanation for how the exposure causes disease."]]},{"id":"W3-Q05","type":"mcq","ch":"W3-C1","src":"W3 Part 1, slide 5","added":"2026-10-26","q":"Which of the following is NOT one of the Bradford Hill (1965) criteria listed in the lecture?","opts":[["Strength of association",false,"Listed, shown by a high relative risk."],["Random allocation to groups",true,"Random allocation is a feature of RCTs on the design tree, not a Bradford Hill criterion."],["Consistency",false,"Listed."],["A plausible mechanism",false,"Listed."]]},{"id":"W3-Q06","type":"mcq","ch":"W3-C1","src":"W3 Part 1, slide 6","added":"2026-10-26","q":"On the study design tree, which question separates descriptive studies from analytical studies?","opts":[["Did the investigator assign exposures?",false,"That splits experimental from observational studies."],["Random allocation to groups?",false,"That splits RCTs from non-randomised experimental designs."],["Was sampling based on exposure or outcome?",false,"That splits the analytical designs (cohort, case-control, cross-sectional)."],["Testing a hypothesis?",true,"Observational studies that test a hypothesis are analytical; those that do not are descriptive."]]},{"id":"W3-Q07","type":"mcq","ch":"W3-C2","src":"W3 Part 2, slide 4","added":"2026-10-26","q":"When does confounding occur?","opts":[["When a third variable is associated with both the exposure and the outcome",true,"This is the slide definition. If the third variable is ignored, the exposure-outcome link may be misread."],["When participants are randomly assigned to groups",false,"Randomization is what spreads confounders evenly."],["When participants misremember past exposures",false,"That is recall bias."],["When data are measured for populations instead of individuals",false,"That describes an ecological study."]]},{"id":"W3-Q08","type":"mcq","ch":"W3-C2","src":"W3 Part 2, slide 5","added":"2026-10-26","case":"A study finds that children born fourth or later among their siblings are more likely to have Down syndrome. Researchers then adjust statistically for maternal age over 35.","q":"What happens, and what does it show?","opts":[["The association gets stronger, showing birth order is a cause",false,"The slide reports the opposite."],["Nothing changes, showing maternal age is unrelated",false,"Maternal age is linked to both birth order and Down syndrome."],["The association disappears, showing Down syndrome causes later birth order",false,"Adjusting points to a third variable, not to reverse causation."],["The association disappears, showing maternal age was a confounder",true,"Higher birth order is linked to higher maternal age, which is the more plausible cause. Adjusting removes the birth order association."]]},{"id":"W3-Q09","type":"mcq","ch":"W3-C2","src":"W3 Part 2, slide 8","added":"2026-10-26","case":"A physician publishes a detailed description of a single patient with a very rare skin disease, including how it progressed and responded to treatment.","q":"Which design is this?","opts":[["Case series",false,"A case series covers multiple similar cases."],["Case study",true,"A study of one diseased individual describing an uncommon disease."],["Cross-sectional study",false,"Cross-sectional studies record associations between variables in a sample."],["Case-control study",false,"There is no control group and no comparison."]]},{"id":"W3-Q10","type":"mcq","ch":"W3-C2","src":"W3 Part 2, slides 8-9","added":"2026-10-26","q":"Hymes et al. (1981) reported eight men with Kaposi's sarcoma. Which statement about this kind of study is true?","opts":[["It tested a causal hypothesis using a control group",false,"Case series have no control group and do not test hypotheses."],["It is analytical because it involves more than one person",false,"Number of people does not make a study analytical. Testing a hypothesis does."],["It is a case series that may generate causal hypotheses",true,"Results from case series may generate causal hypotheses but do not test them."],["It is ranked above cohort studies on the evidence pyramid",false,"Case reports/series are at the base of the pyramid."]]},{"id":"W3-Q11","type":"mcq","ch":"W3-C2","src":"W3 Part 2, slide 8","added":"2026-10-26","q":"Which statement about case series is NOT true?","opts":[["They are usually carried out by clinicians",false,"True: usually by clinicians and published in medical journals."],["Investigators can calculate the frequency of symptoms",false,"True, stated on the slide."],["They include a comparison or control group",true,"Not true. Case studies and case series do not include a comparison or control group."],["They may generate causal hypotheses",false,"True, though they do not test them."]]},{"id":"W3-Q12","type":"mcq","ch":"W3-C2","src":"W3 Part 2, slides 12-13","added":"2026-10-26","case":"Researchers survey 2,000 men once, measuring beer intake and waist-to-hip ratio, to see whether the two are associated. Sampling is not based on exposure or on outcome.","q":"Which design is this?","opts":[["Cross-sectional study",true,"An analytical survey that records associations between variables, sampling on neither exposure nor outcome (Bobak et al., 2003)."],["Cohort study",false,"No one is followed over time from an exposure."],["Descriptive study",false,"It is testing an association, not only reporting frequencies."],["Ecological study",false,"Data are on individual men, not population averages."]]},{"id":"W3-Q13","type":"mcq","ch":"W3-C2","src":"W3 Part 2, slide 27","added":"2026-10-26","case":"Researchers compare cancer rates in people from one country with rates among the same population after they migrate to a new country, using government statistics.","q":"Which design is this, and what is a disadvantage?","opts":[["Cohort study; blinding is difficult",false,"Population rates are compared; no individuals are followed by exposure."],["Ecological study; it cannot prove cause and effect",true,"Following migrating populations is an ecological example on the slides. Cause and effect needs data on individuals."],["Case-control study; it has recall bias",false,"There are no cases and matched controls here."],["Ecological study; it cannot use existing data",false,"Using existing data such as government statistics is an advantage of ecological studies."]]},{"id":"W3-Q14","type":"mcq","ch":"W3-C3","src":"W3 Part 2, slides 15, 19","added":"2026-10-26","case":"Since 1948, researchers in a Massachusetts town have recorded residents' exercise, tobacco use, blood pressure and cholesterol, then followed them for decades to see who develops coronary heart disease.","q":"Which design is this?","opts":[["Case-control study",false,"Groups were not chosen by whether they had heart disease."],["Cohort study",true,"This is the Framingham Heart Study: people grouped by exposure and followed forward over time."],["Randomized controlled trial",false,"No one was assigned to smoke or to have high blood pressure."],["Cross-sectional study",false,"People are followed over time, not measured once."]]},{"id":"W3-Q15","type":"mcq","ch":"W3-C3","src":"W3 Part 2, slides 21-22","added":"2026-10-26","case":"200 people with stomach cancer and 200 people without it, matched for age and sex, fill out questionnaires about what they ate over the past 20 years.","q":"Which design is this?","opts":[["Cohort study",false,"A cohort starts with people without the disease and follows them forward."],["Cross-sectional study",false,"Sampling here is based on outcome, not on neither."],["Case-control study",true,"Groups are identified by outcome (cancer vs no cancer) and exposures are looked at retrospectively."],["Case series",false,"A case series has no control group."]]},{"id":"W3-Q16","type":"mcq","ch":"W3-C3","src":"W3 Part 2, slide 17","added":"2026-10-26","case":"A cohort of 1,000 smokers and 1,000 non-smokers is followed for 10 years. 100 smokers and 25 non-smokers develop lung disease.","q":"What is the relative risk for smokers?","opts":[["4.0",true,"Risk in smokers = 100/1,000 = 0.10. Risk in non-smokers = 25/1,000 = 0.025. RR = 0.10 / 0.025 = 4.0."],["0.075",false,"This is the difference in risk (0.10 - 0.025), not the ratio."],["0.25",false,"This is the non-smokers' risk divided by the smokers' risk, upside down."],["75",false,"This is the difference in case counts (100 - 25)."]]},{"id":"W3-Q17","type":"mcq","ch":"W3-C3","src":"W3 Part 2, slide 17","added":"2026-10-26","case":"In a cohort study, 30 of 200 exposed people and 15 of 300 unexposed people develop the outcome.","q":"What is the relative risk?","opts":[["2.0",false,"This is 30/15, case counts only. Each count must be divided by its group size."],["0.10",false,"This is the risk difference (0.15 - 0.05)."],["1.5",false,"This mixes up the group sizes (300/200)."],["3.0",true,"Risk exposed = 30/200 = 0.15. Risk unexposed = 15/300 = 0.05. RR = 0.15 / 0.05 = 3.0."]]},{"id":"W3-Q18","type":"mcq","ch":"W3-C3","src":"W3 Part 2, slide 17","added":"2026-10-26","case":"A cohort study follows 400 people who exercise regularly and 400 who do not. 20 exercisers and 40 non-exercisers develop type 2 diabetes. Exercise is treated as the exposure.","q":"What is the relative risk, and what does it mean?","opts":[["2.0; exercisers have twice the risk",false,"This puts the unexposed risk on top. Exposed (exercisers) must be the numerator."],["0.5; exercisers have half the risk of non-exercisers",true,"Risk exposed = 20/400 = 0.05. Risk unexposed = 40/400 = 0.10. RR = 0.05 / 0.10 = 0.5."],["0.05; exercisers have a 5% risk",false,"0.05 is the incidence among exercisers, not the relative risk."],["1.0; exercise makes no difference",false,"The two risks differ (0.05 vs 0.10), so RR is not 1.0."]]},{"id":"W3-Q19","type":"mcq","ch":"W3-C3","src":"W3 Part 2, slide 17","added":"2026-10-26","case":"In a cohort study, 250 people are exposed to a risk factor. 50 of them develop the disease.","q":"What is the risk (incidence) of disease in the exposed group?","opts":[["50%",false,"This would need 125 cases out of 250."],["25%",false,"This is 50/200, which uses the wrong denominator. The denominator is everyone exposed (a + b = 250)."],["20%",true,"Risk in the exposed = a/(a + b) = 50/250 = 0.20, or 20%. The slide calls this the incidence."],["5%",false,"This would need 12.5 cases out of 250."]]},{"id":"W3-Q20","type":"mcq","ch":"W3-C3","src":"W3 Part 2, slide 23","added":"2026-10-26","case":"A case-control study: of 100 cases, 50 were exposed and 50 were not. Of 100 controls, 25 were exposed and 75 were not. So a = 50, b = 25, c = 50, d = 75.","q":"What is the odds ratio?","opts":[["2.0",false,"This is 50/25, cases exposed over controls exposed. Use ad/bc."],["0.33",false,"This is bc/ad, the inverse."],["1.5",false,"This is 75/50, which is only part of the calculation."],["3.0",true,"OR = ad/bc = (50 x 75) / (25 x 50) = 3750 / 1250 = 3.0."]]},{"id":"W3-Q21","type":"mcq","ch":"W3-C3","src":"W3 Part 2, slide 23","added":"2026-10-26","case":"A case-control study of a rare liver cancer finds: a = 40 cases exposed, c = 10 cases unexposed, b = 20 controls exposed, d = 40 controls unexposed.","q":"What is the odds ratio, and how should it be read?","opts":[["8.0; cases had much greater odds of having been exposed than controls",true,"OR = ad/bc = (40 x 40) / (20 x 10) = 1600 / 200 = 8.0. Because the disease is rare, it also approximates the RR."],["2.0; cases were twice as likely to have been exposed",false,"This is a/b (40/20). The OR is ad/bc."],["0.125; exposure protects against the cancer",false,"This is bc/ad, the inverse."],["4.0; the incidence in the exposed is 4%",false,"Case-control studies start from cases, so they do not give incidence."]]},{"id":"W3-Q22","type":"mcq","ch":"W3-C3","src":"W3 Part 2, slide 26","added":"2026-10-26","q":"What is the main difference between how groups are formed in cohort and case-control studies?","opts":[["Cohorts are randomized; case-control studies are not",false,"Neither is randomized. Both are observational."],["Cohort groups are classified by exposure status; case-control groups by health outcome",true,"This is the slide's stated difference."],["Cohorts use population-level data; case-control studies use individual data",false,"Both use individual data. Population-level data is ecological."],["Cohort groups are classified by health outcome; case-control groups by exposure",false,"This is reversed."]]},{"id":"W3-Q23","type":"mcq","ch":"W3-C3","src":"W3 Part 2, slides 18, 24","added":"2026-10-26","q":"Which is a disadvantage of case-control studies compared with cohort studies?","opts":[["They take longer and cost more",false,"That is a cohort disadvantage. Case-control studies need less time."],["They cannot study rare diseases",false,"Case-control studies are good for rare diseases."],["Data quality problems such as memory and recall bias",true,"Retrospective studies have more data quality problems, including memory and recall bias."],["Only one risk factor can be studied at a time",false,"Case-control studies can look at multiple risk factors."]]},{"id":"W3-Q24","type":"mcq","ch":"W3-C4","src":"W3 Part 3, slide 4","added":"2026-10-26","case":"Two weight studies run at the same time. In Study A, participants choose their own meals and researchers record their weight each month. In Study B, researchers prescribe and deliver all meals and participants keep a food diary.","q":"How should the two studies be classified?","opts":[["Both are experimental because weight is measured",false,"Measuring an outcome does not make a study experimental."],["A is experimental; B is observational",false,"This is reversed."],["A is observational; B is experimental",true,"In B the investigator controls the primary exposure (diet). In A participants choose it."],["Both are observational because no drug is used",false,"Experimental studies include dietary changes, not just drugs."]]},{"id":"W3-Q25","type":"mcq","ch":"W3-C4","src":"W3 Part 3, slide 6","added":"2026-10-26","q":"In an RCT, what may the control group receive?","opts":[["Only the experimental treatment at a lower dose",false,"That is not listed. The control group is a comparison for the experimental treatment."],["No treatment, the conventional treatment, or a placebo",true,"These are the three options listed on the slide."],["Whatever treatment each participant prefers",false,"Participants are randomly assigned, not choosing their treatment."],["The experimental treatment after a case series",false,"Not on the slide."]]},{"id":"W3-Q26","type":"mcq","ch":"W3-C4","src":"W3 Part 3, slide 9","added":"2026-10-26","q":"What is the main advantage of randomization in an RCT?","opts":[["Participants know which treatment they get",false,"That is the opposite of blinding."],["It removes the need for informed consent",false,"Free and informed consent is always required."],["Confounding factors are likely equally represented in each group",true,"So, assuming no systematic error or bias, the only difference between groups should be the intervention."],["It lets researchers study rare diseases quickly",false,"That is an advantage of case-control studies."]]},{"id":"W3-Q27","type":"mcq","ch":"W3-C4","src":"W3 Part 3, slide 10","added":"2026-10-26","case":"An RCT finds that a new sleep drug improves sleep slightly more than placebo. The probability that this difference is due to chance alone is p = 0.20.","q":"What should the researchers conclude?","opts":[["The difference is significant because the drug group did better",false,"Doing better is not enough. p must be 0.05 or less."],["The null hypothesis is disproved",false,"p = 0.20 is above 0.05, so it is not disproved."],["The difference is not significant at p ≤ 0.05",true,"There is a 1 in 5 chance the difference is due to chance alone, which is more than 1 in 20."],["The trial is unethical and must stop",false,"Nothing suggests the drug is obviously effective or dangerous."]]},{"id":"W3-Q28","type":"mcq","ch":"W3-C4","src":"W3 Part 3, slide 13","added":"2026-10-26","case":"A vaccine has been approved by Health Canada and is in wide public use. Health officials keep tracking reports of rare side effects.","q":"Which clinical trial phase is this?","opts":[["Phase I",false,"Phase I tests a new treatment in a small group for side effects and safe dosage."],["Phase II",false,"Phase II tests larger groups for efficacy and safety before approval."],["Phase III",false,"Phase III is a series of RCTs before approval."],["Phase IV",true,"After approval and public use: post-marketing surveillance, not RCTs."]]},{"id":"W3-Q29","type":"mcq","ch":"W3-C4","src":"W3 Part 3, slide 13","added":"2026-10-26","case":"A new drug is given for the first time to 20 people to examine side effects and find a safe dosage.","q":"Which phase is this?","opts":[["Phase I",true,"Phase I: a new drug or treatment is tested in a small group for side effects and safe dosage."],["Phase II",false,"Phase II uses larger groups with a focus on efficacy and safety."],["Phase III",false,"Phase III is a series of RCTs comparing with common treatments."],["Phase IV",false,"Phase IV happens after approval."]]},{"id":"W3-Q30","type":"mcq","ch":"W3-C4","src":"W3 Part 3, slide 11","added":"2026-10-26","q":"According to the ethics of RCTs, when is it appropriate to run an RCT?","opts":[["When there is genuine uncertainty about whether the treatment is superior",true,"This balances two principles: not denying an effective treatment, and not adopting a treatment without rigorous testing."],["When the treatment is already known to be effective",false,"Then denying it to the control group would be unethical."],["When the disease is too rare for a case-control study",false,"Rarity favours case-control studies, not RCTs."],["Only after Phase IV surveillance is complete",false,"Phase III RCTs come before approval and Phase IV."]]},{"id":"W3-Q31","type":"mcq","ch":"W3-C5","src":"W3 Part 3, slide 14","added":"2026-10-26","q":"Which list orders study designs from strongest to weakest evidence?","opts":[["RCT, meta-analysis, cohort study, case-control study",false,"Meta-analysis sits above the RCT."],["Systematic review, practice guideline, RCT, cohort study",true,"This follows the pyramid from the top down."],["Practice guideline, systematic review, case-control study, cohort study",false,"Systematic review is above practice guideline, and cohort is above case-control."],["Cohort study, RCT, case-control study, case series",false,"RCTs sit above cohort studies."]]},{"id":"W3-Q32","type":"mcq","ch":"W3-C5","src":"W3 Part 3, slides 15-16","added":"2026-10-26","case":"The Canadian Task Force on Preventive Health Care reviews the literature and issues a statement telling primary care providers how to prevent and manage overweight and obesity in children and youth.","q":"What is this document?","opts":[["A meta-analysis",false,"A meta-analysis statistically combines data into one result. This is guidance for practice."],["A case series",false,"No individual cases are described."],["A randomized controlled trial",false,"No one is assigned to groups."],["A practice guideline",true,"An expert panel statement, after extensive literature review, that guides clinical practice."]]},{"id":"W3-Q33","type":"mcq","ch":"W3-C5","src":"W3 Part 3, slides 17-18","added":"2026-10-26","case":"A researcher gathers every relevant trial comparing school-based and family-based childhood obesity programs, uses strict rules for which studies to include, and rates each study's quality with the CASP tool. No data are pooled into one number.","q":"Which type of study is this?","opts":[["Systematic review",true,"A comprehensive review of all relevant studies with stringent selection criteria (Kothandan, 2014)."],["Meta-analysis",false,"A meta-analysis would statistically combine the data into a single result."],["Practice guideline",false,"A guideline gives advice for clinical practice from an expert panel."],["Cohort study",false,"No participants are followed over time by the researcher."]]},{"id":"W3-Q34","type":"mcq","ch":"W3-C5","src":"W3 Part 3, slide 19","added":"2026-10-26","q":"Which statement about meta-analysis is true?","opts":[["It is ranked below practice guidelines on the evidence pyramid",false,"Meta-analysis is at the top of the pyramid."],["It can only include studies that agree with each other",false,"It can establish statistical significance when studies have conflicting results."],["It describes one unusual patient in detail",false,"That is a case study."],["It can establish statistical significance among studies with conflicting results",true,"Stated on the slide. Combining several RCTs gives the highest level of evidence."]]},{"id":"W3-Q35","type":"mcq","ch":"W3-C6","src":"W3 Part 4, slide 2","added":"2026-10-26","q":"Which is NOT one of 'the five Ds' of health measures?","opts":[["Disability",false,"One of the five Ds."],["Distress",false,"One of the five Ds."],["Diagnosis",true,"The five Ds are death, disease, disability, discomfort and distress."],["Discomfort",false,"One of the five Ds."]]},{"id":"W3-Q36","type":"mcq","ch":"W3-C6","src":"W3 Part 4, slides 9-10","added":"2026-10-26","case":"A town has 10,000 adults. On January 1, 1,500 of them have asthma. During the year, 400 new cases of diabetes appear among the 8,000 adults at risk of diabetes.","q":"Which pair of values is correct?","opts":[["Asthma incidence 15%; diabetes prevalence 5%",false,"The labels are swapped. The asthma count is at one point in time; the diabetes count is new cases."],["Asthma prevalence 15%; diabetes incidence 4% per year",false,"4% uses the whole population (400/10,000). Incidence divides by the people at risk (8,000)."],["Asthma prevalence 1.5%; diabetes incidence 5% per year",false,"1,500/10,000 is 15%, not 1.5%."],["Asthma prevalence 15%; diabetes incidence 5% per year",true,"Prevalence = 1,500/10,000 = 15%. Incidence = 400/8,000 = 5% over the year."]]},{"id":"W3-Q37","type":"mcq","ch":"W3-C6","src":"W3 Part 4, slides 2, 6","added":"2026-10-26","case":"A region has 600 deaths in one year. Its population at the middle of the year is 200,000.","q":"What is the mortality rate per 1,000?","opts":[["0.3 per 1,000",false,"This is 600/200,000 x 100, not x 1,000."],["3 per 1,000",true,"600 / 200,000 = 0.003. Times 1,000 = 3 deaths per 1,000 people."],["30 per 1,000",false,"This is ten times too high."],["333 per 1,000",false,"This divides the population by the deaths."]]},{"id":"W3-Q38","type":"mcq","ch":"W3-C6","src":"W3 Part 4, slide 3","added":"2026-10-26","case":"A health report rates provinces on how fairly people with low and high incomes can get health care.","q":"What class of population-level indicator is social equity in access to health care?","opts":[["Aggregate measure",false,"Aggregate measures add up individual data, like prevalence of obesity."],["Environmental indicator",false,"Environmental indicators are external factors like air or water quality and may have individual analogues."],["Individual measure",false,"Equity of access describes a population, not a person."],["Global indicator",true,"Global indicators have no analogue at the individual level. Social equity in access to health care is a slide example."]]},{"id":"W3-Q39","type":"mcq","ch":"W3-C6","src":"W3 Part 4, slide 15","added":"2026-10-26","case":"Sam has a disabling injury at 40 and lives to 52. Assume each year after the injury is worth 0.5 of a normal year. His identical twin, with no injury, also dies at 52.","q":"Using the quality-adjusted approach from the Bob and Bill example, how many years did the injury cost Sam?","opts":[["6 years",true,"12 years x 0.5 = 6 quality-adjusted years. 12 - 6 = 6 years lost."],["12 years",false,"12 is the number of years lived after the injury, not the years lost."],["0 years",false,"Both twins died at 52, but quality adjustment still counts years lost."],["2 years",false,"That is Bob's result from the stroke example (10 years at 0.8)."]]},{"id":"W3-Q40","type":"mcq","ch":"W3-C6","src":"W3 Part 4, slides 13, 16","added":"2026-10-26","q":"Which statement about disease impact measures is true?","opts":[["HALE measures only how long people live, not how healthy they are",false,"HALE is the average years lived in a healthy state, so it reflects quality and quantity."],["Priorities based on PYLL will differ from priorities based on simple mortality rates",true,"Stated on the PYLL slide. In Canada 2004 to 2007, unintentional injury and suicide had larger PYLL bars than mortality-rate bars."],["PYLL and mortality rates always rank diseases the same way",false,"The slide says the priorities will be different."],["QALYs measure mortality only",false,"QALYs combine morbidity and mortality outcomes."]]}],"review":[{"id":"W3-R01","ch":"W3-C2","src":"W3 Part 2, slides 3-5","added":"2026-10-26","q":"What is confounding? Explain it with the Down syndrome and birth order example.","answer":"Confounding happens when a third variable is associated with both the exposure and the outcome. If it is not taken into account, the link between the exposure and outcome can be misinterpreted. A study saw that children born fourth or later were more likely to have Down syndrome. Higher birth order goes with higher maternal age, and maternal age over 35 is a more plausible cause of Down syndrome. When researchers adjusted statistically for maternal age, the birth order association disappeared, so maternal age was the confounder. Confounding is a risk in observational studies because groups are not randomized.","points":["Third variable linked to BOTH exposure and outcome","Exposure = birth order 4th or higher; outcome = Down syndrome","Confounder = maternal age over 35","Adjusting for maternal age made the association disappear","Observational, non-randomized designs are prone to it"]},{"id":"W3-R02","ch":"W3-C3","src":"W3 Part 2, slides 15-26","added":"2026-10-26","q":"Compare cohort and case-control studies: how groups are chosen, the direction in time, the measure of association, and one advantage and disadvantage of each.","answer":"A cohort (prospective) study chooses people without the disease and classifies them by exposure, then follows them forward in time to count new cases. It uses the relative risk, [a/(a+b)] / [c/(c+d)]. It can clearly establish the temporal relationship, but it is long and expensive. A case-control (retrospective) study chooses people by outcome, cases with the disease and similar controls without it, and looks back at past exposures. It uses the odds ratio, ad/bc, which approximates the RR when the disease is rare. It is good for rare diseases and faster, but it has data quality problems such as recall bias.","points":["Cohort groups by exposure; case-control groups by outcome","Cohort follows forward; case-control looks back","Cohort gives RR; case-control gives OR (ad/bc)","One valid advantage and disadvantage for each","OR approximates RR when disease is rare"]},{"id":"W3-R03","ch":"W3-C4","src":"W3 Part 3, slides 6-11","added":"2026-10-26","q":"Describe the steps of a randomized controlled trial and explain why randomization and the null hypothesis matter.","answer":"An RCT states a hypothesis, assembles participants as similar as possible who give free and informed consent, and randomly assigns them to the experimental group or a control group that gets no treatment, the conventional treatment or a placebo. The intervention is given, preferably double-blind, and outcomes are measured at a pre-determined time. Randomization makes it likely that confounders, like genetic characteristics, are equally spread across groups, so the intervention should be the only difference. The null hypothesis says the treatment had no effect. If the probability that the difference is due to chance is 0.05 or less, the null is disproved and the result is significant.","points":["Hypothesis, similar participants, informed consent","Random assignment to experimental or control (none, conventional, placebo)","Preferably double-blind; outcomes at a set time","Randomization balances confounders","Null hypothesis rejected when p ≤ 0.05"]},{"id":"W3-R04","ch":"W3-C5","src":"W3 Part 3, slides 14-21; W3 Part 2, slides 8, 10","added":"2026-10-26","q":"List the levels of the evidence pyramid from top to bottom. Why is a meta-analysis at the top, and why is a case series such as Wakefield (1998) at the bottom?","answer":"From top to bottom: meta-analysis, systematic review, practice guideline, randomized control trial, cohort study, case control study, case reports/series. A meta-analysis systematically combines data from different studies into a single conclusion and can establish significance when studies conflict; combining several RCTs is the highest level of evidence. A case series describes several unusual cases with no control group. It may generate a causal hypothesis but cannot test one. The Wakefield case series of 12 children linked MMR and autism only through what parents or a pediatrician reported, with nothing to compare against.","points":["Correct order of all seven levels","Meta-analysis combines data from many studies into one conclusion","Pooling several RCTs is the highest evidence","Case series have no control group and do not test hypotheses","Wakefield: 12 children, cause named by parents or pediatrician"]},{"id":"W3-R05","ch":"W3-C6","src":"W3 Part 4, slides 5, 9-10","added":"2026-10-26","q":"Distinguish prevalence from incidence. Which is better for the burden of chronic disease, and which for communicating risk?","answer":"Both measure morbidity. Prevalence is the number of people with a condition at a given time divided by the population at risk; it answers 'how many people are sick?'. It is good for assessing the burden of chronic disease. Incidence is the number of new cases in a specified time divided by the people at risk; it answers 'how many people get sick?' and measures the speed at which new cases arise. Incidence is useful for communicating risk and can be measured in a cohort study to calculate a relative risk.","points":["Prevalence = existing cases at a given time / population at risk","Incidence = new cases in a set time / people at risk","Prevalence for chronic disease burden","Incidence for risk; used in cohort studies for RR"]},{"id":"W3-R06","ch":"W3-C6","src":"W3 Part 4, slides 11-16","added":"2026-10-26","q":"Why are measures beyond mortality and morbidity needed? Use the Bob and Bill example to explain QALYs, and name the other combined measures.","answer":"Morbidity and mortality measures only apply to serious conditions, show nothing about positive health and do not show level of function. PYLL ranks diseases by the years of life lost, which gives different priorities than simple mortality rates. QALYs, DALYs and HALE combine morbidity and mortality. In the example, twins Bob and Bill both die at 65, but Bob had a disabling stroke at 55. If a year after a stroke is worth 0.8 normal years, his last 10 years count as 8, so he lost the equivalent of 2 years: 10 - (10 x 0.8) = 2. HALE is the average number of years a person is expected to live in a healthy state.","points":["Limits: serious conditions only, no positive health, no function","PYLL priorities differ from mortality-rate priorities","Bob: 10 - (10 x 0.8) = 2 years lost","QALYs, DALYs and HALE combine morbidity and mortality","HALE = expected years in a healthy state"]}],"explore":[{"fig":"designs","title":"Study design decision tree","caption":"Fig 5.1 from the AFMC Primer on Population Health. Work down from 'Did the investigator assign exposures?'","items":{"exp":{"label":"Experimental study","text":"The investigator assigned the exposure and controls its timing, dose and intensity.","src":"W3 Part 3, slides 3-4"},"obs":{"label":"Observational study","text":"The researcher observes exposures outside their control. Non-randomized, so confounders can make causation hard to infer.","src":"W3 Part 2, slide 3"},"rct":{"label":"Randomised controlled trial","text":"Participants are randomly allocated to experimental or control groups. The 'gold standard' for evaluation.","src":"W3 Part 3, slide 6"},"nonrand":{"label":"Non-randomised designs","text":"Experimental studies where the investigator assigns exposure but there is no random allocation to groups.","src":"W3 Part 1, slide 6"},"desc":{"label":"Descriptive study","text":"Does not test a hypothesis; describes how things are. Includes case studies and case series.","src":"W3 Part 2, slides 6, 8"},"anal":{"label":"Analytical study","text":"Tests a hypothesis about an outcome in relation to an exposure, such as CVD and smoking.","src":"W3 Part 2, slide 6"},"cohort":{"label":"Cohort study","text":"Sampling based on exposure. People without the disease are followed over time; gives relative risk.","src":"W3 Part 2, slides 15-17"},"cc":{"label":"Case-control study","text":"Sampling based on outcome. Cases and similar controls are compared for past exposure; gives the odds ratio.","src":"W3 Part 2, slides 21-23"},"cross":{"label":"Cross-sectional study","text":"Sampling based on neither. A survey that records associations between variables.","src":"W3 Part 2, slide 12"}}},{"fig":"pyramid","title":"Evidence pyramid","caption":"Study design pyramid. Evidence gets stronger toward the top.","items":{"meta":{"label":"Meta-analysis","text":"Systematically combines data from different studies into a single conclusion. Combining several RCTs is the highest level of evidence.","src":"W3 Part 3, slide 19"},"sr":{"label":"Systematic review","text":"A panel's comprehensive review of all relevant studies on a question, with stringent selection criteria.","src":"W3 Part 3, slide 17"},"guide":{"label":"Practice guideline","text":"Expert panel statement after an extensive literature review that guides clinical practice. Example: CTFPHC guideline on child obesity.","src":"W3 Part 3, slides 15-16"},"rct":{"label":"Randomized control trial","text":"Random assignment to experimental or control group, preferably double-blind. Example: the MEND trial (Sacher 2010).","src":"W3 Part 3, slides 6-8, 12"},"cohort":{"label":"Cohort study","text":"Follows people grouped by exposure forward in time. Example: the Framingham Heart Study, started in 1948.","src":"W3 Part 2, slides 15, 19"},"cc":{"label":"Case control study","text":"Compares cases with similar controls for past exposure. Good for rare diseases but prone to recall bias.","src":"W3 Part 2, slides 21, 24"},"case":{"label":"Case reports/series","text":"Detailed descriptions of one or several unusual cases with no control group. Example: Hymes et al. (1981).","src":"W3 Part 2, slides 8-9"}}}]},{"id":"W4","n":4,"added":"2026-10-26","title":"Psychological Health and Psychological Disorders","short":"Psychological health","blurb":"What psychological health is, how we grow and cope across life, and the main anxiety, mood and psychotic disorders with their treatments.","topics":["Maslow and the dual continua model","Erikson's 8 stages and adult identity","Self-talk, defence mechanisms, anger","DSM-5 and Canadian prevalence","Anxiety and mood disorders","Treatments, models and getting help"],"lectures":["Week 4 Part 1: Defining Psychological Health and Meeting Life's Challenges","Week 4 Part 2: Psychological Disorders"],"terms":[{"id":"W4-T-psychological-health","term":"Psychological health","def":"Our capacity to think, feel and behave in ways that contribute to our ability to enjoy life and manage challenges. It can be defined negatively, as the absence of illness, or positively, as the presence of wellness. It matters to every dimension of wellness and is influenced by factors such as diet, sleep patterns and relationship issues.","src":"W4 Part 1, slide 2","ch":"W4-C1","added":"2026-10-26"},{"id":"W4-T-maslows-hierarchy-of-needs","term":"Maslow's hierarchy of needs","def":"Abraham Maslow (1960s) took a positive view of psychological health and described a hierarchy of needs one works toward. Bottom to top: physiological needs, safety and security, love and belongingness, self-esteem, and self-actualization.","ex":"Physiological needs include food and water, shelter, sleep, exercise and sex. Safety includes safe surroundings, protection by others and knowing to avoid risks.","src":"W4 Part 1, slides 3-4","ch":"W4-C1","added":"2026-10-26"},{"id":"W4-T-self-actualization","term":"Self-actualization","def":"The top level of Maslow's hierarchy. Its qualities: realism (being realistic), acceptance (accepting oneself, positive self-concept, high but realistic self-esteem, tolerance of one's own imperfections), autonomy (independent and inner-directed, not other-directed), authenticity (not afraid to be judged for being yourself), capacity for intimacy (sharing feelings and thoughts without fear of rejection) and creativity (renewed appreciation of the world, openness to new experiences).","ex":"Choosing a program from your own interests rather than to please others shows autonomy.","src":"W4 Part 1, slides 4-6","ch":"W4-C1","added":"2026-10-26"},{"id":"W4-T-psychological-normality","term":"Psychological normality","def":"Being close to average. Psychological health is not the same as psychological normality. Psychological diversity is a valuable asset to society that brings a wide variety of ideas, lifestyles and attitudes, and the mere presence or absence of symptoms does not decide whether someone is mentally ill or mentally healthy.","src":"W4 Part 1, slide 7","ch":"W4-C1","added":"2026-10-26"},{"id":"W4-T-dual-continua-model","term":"Dual continua model of mental health","def":"A newer model in which mental health is a combination of where a person sits on two continua: mental well-being (high to low) and mental illness (low to high). The two are related but distinct, and the absence of illness does not guarantee high well-being.","ex":"Quadrants: flourishing (high well-being, low illness), symptomatic but content (high well-being, high illness), vulnerable (low well-being, low illness), languishing (low well-being, high illness).","src":"W4 Part 1, slide 8","ch":"W4-C1","added":"2026-10-26"},{"id":"W4-T-erik-erikson","term":"Erik Erikson","def":"Proposed (Childhood and Society, 1963) that development progresses through 8 stages across the lifetime, each with a conflict. Once one stage is mastered we may move to the next; failing to master a stage before moving on can have repercussions later in life, such as an identity crisis.","ex":"Birth to 1 year: trust vs. mistrust. Adolescence: identity vs. identity confusion. Older adulthood: integrity vs. despair.","src":"W4 Part 1, slides 10-11","ch":"W4-C1","added":"2026-10-26"},{"id":"W4-T-eriksons-stages","term":"Erikson's 8 stages (Table 2.1)","def":"Birth to 1 year: trust vs. mistrust (primary caregiver). 1 to 3 years: autonomy vs. shame and self-doubt (parents). 3 to 6 years: initiative vs. guilt (family). 6 to 12 years: industry vs. inferiority (community). Adolescence: identity vs. identity confusion (peers). Young adulthood: intimacy vs. isolation (close friends, sex partners). Middle adulthood: generativity vs. self-absorption (work associates, children, community). Older adulthood: integrity vs. despair (society).","ex":"Middle adulthood task: doing things for others, including parenting and civic activities.","src":"W4 Part 1, slide 11","ch":"W4-C1","added":"2026-10-26"},{"id":"W4-T-adult-identity","term":"Adult identity","def":"A unified self characterized by attitudes, beliefs and ways of acting: knowing who you are, what you are capable of, what roles you play and your place among your peers. It begins in adolescence, is a lifelong process and is an important part of psychological wellness.","ex":"Characteristics include gender, interests and talents, socioeconomic status, ethnicity, religion, sexual orientation, style of dress and choice of major. Some are permanent, others change over time; role models help.","src":"W4 Part 1, slides 12-14","ch":"W4-C1","added":"2026-10-26"},{"id":"W4-T-values","term":"Values","def":"Beliefs that underlie our moral decisions and behaviour by helping us tell 'good' from 'bad'. They are often reexamined throughout life. Living by your values means considering options carefully, choosing the best option without pressures that oppose your values, and making a choice and acting on it rather than doing nothing.","ex":"Assessing values: which personality traits, activities, social ideals and institutions you value, and how well your lifestyle reflects them.","src":"W4 Part 1, slides 16-18","ch":"W4-C1","added":"2026-10-26"},{"id":"W4-T-spiritual-wellness","term":"Spiritual wellness","def":"A very personal wellness component associated with greater coping skills. It is linked to longer life expectancy, reduced risk of disease, faster recovery and improved emotional health. Explanations for why it helps: social support, healthy habits, positive attitude and moments of relaxation.","src":"W4 Part 1, slides 19-20","ch":"W4-C2","added":"2026-10-26"},{"id":"W4-T-self-concept","term":"Positive self-concept","def":"Begins in childhood by feeling loved, feeling one can give love, and sensing one can accomplish goals. Integration, feeling that you created your own self-concept rather than adopting an image others created, is essential. Stability depends on that integration and on freedom from contradictions.","src":"W4 Part 1, slide 21","ch":"W4-C2","added":"2026-10-26"},{"id":"W4-T-cognitive-distortion","term":"Cognitive distortion","def":"A negative, unrealistic pattern of thinking that harms self-esteem. Types in the table: focusing on negatives, expecting the worst, overgeneralizing, minimizing, blaming others, expecting perfection, believing you're the cause of everything, thinking in black and white, and magnifying events.","src":"W4 Part 1, slides 22-23","ch":"W4-C2","added":"2026-10-26"},{"id":"W4-T-realistic-self-talk","term":"Realistic self-talk","def":"Replacing distorted negative self-talk with a balanced statement. To meet challenges to self-esteem: notice your patterns of thinking, avoid focusing on the negative (avoid cognitive distortion), and develop realistic self-talk.","ex":"Negative: 'I know I'm going to fail this course.' Realistic: 'I'm not doing well; I should ask my professor what help I can get.'","src":"W4 Part 1, slides 22-23","ch":"W4-C2","added":"2026-10-26"},{"id":"W4-T-defence-mechanisms","term":"Defence mechanisms","def":"When our wants conflict with the people around us or with our conscience and we cannot change the external situation, frustration or anxiety can result. To resolve the conflict internally we sometimes rearrange our thoughts and feelings; these are defence mechanisms (Table 2.2).","src":"W4 Part 1, slide 24","ch":"W4-C2","added":"2026-10-26"},{"id":"W4-T-projection","term":"Projection","def":"Reacting to unacceptable inner impulses as if they were from outside the self.","ex":"A student who dislikes a roommate feels that the roommate dislikes them.","src":"W4 Part 1, slide 25","ch":"W4-C2","added":"2026-10-26"},{"id":"W4-T-repression","term":"Repression","def":"Expelling from awareness an unpleasant feeling, idea or memory.","ex":"The child of an alcoholic, neglectful person remembers them as a giving, loving person.","src":"W4 Part 1, slide 25","ch":"W4-C2","added":"2026-10-26"},{"id":"W4-T-denial","term":"Denial","def":"Refusing to acknowledge to yourself what you really know to be true.","ex":"A person believes smoking won't harm them because they're young and healthy.","src":"W4 Part 1, slide 25","ch":"W4-C2","added":"2026-10-26"},{"id":"W4-T-passive-aggressive-behaviour","term":"Passive-aggressive behaviour","def":"Expressing hostility toward someone by being covertly uncooperative or passive.","ex":"A person promises to help a competing co-worker with a report, then never follows through.","src":"W4 Part 1, slide 25","ch":"W4-C2","added":"2026-10-26"},{"id":"W4-T-displacement","term":"Displacement","def":"Shifting your feelings about a person to another person.","ex":"A student angry with a professor goes home and yells at a housemate.","src":"W4 Part 1, slide 25","ch":"W4-C2","added":"2026-10-26"},{"id":"W4-T-rationalization","term":"Rationalization","def":"Giving a false, acceptable reason when the real reason is unacceptable.","ex":"A shy student skips a residence party, telling themself they'd be bored.","src":"W4 Part 1, slide 25","ch":"W4-C2","added":"2026-10-26"},{"id":"W4-T-substitution","term":"Substitution","def":"Deliberately replacing a frustrating goal with one that is more attainable.","ex":"A student struggling in chemistry switches majors from biology to economics.","src":"W4 Part 1, slide 25","ch":"W4-C2","added":"2026-10-26"},{"id":"W4-T-humour","term":"Humour (coping)","def":"Finding something funny in unpleasant situations.","ex":"A student whose bike was stolen pictures the thief's surprise on discovering the brakes don't work.","src":"W4 Part 1, slide 26","ch":"W4-C2","added":"2026-10-26"},{"id":"W4-T-altruism","term":"Altruism","def":"Serving others without expecting anything in return.","ex":"A person with little money to spare volunteers at a foundation that helps people get out of poverty.","src":"W4 Part 1, slide 26","ch":"W4-C2","added":"2026-10-26"},{"id":"W4-T-acting-out","term":"Acting out","def":"Engaging in an action that makes an unacceptable feeling go away.","ex":"A person who feels disrespected and devalued gets into a fight at a bar with a stranger.","src":"W4 Part 1, slide 26","ch":"W4-C2","added":"2026-10-26"},{"id":"W4-T-reaction-formation","term":"Reaction formation","def":"Concealing emotions or impulses by exaggerating the opposite ones.","ex":"A person who dislikes children often buys expensive gifts for, and speaks with enthusiasm about, friends' children.","src":"W4 Part 1, slide 26","ch":"W4-C2","added":"2026-10-26"},{"id":"W4-T-dissociation","term":"Dissociation","def":"Detaching from a current experience to avoid emotional distress.","ex":"Rather than listen to an angry parent, a child composes a piece of music in their head.","src":"W4 Part 1, slide 26","ch":"W4-C2","added":"2026-10-26"},{"id":"W4-T-pessimism","term":"Pessimism","def":"Expecting repeated failure and rejection and feeling you deserve it. It is typically learned at a young age from parents or other authority figures. Overcoming it requires recognizing and disputing irrational, false and negative self-talk.","src":"W4 Part 1, slide 27","ch":"W4-C2","added":"2026-10-26"},{"id":"W4-T-assertiveness","term":"Assertiveness","def":"Expression that is confident and direct but not hostile. It helps when fear of denial or rejection keeps us from communicating clearly even though we know what we want.","src":"W4 Part 1, slide 28","ch":"W4-C2","added":"2026-10-26"},{"id":"W4-T-dealing-with-anger","term":"Dealing with anger","def":"Expressing anger is commonly thought to be healthy, but studies suggest overtly hostile people are at higher risk for heart attacks. For your own anger, reframe and distract when explosive anger is coming on. With other people's anger: react with calmness, validate their feelings, try to solve the problem, and when all else fails, disengage.","src":"W4 Part 1, slides 30-31","ch":"W4-C2","added":"2026-10-26"},{"id":"W4-T-psychological-disorder","term":"Psychological disorder","def":"When feelings or thoughts such as anxiety, feeling down or irrational thoughts interfere with daily activities and rob us of peace of mind. Types include anxiety disorders, mood disorders and schizophrenia. Contributing factors: genetics, learning and life events, exposure to trauma, and parental and peer influences.","src":"W4 Part 2, slide 2","ch":"W4-C3","added":"2026-10-26"},{"id":"W4-T-dsm-5","term":"DSM-5","def":"The Diagnostic and Statistical Manual of Mental Disorders. It lists a wider range of conditions than the textbook covers: mood disorders (unipolar and bipolar depression), behavioural addiction, anxiety disorders, learning disorders, schizophrenia, eating disorders, substance use disorders, Alzheimer's disease and other dementias, ADHD, and autism spectrum disorders.","src":"W4 Part 2, slide 3","ch":"W4-C3","added":"2026-10-26"},{"id":"W4-T-mental-illness-prevalence","term":"Mental illness prevalence in Canada","def":"1 in 5 Canadians live with a mental illness in any given year. Lifetime: 14% major depressive disorder, 13.3% generalized anxiety disorder, 21.6% substance use disorder, 3.4% bipolar disorder. Schizophrenia affects about 1%. About 0.3 to 1% experience an eating disorder (rate 10 times higher for women), which has the highest mortality rate of any mental illness. In 2020, 23% of hospitalizations of people aged 5 to 24 were for a mental illness.","src":"W4 Part 2, slide 4","ch":"W4-C3","added":"2026-10-26"},{"id":"W4-T-anxiety","term":"Anxiety","def":"Another word for fear, especially fear that is not in response to any definite threat. When fear is disproportionate to the actual danger, it can be considered a problem.","src":"W4 Part 2, slide 6","ch":"W4-C3","added":"2026-10-26"},{"id":"W4-T-specific-phobia","term":"Simple (specific) phobia","def":"Fear of something definite, such as a particular animal or heights.","src":"W4 Part 2, slide 8","ch":"W4-C3","added":"2026-10-26"},{"id":"W4-T-social-anxiety-disorder","term":"Social anxiety disorder","def":"Fear of humiliation or embarrassment while being observed by others.","ex":"Dreading a class presentation because others will watch you.","src":"W4 Part 2, slide 8","ch":"W4-C3","added":"2026-10-26"},{"id":"W4-T-panic-disorder","term":"Panic disorder","def":"Sudden, unexpected surges of anxiety with a rapid and strong heartbeat, shortness of breath, loss of physical equilibrium and a feeling of losing mental control. Agoraphobia is listed under panic disorders.","src":"W4 Part 2, slide 9","ch":"W4-C3","added":"2026-10-26"},{"id":"W4-T-generalized-anxiety-disorder","term":"Generalized anxiety disorder (GAD)","def":"Excessive, uncontrollable worry about all kinds of things and anxiety in many situations.","src":"W4 Part 2, slide 10","ch":"W4-C3","added":"2026-10-26"},{"id":"W4-T-obsessive-compulsive-disorder","term":"Obsessive-compulsive disorder (OCD)","def":"Obsessions are recurrent, unwanted thoughts. Compulsions are repetitive, difficult-to-resist actions.","ex":"A recurring thought that the door is unlocked (obsession) and checking it again and again (compulsion).","src":"W4 Part 2, slide 10","ch":"W4-C3","added":"2026-10-26"},{"id":"W4-T-behavioural-addiction","term":"Behavioural addiction","def":"The urge to engage in a behaviour creates anxiety, and engaging in the behaviour brings relief. Listed with the anxiety disorders, and as its own DSM-5 category.","src":"W4 Part 2, slides 3, 11","ch":"W4-C3","added":"2026-10-26"},{"id":"W4-T-ptsd","term":"Post-traumatic stress disorder (PTSD)","def":"A reaction to a severely traumatic event in which the person relives it through dreams, flashbacks or hallucinations.","src":"W4 Part 2, slide 11","ch":"W4-C3","added":"2026-10-26"},{"id":"W4-T-benzodiazepines","term":"Benzodiazepines","def":"Antianxiety medications, such as Valium, that enhance the activity of the neurotransmitter GABA.","src":"W4 Part 2, slides 12, 25","ch":"W4-C3","added":"2026-10-26"},{"id":"W4-T-cognitive-behavioural-therapy","term":"Cognitive-behavioural therapy (CBT)","def":"A psychological intervention that concentrates on a person's thoughts and behaviours. For anxiety disorders it is usually combined with medication. For mood disorders, cognitive and behavioural therapies address learned beliefs and behaviours that contribute to the disorder.","src":"W4 Part 2, slides 12, 24","ch":"W4-C3","added":"2026-10-26"},{"id":"W4-T-mood-disorder","term":"Mood disorder","def":"An emotional disturbance intense and persistent enough to affect normal functioning, unlike daily, temporary mood changes. Prevalence of major depressive episodes in Canadians aged 15 and up is 7.6%, and women are 2 times as likely as men. Depression and anxiety disorders are often co-morbid.","ex":"Undergraduates' self-reported depression diagnosis over 12 months: 26.9% of cisgender women, 13.4% of cisgender men, 47.8% of trans and gender nonconforming students, and higher rates for Indigenous students.","src":"W4 Part 2, slides 13-14, 16","ch":"W4-C4","added":"2026-10-26"},{"id":"W4-T-dysphoria","term":"Dysphoria","def":"A feeling of sadness and hopelessness; a symptom of depression.","src":"W4 Part 2, slide 15","ch":"W4-C4","added":"2026-10-26"},{"id":"W4-T-anhedonia","term":"Anhedonia","def":"Loss of pleasure in doing usual activities; a symptom of depression.","ex":"No longer enjoying a sport or hobby you used to love.","src":"W4 Part 2, slide 15","ch":"W4-C4","added":"2026-10-26"},{"id":"W4-T-rumination","term":"Rumination","def":"Constantly thinking about past 'bad events'; a symptom of depression.","src":"W4 Part 2, slide 15","ch":"W4-C4","added":"2026-10-26"},{"id":"W4-T-unipolar-disorder","term":"Unipolar disorder","def":"One of the two main forms of depression: negative moods, sadness and loss of interest in the activities of life. Neuroinflammation may be a biological correlate of depression.","src":"W4 Part 2, slide 16","ch":"W4-C4","added":"2026-10-26"},{"id":"W4-T-persistent-depressive-disorder","term":"Persistent depressive disorder","def":"Persistent symptoms of mild or moderate depression for 2 years or longer. Listed under unipolar depression.","src":"W4 Part 2, slide 16","ch":"W4-C4","added":"2026-10-26"},{"id":"W4-T-bipolar-disorder","term":"Bipolar disorder (manic-depression)","def":"The person swings between opposite states of mania (restlessness, euphoria, recklessness, lots of energy) and depression. 3.4% of Canadians will experience it. Reckless behaviour is listed as a symptom of bipolar depression.","src":"W4 Part 2, slides 4, 15-16","ch":"W4-C4","added":"2026-10-26"},{"id":"W4-T-depression-rating-scales","term":"Depression rating scales","def":"Clinical rating scales such as the Hamilton Rating Scale for Depression and the Beck Depression Inventory. Family doctors, psychiatrists, clinical psychologists, counsellors, social workers and researchers use them to measure the intensity of symptoms and changes over time.","src":"W4 Part 2, slide 17","ch":"W4-C4","added":"2026-10-26"},{"id":"W4-T-treating-depression","term":"Treating depression","def":"80% of Canadians respond well to treatment, but only 10% of Canadians with depression seek treatment. Options: drug therapy, psychotherapy or a combination; exercise as an adjunct; rTMS (repetitive transcranial magnetic stimulation); electroconvulsive therapy (ECT) for severe depression; light therapy for seasonal affective disorder (SAD).","src":"W4 Part 2, slide 23","ch":"W4-C4","added":"2026-10-26"},{"id":"W4-T-interpersonal-psychotherapy","term":"Interpersonal psychotherapy (IPT)","def":"Psychotherapy that focuses on problems in relationships and on understanding events that may have triggered depression, and works to remove guilt and self-blame.","src":"W4 Part 2, slide 24","ch":"W4-C4","added":"2026-10-26"},{"id":"W4-T-antidepressants","term":"Antidepressant classes","def":"Selective serotonin reuptake inhibitors (SSRIs), serotonin and norepinephrine reuptake inhibitors (SNRIs), tricyclic antidepressants (TCAs), monoamine oxidase inhibitors (MAOIs) and other newer medications. Benzodiazepines (Valium) appear on the same slide for anxiety.","src":"W4 Part 2, slide 25","ch":"W4-C4","added":"2026-10-26"},{"id":"W4-T-schizophrenia","term":"Schizophrenia","def":"Symptoms vary from severe and debilitating to mild and hardly noticeable, and may include disorganized thoughts, inappropriate emotions, delusions, auditory hallucinations and deteriorating social and work functioning. About 1% of Canadians have been diagnosed. Caused by a combination of genes and environmental factors; treatment may include psychotherapy and medication.","src":"W4 Part 2, slide 29","ch":"W4-C4","added":"2026-10-26"},{"id":"W4-T-models-of-human-nature","term":"Four models of human nature","def":"Biological: the mind depends entirely on the brain and its genetic makeup; treated with drugs (antidepressants, mood stabilizers, antipsychotics). Behavioural: stimulus, response and reinforcement determine behaviour; identify and alter reinforcers. Cognitive: attitudes, expectations and motives determine behaviour; expose and identify false ideas that produce anxiety or depression. Psychodynamic: unconscious ideas and impulses feed thoughts and behaviours; patients speak freely to gain insight.","src":"W4 Part 2, slides 30-31","ch":"W4-C4","added":"2026-10-26"},{"id":"W4-T-when-to-get-professional-help","term":"When professional help is indicated","def":"When depression, anxiety or other emotional problems seriously interfere with school, work or relationships; when suicide is attempted or seriously considered; when hallucinations, delusions, memory loss or incoherent speech occur; or when alcohol or drugs impair normal functioning or cutting back causes psychological withdrawal symptoms. Other routes to help: self-help, peer counselling and support groups.","src":"W4 Part 2, slides 32-33","ch":"W4-C4","added":"2026-10-26"},{"id":"W4-T-psychiatrist","term":"Psychiatrist","def":"A specialized medical physician who can prescribe medications and determine whether there is a medical cause or connection for the patient's problems.","src":"W4 Part 2, slide 34","ch":"W4-C4","added":"2026-10-26"},{"id":"W4-T-clinical-psychologist","term":"Clinical psychologist","def":"Usually holds a PhD; treatment is generally based on behavioural and cognitive therapies. Other professionals on the slide: social workers (master's degree, skilled in counselling and finding community support), licensed counsellors, and clergy with additional counselling training.","src":"W4 Part 2, slide 34","ch":"W4-C4","added":"2026-10-26"},{"id":"W4-T-indigenous-mental-health","term":"Traditional mental health support for Indigenous Peoples","def":"Colonization and intergenerational trauma have caused difficult mental health challenges for Indigenous Peoples in Canada. Effective, culturally appropriate supports must be respectful and honour the history and values of the people harmed. Holistic and traditional practices are paramount for healing.","src":"W4 Part 2, slide 35","ch":"W4-C4","added":"2026-10-26"},{"id":"W4-T-suicide-severe-depression","term":"Suicide and severe depression","def":"Suicide is one of the principal dangers of severe depression. An attempt can happen unpredictably and without depression, but the chances are greater when symptoms are numerous and severe.","src":"W4 Part 2, slide 18","ch":"W4-C5","added":"2026-10-26"},{"id":"W4-T-is-path-warm","term":"IS PATH WARM?","def":"A mnemonic for the warning signs of suicide: Ideation, Substance abuse, Purposeless, Anxiety, Trapped, Hopelessness, Withdrawal, Anger, Recklessness, Mood changes.","src":"W4 Part 2, slide 21","ch":"W4-C5","added":"2026-10-26"},{"id":"W4-T-suicide-15-34","term":"Suicide in people aged 15 to 34","def":"Suicide is the second leading cause of death among people aged 15 to 34 in Canada.","src":"W4 Part 2, slide 4","ch":"W4-C5","added":"2026-10-26"},{"id":"W4-T-tb-healthy-self-esteem","term":"Healthy self-esteem","def":"Regarding your self, which includes all aspects of your identity, as good, competent and worthy of love. The textbook calls it a critical component of wellness. Psychological health needs an appropriately high but realistic level of self-esteem, and self-acceptance includes tolerating your own imperfections.","src":"Textbook Ch 2, p. 38","ch":"W4-C6","added":"2026-10-26"},{"id":"W4-T-tb-demoralization","term":"Demoralization","def":"The worst reaction to a challenge to your self-concept: a lasting negative self-concept in which you feel bad, unloved and ineffective. Instead of coping, the person gives up, which reinforces the negative self-concept and starts a cycle of bad self-concept and failure. In people genetically predisposed to depression it can progress to further symptoms.","ex":"After one failed test, deciding you are hopeless and no longer studying at all.","src":"Textbook Ch 2, p. 39","ch":"W4-C6","added":"2026-10-26"},{"id":"W4-T-tb-inner-directed","term":"Inner-directed vs. other-directed","def":"Autonomous people are inner-directed: they find guidance from within, from their own rules and values, and have an internal locus of control and high self-efficacy. Other-directed people act mainly in response to pressure from others and tend to say what they think will make other people happy instead of their true feelings.","ex":"Saying honestly that you would rather not go to a party (inner-directed) vs. agreeing only because you think it will please your friends (other-directed).","src":"Textbook Ch 2, p. 35","ch":"W4-C6","added":"2026-10-26"},{"id":"W4-T-tb-identity-crisis","term":"Identity crisis","def":"Erikson's term for internal confusion about who you are, which happens without a personal identity. Until we have found ourselves we cannot have much self-esteem, because a self is not firmly in place.","src":"Textbook Ch 2, p. 37","ch":"W4-C6","added":"2026-10-26"},{"id":"W4-T-tb-moral-development","term":"Stages of moral development","def":"Young child: good is what brings immediate, tangible rewards and bad is whatever brings punishment. Older child: right and wrong are explained by authority figures and rules. Final stage, which not everyone reaches: right and wrong in abstract terms such as justice and virtue.","ex":"A values exercise from the textbook: write a draft of your own obituary as an honest, realistic appraisal, then ask how you will have to change to be the person you want to be.","src":"Textbook Ch 2, p. 37","ch":"W4-C6","added":"2026-10-26"},{"id":"W4-T-tb-realistic-vs-positive","term":"Realistic thinking vs. positive thinking","def":"Self-talk is the statements you make to yourself inside your own mind. Positive thinking means substituting a positive thought for a negative one. The textbook's approach is different: make your thoughts as logical and accurate as possible, based on the facts as you know them, not on snap judgments.","ex":"A friend is 30 minutes late. Neutral, realistic self-talk: 'He's never late. Something must be holding him up. I'll call and make sure everything is all right.'","src":"Textbook Ch 2, p. 40","ch":"W4-C6","added":"2026-10-26"},{"id":"W4-T-tb-self-fulfilling-prophecy","term":"Self-fulfilling prophecy","def":"Demoralized people can hold negative beliefs so firmly that their own behaviour makes the beliefs come true.","ex":"Concluding you are so boring that no one will like you, you stop socializing, and the belief becomes reality.","src":"Textbook Ch 2, p. 40","ch":"W4-C6","added":"2026-10-26"},{"id":"W4-T-tb-honest-communication","term":"Honest communication","def":"Recognize what you want to communicate, then express it clearly. Others can hardly meet your needs if they do not know them. Indirect statements may avoid a confrontation but are unfair because you are not clear about what you want.","ex":"'I feel like staying home tonight' may really mean 'Don't bother me' or may be opening a negotiation.","src":"Textbook Ch 2, p. 42","ch":"W4-C6","added":"2026-10-26"},{"id":"W4-T-tb-assertiveness-training","term":"Assertiveness training","def":"Learning to insist on your rights and bargain for what you want, including being able to say no or yes depending on the situation. It helps people who know what they want but do not say it because they fear a refusal, which they take as personal rejection.","src":"Textbook Ch 2, p. 42","ch":"W4-C6","added":"2026-10-26"},{"id":"W4-T-tb-loneliness","term":"Loneliness","def":"A passive feeling state. It may come from not knowing how to be happy alone, or from reading time alone as a sign of rejection. Fear of being alone is not the best reason to socialize, and rushing into a relationship can trade loneliness for worse problems. The remedy is to take action, such as joining a group around a real interest.","src":"Textbook Ch 2, pp. 42-43","ch":"W4-C6","added":"2026-10-26"},{"id":"W4-T-tb-ied","term":"Intermittent explosive disorder (IED)","def":"Anger that is explosive or misdirected. It is often accompanied by depression or another disorder. Like a child's tantrum, it leaves the person temporarily unable to think straight or act in their own interest; they may lash out, hurting someone or destroying property. Anyone who expresses anger this way should seek professional help.","src":"Textbook Ch 2, p. 43","ch":"W4-C6","added":"2026-10-26"},{"id":"W4-T-tb-reframing","term":"Reframing and distraction (own anger)","def":"Two strategies to head off explosive anger. Reframe: change what you are thinking, for example by considering that the other person's behaviour was not aimed at you, and avoid replaying past unjust criticism. Distract: count to 10, focus on your breathing, or take a cooling-off period, then return to the issue once you can think clearly.","ex":"A driver cuts in front of you. You consider that he did not see you or was rushing to an emergency.","src":"Textbook Ch 2, pp. 43-44","ch":"W4-C6","added":"2026-10-26"},{"id":"W4-T-tb-asymmetrical-response","term":"Asymmetrical response to anger","def":"Anger is infectious, so respond to an angry person with calm, not anger. Validate that they have some reason to be angry (without apologizing if you are not to blame, and never accepting verbal abuse), focus on solving the problem, and if they cannot be calmed, disengage for a time-out.","src":"Textbook Ch 2, p. 44","ch":"W4-C6","added":"2026-10-26"},{"id":"W4-T-tb-agoraphobia","term":"Agoraphobia","def":"An anxiety condition that can grow out of panic disorder: fear of attacks in places where escape is hard, loss of control would be dangerous or embarrassing, or no help is available spreads until the person is virtually housebound. Glossary: fear of being alone, away from help, with avoidance of many places and situations; in extreme cases, fear of leaving home.","ex":"People with panic disorder can often manage feared situations if someone they trust goes with them.","src":"Textbook Ch 2, p. 45","ch":"W4-C7","added":"2026-10-26"},{"id":"W4-T-tb-shyness","term":"Shyness","def":"A form of social anxiety: fear of what others will think of your behaviour or appearance. It is not the same as being introverted. Introverts prefer solitude; shy people often long to be more outgoing, but their negative thoughts get in the way. Help includes shyness classes, assertiveness groups, and for serious cases CBT and antidepressants.","src":"Textbook Ch 2, p. 46","ch":"W4-C7","added":"2026-10-26"},{"id":"W4-T-tb-mania","term":"Mania","def":"A less common feature of mood disorders. People are restless, have a lot of energy, need little sleep and often talk nonstop. They may take on fantastic projects and spend more money than they can afford. The chapter summary adds exalted mood with unrealistically high self-esteem.","src":"Textbook Ch 2, pp. 52, 60","ch":"W4-C7","added":"2026-10-26"},{"id":"W4-T-tb-dysthymic-disorder","term":"Dysthymic disorder","def":"The textbook's name for persistent symptoms of mild or moderate depression for two years or longer. The slides use the current name, persistent depressive disorder. Some depression is a clear reaction to an event such as a loss; in other cases no trigger is obvious.","src":"Textbook Ch 2, p. 48","ch":"W4-C7","added":"2026-10-26"},{"id":"W4-T-tb-sad","term":"Seasonal affective disorder (SAD)","def":"Depression that worsens in winter as daylight hours shrink and improves in spring and summer. It is more common at higher latitudes. It is treated with light therapy: sitting with eyes open in front of a bright light every morning, which may work by making the brain perceive a longer day.","src":"Textbook Ch 2, p. 51","ch":"W4-C7","added":"2026-10-26"},{"id":"W4-T-tb-ect","term":"Electroconvulsive therapy (ECT)","def":"Used for severe depression when other approaches, including medication and magnetic stimulation, have failed. An electrical impulse through electrodes on the head induces an epileptic-like seizure. Patients get an anaesthetic and a muscle relaxant. A typical course is three treatments a week for two to four weeks.","src":"Textbook Ch 2, p. 51","ch":"W4-C7","added":"2026-10-26"},{"id":"W4-T-tb-reuptake","term":"Neurotransmitter reuptake","def":"Neurotransmitters such as serotonin and norepinephrine are released into the synapse and attach to receptors on the next neuron. Their level depends on how much is released and how much is reabsorbed (reuptake) by the sending cell. Prozac, an SSRI, raises serotonin by slowing its reuptake.","src":"Textbook Ch 2, p. 52","ch":"W4-C7","added":"2026-10-26"},{"id":"W4-T-tb-mood-stabilizers","term":"Mood stabilizers","def":"Drugs such as lithium carbonate, valproic acid, lamotrigine and topiramate, taken to prevent the mood swings of bipolar disorder and certain kinds of schizophrenia. Tranquilizers are used for individual manic episodes.","src":"Textbook Ch 2, pp. 52, 54","ch":"W4-C7","added":"2026-10-26"},{"id":"W4-T-tb-antipsychotics","term":"Antipsychotics","def":"Older drugs (haloperidol, fluphenazine) and newer 'atypical' drugs (clozapine, olanzapine, risperidone and others) that reduce hallucinations and disordered thinking in schizophrenia, bipolar disorder and delirium, and calm agitated patients.","src":"Textbook Ch 2, p. 54","ch":"W4-C7","added":"2026-10-26"},{"id":"W4-T-tb-delusion","term":"Delusion","def":"A firmly held false belief, such as that your mind is controlled by outside forces, that people can read your mind, that you are a great personage, or that a group is persecuting you. One of the general characteristics of schizophrenia, with disorganized thoughts, inappropriate emotions, auditory hallucinations and deteriorating social and work functioning. None of these is always present.","src":"Textbook Ch 2, p. 53","ch":"W4-C7","added":"2026-10-26"},{"id":"W4-T-tb-exposure","term":"Exposure","def":"A behavioural technique for treating fear: the person deliberately and repeatedly enters the feared situation and stays in it until the fear begins to fade. Exposure to the real situation works best, but imagined or virtual reality exposure can also work.","ex":"Someone afraid of flying vividly imagines boarding and takeoff until the fear eases.","src":"Textbook Ch 2, p. 55","ch":"W4-C7","added":"2026-10-26"},{"id":"W4-T-tb-reinforcement","term":"Stimulus, response and reinforcement","def":"A stimulus is anything that causes a response; a response is a reaction to a stimulus; reinforcement increases the future probability of a response by following it with a reward. Behaviour therapy finds the reinforcements that keep an unwanted behaviour going and changes them.","ex":"Being asked to speak in class (stimulus), leaving the room (response), feeling instant relief (reinforcement for future avoidance).","src":"Textbook Ch 2, p. 55","ch":"W4-C7","added":"2026-10-26"},{"id":"W4-T-tb-placebo-effect","term":"Placebo effect","def":"People improve while taking pills that contain inactive compounds. The textbook reports it is significant in studies of depression and can exceed 30%.","src":"Textbook Ch 2, p. 56","ch":"W4-C7","added":"2026-10-26"},{"id":"W4-T-tb-self-injury","term":"Self-injury","def":"Cutting, burning, hitting or other self-inflicted harm, sometimes mistaken for a suicide attempt. A maladaptive coping strategy believed to relieve unbearable psychological distress, perhaps through the release of endorphins. It should be taken very seriously because it may signal an increased risk of suicide.","src":"Textbook Ch 2, p. 49","ch":"W4-C7","added":"2026-10-26"},{"id":"W4-T-tb-suicide-risk-factors","term":"Suicide warning signs and risk factors (textbook)","def":"Warning signs: expressing a wish to be dead or revealing planned methods, increasing social withdrawal and isolation, and a sudden, unexplained lightening of mood (which can mean the person has decided to act). Risk factors: previous attempts, suicide by a family member or friend, readily available means such as guns or pills, a history of substance abuse or eating disorders, and serious medical problems.","src":"Textbook Ch 2, p. 48","ch":"W4-C7","added":"2026-10-26"},{"id":"W4-T-tb-peer-counselling","term":"Peer counselling and support groups","def":"Peer counselling is usually done by volunteer students with special training that emphasizes confidentiality; they may steer you to a campus or community resource or simply listen. Support groups bring together people with a specific shared problem, such as eating disorders or substance abuse, to share experiences and support one another.","src":"Textbook Ch 2, p. 58","ch":"W4-C7","added":"2026-10-26"},{"id":"W4-T-tb-self-help","term":"Self-help","def":"A smart first step for a personal problem. Behavioural and some cognitive approaches are especially useful: notice self-defeating actions and ideas and combat them by being more assertive, communicating honestly, countering negative thoughts, and confronting rather than avoiding what you fear. Journaling and, for some, religious practice can also help. Be selective with self-help books that make fantastic claims.","src":"Textbook Ch 2, pp. 57-58","ch":"W4-C7","added":"2026-10-26"}],"chapters":[{"id":"W4-C1","title":"Defining psychological health and growing up","src":"W4 Part 1, slides 2-18","blurb":"Maslow, health vs. normality, the dual continua model, Erikson's stages, identity and values.","learn":"<b>Psychological health</b> is our capacity to think, feel and behave in ways that let us enjoy life and manage challenges. It can be defined negatively (absence of illness) or positively (presence of wellness).<br><b>Maslow</b> (1960s) took the positive view. We work up from physiological needs to safety, love and belongingness, self-esteem, and finally <b>self-actualization</b>: realism, acceptance, autonomy, authenticity, capacity for intimacy and creativity.<br>Psychological health is not <b>normality</b>, which only means being close to average. The <b>dual continua model</b> treats mental well-being and mental illness as related but distinct, so having no illness does not guarantee high well-being.<br><b>Erikson</b> described 8 stages, each with a conflict to master. Failing one can cause problems later, such as an identity crisis. <b>Adult identity</b> begins in adolescence and is lifelong. <b>Values</b> help us tell good from bad and guide our choices.","steps":[{"id":"W4-C1-S1","type":"label","fig":"maslow","prompt":"Drag each level of Maslow's hierarchy of needs onto the pyramid, from the base to the top.","src":"W4 Part 1, slide 4"},{"id":"W4-C1-S2","type":"label","fig":"dual","prompt":"Place each quadrant of the dual continua model. Vertical axis: mental well-being (high at the top). Horizontal axis: mental illness (low on the left, high on the right).","src":"W4 Part 1, slide 8"},{"id":"W4-C1-S3","type":"match","prompt":"Match each Erikson conflict to its age. (Trust vs. mistrust is birth to 1 year.)","src":"W4 Part 1, slide 11","pairs":[["Autonomy vs. shame and self-doubt","1 to 3 years"],["Initiative vs. guilt","3 to 6 years"],["Industry vs. inferiority","6 to 12 years"],["Identity vs. identity confusion","Adolescence"],["Intimacy vs. isolation","Young adulthood"],["Generativity vs. self-absorption","Middle adulthood"],["Integrity vs. despair","Older adulthood"]]},{"id":"W4-C1-S4","type":"mcq","ch":"W4-C1","added":"2026-10-26","src":"W4 Part 1, slide 11","case":"Two-year-old Theo insists on walking without holding hands and feeding himself. His parents let him try while setting clear limits.","q":"Which Erikson conflict is Theo working through?","opts":[["Autonomy vs. shame and self-doubt",true,"Ages 1 to 3, with parents as the important people. The task is learning self-control through locomotion and exploration without losing assertiveness."],["Initiative vs. guilt",false,"That stage is 3 to 6 years and centres on developing a conscience through playful talking and locomotion."],["Trust vs. mistrust",false,"That stage is birth to 1 year and centres on being fed and comforted by a primary caregiver."],["Industry vs. inferiority",false,"That stage is 6 to 12 years and centres on school and accomplishment with peers."]]}],"summary":"Psychological health is the presence of wellness, not just the absence of illness or being average. It keeps developing across life through Erikson's stages, adult identity and values."},{"id":"W4-C2","title":"Self-esteem, defences and everyday challenges","src":"W4 Part 1, slides 19-31","blurb":"Spiritual wellness, self-concept, self-talk, defence mechanisms, optimism, assertiveness, loneliness and anger.","learn":"<b>Spiritual wellness</b> is linked to better coping, longer life expectancy, lower disease risk, faster recovery and better emotional health, possibly through social support, healthy habits, a positive attitude and moments of relaxation.<br>A positive <b>self-concept</b> starts in childhood and depends on <b>integration</b>: you built your self-image yourself instead of adopting one others made. To protect self-esteem, notice your thinking patterns, avoid <b>cognitive distortions</b> and use <b>realistic self-talk</b>.<br>When our wants clash with others or our conscience and we cannot change the situation, we may use <b>defence mechanisms</b> (Table 2.2) to resolve the conflict inside our heads.<br><b>Pessimists</b> expect failure and feel they deserve it; disputing negative self-talk helps. <b>Assertiveness</b> is confident and direct but not hostile. Learning to be happy alone helps with <b>loneliness</b>. Overtly hostile people are at higher risk of heart attacks, so reframe and distract when anger builds.","steps":[{"id":"W4-C2-S1","type":"match","prompt":"Match each cognitive distortion to the negative self-talk that shows it.","src":"W4 Part 1, slide 23","pairs":[["Focusing on negatives","Babysitting is such a pain. I wish I didn't need the extra money so badly."],["Expecting the worst","I know I'm going to fail this course. I should just drop out now."],["Overgeneralizing","My hair is a mess and I'm gaining weight. No one would ever want to date me."],["Minimizing","Everyone ate the dinner I cooked even though I ruined it. I'm such a rotten cook."],["Blaming others","Everyone I meet is such a jerk. Why aren't people friendlier?"],["Expecting perfection","I can't believe I flubbed that solo. They won't even let me audition next year."],["Thinking in black and white","After what Mike said today, I realize we have nothing in common."]]},{"id":"W4-C2-S2","type":"sort","prompt":"Which defence mechanism is each person using?","src":"W4 Part 1, slides 25-26","bins":["Projection","Displacement","Rationalization","Reaction formation"],"items":[["Dev resents his lab partner but keeps insisting that the lab partner has a problem with him.",0,"He treats his own unacceptable feeling as if it came from outside himself."],["Furious at her coach after practice, Aisha comes home and slams doors at her roommate.",1,"Her anger at one person is shifted onto another person."],["Leo is not picked for a leadership role he badly wanted and tells himself it would have taken too much time anyway.",2,"He gives a false, acceptable reason in place of the real, painful one."],["Nina envies a classmate's grades and goes out of her way to praise her loudly in front of everyone.",3,"She hides envy by exaggerating the opposite feeling."],["A worker who is angry at a rude customer later yells at his younger brother over nothing.",1,"The feeling about the customer is moved onto his brother."],["A student who is tempted to cheat on an exam becomes convinced that everyone else in the room is cheating.",0,"His own unacceptable impulse is seen as coming from other people."],["Sam skips the campus gym and tells himself it is to rest his muscles, when really he feels self-conscious there.",2,"A false but acceptable reason covers the real one."],["A man who feels hostile toward his new step-parent is extremely polite to them and buys them gifts.",3,"Hostility is concealed by exaggerated kindness, the opposite impulse."]]},{"id":"W4-C2-S3","type":"order","prompt":"Put the steps for dealing with anger in other people in the order the slides give them.","src":"W4 Part 1, slide 31","items":["React with calmness","Validate their feelings","Try to solve the problem","When all else fails, disengage"],"why":"Start calm, show the person their feelings are understood, then work on the problem. Disengaging is the last resort when nothing else works."},{"id":"W4-C2-S4","type":"mcq","ch":"W4-C2","added":"2026-10-26","src":"W4 Part 1, slides 23, 25, 29-30","case":"Since moving into residence, Theo spends most Friday nights alone. He reads each one as proof that nobody likes him and feels miserable whenever he is by himself.","q":"Based on the slides, what would help Theo most?","opts":[["Venting his anger openly at floormates, since expressing anger is good for health",false,"Slide 30: studies suggest overtly hostile people are at higher risk for heart attacks."],["Learning to be happy by himself and not reading time alone as a sign of rejection",true,"Slide 29: unhappiness with being alone may come from interpreting it as rejection, and being happy alone helps you cope when you must be alone."],["Telling himself he prefers being alone even though he does not",false,"That is rationalization, a defence mechanism that gives a false reason instead of dealing with the feeling."],["Focusing on the worst outcomes so he is never disappointed",false,"Expecting the worst and focusing on negatives are cognitive distortions to avoid."]]}],"summary":"Realistic self-talk, healthy self-concept and assertive communication protect self-esteem. Defence mechanisms rearrange thoughts and feelings when a conflict cannot be solved in the outside world."},{"id":"W4-C3","title":"Psychological disorders and anxiety","src":"W4 Part 2, slides 2-12","blurb":"What counts as a disorder, the DSM-5, how common mental illness is in Canada, and the anxiety disorders.","learn":"A <b>psychological disorder</b> is present when anxiety, low mood or irrational thoughts interfere with daily life and rob us of peace of mind. Contributing factors include genetics, learning and life events, trauma, and parental and peer influences. The <b>DSM-5</b> lists many conditions, from mood and anxiety disorders to ADHD and dementias.<br>Mental illness is common: 1 in 5 Canadians live with one in any given year. Ethnicity can affect how symptoms are expressed, along with assimilation and biological risk factors.<br><b>Anxiety</b> is fear not tied to a definite threat; it is a problem when it is out of proportion to the danger. Types: specific phobia, social anxiety disorder, panic disorder (with agoraphobia), GAD, OCD, behavioural addictions and PTSD.<br>Treatment ranges from antianxiety drugs such as <b>benzodiazepines</b> (Valium, which enhances GABA) to <b>cognitive-behavioural therapy</b>, usually a combination of the two.","steps":[{"id":"W4-C3-S1","type":"table","src":"W4 Part 2, slide 7","prompt":"Read Figure 2.3, then answer the questions.","caption":"Figure 2.3: 12-month prevalence of selected mental disorders in Canada, 2012 and 2022 (Statistics Canada, 2023). Values are read off the bar chart, so they are approximate.","head":["Disorder","Group","2012","2022"],"rows":[["Major depressive episode","Mood disorder","about 4.7%","about 7.6%"],["Bipolar disorder","Mood disorder","about 1.5%","about 2.1%"],["Generalized anxiety disorder","Anxiety disorder","about 2.6%","about 5.2%"],["Social phobia","Anxiety disorder","about 3.0%","about 7.1%"]],"qs":[{"id":"W4-C3-S1a","type":"mcq","ch":"W4-C3","added":"2026-10-26","src":"W4 Part 2, slide 7","q":"Which disorder had the largest increase in 12-month prevalence from 2012 to 2022?","opts":[["Major depressive episode",false,"About 4.7% to 7.6%, a rise of roughly 3 points."],["Generalized anxiety disorder",false,"About 2.6% to 5.2%, a rise of roughly 2.6 points."],["Social phobia",true,"About 3.0% to 7.1%, a rise of roughly 4 percentage points."],["Bipolar disorder",false,"About 1.5% to 2.1%, the smallest change."]]},{"id":"W4-C3-S1b","type":"mcq","ch":"W4-C3","added":"2026-10-26","src":"W4 Part 2, slide 7","q":"Which statement does Figure 2.3 support?","opts":[["Bipolar disorder was the most common of the four disorders in 2022",false,"It was the least common, at about 2.1%."],["Mood disorders decreased while anxiety disorders increased",false,"All four disorders increased."],["Social phobia was less common than generalized anxiety disorder in 2022",false,"Social phobia (about 7.1%) was higher than GAD (about 5.2%)."],["Generalized anxiety disorder prevalence roughly doubled from 2012 to 2022",true,"About 2.6% in 2012 and about 5.2% in 2022."]]}]},{"id":"W4-C3-S2","type":"match","prompt":"Match each Canadian statistic from slide 4 to the condition it describes.","src":"W4 Part 2, slide 4","pairs":[["1 in 5 Canadians in any given year","Living with a mental illness"],["14% of Canadians in their lifetime","Major depressive disorder"],["13.3% of Canadians in their lifetime","Generalized anxiety disorder"],["21.6% of Canadians","Substance use disorder"],["3.4% of Canadians","Bipolar disorder"],["About 1% of Canadians","Schizophrenia"],["About 0.3 to 1%, with a rate 10 times higher in women","Eating disorder"]]},{"id":"W4-C3-S3","type":"sort","prompt":"Sort each person into the anxiety disorder that best fits.","src":"W4 Part 2, slides 8-11","bins":["Specific phobia","Social anxiety disorder","Panic disorder","Generalized anxiety disorder","Obsessive-compulsive disorder","Post-traumatic stress disorder"],"items":[["Jun avoids hiking trips because standing anywhere high terrifies him.",0,"Fear of something definite, such as heights."],["Bea dreads presentations because she fears looking foolish while classmates watch.",1,"Fear of humiliation or embarrassment while being observed."],["Out of nowhere in a grocery line, Raj's heart pounds, he can't catch his breath and he feels he is losing control of his mind.",2,"A sudden, unexpected surge of anxiety with physical symptoms and a feeling of losing mental control."],["Kim worries constantly about grades, money, her parents' health and the weather, and cannot switch it off.",3,"Excessive, uncontrollable worry about all kinds of things."],["Ola has recurring unwanted thoughts that her hands are contaminated and washes them over and over.",4,"A recurrent unwanted thought (obsession) plus a repetitive, hard-to-resist action (compulsion)."],["Months after a serious car crash, Ben keeps reliving it in nightmares and flashbacks.",5,"Reliving a severely traumatic event through dreams and flashbacks."],["Lia won't eat in the dining hall because she fears people will watch her and judge her.",1,"The fear is about being observed and embarrassed."],["Sam cannot go near any dog, even a puppy on a leash.",0,"Fear of a particular animal."]]},{"id":"W4-C3-S4","type":"mcq","ch":"W4-C3","added":"2026-10-26","src":"W4 Part 2, slide 12","case":"A physician prescribes a benzodiazepine to a patient with generalized anxiety disorder and refers them to a therapist who will work on their thoughts and behaviours.","q":"Which statement about this plan matches the slides?","opts":[["It combines an antianxiety drug that enhances GABA with cognitive-behavioural therapy, which is the usual approach",true,"Slide 12: benzodiazepines like Valium enhance GABA, and treatment is usually a combination of medication and CBT."],["Benzodiazepines work by blocking the reuptake of serotonin",false,"That describes SSRIs, an antidepressant class. Benzodiazepines enhance GABA."],["Medication and therapy should not be combined for anxiety disorders",false,"The slide says treatment is usually a combination of the two."],["The therapy will focus on unconscious impulses from early life",false,"That is the psychodynamic model. CBT concentrates on thoughts and behaviours."]]}],"summary":"Mental illness is common in Canada, and both mood and anxiety disorders rose from 2012 to 2022. Anxiety disorders differ by what triggers the fear, and treatment usually combines medication with CBT."},{"id":"W4-C4","title":"Mood disorders, treatment and getting help","src":"W4 Part 2, slides 13-17, 23-35","blurb":"Depression and bipolar disorder, how they are measured and treated, schizophrenia, four models of human nature, and getting help.","learn":"<b>Mood disorders</b> are emotional disturbances intense and persistent enough to affect normal functioning. 7.6% of Canadians aged 15 and up have had a major depressive episode; women are twice as likely as men. Symptoms include <b>dysphoria</b> (sadness, hopelessness), <b>anhedonia</b> (loss of pleasure), sleep and appetite changes, self-loathing and <b>rumination</b>.<br><b>Unipolar</b> depression brings negative moods and loss of interest; <b>persistent depressive disorder</b> means mild or moderate symptoms for 2 years or longer. In <b>bipolar disorder</b> a person swings between mania and depression. Scales such as the Beck Depression Inventory track symptoms over time.<br>80% respond well to treatment, yet only 10% seek it. Options: antidepressants, psychotherapy (IPT, CBT), exercise as an adjunct, rTMS, ECT for severe cases, and light therapy for SAD.<br><b>Schizophrenia</b> affects about 1%. Four models (biological, behavioural, cognitive, psychodynamic) guide treatment.","steps":[{"id":"W4-C4-S1","type":"match","prompt":"Match each treatment to how the slides describe its use.","src":"W4 Part 2, slides 12, 23-25","pairs":[["Light therapy","Typical treatment for seasonal affective disorder (SAD)"],["Electroconvulsive therapy (ECT)","May be used for severe depression"],["Interpersonal psychotherapy (IPT)","Works on relationship problems and events that may have triggered depression"],["Cognitive and behavioural therapies","Address learned beliefs and behaviours that contribute to the mood disorder"],["Exercise","Sometimes used as an adjunct to other treatments"],["SSRIs","Selective serotonin reuptake inhibitors, an antidepressant class"],["Benzodiazepines (Valium)","Medication listed for anxiety"]]},{"id":"W4-C4-S2","type":"compare","src":"W4 Part 2, slides 27-28","prompt":"Psychotherapy or pharmacotherapy? Pick the one whose pros fit each person best.","a":{"name":"Psychotherapy","points":["Pro: can give long-term skills that last after treatment","Pro: can reduce relapse rates","Pro: effective for several types of psychological disorders","Pro: no side effects","Con: depression can impair executive functioning, making the cognitive control therapy needs hard","Con: not as effective in severe depression (needs a combination with drugs)"]},"b":{"name":"Pharmacotherapy","points":["Pro: easier to access than psychotherapy","Pro: recommended for severe depression","Pro: some disorders need medication to relieve symptoms","Requires a visit to a family doctor or psychiatrist","Con: side effects can be severe (GI and sexual problems, fainting, dry mouth)","Con: poor compliance, hard to find the right drug and dose, tolerance, relapse, drug interactions"]},"scenarios":[["Ravi wants to learn skills he can keep using after treatment ends.",0,"Psychotherapy can provide long-term skills that last after treatment."],["Dana's depression is severe, and her doctor wants the option the slides recommend for severe cases.",1,"Pharmacotherapy is recommended for severe depression; psychotherapy alone is not as effective there."],["Jess had bad reactions to medications before and wants a treatment with no side effects.",0,"Psychotherapy is listed as having no side effects."],["Tom lives far from any therapist and needs the option that is easier to access.",1,"Pharmacotherapy is easier to access than psychotherapy."],["Alex's main goal is lowering the chance of relapse.",0,"Psychotherapy can reduce relapse rates; with medication, people can relapse."]]},{"id":"W4-C4-S3","type":"match","prompt":"Match each model of human nature to its view of what drives behaviour.","src":"W4 Part 2, slide 31","pairs":[["Biological model","The mind's activity depends entirely on the brain and its genetic makeup"],["Behavioural model","Stimulus, response and reinforcement determine behaviour"],["Cognitive model","Attitudes, expectations and motives determine behaviour"],["Psychodynamic model","Unconscious ideas and impulses feed thoughts and behaviours"]]},{"id":"W4-C4-S4","type":"mcq","ch":"W4-C4","added":"2026-10-26","src":"W4 Part 2, slides 13, 33","q":"Which situation most clearly shows that professional help is indicated, according to the slides?","opts":[["A student feels down for an afternoon after a low quiz mark",false,"Daily, temporary mood changes typically don't affect overall emotional state (slide 13)."],["A student's anxiety has grown so strong that she stopped going to class and avoids her friends",true,"Slide 33: help is indicated when emotional problems seriously interfere with school, work or relationships."],["A student feels nervous before a big exam but studies and writes it",false,"This fear fits the situation and does not interfere with functioning."],["A student enjoys spending some evenings alone reading",false,"Being happy by yourself is a healthy skill, not a warning sign."]]}],"summary":"Depression is common and treatable, but few people seek treatment. Psychotherapy and medication each have trade-offs, and severe cases often need both."},{"id":"W4-C5","title":"Suicide: warning signs and getting help","src":"W4 Part 2, slides 4, 18 to 22","added":"2026-10-26","blurb":"Why severe depression raises risk, the IS PATH WARM signs, common myths and what to do.","learn":"Suicide is one of the principal dangers of severe depression. Risk is greater when symptoms are numerous and severe, although an attempt can also happen unpredictably. In Canada, suicide is the second leading cause of death among people aged 15 to 34, and the suicide mortality rate for males is about three times the rate for females (Fig 2.4, 2006 to 2020).<br><br>Warning signs follow the mnemonic <b>IS PATH WARM?</b>: Ideation, Substance abuse, Purposeless, Anxiety, Trapped, Hopelessness, Withdrawal, Anger, Recklessness, Mood changes.<br><br>Table 2.3 corrects common myths: most people who die by suicide have talked about it; few people are single-minded about it; many are not mentally ill by ordinary criteria. If you are worried about someone: expert help is essential, do not be afraid to discuss suicide, and do not leave the person alone if the danger seems immediate. Campus and crisis resources (Counselling Services, Good2Talk, Here 24/7) are listed in the course outline.","summary":"Know the IS PATH WARM signs, know that talking about suicide is a warning sign and not a reason to do nothing, and know that expert help is essential.","steps":[{"id":"W4-C5-S1","type":"match","prompt":"Match each letter of IS PATH WARM? to its warning sign.","src":"W4 Part 2, slide 21","pairs":[["I","Ideation"],["S","Substance abuse"],["P","Purposeless"],["T","Trapped"],["H","Hopelessness"],["W","Withdrawal"],["R","Recklessness"]]},{"id":"W4-C5-S2","type":"sort","prompt":"Table 2.3: myth or fact?","src":"W4 Part 2, slide 20","bins":["Myth","Fact (per Table 2.3)"],"items":[["People who really intend to kill themselves do not let anyone know.",0,"Most people who eventually die by suicide have talked about doing it."],["Most people who eventually die by suicide have talked about it.",1,"This is the fact that corrects the first myth in Table 2.3."],["People who really want to die will do it regardless of attempts to prevent them.",0,"Few people are single-minded about suicide, even at the moment of attempting it."],["Someone determined today may completely change their mind tomorrow.",1,"Table 2.3 makes this point when correcting the 'regardless of prevention' myth."],["Suicide is proof of mental illness.",0,"Many deaths by suicide are by people who do not meet ordinary criteria for mental illness, though rates are higher with depression, schizophrenia and substance use disorders."],["People inherit suicidal tendencies.",0,"Some depression has a genetic component, but family patterns can also come from identifying with a family member."],["People with depression or schizophrenia have a much higher than average suicide rate.",1,"Table 2.3 states this while correcting the 'proof of mental illness' myth."]]},{"id":"W4-C5-S3","type":"mcq","src":"W4 Part 2, slide 22","case":"Your roommate says they have been thinking about ending their life and that it 'would be easier for everyone'. You think the danger may be immediate.","q":"Which response follows the lecture's guidance?","opts":[["Stay with them and contact expert help right away.",true,"Slide 22: expert help is essential, and do not leave the person alone if the danger seems immediate."],["Avoid the word suicide so you do not put the idea in their head.",false,"Slide 22 says not to be afraid to discuss suicide."],["Give them space for the night and check in tomorrow.",false,"Do not leave the person alone if you feel the danger is immediate."],["Assume they are not serious, since people who mean it do not tell anyone.",false,"That is a myth from Table 2.3. Most people who die by suicide have talked about it."]]}]},{"id":"W4-C6","title":"Reading: Meeting life's challenges","src":"Textbook Ch 2, pp. 34-44","added":"2026-10-26","blurb":"Textbook detail on self-esteem, demoralization, realistic self-talk, communication, loneliness and anger.","learn":"<b>Healthy self-esteem</b> means regarding yourself as good, competent and worthy of love. When a challenge hits, such as a failure or a rejection, the best response is to admit something went wrong and try again, adjusting your goals to your abilities. Denying the problem or blaming others is less productive. The worst response is <b>demoralization</b>: a lasting negative self-concept that sets up a cycle of failure.<br><br>To fight it, notice your thinking and use realistic self-talk. This is <i>not</i> positive thinking. The aim is thoughts that are logical and accurate, based on the facts you have. Otherwise negative beliefs can become <b>self-fulfilling prophecies</b>.<br><br>Defence mechanisms often work for a short time but make permanent solutions harder. Honest communication means knowing what you want and saying it clearly. Loneliness is a passive state, so take action. For your own anger, <b>reframe</b> and distract. For someone else's anger, respond <b>asymmetrically</b>, with calm. Explosive anger (IED) needs professional help.","summary":"Adjust goals instead of giving up, think accurately rather than just positively, say what you want clearly, and meet anger with reframing, distraction or calm.","steps":[{"id":"W4-C6-S1","type":"sort","src":"Textbook Ch 2, p. 39","prompt":"A first-year student gets 52% on a midterm. Sort each reaction by how the textbook rates responses to a challenge to self-concept.","bins":["Best approach","Less productive","Worst: demoralization"],"items":[["'That study plan didn't work. I'll go to office hours and aim for 70 next time.'",0,"Acknowledge that something went wrong and try again."],["'I'll keep my program but take a lighter course load so I can keep up.'",0,"Adjusting goals to your abilities without radically revising your self-concept."],["'Nothing went wrong. That mark doesn't mean anything.'",1,"Denying that anything went wrong may protect self-concept for a while but keeps you from meeting the challenge."],["'The prof wrote an unfair test. It's not on me.'",1,"Blaming someone else is a less productive response."],["'I'm just not smart enough for university. There's no point studying for the final.'",2,"Giving up and feeling ineffective is demoralization."],["'I fail at everything, so I've stopped going to class.'",2,"Giving up reinforces the negative self-concept and starts a cycle of failure."]]},{"id":"W4-C6-S2","type":"match","src":"Textbook Ch 2, p. 41 (Table 2.2)","prompt":"Match each new example to the Table 2.2 defence or coping mechanism it shows.","pairs":[["After a fight with her manager, Priya snaps at her younger brother at dinner.","Displacement"],["Omar resents his lab partner but is sure the lab partner resents him.","Projection"],["Jess agrees to share notes with a classmate she competes with, then 'forgets' every week.","Passive-aggressive behaviour"],["Leo, a heavy drinker, insists alcohol can't hurt him because he works out.","Denial"],["Ana skips the club fair, telling herself the clubs are boring, when she is really afraid no one will talk to her.","Rationalization"],["After failing to make the varsity team, Sam joins an intramural league instead.","Substitution"],["When his laptop dies before a deadline, Ravi jokes that at least it picked a dramatic exit.","Humour"]]},{"id":"W4-C6-S3","type":"mcq","src":"Textbook Ch 2, pp. 39-40","case":"You are waiting for a friend at a restaurant. He is 30 minutes late and has not texted.","q":"Which self-talk matches the textbook's realistic, neutral approach?","opts":[["'He's never late. Something must be holding him up. I'll call and check everything is OK.'",true,"This is the textbook's example: it recognizes a problem may exist but does not judge or assign blame."],["'He isn't coming. He probably finds me boring.'",false,"Negative self-talk: it jumps to an unverified conclusion and personalizes the situation."],["'Everything happens for a reason, and tonight will be amazing no matter what!'",false,"That is positive thinking, which the textbook says is not the same as realistic self-talk based on the facts."],["'He's so inconsiderate. I'll leave and ignore his calls.'",false,"This places blame without knowing the facts."]]},{"id":"W4-C6-S4","type":"mcq","src":"Textbook Ch 2, p. 44","case":"Your housemate storms into the kitchen shouting that you used all the hot water right before her exam.","q":"Which response follows the textbook's advice for dealing with anger in other people?","opts":[["Stay calm, acknowledge she has some reason to be upset, and ask what would help right now.",true,"Respond asymmetrically with calm, validate her, and focus on solving the problem."],["Raise your voice to match hers so she knows you won't be pushed around.",false,"Anger is infectious. The textbook says to react with calm, not anger."],["Apologize over and over and accept any insults, since she is stressed.",false,"Validating does not mean apologizing if you are not to blame, and verbal abuse is always inappropriate."],["Walk out and never raise the hot water issue again.",false,"Disengaging is a temporary last resort. A time-out does not mean permanently avoiding the issue."]]}]},{"id":"W4-C7","title":"Reading: Disorders, models of change and getting help","src":"Textbook Ch 2, pp. 44-58","added":"2026-10-26","blurb":"Textbook detail on anxiety and mood disorders, schizophrenia, suicide risk, the four models and where to get help.","learn":"The textbook adds detail to the anxiety disorders. A <b>simple phobia</b> is the most common and most understandable; fear of blood or injections usually comes from a tendency to faint. <b>Panic disorder</b> can spread into <b>agoraphobia</b>, where avoidance leaves a person nearly housebound. GAD worries are about ordinary concerns, while OCD obsessions are improbable fears. Simple phobias are best treated without drugs.<br><br>Depression usually involves demoralization, and loss of interest or pleasure seems to be universal. <b>Mania</b> brings high energy, little sleep and nonstop talk. A sudden, unexplained lightening of mood can be a suicide warning sign.<br><br>Each model leads to a therapy: biological (medication), behavioural (change reinforcements, use <b>exposure</b>), cognitive (test false ideas) and psychodynamic (speak freely to gain insight). Cognitive behavioural packages combine the middle two. For anxiety disorders, drugs and CBT work equally well, but CBT gains last longer.<br><br>Help ranges from self-help and peer counselling to support groups and mental health professionals.","summary":"Know how the anxiety disorders differ, the textbook's suicide warning signs and risk factors, how each model treats a problem, and the levels of help.","steps":[{"id":"W4-C7-S1","type":"sort","src":"Textbook Ch 2, pp. 44-47","prompt":"Which anxiety disorder does each description fit best?","bins":["Simple phobia","Social anxiety (social phobia)","Panic disorder","Generalized anxiety disorder","Obsessive-compulsive disorder","PTSD"],"items":[["Feels faint and nauseated at the sight of a needle during a flu shot.",0,"Fear of blood or injections is a special kind of simple phobia, usually from a tendency to faint."],["Has avoided high places ever since a fall from a ladder as a child.",0,"A fear of something definite, sometimes starting with a bad experience."],["Turned down a promotion because it would mean presenting to clients.",1,"Fear of humiliation while being observed; people may restrict themselves to jobs that avoid it."],["Gets sudden surges of pounding heart and breathlessness, and now avoids elevators and driving in case it happens there.",2,"Sudden unexpected surges of anxiety, then fear of places where escape is hard or loss of control is dangerous."],["Lies awake worrying about next Friday's exam and how to pay for car repairs; the worry goes in circles.",3,"GAD worries are about ordinary concerns but take on a life of their own."],["Fears having been contaminated by germs and washes their hands dozens of times a day.",4,"An improbable fear (obsession) with a repetitive action (compulsion)."],["Since a serious car crash, has intrusive memories, nightmares and avoids anything linked to the crash.",5,"Reexperiencing the trauma and avoiding reminders are PTSD symptoms."],["Checks again and again that the stove is off before leaving home.",4,"Repeated checking is a common compulsion."]]},{"id":"W4-C7-S2","type":"compare","src":"Textbook Ch 2, p. 55","prompt":"A student is afraid to speak in class. Decide which model each part of his treatment comes from.","a":{"name":"Behavioural model","points":["Focuses on overt behaviour, not brain chemistry or thoughts","Treats problems as maladaptive behaviours or bad habits","Analyzes stimulus, response and reinforcement","Changes the reinforcements; uses exposure for fears"]},"b":{"name":"Cognitive model","points":["Emphasizes the effect of ideas on behaviour and feeling","Behaviour comes from attitudes, expectations and motives","Exposes and tests false ideas that cause anxiety","Substitutes realistic thoughts and repeatedly tests assumptions"]},"scenarios":[["He keeps a diary of each class contribution, how long he spoke and his anxiety level before, during and after.",0,"The textbook's behavioural program starts with a diary of the behaviour."],["He asks himself whether one presentation will really change what classmates think of him.",1,"Critically examining an unrealistic expectation is cognitive therapy."],["He rewards himself with time on a hobby each week he meets his speaking goal.",0,"Contracting to reward success changes the reinforcement."],["He writes out the chain 'say something stupid, lose respect, get a low grade' and tests each link.",1,"Exposing and testing false ideas that produce anxiety is the cognitive approach."],["He deliberately speaks up in every seminar until the fear starts to fade.",0,"Exposure is a behavioural technique."]]},{"id":"W4-C7-S3","type":"mcq","src":"Textbook Ch 2, pp. 48-49","case":"For a month, Dev has been withdrawn and hopeless and has skipped every social plan. This week he suddenly seems calm and cheerful, and he mentioned he 'won't be a problem much longer'.","q":"Which conclusion matches the textbook?","opts":[["The sudden lightening of mood and his comment are warning signs. Ask him directly about suicide and get expert help.",true,"A sudden, unexplained lightening of mood can mean the person has decided to act. Asking direct questions is the best way to find out."],["His mood has lifted, so the risk has passed.",false,"The textbook lists a sudden lightening of mood as a warning sign, not a sign of safety."],["Asking about suicide could give him the idea, so avoid the topic.",false,"You won't give someone an idea they haven't already thought of."],["He is probably just looking for attention, so wait and see.",false,"Most people who die by suicide have talked about it. Expert help is essential."]]},{"id":"W4-C7-S4","type":"mcq","src":"Textbook Ch 2, p. 58","case":"Mia feels stressed about living away from home for the first time. Her marks are fine, she has no thoughts of suicide and no substance use problem. She wants someone confidential to listen and point her to resources.","q":"Which option fits the textbook's description best?","opts":[["Campus peer counselling",true,"Trained student volunteers who emphasize confidentiality and may steer you to resources or simply listen."],["A psychiatrist, to start medication",false,"Psychiatrists are the experts when a medical cause is suspected or medication or hospitalization is needed. None of the strong indications applies here."],["An eating disorders support group",false,"Support groups are organized around a specific shared problem she does not have."],["Nothing until her symptoms are severe",false,"Self-help and peer support are reasonable first steps. Waiting is not advised."]]}]}],"questions":[{"id":"W4-Q01","type":"mcq","ch":"W4-C1","src":"W4 Part 1, slides 2, 7","added":"2026-10-26","q":"Defined positively, psychological health is:","opts":[["The absence of illness",false,"That is the negative definition."],["Being close to average in thoughts and behaviour",false,"That is psychological normality, which the slides say is not the same as psychological health."],["The presence of wellness",true,"Slide 2 gives this as the positive definition."],["Having no symptoms of any disorder",false,"Slide 7: the presence or absence of symptoms alone does not decide whether someone is mentally healthy."]]},{"id":"W4-Q02","type":"mcq","ch":"W4-C1","src":"W4 Part 1, slide 4","added":"2026-10-26","case":"A family that fled a conflict now has stable housing, regular meals and a safe neighbourhood. They have no friends or community in their new city yet.","q":"According to Maslow's hierarchy, which need are they working toward next?","opts":[["Self-esteem",false,"Self-esteem sits above love and belongingness."],["Physiological needs",false,"Food and shelter are already in place."],["Safety and security",false,"They already have safe surroundings."],["Love and belongingness",true,"Physiological and safety needs are met, so the next level is being loved, loving and connected."]]},{"id":"W4-Q03","type":"mcq","ch":"W4-C1","src":"W4 Part 1, slides 5-6","added":"2026-10-26","case":"Hana chooses her university program based on her own interests and standards, even though her parents and friends push her toward a different field.","q":"Which quality of self-actualization does Hana show most clearly?","opts":[["Autonomy",true,"Being independent and inner-directed as opposed to other-directed."],["Realism",false,"Realism means being realistic; the case is about whose direction she follows."],["Capacity for intimacy",false,"That is sharing feelings and thoughts without fear of rejection."],["Creativity",false,"That is renewed appreciation of the world and openness to new experiences."]]},{"id":"W4-Q04","type":"mcq","ch":"W4-C1","src":"W4 Part 1, slide 7","added":"2026-10-26","q":"Which statement matches the slides on what psychological health is not?","opts":[["Psychological diversity is a risk to society, so health means fitting the average",false,"The slide calls psychological diversity a valuable asset to society."],["Being mentally normal simply means being close to average, which is not the same as being psychologically healthy",true,"Slide 7 says this directly."],["A person with no symptoms is by definition mentally healthy",false,"The mere presence or absence of symptoms does not decide this."],["Psychological health can only be defined as the absence of illness",false,"It can also be defined positively as the presence of wellness."]]},{"id":"W4-Q05","type":"mcq","ch":"W4-C1","src":"W4 Part 1, slide 8","added":"2026-10-26","case":"Marco has no symptoms of mental illness, but he says he feels flat and disconnected, with low well-being most days.","q":"Where does Marco sit in the dual continua model?","opts":[["Languishing",false,"Languishing is low well-being with high mental illness."],["Flourishing",false,"Flourishing needs high well-being."],["Vulnerable",true,"Low mental illness with low well-being. The absence of illness does not guarantee high well-being."],["Symptomatic but content",false,"That quadrant has high illness and high well-being."]]},{"id":"W4-Q06","type":"mcq","ch":"W4-C1","src":"W4 Part 1, slide 11","added":"2026-10-26","case":"Four-year-old Zara makes up games and wants to help cook dinner. Her parents scold her harshly every time she tries something new.","q":"Which Erikson conflict is Zara facing, and what is at risk?","opts":[["Autonomy vs. shame and self-doubt; she may lose her capacity for assertiveness",false,"That stage is 1 to 3 years."],["Industry vs. inferiority; she may feel inadequate compared with peers at school",false,"That stage is 6 to 12 years."],["Trust vs. mistrust; she may not trust others to meet her needs",false,"That stage is birth to 1 year."],["Initiative vs. guilt; she may develop a conscience that is too inhibiting",true,"Ages 3 to 6, with family. The task is developing a conscience that is not too inhibiting."]]},{"id":"W4-Q07","type":"mcq","ch":"W4-C1","src":"W4 Part 1, slide 11","added":"2026-10-26","case":"Raj, 52, coaches his daughter's soccer team, mentors new staff at work and sits on a neighbourhood community board.","q":"Which Erikson stage does this fit?","opts":[["Generativity vs. self-absorption",true,"Middle adulthood: doing things for others, including parenting and civic activities."],["Integrity vs. despair",false,"That is older adulthood: affirming the value of life and its ideals."],["Intimacy vs. isolation",false,"That is young adulthood: learning to live and share intimately with others."],["Industry vs. inferiority",false,"That is 6 to 12 years: learning the value of accomplishment and perseverance."]]},{"id":"W4-Q08","type":"mcq","ch":"W4-C1","src":"W4 Part 1, slide 11","added":"2026-10-26","case":"A 16-year-old keeps trying new friend groups, styles and beliefs while she works out what she values and who she is.","q":"Which stage and important people does Table 2.1 link to this?","opts":[["Intimacy vs. isolation, with close friends and sex partners",false,"That is young adulthood."],["Identity vs. identity confusion, with peers",true,"Adolescence: developing a stable sense of your needs, abilities, interpersonal style and values."],["Industry vs. inferiority, with the community",false,"That is 6 to 12 years."],["Initiative vs. guilt, with the family",false,"That is 3 to 6 years."]]},{"id":"W4-Q09","type":"mcq","ch":"W4-C1","src":"W4 Part 1, slides 12-14","added":"2026-10-26","q":"Which statement about adult identity is true according to the slides?","opts":[["It is complete by the end of adolescence",false,"The slides say it is a lifelong process."],["All of its characteristics are permanent once formed",false,"Some characteristics are permanent, others may change over time."],["It begins in adolescence, is a lifelong process, and role models help develop it",true,"Slides 12 and 14 state each part of this."],["Lacking a personal identity has no effect on wellness",false,"Without a personal identity we can feel confused about who we are, which can lead to an identity crisis."]]},{"id":"W4-Q10","type":"mcq","ch":"W4-C1","src":"W4 Part 1, slide 17","added":"2026-10-26","q":"According to the slides, which is NOT part of living according to your values?","opts":[["Considering your options carefully before making a choice",false,"This is listed on slide 17."],["Choosing the best option without pressures that oppose your values",false,"This is listed on slide 17."],["Making a choice and acting on it",false,"This is listed on slide 17."],["Putting off a choice so you never have to act on it",true,"The slides say living by values means making a choice and acting on it rather than doing nothing."]]},{"id":"W4-Q11","type":"mcq","ch":"W4-C2","src":"W4 Part 1, slide 20","added":"2026-10-26","q":"Which is NOT one of the explanations on the slides for why spirituality improves health?","opts":[["Stronger genetic protection against disease",true,"Genetics is not among the explanations given."],["Social support",false,"Listed on slide 20."],["Healthy habits",false,"Listed on slide 20."],["Moments of relaxation",false,"Listed on slide 20, along with a positive attitude."]]},{"id":"W4-Q12","type":"mcq","ch":"W4-C2","src":"W4 Part 1, slide 21","added":"2026-10-26","case":"Jordan's whole sense of who he is comes from what his parents and coach have told him he should be. He has never formed his own view of himself.","q":"Which element that the slides call essential to a positive self-concept is missing?","opts":[["Assertiveness",false,"Assertiveness is about confident, direct communication, not how a self-concept forms."],["Integration",true,"Feeling that you created your own self-concept rather than adopting an image others created."],["Altruism",false,"Altruism is a coping mechanism: serving others without expecting anything back."],["Stability",false,"Stability depends on integration; integration is the missing piece here."]]},{"id":"W4-Q13","type":"mcq","ch":"W4-C2","src":"W4 Part 1, slide 23","added":"2026-10-26","case":"The night before her job interview, Leila thinks: 'I'll freeze and they'll reject me, so there's no point preparing.'","q":"Which cognitive distortion is this?","opts":[["Magnifying events",false,"Magnifying blows up a small thing that already happened, like one stutter in a speech."],["Overgeneralizing",false,"Overgeneralizing draws a sweeping conclusion from a few details."],["Expecting the worst",true,"She predicts failure before it happens and gives up."],["Minimizing",false,"Minimizing downplays good outcomes, like guests eating every bite of a 'ruined' meal."]]},{"id":"W4-Q14","type":"mcq","ch":"W4-C2","src":"W4 Part 1, slide 25","added":"2026-10-26","case":"Nico, 19, vapes daily and has had a cough for weeks. He tells himself vaping can't hurt him because he is young and plays varsity sports.","q":"Which defence mechanism is Nico using?","opts":[["Repression",false,"Repression expels an unpleasant feeling, idea or memory from awareness altogether."],["Projection",false,"Projection treats your own impulses as if they came from outside you."],["Substitution",false,"Substitution replaces a frustrating goal with a more attainable one."],["Denial",true,"Refusing to acknowledge to yourself what you really know to be true."]]},{"id":"W4-Q15","type":"mcq","ch":"W4-C2","src":"W4 Part 1, slide 25","added":"2026-10-26","case":"Priya resents being given the hardest part of a group project. She agrees to do it, then keeps 'forgetting' and misses every deadline.","q":"Which defence mechanism is this?","opts":[["Passive-aggressive behaviour",true,"Hostility expressed by being covertly uncooperative or passive."],["Acting out",false,"Acting out is an action that makes the feeling go away, such as getting into a fight."],["Displacement",false,"Displacement shifts feelings about one person onto a different person."],["Reaction formation",false,"Reaction formation would mean showing exaggerated enthusiasm for the task."]]},{"id":"W4-Q16","type":"mcq","ch":"W4-C2","src":"W4 Part 1, slide 25","added":"2026-10-26","case":"After failing to make the varsity hockey team, Ethan deliberately sets a new goal of becoming captain of his intramural team.","q":"Which mechanism is Ethan using?","opts":[["Rationalization",false,"Rationalization would be telling himself he never wanted to make varsity."],["Substitution",true,"Deliberately replacing a frustrating goal with one that is more attainable."],["Denial",false,"He is not refusing to acknowledge what happened."],["Altruism",false,"Altruism is serving others without expecting anything in return."]]},{"id":"W4-Q17","type":"mcq","ch":"W4-C2","src":"W4 Part 1, slide 26","added":"2026-10-26","case":"Dylan feels disrespected after being passed over at work. That night he picks a fight at a bar to make the feeling go away.","q":"Which mechanism from Table 2.2 fits best?","opts":[["Dissociation",false,"Dissociation detaches from a current experience to avoid distress."],["Substitution",false,"Substitution deliberately swaps in a more attainable goal."],["Acting out",true,"Engaging in an action that makes an unacceptable feeling go away."],["Reaction formation",false,"Reaction formation exaggerates the opposite feeling, such as being overly friendly."]]},{"id":"W4-Q18","type":"mcq","ch":"W4-C2","src":"W4 Part 1, slide 25","added":"2026-10-26","case":"Ines is attracted to her best friend's partner but becomes convinced that the partner is the one flirting with her.","q":"Which defence mechanism is Ines using?","opts":[["Reaction formation",false,"That would mean acting cold or hostile toward the partner to hide the attraction."],["Displacement",false,"Displacement shifts feelings about one person onto a different person."],["Denial",false,"Denial refuses to acknowledge a fact; here she relocates her impulse onto someone else."],["Projection",true,"She reacts to her own unacceptable impulse as if it came from outside herself."]]},{"id":"W4-Q19","type":"mcq","ch":"W4-C2","src":"W4 Part 1, slides 25-26","added":"2026-10-26","case":"While his parents argue loudly, 10-year-old Sami mentally replays every level of his favourite video game until the argument is over.","q":"Which mechanism is Sami using?","opts":[["Dissociation",true,"Detaching from a current experience to avoid emotional distress."],["Repression",false,"Repression expels a feeling, idea or memory from awareness; Sami is tuning out something happening now."],["Humour",false,"Humour finds something funny in the situation."],["Rationalization",false,"Rationalization gives a false, acceptable reason for something."]]},{"id":"W4-Q20","type":"mcq","ch":"W4-C2","src":"W4 Part 1, slide 27","added":"2026-10-26","q":"Which statement about pessimism matches the slides?","opts":[["It is inherited and cannot be changed",false,"The slide says it is typically learned."],["It is typically learned young from parents or other authority figures, and overcoming it means disputing negative self-talk",true,"Slide 27 states both points."],["Pessimists expect failure but feel they do not deserve it",false,"Pessimists expect failure and rejection and feel they deserve it."],["Expressing anger openly is the main way to overcome it",false,"The slides tie overcoming pessimism to disputing irrational, negative self-talk."]]},{"id":"W4-Q21","type":"mcq","ch":"W4-C2","src":"W4 Part 1, slides 25, 28","added":"2026-10-26","case":"Your roommate plays loud music past midnight on weeknights, and you have 8:30 classes.","q":"Which response is assertive as the slides define it?","opts":[["Say nothing and hope they notice how tired you look",false,"This avoids clear communication, often from fear of rejection."],["'You are the most inconsiderate person I have ever lived with.'",false,"This is hostile, not assertive."],["'I need quiet after 11 on weeknights so I can sleep. Could you use headphones after that?'",true,"Confident and direct but not hostile."],["Agree it's fine, then quietly unplug their speaker whenever they leave",false,"This is covertly uncooperative, which is passive-aggressive behaviour."]]},{"id":"W4-Q22","type":"mcq","ch":"W4-C3","src":"W4 Part 2, slide 3","added":"2026-10-26","q":"Which statement about the DSM-5 matches the slides?","opts":[["It lists only anxiety disorders, mood disorders and schizophrenia",false,"Those are the three types the textbook focuses on; the DSM-5 lists more."],["It is a Statistics Canada survey of how common mental disorders are",false,"That describes the source of Figure 2.3."],["It excludes substance use disorders and dementias",false,"Both are on the DSM-5 list on slide 3."],["It lists a wider range of conditions than the textbook covers, including ADHD and autism spectrum disorders",true,"Slide 3 says this and lists both."]]},{"id":"W4-Q23","type":"mcq","ch":"W4-C3","src":"W4 Part 2, slide 4","added":"2026-10-26","q":"According to the slides, how many Canadians are living with a mental illness in any given year?","opts":[["1 in 5",true,"Slide 4."],["1 in 10",false,"Too low; slide 4 says 1 in 5."],["1 in 3",false,"Too high; slide 4 says 1 in 5."],["1 in 100",false,"About 1% is the figure for schizophrenia."]]},{"id":"W4-Q24","type":"mcq","ch":"W4-C3","src":"W4 Part 2, slide 4","added":"2026-10-26","q":"Of these conditions on slide 4, which has the highest percentage of Canadians affected?","opts":[["Major depressive disorder",false,"14% over a lifetime."],["Substance use disorder",true,"21.6% of Canadians."],["Generalized anxiety disorder",false,"13.3% over a lifetime."],["Bipolar disorder",false,"3.4%."]]},{"id":"W4-Q25","type":"mcq","ch":"W4-C3","src":"W4 Part 2, slide 4","added":"2026-10-26","q":"Which statement about eating disorders matches slide 4?","opts":[["They affect about 3.4% of Canadians",false,"3.4% is the figure for bipolar disorder."],["They are about 10 times more common in men",false,"The rate is 10 times higher for women."],["About 0.3 to 1% of Canadians experience one, the rate is 10 times higher in women, and they have the highest mortality rate of any mental illness",true,"All three points are on slide 4."],["They have the lowest mortality rate of any mental illness",false,"They have the highest mortality rate."]]},{"id":"W4-Q26","type":"mcq","ch":"W4-C3","src":"W4 Part 2, slide 6","added":"2026-10-26","case":"Uma feels intense dread every time she opens her email, though nothing bad has ever arrived and there is no specific threat.","q":"According to the slides, when does fear like this become a problem?","opts":[["Any time fear is felt at all",false,"Everyone feels anxious at times; that alone is not a disorder."],["Only once it has lasted 2 years or longer",false,"The 2-year rule is for persistent depressive disorder."],["Only when it comes with hallucinations",false,"Hallucinations are linked to schizophrenia and PTSD, not the definition of anxiety."],["When it is disproportionate to the actual danger",true,"Slide 6: fear out of proportion to the danger can be considered a problem."]]},{"id":"W4-Q27","type":"mcq","ch":"W4-C3","src":"W4 Part 2, slide 10","added":"2026-10-26","case":"Dev has recurring, unwanted thoughts that he left the stove on, and he checks it 15 times before he can leave home.","q":"In OCD terms, the repeated checking is:","opts":[["A compulsion: a repetitive, difficult-to-resist action",true,"Compulsions are the actions; obsessions are the thoughts."],["An obsession: a recurrent, unwanted thought",false,"The thought about the stove is the obsession; the checking is the action."],["A panic attack: a sudden surge of anxiety",false,"Panic disorder involves sudden, unexpected surges with physical symptoms."],["A specific phobia: fear of something definite",false,"A phobia is fear of a definite object or situation, such as heights."]]},{"id":"W4-Q28","type":"mcq","ch":"W4-C3","src":"W4 Part 2, slide 9","added":"2026-10-26","case":"During a lecture, with no warning, Ana's heart races, she is short of breath and dizzy, and she fears she is losing control of her mind.","q":"Which anxiety disorder do these symptoms describe?","opts":[["Generalized anxiety disorder",false,"GAD is ongoing, excessive worry about many things, not a sudden surge."],["Panic disorder",true,"Sudden, unexpected surges of anxiety with a racing heart, shortness of breath, loss of equilibrium and a feeling of losing mental control."],["Social anxiety disorder",false,"That is fear of embarrassment while being observed."],["Post-traumatic stress disorder",false,"PTSD involves reliving a traumatic event."]]},{"id":"W4-Q29","type":"mcq","ch":"W4-C4","src":"W4 Part 2, slide 15","added":"2026-10-26","case":"Since the fall, Lucy no longer enjoys painting or playing piano, activities she used to love.","q":"Which symptom of depression is this?","opts":[["Dysphoria",false,"Dysphoria is a feeling of sadness and hopelessness."],["Rumination",false,"Rumination is constantly thinking about past bad events."],["Anhedonia",true,"Loss of pleasure in doing usual activities."],["Self-loathing",false,"Self-loathing is thoughts of worthlessness and guilt."]]},{"id":"W4-Q30","type":"mcq","ch":"W4-C4","src":"W4 Part 2, slide 15","added":"2026-10-26","case":"Mateo keeps replaying an argument from last year and a failed exam from high school, over and over, for hours.","q":"Which symptom does this describe?","opts":[["Anhedonia",false,"Anhedonia is loss of pleasure in usual activities."],["Mania",false,"Mania is restlessness, euphoria, recklessness and lots of energy."],["Dysphoria",false,"Dysphoria is a feeling of sadness and hopelessness, not repeated replaying of events."],["Rumination",true,"Constantly thinking about past bad events."]]},{"id":"W4-Q31","type":"mcq","ch":"W4-C4","src":"W4 Part 2, slide 16","added":"2026-10-26","case":"For the past 3 years, Joy has had mild to moderate depressive symptoms that never fully go away.","q":"Which diagnosis fits best?","opts":[["Persistent depressive disorder",true,"Persistent mild or moderate depressive symptoms for 2 years or longer."],["Bipolar disorder",false,"There are no swings into mania."],["Seasonal affective disorder",false,"Her symptoms are constant, not tied to a season."],["Generalized anxiety disorder",false,"GAD is excessive, uncontrollable worry; her main symptoms are depressive."]]},{"id":"W4-Q32","type":"mcq","ch":"W4-C4","src":"W4 Part 2, slides 15-16","added":"2026-10-26","case":"For several weeks Leo is restless, euphoric, takes reckless risks and seems to have endless energy. Later he becomes sad and hopeless and loses interest in everything.","q":"Which disorder does this pattern describe?","opts":[["Unipolar disorder",false,"Unipolar depression has negative moods without manic states."],["Bipolar disorder",true,"Swinging between opposite states of mania and depression."],["Persistent depressive disorder",false,"That is long-lasting mild or moderate depression, with no mania."],["Schizophrenia",false,"Schizophrenia involves symptoms such as delusions and auditory hallucinations, not mood swings between mania and depression."]]},{"id":"W4-Q33","type":"mcq","ch":"W4-C4","src":"W4 Part 2, slide 17","added":"2026-10-26","case":"A counsellor has a client complete the Beck Depression Inventory at the first session and again 8 weeks later.","q":"What is the main purpose of using the scale this way?","opts":[["To choose which antidepressant to prescribe",false,"Counsellors do not prescribe; the scale measures symptoms."],["To diagnose schizophrenia",false,"The Beck Depression Inventory measures depressive symptoms."],["To measure the intensity of symptoms and how they change over time",true,"Slide 17: rating scales measure symptom intensity and changes over time."],["To uncover unconscious impulses",false,"That is the aim of the psychodynamic approach, not a rating scale."]]},{"id":"W4-Q34","type":"mcq","ch":"W4-C4","src":"W4 Part 2, slide 23","added":"2026-10-26","case":"Every winter Sofia's mood drops and she sleeps much more, then she recovers in spring. She is diagnosed with seasonal affective disorder.","q":"Which treatment do the slides list as typical for her condition?","opts":[["Electroconvulsive therapy",false,"ECT is listed for severe depression."],["Benzodiazepines",false,"Benzodiazepines are listed for anxiety."],["Repetitive transcranial magnetic stimulation",false,"rTMS is listed as a depression treatment, but light therapy is the one named for SAD."],["Light therapy",true,"SAD is typically treated with light therapy."]]},{"id":"W4-Q35","type":"mcq","ch":"W4-C4","src":"W4 Part 2, slides 24, 31","added":"2026-10-26","case":"A therapist helps a client look at conflict with her partner and at the breakup that seemed to trigger her depression, and works to remove her guilt and self-blame.","q":"Which type of psychotherapy is this?","opts":[["Interpersonal psychotherapy (IPT)",true,"IPT focuses on relationship problems and events that may have triggered depression, and removes guilt and self-blame."],["Cognitive and behavioural therapy",false,"That addresses learned beliefs and behaviours that contribute to the mood disorder."],["Psychodynamic therapy",false,"That has patients speak freely to understand unconscious sources of their feelings."],["Electroconvulsive therapy",false,"ECT is not a psychotherapy; it is listed for severe depression."]]},{"id":"W4-Q36","type":"mcq","ch":"W4-C4","src":"W4 Part 2, slide 25","added":"2026-10-26","q":"Which medication on the pharmacological therapy slide is listed for anxiety rather than as an antidepressant class?","opts":[["Selective serotonin reuptake inhibitors (SSRIs)",false,"An antidepressant class."],["Benzodiazepines (Valium)",true,"Listed 'for anxiety'; they enhance GABA."],["Serotonin and norepinephrine reuptake inhibitors (SNRIs)",false,"An antidepressant class."],["Monoamine oxidase inhibitors (MAOIs)",false,"An antidepressant class."]]},{"id":"W4-Q37","type":"mcq","ch":"W4-C4","src":"W4 Part 2, slides 30-31","added":"2026-10-26","case":"In therapy, Ken talks freely about whatever comes to mind so he can understand the basis of his feelings and gain insight.","q":"Which model of human nature guides this treatment?","opts":[["Cognitive model",false,"Cognitive therapy exposes and identifies false ideas that produce anxiety or depression."],["Behavioural model",false,"Behavioural treatment identifies and alters reinforcers of behaviour."],["Psychodynamic model",true,"Unconscious ideas and impulses feed thoughts and behaviours; patients speak freely to gain insight."],["Biological model",false,"Biological treatment is pharmacological therapy."]]},{"id":"W4-Q38","type":"mcq","ch":"W4-C4","src":"W4 Part 2, slide 34","added":"2026-10-26","case":"Amira's family doctor thinks her symptoms may have a medical cause and that she may need medication.","q":"Which professional on the slides can prescribe and determine whether there is a medical cause?","opts":[["Clinical psychologist",false,"Usually holds a PhD and treats with behavioural and cognitive therapies."],["Social worker",false,"Holds a master's degree; skilled in counselling and finding community support."],["Licensed counsellor",false,"Requirements vary; the slides do not describe them as prescribing."],["Psychiatrist",true,"A specialized medical physician who can prescribe medications and check for a medical cause."]]},{"id":"W4-Q39","type":"mcq","ch":"W4-C4","src":"W4 Part 2, slide 29","added":"2026-10-26","q":"Which statement about schizophrenia matches the slides?","opts":[["It is caused by a combination of genes and environmental factors, and symptoms can include delusions and auditory hallucinations",true,"Slide 29 lists both points."],["It affects about 13.3% of Canadians",false,"About 1% of Canadians have been diagnosed; 13.3% is the GAD figure."],["Its symptoms are always severe and debilitating",false,"Symptoms range from severe to mild and hardly noticeable."],["It is treated with light therapy",false,"Treatment may include psychotherapy and medication; light therapy is for SAD."]]},{"id":"W4-Q40","type":"mcq","ch":"W4-C4","src":"W4 Part 2, slide 35","added":"2026-10-26","q":"Which approach to mental health support for Indigenous Peoples in Canada matches the slides?","opts":[["The same standard approach used for every group, without reference to history",false,"The slide stresses respect for the history of colonization and intergenerational trauma."],["Culturally appropriate supports that honour the history and values of the people harmed, with holistic and traditional practices",true,"Slide 35 says these are paramount for healing."],["Medication alone, since challenges are mainly biological",false,"The slide ties the challenges to colonization and intergenerational trauma."],["Avoiding traditional practices in favour of new ones",false,"Holistic and traditional practices are called paramount."]]},{"id":"W4-Q41","ch":"W4-C5","src":"W4 Part 2, slide 21","added":"2026-10-26","q":"In the IS PATH WARM? mnemonic for suicide warning signs, what does the T stand for?","opts":[["Trapped",true,"I-S-P-A-T-H: the T is Trapped."],["Tension",false,"Not part of the mnemonic."],["Trauma",false,"Not part of the mnemonic."],["Tearfulness",false,"Not part of the mnemonic."]]},{"id":"W4-Q42","ch":"W4-C5","src":"W4 Part 2, slide 20","added":"2026-10-26","q":"According to Table 2.3, which statement about suicide is a myth?","opts":[["Suicide is proof of mental illness.",true,"Many deaths by suicide are by people who do not meet ordinary criteria for mental illness."],["Most people who die by suicide have talked about it beforehand.",false,"This is the fact."],["People determined today may change their minds tomorrow.",false,"This is stated as fact."],["People with depression have a higher than average suicide rate.",false,"This is stated as fact."]]},{"id":"W4-Q43","ch":"W4-C5","src":"W4 Part 2, slide 19","added":"2026-10-26","q":"Fig 2.4 shows Canadian suicide mortality rates by sex from 2006 to 2020. What pattern does it show?","opts":[["The male rate is about three times the female rate in every year.",true,"Males sit around 16 to 19 per 100,000; females around 5 to 6."],["The female rate is higher than the male rate in most years.",false,"The male line is above the female line in every year."],["Male and female rates are about equal.",false,"There is a large, steady gap."],["Both rates fell by half between 2006 and 2020.",false,"Both lines are fairly flat across the period."]]},{"id":"W4-Q44","ch":"W4-C5","src":"W4 Part 2, slide 4","added":"2026-10-26","q":"Among Canadians aged 15 to 34, where does suicide rank as a cause of death?","opts":[["Second",true,"Slide 4: suicide is the second leading cause of death among people aged 15 to 34."],["First",false,"Second, per slide 4."],["Fifth",false,"Second, per slide 4."],["Tenth",false,"Second, per slide 4."]]},{"id":"W4-TQ01","ch":"W4-C6","src":"Textbook Ch 2, p. 39","added":"2026-10-26","q":"According to the textbook, what is the best way to react when a challenge hits your self-concept, such as failing at a goal?","opts":[["Acknowledge that something went wrong and try again, adjusting your goals to your abilities.",true,"This is the textbook's best approach; it does not require radically revising your self-concept."],["Deny that anything went wrong so your self-concept stays intact.",false,"Denial is a less productive response. It protects self-concept only temporarily."],["Blame someone else so you can keep your goal unchanged.",false,"Blaming others is also listed as less productive."],["Radically revise your self-concept so you are not disappointed again.",false,"The best approach adjusts goals without radically revising self-concept."]]},{"id":"W4-TQ02","ch":"W4-C6","src":"Textbook Ch 2, p. 39","added":"2026-10-26","q":"Kai fails his driving test twice. He decides he is useless at everything, stops applying for jobs and no longer tries anything new. Which textbook term fits best?","opts":[["Demoralization",true,"A lasting negative self-concept where the person gives up instead of coping, starting a cycle of failure."],["Substitution",false,"Substitution deliberately replaces a frustrating goal with a more attainable one. Kai has given up on goals."],["Rationalization",false,"Rationalization gives a false, acceptable reason for a choice. Kai is not offering an excuse."],["Identity crisis",false,"An identity crisis is confusion about who you are, not giving up after failure."]]},{"id":"W4-TQ03","ch":"W4-C6","src":"Textbook Ch 2, p. 40","added":"2026-10-26","q":"Ella is sure her new lab group finds her annoying, so she stops speaking in meetings. Soon the group stops asking for her opinion. What does the textbook call this pattern?","opts":[["A self-fulfilling prophecy",true,"A negative belief held so firmly that the person's behaviour makes it come true."],["Displacement",false,"Displacement shifts feelings about one person onto another."],["Assertiveness",false,"Assertiveness would mean stating her views clearly, the opposite of what she did."],["Altruism",false,"Altruism is serving others without expecting a return."]]},{"id":"W4-TQ04","ch":"W4-C6","src":"Textbook Ch 2, p. 40","added":"2026-10-26","q":"How does the textbook distinguish realistic self-talk from positive thinking?","opts":[["Realistic self-talk aims for logical, accurate thoughts based on the facts; positive thinking just swaps a negative thought for a positive one.",true,"The textbook says controlling your reactions this way 'is not the same as positive thinking'."],["They are the same thing under different names.",false,"The textbook explicitly says they differ."],["Realistic self-talk means always assuming the best about other people.",false,"It means sticking to the facts as you know them, not assuming the best or the worst."],["Positive thinking is based on facts, while realistic self-talk is based on feelings.",false,"This reverses the idea. Realistic self-talk is the fact-based one."]]},{"id":"W4-TQ05","ch":"W4-C6","src":"Textbook Ch 2, p. 35","added":"2026-10-26","q":"Whenever friends ask Lina's opinion, she says whatever she thinks will make them happy, even when she disagrees. In Maslow's terms as the textbook explains them, Lina is:","opts":[["Other-directed",true,"Other-directed people act in response to outside pressure and say what they believe will please others."],["Inner-directed",false,"Inner-directed people take guidance from their own rules and values."],["Showing authenticity",false,"Authentic people respond in a real, spontaneous way without worrying about being judged."],["Showing an internal locus of control",false,"An internal locus of control goes with autonomy and inner direction."]]},{"id":"W4-TQ06","ch":"W4-C6","src":"Textbook Ch 2, p. 37","added":"2026-10-26","q":"An eight-year-old says lying is wrong 'because the teacher said so and it's against the rules.' Which stage of moral development does the textbook link to this?","opts":[["The older child stage: right and wrong explained by authority figures and rules",true,"The textbook says an older child explains right and wrong in terms of authority figures and rules."],["The young child stage: good means immediate rewards, bad means punishment",false,"That earliest stage is about rewards and punishment, not rules and authority."],["The final stage: right and wrong in abstract terms such as justice and virtue",false,"The child is not reasoning about abstract principles."],["Erikson's integrity vs. despair",false,"That is Erikson's stage for older adulthood, not a stage of moral reasoning."]]},{"id":"W4-TQ07","ch":"W4-C6","src":"Textbook Ch 2, pp. 40, 42","added":"2026-10-26","q":"According to the textbook, what is the main drawback of many defence mechanisms?","opts":[["They succeed temporarily but make finding permanent solutions harder.",true,"Stated directly with Table 2.2."],["They are always deliberate, conscious choices.",false,"The textbook says they have often become habits that occur unconsciously."],["Only people with psychological disorders use them.",false,"Everyone uses them when wants conflict with others or with conscience."],["They work by changing the external situation.",false,"They resolve conflict internally by rearranging thoughts and feelings when the outside situation cannot be changed."]]},{"id":"W4-TQ08","ch":"W4-C6","src":"Textbook Ch 2, p. 42","added":"2026-10-26","q":"Sasha says 'I feel like staying home tonight' when she really wants her partner to suggest a different plan. What problem does the textbook point out with this kind of statement?","opts":[["It avoids a confrontation but is unfair because she is not clear about what she wants.",true,"Good communication means expressing yourself clearly."],["It is too assertive and may sound hostile.",false,"The statement is indirect, not forceful."],["It is an example of displacement.",false,"Displacement shifts feelings from one person to another."],["There is no problem, because avoiding confrontation is always best.",false,"The textbook calls this approach unfair to the other person."]]},{"id":"W4-TQ09","ch":"W4-C6","src":"Textbook Ch 2, p. 42","added":"2026-10-26","q":"Jon never asks his roommate to turn the music down, because he fears a 'no' would mean the roommate dislikes him. What does the textbook suggest could help?","opts":[["Assertiveness training",true,"For people who fear a refusal and take it as personal rejection, learning to insist on their rights and bargain for what they want."],["Antianxiety medication",false,"Nothing suggests a disorder; this is a communication skill problem."],["Repressing his annoyance",false,"Repression is a defence mechanism that would leave the problem unsolved."],["Waiting until the roommate notices on his own",false,"Others can hardly respond to our needs if they do not know them."]]},{"id":"W4-TQ10","ch":"W4-C6","src":"Textbook Ch 2, pp. 42-43","added":"2026-10-26","q":"Which statement about loneliness matches the textbook?","opts":[["Loneliness is a passive feeling state; if you are not spending enough time with people, take action to change it.",true,"The textbook suggests joining a group based on a genuine interest."],["Fear of being alone is the best reason to spend time with others.",false,"The textbook says it is not the best reason to socialize."],["Being alone is a reliable sign that others have rejected you.",false,"Reading time alone as rejection is a thinking pattern to examine."],["Starting a close relationship as quickly as possible is the surest cure.",false,"Pressure to find a relationship may trade loneliness for worse problems."]]},{"id":"W4-TQ11","ch":"W4-C6","src":"Textbook Ch 2, p. 43","added":"2026-10-26","q":"During arguments, Marc sometimes loses control, punches walls and once smashed a friend's phone. Afterward he says he 'couldn't think straight.' Which does the textbook describe, and what does it advise?","opts":[["Intermittent explosive disorder; he should seek professional help.",true,"IED is explosive or misdirected anger that leaves people unable to think straight; anyone who expresses anger this way should get professional help."],["Passive-aggressive behaviour; he should be more direct.",false,"Passive-aggressive behaviour is covert, not explosive."],["Healthy venting; expressing anger protects the heart.",false,"Overtly hostile people seem to be at higher risk for heart attacks."],["Displacement; he should yell at the person he is really angry with.",false,"His anger is aimed at the people he argues with, and yelling is not the advice."]]},{"id":"W4-TQ12","ch":"W4-C6","src":"Textbook Ch 2, p. 43","added":"2026-10-26","q":"A driver cuts in front of you. Feeling your anger rise, you remind yourself that he may not have seen you, or may be rushing to an emergency. Which strategy is this?","opts":[["Reframing",true,"Changing what you are thinking, for example by considering that the behaviour was not aimed at you."],["Distraction",false,"Distraction is counting to 10, focusing on breathing or taking a cooling-off period."],["Responding asymmetrically",false,"That is the strategy for dealing with another person's anger in front of you."],["Rationalization",false,"Rationalization gives a false, acceptable reason for your own unacceptable motive."]]},{"id":"W4-TQ13","ch":"W4-C6","src":"Textbook Ch 2, p. 37","added":"2026-10-26","q":"Noor has changed majors three times and says she doesn't know who she is or what she values. She feels she can't feel good about herself until she figures it out. Which term fits, and why does it affect her self-esteem?","opts":[["Identity crisis; without a self firmly in place, a person cannot have much self-esteem.",true,"Erikson's term for internal confusion about who you are."],["Demoralization; she has given up on all her goals.",false,"She is still searching, not giving up."],["Self-actualization; she is fulfilling her potential.",false,"Self-actualization is the top of Maslow's hierarchy, not confusion about identity."],["Generativity vs. self-absorption; she is focused on herself.",false,"That is Erikson's middle adulthood conflict, about doing things for others."]]},{"id":"W4-TQ14","ch":"W4-C7","src":"Textbook Ch 2, p. 44","added":"2026-10-26","q":"Which anxiety disorder does the textbook call the most common and most understandable?","opts":[["Simple (specific) phobia",true,"A fear of something definite, such as lightning, an animal or a location."],["Generalized anxiety disorder",false,"GAD is described as excessive worry about ordinary concerns, not as the most common."],["Obsessive-compulsive disorder",false,"Not described this way."],["Panic disorder",false,"Not described this way."]]},{"id":"W4-TQ15","ch":"W4-C7","src":"Textbook Ch 2, p. 45","added":"2026-10-26","q":"After several sudden attacks of pounding heart and dizziness, Rosa began avoiding malls, then buses, and now rarely leaves home unless her sister comes with her. What has developed?","opts":[["Agoraphobia, arising from panic disorder",true,"Fears and avoidance spread until the person is virtually housebound; a trusted companion often helps."],["Social anxiety disorder",false,"Social anxiety is fear of humiliation while being observed, not fear of panic attacks."],["Generalized anxiety disorder",false,"GAD is ongoing worry about ordinary concerns, not avoidance after panic attacks."],["A simple phobia of malls",false,"Her fear has spread to many places and is tied to the attacks."]]},{"id":"W4-TQ16","ch":"W4-C7","src":"Textbook Ch 2, p. 46","added":"2026-10-26","q":"According to the textbook, what separates the obsessions of OCD from the worries of GAD?","opts":[["Obsessions are improbable fears, such as of contamination or of suddenly committing an antisocial act; GAD worries are about ordinary concerns.",true,"The textbook draws exactly this contrast."],["GAD worries come with repetitive rituals; obsessions do not.",false,"Rituals (compulsions) go with OCD."],["Obsessions are usually about exams and money.",false,"Exams and money are the textbook's examples of GAD worries."],["GAD worries can be stopped by an effort of will.",false,"GAD worries refuse banishment by any effort of will."]]},{"id":"W4-TQ17","ch":"W4-C7","src":"Textbook Ch 2, p. 47","added":"2026-10-26","q":"According to the textbook, which anxiety disorder is best treated without drugs?","opts":[["Simple phobias",true,"Both drugs and CBT work for panic disorder, OCD and GAD, but simple phobias are best treated without drugs."],["Panic disorder",false,"Drug treatments and CBT are both effective."],["Obsessive-compulsive disorder",false,"Drug treatments and CBT are both effective."],["Generalized anxiety disorder",false,"Drug treatments and CBT are both effective."]]},{"id":"W4-TQ18","ch":"W4-C7","src":"Textbook Ch 2, p. 46","added":"2026-10-26","q":"Ben prefers quiet evenings alone and has no wish to be more social. Cal wishes he could join conversations, but his negative thoughts stop him. Which is correct?","opts":[["Ben is introverted; Cal is shy.",true,"Introverts prefer solitude. Shy people often long to be more outgoing but their negative thoughts get in the way."],["Both are shy.",false,"Ben does not want more social contact, so he is not shy by the textbook's definition."],["Ben is shy; Cal is introverted.",false,"This reverses the definitions."],["Cal has agoraphobia.",false,"Agoraphobia is avoidance of places linked to panic, not social self-consciousness."]]},{"id":"W4-TQ19","ch":"W4-C7","src":"Textbook Ch 2, pp. 48, 60","added":"2026-10-26","q":"Which symptom of depression does the textbook say seems to be universal?","opts":[["Loss of interest or pleasure in things",true,"People can have depression without feeling depressed, but they usually lose interest or pleasure."],["Poor appetite and weight loss",false,"Some people instead eat too much."],["Insomnia",false,"Some people instead sleep too long."],["Feeling sad",false,"People can have most symptoms of depression without feeling depressed."]]},{"id":"W4-TQ20","ch":"W4-C7","src":"Textbook Ch 2, p. 52","added":"2026-10-26","q":"For a week, Tia has slept about three hours a night, talks nonstop, has launched three business ideas and maxed out her credit card. Which does this describe?","opts":[["Mania",true,"Restless, lots of energy, little need for sleep, nonstop talk, fantastic projects and overspending."],["Generalized anxiety disorder",false,"GAD is persistent worry, not elevated energy and mood."],["Dysthymic disorder",false,"That is long-lasting mild or moderate depression."],["Agoraphobia",false,"Agoraphobia is avoidance of places, not elevated mood."]]},{"id":"W4-TQ21","ch":"W4-C7","src":"Textbook Ch 2, p. 51","added":"2026-10-26","q":"Every November, Erik in Yellowknife feels low and sluggish, and every spring he feels better. Which treatment does the textbook describe for this pattern?","opts":[["Sitting in front of a bright light every morning",true,"Light therapy for SAD may work by making the brain perceive a longer day."],["Electroconvulsive therapy as the first step",false,"ECT is for severe depression when other approaches have failed."],["Antipsychotic medication",false,"Antipsychotics target hallucinations and disordered thinking."],["St. John's wort instead of seeing a doctor",false,"The textbook advises a medical evaluation rather than self-treating with supplements."]]},{"id":"W4-TQ22","ch":"W4-C7","src":"Textbook Ch 2, p. 52","added":"2026-10-26","q":"How does the antidepressant Prozac (an SSRI) raise serotonin levels in the synapse?","opts":[["By slowing the reuptake of serotonin by the sending neuron",true,"Figure 2.3: neurotransmitter levels depend on how much is released and how much is reabsorbed."],["By blocking serotonin receptors on the receiving neuron",false,"Blocking receptors would reduce the signal."],["By inhibiting the enzyme monoamine oxidase",false,"That is how MAOIs such as Nardil work."],["By making the axon grow longer",false,"Not a mechanism in the textbook."]]},{"id":"W4-TQ23","ch":"W4-C7","src":"Textbook Ch 2, p. 53","added":"2026-10-26","q":"Lucas firmly believes the RCMP is tracking him and that his neighbours can read his mind, yet he speaks logically on other topics. Which feature of schizophrenia is this?","opts":[["Delusions",true,"Firmly held false beliefs. Some people with schizophrenia are logical except on the subject of their delusions."],["Auditory hallucinations",false,"Hallucinations are hearing voices when no one is present."],["Inappropriate emotions",false,"That is emotion that is absent or strong but inappropriate."],["Mania",false,"Mania is a mood state with high energy, not a fixed false belief."]]},{"id":"W4-TQ24","ch":"W4-C7","src":"Textbook Ch 2, p. 55","added":"2026-10-26","q":"A therapist notes that each time Ana leaves a party early, she feels instant relief, and now she leaves sooner each time. Therapy focuses on changing what keeps the leaving going. Which model guides this?","opts":[["Behavioural",true,"Analyzes stimulus, response and reinforcement and changes the reinforcement that keeps the behaviour going."],["Cognitive",false,"The cognitive model would target her ideas and expectations."],["Psychodynamic",false,"The psychodynamic model seeks insight into unconscious ideas."],["Biological",false,"The biological model would use medication."]]},{"id":"W4-TQ25","ch":"W4-C7","src":"Textbook Ch 2, p. 57","added":"2026-10-26","q":"Which statement about evaluating the models is NOT true, according to the textbook?","opts":[["For anxiety disorders, drug therapy gives longer-lasting improvement than cognitive behavioural therapy.",true,"This is the false one. Drug effects last only while the drug is taken; CBT gives longer-term improvement."],["Cognitive behavioural packages combine effective elements of the behavioural and cognitive models.",false,"True. For example, social anxiety treatment combines exposure with changing thinking patterns."],["For schizophrenia, drug therapy is necessary, but a continuing relationship with therapists is also indispensable.",false,"True as stated in the textbook."],["Psychodynamic therapies have been criticized as ineffective and endless.",false,"True. The textbook adds that their effectiveness is hard to demonstrate."]]},{"id":"W4-TQ26","ch":"W4-C7","src":"Textbook Ch 2, p. 49","added":"2026-10-26","q":"A friend tells you she sometimes cuts herself when stress feels unbearable, but says she is not suicidal. What does the textbook say about this?","opts":[["Take it very seriously; self-injury is a maladaptive coping strategy that may signal increased suicide risk.",true,"Self-harm should be taken very seriously, and psychotherapy can help."],["It is harmless because it relieves stress.",false,"It is a maladaptive coping strategy, not harmless."],["It is the same thing as a suicide attempt.",false,"It is sometimes mistaken for a suicide attempt but is described separately."],["Ignore it, since she says she is not suicidal.",false,"It may signal increased risk, so it should not be ignored."]]},{"id":"W4-TQ27","ch":"W4-C7","src":"Textbook Ch 2, p. 51","added":"2026-10-26","q":"Which statement does the textbook's suicide myths box identify as a myth?","opts":[["People who survive a suicide attempt did not really intend to die.",true,"Myth. People who seriously want to die may fail because they misjudge what it takes."],["Most people who eventually die by suicide have talked about doing it.",false,"This is the fact used to correct a different myth."],["Someone determined to die today may change their mind tomorrow.",false,"Stated as fact: few people are single-minded about suicide."],["Many suicides are by people who do not meet ordinary criteria for mental illness.",false,"Stated as fact."]]},{"id":"W4-TQ28","ch":"W4-C7","src":"Textbook Ch 2, p. 48","added":"2026-10-26","q":"Which of these does the textbook list as a risk factor for suicide, rather than a warning sign?","opts":[["Readily available means, such as guns or pills",true,"Listed with previous attempts, a suicide by a family member or friend, substance abuse or eating disorders, and serious medical problems."],["A sudden, unexplained lightening of mood",false,"This is listed as a warning sign."],["Increasing social withdrawal and isolation",false,"This is listed as a warning sign."],["Expressing a wish to be dead",false,"This is listed as a warning sign."]]},{"id":"W4-TQ29","ch":"W4-C7","src":"Textbook Ch 2, p. 58","added":"2026-10-26","q":"According to the textbook, who usually provides peer counselling at universities?","opts":[["Volunteer students with special training that emphasizes confidentiality",true,"They may refer you to a campus or community resource or simply offer a sympathetic ear."],["Psychiatrists",false,"Psychiatrists are medical doctors, not peers."],["Clinical psychologists with a PhD",false,"These are mental health professionals."],["Members of a support group for a specific problem",false,"Support groups are a separate option organized around a shared problem."]]},{"id":"W4-TQ30","ch":"W4-C7","src":"Textbook Ch 2, p. 57","added":"2026-10-26","q":"Which approaches does the textbook say are especially useful for helping yourself?","opts":[["Behavioural and some cognitive approaches",true,"They involve noticing self-defeating actions and ideas and combating them, for example by confronting rather than avoiding fears."],["Psychodynamic approaches",false,"These depend on speaking freely in front of a therapist."],["Self-treating with herbal supplements such as St. John's wort",false,"The textbook advises a medical evaluation instead of self-treating."],["Pharmacological approaches",false,"Medications require a prescription from a psychiatrist or other medical doctor."]]}],"review":[{"id":"W4-R01","ch":"W4-C1","src":"W4 Part 1, slides 2, 7-8","added":"2026-10-26","q":"Explain why psychological health is not the same as psychological normality, and use the dual continua model to show why having no mental illness does not guarantee wellness.","answer":"Psychological health is our capacity to think, feel and behave in ways that help us enjoy life and manage challenges, and it can be defined positively as the presence of wellness. Normality only means being close to average, and psychological diversity is a valuable asset to society. The presence or absence of symptoms alone does not decide whether someone is mentally healthy. The dual continua model places people on two related but distinct continua, mental well-being and mental illness. A person with low illness can still have low well-being (vulnerable), and a person with high illness can still have high well-being (symptomatic but content).","points":["Defines psychological health (capacity to enjoy life and manage challenges; presence of wellness)","Normality = close to average; diversity is an asset","Symptoms alone do not decide mental health","Two continua: well-being and mental illness, related but distinct","Uses a quadrant example such as vulnerable or symptomatic but content"]},{"id":"W4-R02","ch":"W4-C1","src":"W4 Part 1, slides 10-13","added":"2026-10-26","q":"Describe Erikson's view of development. Which stages are first-year university students in or entering, and what can happen if an earlier stage is not mastered?","answer":"Erikson proposed that development progresses through 8 stages across the lifetime, each with a conflict. Once one stage is mastered we may move to the next. In adolescence the conflict is identity vs. identity confusion, with peers as the important people, and the task is developing a stable sense of your needs, abilities, interpersonal style and values. Young adulthood brings intimacy vs. isolation, learning to live and share intimately with close friends and partners. Failing to master a stage before moving on can have repercussions later, such as an identity crisis. Adult identity begins in adolescence and is a lifelong process.","points":["8 stages across life, each with a conflict","Adolescence: identity vs. identity confusion, peers","Young adulthood: intimacy vs. isolation","Unmastered stage can cause later problems, e.g., identity crisis","Adult identity begins in adolescence and is lifelong"]},{"id":"W4-R03","ch":"W4-C2","src":"W4 Part 1, slides 22-23","added":"2026-10-26","q":"Describe how to meet challenges to self-esteem. Pick one cognitive distortion from the realistic self-talk table, give an example of negative self-talk, and rewrite it as realistic self-talk.","answer":"To meet challenges to self-esteem, notice your patterns of thinking, avoid focusing on the negative by avoiding cognitive distortions, and develop realistic self-talk. One distortion is expecting the worst. Negative self-talk would be: 'I know I'm going to fail this course, so I should drop out.' Realistic self-talk would be: 'I'm not doing well in this course, so I should talk to my professor about what help I can get.' The realistic version admits the problem but points to an action instead of giving up.","points":["Notice patterns of thinking","Avoid focusing on the negative / cognitive distortions","Names a distortion from the table","Gives a negative statement and a realistic rewrite","Explains how the rewrite is balanced and action-focused"]},{"id":"W4-R04","ch":"W4-C2","src":"W4 Part 1, slides 24-26","added":"2026-10-26","q":"Define defence mechanisms and explain why people use them. Then distinguish projection, displacement and reaction formation, with an example of each.","answer":"When our wants conflict with people around us or with our conscience and we cannot change the external situation, frustration or anxiety can result. Defence mechanisms are ways we rearrange our thoughts and feelings to resolve the conflict internally. Projection is reacting to unacceptable inner impulses as if they came from outside, such as a student who dislikes a roommate feeling that the roommate dislikes them. Displacement is shifting feelings about one person to another person, such as yelling at a housemate when you are angry at a professor. Reaction formation is concealing feelings by exaggerating the opposite ones, such as a person who dislikes children buying them expensive gifts.","points":["Conflict with others or conscience that can't be changed externally","Rearranging thoughts and feelings to resolve it internally","Projection defined with example","Displacement defined with example","Reaction formation defined with example"]},{"id":"W4-R05","ch":"W4-C4","src":"W4 Part 2, slides 14-16, 23","added":"2026-10-26","q":"Describe how common depression is in Canada and among undergraduates, the symptoms it can involve, and the treatment options listed in the slides.","answer":"The prevalence of major depressive episodes in Canadians aged 15 and up is 7.6%, and women are twice as likely as men to be affected. Among undergraduates, self-reported depression diagnosis over 12 months was 26.9% of cisgender women, 13.4% of cisgender men and 47.8% of trans and gender nonconforming students, with even higher rates for Indigenous students. Symptoms can include dysphoria, anhedonia, appetite and sleep changes, restlessness or fatigue, self-loathing, poor concentration, irritability and rumination. 80% of Canadians respond well to treatment, but only 10% of those with depression seek it. Treatment can be drug therapy, psychotherapy or both, with exercise as an adjunct, rTMS, ECT for severe depression, and light therapy for SAD.","points":["7.6% major depressive episodes; women 2x men","Undergraduate rates by gender identity","Names several symptoms including dysphoria, anhedonia, rumination","80% respond to treatment but only 10% seek it","Lists drug therapy, psychotherapy, exercise, rTMS, ECT, light therapy"]},{"id":"W4-R06","ch":"W4-C4","src":"W4 Part 2, slides 27-28","added":"2026-10-26","q":"Compare psychotherapy and pharmacotherapy for depression. When do the slides suggest combining them?","answer":"Psychotherapy can give long-term skills that last after treatment, can reduce relapse rates, works for several disorders and has no side effects. Its drawbacks are that depression can impair executive functioning, which makes the cognitive control therapy needs hard, and it is not as effective in severe depression. Pharmacotherapy is easier to access, is recommended for severe depression and is needed to relieve symptoms in some disorders. Its drawbacks include severe side effects such as GI and sexual problems, poor compliance, difficulty finding the right drug and dose, tolerance, relapse and drug interactions. For severe depression the slides say a combination of psychotherapy and pharmacotherapy is needed.","points":["At least two psychotherapy pros (lasting skills, lower relapse, no side effects)","At least one psychotherapy con (executive function, less effective when severe)","At least two pharmacotherapy pros (access, severe depression)","At least two pharmacotherapy cons (side effects, compliance, tolerance, relapse)","Combination recommended for severe depression"]},{"id":"W4-TR01","ch":"W4-C6","src":"Textbook Ch 2, pp. 39-40","added":"2026-10-26","q":"A friend is 30 minutes late for dinner. Using the textbook, contrast negative self-talk, positive thinking and realistic self-talk in this situation, and explain how negative self-talk can lead to demoralization.","answer":"Negative self-talk jumps to a conclusion and assigns blame: 'He isn't coming; he probably finds me boring.' Positive thinking simply swaps in a cheerful thought, which the textbook says is not the goal. Realistic self-talk sticks to the facts as you know them: 'He's never late, so something must be holding him up; I'll call.' Repeated negative self-talk feeds cognitive distortions and can become a self-fulfilling prophecy, for example avoiding people because you expect to be disliked. Over time this can produce demoralization, a lasting negative self-concept where the person gives up and starts a cycle of failure.","points":["Negative self-talk judges, blames and jumps to unverified conclusions","Positive thinking substitutes a positive thought; realistic self-talk aims for logical, accurate thoughts","Gives a realistic, neutral example","Self-fulfilling prophecy: behaviour makes the negative belief come true","Demoralization: lasting negative self-concept, giving up, cycle of failure"]},{"id":"W4-TR02","ch":"W4-C6","src":"Textbook Ch 2, pp. 43-44","added":"2026-10-26","q":"Describe the textbook's strategies for managing your own anger and for dealing with anger in other people. When is professional help needed?","answer":"For your own anger, the textbook suggests reframing: change what you are thinking, for example by considering that the other person's behaviour was not aimed at you. Until you can change your thinking, distract yourself by counting to 10, focusing on your breathing or taking a cooling-off period, then return to the issue later. With an angry person, respond asymmetrically with calm, validate that they have some reason to be angry without apologizing if you are not to blame or accepting abuse, and focus on solving the problem. If they cannot be calmed, disengage for a time-out. Explosive or misdirected anger, called intermittent explosive disorder, calls for professional help.","points":["Reframing your thoughts about the other person's intent","Distraction: count to 10, breathing, cooling-off period","Asymmetrical response: calm, validate, problem-solve, disengage if needed","Validation does not mean apologizing or accepting verbal abuse","IED (explosive, misdirected anger) needs professional help"]},{"id":"W4-TR03","ch":"W4-C7","src":"Textbook Ch 2, pp. 55-57","added":"2026-10-26","q":"A student is afraid to speak in class. Explain how the behavioural, cognitive and psychodynamic models would each approach the problem, and what the textbook says about combining them.","answer":"The behavioural model sees the fear as a bad habit kept going by reinforcement: leaving the situation brings relief, which rewards avoidance. Therapy uses a diary, realistic goals, self-rewards and exposure, entering the feared situation repeatedly until fear fades. The cognitive model targets false ideas such as 'If I speak I'll sound stupid, everyone will lose respect for me and I'll fail,' and teaches the student to test these assumptions and substitute realistic thoughts. The psychodynamic model holds that such thoughts are fed by unconscious ideas, so the student would speak freely with a therapist to gain insight. Cognitive behavioural therapy packages combine exposure with changing thinking patterns and produce significant improvement, with longer-lasting effects for anxiety than drugs alone.","points":["Behavioural: stimulus, response, reinforcement; exposure and rewards","Cognitive: identify and test false ideas, substitute realistic thoughts","Psychodynamic: unconscious ideas, speak freely, gain insight","CBT packages combine exposure with changing thinking","For anxiety, CBT gains last longer than drug effects"]}],"explore":[{"fig":"maslow","title":"Maslow's hierarchy of needs","caption":"Maslow (1970), Motivation and Personality. Needs build from the base of the pyramid up to self-actualization.","items":{"physio":{"label":"Physiological needs","text":"The base of the pyramid: food and water, shelter, sleep, exercise and sex.","src":"W4 Part 1, slide 4"},"safety":{"label":"Safety and security","text":"Safe surroundings, protection by others, and knowing to avoid risks.","src":"W4 Part 1, slide 4"},"love":{"label":"Love and belongingness","text":"Being loved, being loving, and feeling connected.","src":"W4 Part 1, slide 4"},"esteem":{"label":"Self-esteem","text":"Esteem as a person and as a doer in relationships.","src":"W4 Part 1, slide 4"},"self":{"label":"Self-actualization","text":"The top level. Its qualities are realism, acceptance, autonomy, authenticity, capacity for intimacy and creativity.","src":"W4 Part 1, slides 4-6"}}},{"fig":"dual","title":"Dual continua model of mental health","caption":"Scutt et al. (2023). Mental well-being and mental illness are related but distinct, so the absence of illness does not guarantee high well-being.","items":{"flourish":{"label":"Flourishing","text":"High mental well-being and low mental illness.","src":"W4 Part 1, slide 8"},"symptomatic":{"label":"Symptomatic but content","text":"High mental illness but still high well-being. Illness and well-being can move separately.","src":"W4 Part 1, slide 8"},"vulnerable":{"label":"Vulnerable","text":"Low mental illness but low well-being. Having no illness does not guarantee wellness.","src":"W4 Part 1, slide 8"},"languish":{"label":"Languishing","text":"High mental illness and low mental well-being.","src":"W4 Part 1, slide 8"}}}]},{"id":"W5","n":5,"added":"2026-10-26","title":"Stress: The Constant Challenge","short":"Stress","blurb":"How the body and mind respond to stressors, how chronic stress wears down health, and how to manage stress.","topics":["Stressor, stress response, stress and the Perceived Stress Scale","Nervous and endocrine systems, HPA and SAM axes","Appraisal, personality, the stress curve and symptoms","GAS, allostatic load and psychoneuroimmunology","Whitehall studies and gradients of health","Sleep, time management and coping techniques"],"lectures":["Week 5 Part 1: Physiological Response to Stress","Week 5 Part 2: Emotional and Behavioral Responses to Stress","Week 5 Part 3: Chronic Stress, Allostatic Load, and Health","Week 5 Part 4: Managing Stress"],"terms":[{"id":"W5-T-stressor","term":"Stressor","def":"A situation or event that triggers physical and emotional reactions.","ex":"An exam, or a mess left by a roommate.","src":"W5 Part 1, slide 2","ch":"W5-C1","added":"2026-10-26"},{"id":"W5-T-stress-response","term":"Stress response","def":"The physical and emotional reactions to a stressor.","ex":"Your heart races and your palms sweat as the exam is handed out.","src":"W5 Part 1, slide 2","ch":"W5-C1","added":"2026-10-26"},{"id":"W5-T-stress","term":"Stress","def":"The general physical and emotional state that accompanies the stress response. In everyday use the word can mean both the triggering situation and the reactions.","src":"W5 Part 1, slide 2","ch":"W5-C1","added":"2026-10-26"},{"id":"W5-T-perceived-stress-scale","term":"Perceived Stress Scale (PSS)","def":"A 10-item test of how much stress you experienced in the past week (Table 3.1, adapted from Cohen, Kamarck and Mermelstein, 1983). Each item is answered never 0, almost never 1, sometimes 2, fairly often 3, very often 4. Add items 1, 2, 3, 6, 9 and 10, then subtract the starred items 4, 5, 7 and 8. A total above 14 means you should take time to develop effective stress management techniques.","ex":"Added items total 18, starred items total 3: score = 18 - 3 = 15, which is above 14.","src":"W5 Part 1, slides 3-4","ch":"W5-C1","added":"2026-10-26"},{"id":"W5-T-cns-pns","term":"CNS and PNS","def":"The nervous system (brain, spinal cord, and nerves) has two parts. The central nervous system (CNS) is the brain and spinal cord. The peripheral nervous system (PNS) divides into the somatic nervous system and the autonomic nervous system.","src":"W5 Part 2, slide 2; W5 Part 1, slide 6","ch":"W5-C1","added":"2026-10-26"},{"id":"W5-T-somatic-nervous-system","term":"Somatic nervous system","def":"Part of the PNS that handles motor and sensory functions, mostly under conscious control.","ex":"Deciding to raise your hand in class.","src":"W5 Part 2, slide 2","ch":"W5-C1","added":"2026-10-26"},{"id":"W5-T-autonomic-nervous-system","term":"Autonomic nervous system","def":"Part of the PNS that controls basic body processes under involuntary control. It is made up of the parasympathetic division and the sympathetic division.","src":"W5 Part 1, slides 6, 8; W5 Part 2, slide 2","ch":"W5-C1","added":"2026-10-26"},{"id":"W5-T-parasympathetic-division","term":"Parasympathetic division","def":"The autonomic division in control when you are relaxed ('rest and digest'). It aids in digesting food, storing energy, and promoting growth. Once a stressful situation ends, it takes command and stops the stress response.","ex":"An hour after the exam, your heart rate settles and you feel hungry.","src":"W5 Part 1, slides 8-9, 13","ch":"W5-C1","added":"2026-10-26"},{"id":"W5-T-sympathetic-division","term":"Sympathetic division","def":"The autonomic division activated during times of arousal, including exercise, and in emergencies such as severe pain, anger, or fear. It drives the fight-or-flight reaction, and its activation releases catecholamines.","ex":"Your heart pounds when a car swerves toward you.","src":"W5 Part 1, slides 8-9; W5 Part 2, slide 2","ch":"W5-C1","added":"2026-10-26"},{"id":"W5-T-catecholamines","term":"Catecholamines","def":"Chemicals released when the sympathetic division is activated: norepinephrine (noradrenaline) and epinephrine (adrenaline).","src":"W5 Part 1, slide 9","ch":"W5-C1","added":"2026-10-26"},{"id":"W5-T-endocrine-system","term":"Endocrine system","def":"Glands, tissues, and cells that help control bodily functions by releasing hormones. It helps prepare the body to respond to a stressor.","ex":"The slide highlights the hypothalamus, pituitary, and adrenal glands, the three glands of the HPA axis.","src":"W5 Part 1, slide 10","ch":"W5-C1","added":"2026-10-26"},{"id":"W5-T-fight-or-flight","term":"Fight-or-flight reaction","def":"The physical changes that hormones and neurotransmitters trigger in response to a stressor: heart and breathing rates speed up, hearing and vision become more acute, the liver releases extra sugar, perspiration increases, and the brain releases endorphins. Also called the fight-flight-or-freeze reaction.","ex":"Pupils dilate, digestion halts, and skeletal muscles tense (Fig 3.1).","src":"W5 Part 1, slides 11-12","ch":"W5-C1","added":"2026-10-26"},{"id":"W5-T-homeostasis","term":"Homeostasis","def":"A state of stability and consistency in an individual's physiological functioning. The parasympathetic division restores it after the stressful situation ends.","src":"W5 Part 1, slide 13","ch":"W5-C1","added":"2026-10-26"},{"id":"W5-T-hpa-axis","term":"HPA axis","def":"Hypothalamus-pituitary-adrenal axis. The hypothalamus receives sensory stressors and its paraventricular nucleus (PVN) releases CRH. CRH flows to the pituitary, which releases ACTH into the blood. ACTH reaches the adrenal gland, which releases glucocorticoids (cortisol in humans).","src":"W5 Part 1, slides 14, 16","ch":"W5-C2","added":"2026-10-26"},{"id":"W5-T-crh","term":"Corticotropin-releasing hormone (CRH)","def":"Hormone released by the paraventricular nucleus (PVN) of the hypothalamus. It flows through veins to the nearby pituitary gland and stimulates release of ACTH.","src":"W5 Part 1, slide 14","ch":"W5-C2","added":"2026-10-26"},{"id":"W5-T-acth","term":"Adrenocorticotropic hormone (ACTH)","def":"Hormone the pituitary releases into the bloodstream. It flows through blood vessels to the adrenal gland and stimulates release of glucocorticoids.","src":"W5 Part 1, slide 14","ch":"W5-C2","added":"2026-10-26"},{"id":"W5-T-glucocorticoids","term":"Glucocorticoids (cortisol)","def":"Hormones released by the adrenal gland (adrenal cortex) when stimulated by ACTH. In humans the glucocorticoid is cortisol.","src":"W5 Part 1, slides 14, 16","ch":"W5-C2","added":"2026-10-26"},{"id":"W5-T-negative-feedback","term":"Negative feedback (HPA axis)","def":"The process that turns down the stress response. Glucocorticoids bind to glucocorticoid receptors (GCRs) in the hypothalamus, pituitary, and hippocampus, which leads to a decrease in glucocorticoids in the blood.","src":"W5 Part 1, slide 15","ch":"W5-C2","added":"2026-10-26"},{"id":"W5-T-sam-axis","term":"SAM axis","def":"Sympathetic-adrenal-medullary axis. It mediates a rapid response to stress: sympathetic neurons release norepinephrine to organs, glands and vessels, and trigger the adrenal medulla to secrete circulating epinephrine, activating fight or flight.","src":"W5 Part 1, slide 16","ch":"W5-C2","added":"2026-10-26"},{"id":"W5-T-allostasis","term":"Allostasis","def":"How allostatic systems respond to stress: they start the adaptive response, sustain it until the stress ends, then shut it off (recovery). It is started by catecholamines from the autonomic nervous system and glucocorticoids from the adrenal cortex (McEwen, 1998).","src":"W5 Part 1, slide 17","ch":"W5-C2","added":"2026-10-26"},{"id":"W5-T-cognitive-appraisal","term":"Cognitive appraisal","def":"Your mental assessment of a stressor, shaped by successful prediction and perception of control. It is highly individual and strongly related to emotions.","ex":"A student who expected the quiz and feels prepared appraises it as less threatening than one who is caught off guard.","src":"W5 Part 2, slide 3","ch":"W5-C3","added":"2026-10-26"},{"id":"W5-T-effective-ineffective-responses","term":"Effective vs ineffective responses","def":"Effective responses lessen stress: talking, laughing, exercise, and time management. Ineffective responses may make it worse: overeating, procrastination, frustration, and self-medicating.","src":"W5 Part 2, slides 3, 11","ch":"W5-C3","added":"2026-10-26"},{"id":"W5-T-stress-curve","term":"Stress curve (Fig 3.2)","def":"An inverted-U of performance against stress level. A moderate level of stress promotes optimal performance and well-being. Too little stress (underload) means not enough challenge to improve; too much stress (overload) and burnout impair physical and emotional health.","src":"W5 Part 2, slide 4","ch":"W5-C3","added":"2026-10-26"},{"id":"W5-T-big-five","term":"Big Five (Five Factor) model","def":"The most widely used model of personality traits: conscientiousness, agreeableness, neuroticism, openness to experience, and extraversion. Personality is the sum of cognitive, behavioural, and emotional tendencies and affects how people perceive and react to stressors.","src":"W5 Part 2, slides 5-6","ch":"W5-C3","added":"2026-10-26"},{"id":"W5-T-trait-anxiety","term":"Trait anxiety","def":"A personality trait. People with higher trait anxiety are more vulnerable to stress than those who score low on this trait.","src":"W5 Part 2, slide 6","ch":"W5-C3","added":"2026-10-26"},{"id":"W5-T-resilience","term":"Resilience","def":"Personality traits associated with social and academic success in at-risk populations. Resilience helps people handle stress more positively, and academic resilience helps students succeed.","src":"W5 Part 2, slide 7","ch":"W5-C3","added":"2026-10-26"},{"id":"W5-T-general-adaptation-syndrome","term":"General adaptation syndrome (GAS)","def":"A pattern of stress responses with three stages: alarm, resistance, and exhaustion. Some aspects are now outdated and it was replaced by the idea of allostatic load.","src":"W5 Part 3, slides 2-4","ch":"W5-C4","added":"2026-10-26"},{"id":"W5-T-hans-selye","term":"Hans Selye","def":"Canadian endocrinologist, called the father of the field of stress research, who first proposed the general adaptation syndrome. (The slide spells the name Seyle; no year is given.)","src":"W5 Part 3, slide 2","ch":"W5-C4","added":"2026-10-26"},{"id":"W5-T-alarm-stage","term":"Alarm stage","def":"First GAS stage. The body is more susceptible to disease or injury; a person may have headaches, indigestion, anxiety, or disrupted eating or sleep patterns. On Fig 3.3, resistance to injury dips below normal.","src":"W5 Part 3, slides 3-4","ch":"W5-C4","added":"2026-10-26"},{"id":"W5-T-resistance-stage","term":"Resistance stage","def":"Second GAS stage. Homeostasis develops and the body becomes more resistant to disease and injury; resistance rises above the normal level.","src":"W5 Part 3, slides 3-4","ch":"W5-C4","added":"2026-10-26"},{"id":"W5-T-exhaustion-stage","term":"Exhaustion stage","def":"Third GAS stage: a life-threatening physiological state. With prolonged exposure to repeated stressors, resistance falls back to the low levels seen during acute stress.","src":"W5 Part 3, slides 3-4","ch":"W5-C4","added":"2026-10-26"},{"id":"W5-T-eustress-distress","term":"Eustress and distress","def":"Eustress is a pleasant stressor; distress is an unpleasant stressor.","ex":"Starting a job you are excited about (eustress) vs receiving a failing grade (distress).","src":"W5 Part 3, slide 2","ch":"W5-C4","added":"2026-10-26"},{"id":"W5-T-allostatic-load","term":"Allostatic load","def":"The long-term wear and tear of the stress response. High allostatic load may be due to frequent stressors, poor adaptation to common stressors, inability to shut down the stress response, or an inadequate response that leads to hyperactivity in other systems.","ex":"McEwen's four patterns: repeated hits, lack of adaptation, prolonged response, inadequate response.","src":"W5 Part 3, slides 5-8","ch":"W5-C4","added":"2026-10-26"},{"id":"W5-T-psychoneuroimmunology","term":"Psychoneuroimmunology","def":"The study of the interactions among the nervous, endocrine, and immune systems. Increased cortisol leads to decreased numbers of lymphocytes. Neuropeptides translate stressful emotions into biochemical events that affect the immune system. Acute stress moves white blood cells into the periphery to enhance the immune response; chronic stress and prolonged cortisol increase inflammation.","src":"W5 Part 3, slides 5, 16","ch":"W5-C5","added":"2026-10-26"},{"id":"W5-T-hippocampus","term":"Hippocampus","def":"A neurogenic brain region (new neurons keep forming in the adult brain) involved in learning, memory processing, and emotion. Stress, anxiety, and depression are associated with suppressed neurogenesis here; exercise increases it. It is also a site of HPA negative feedback.","ex":"Running animals showed more new hippocampal cells than controls (van Praag et al., 1999).","src":"W5 Part 3, slide 12; W5 Part 1, slide 15","ch":"W5-C5","added":"2026-10-26"},{"id":"W5-T-whitehall-studies","term":"Whitehall studies and gradients of health","def":"Classic studies measuring mortality and morbidity across employment grades in the British Civil Service. Death rate rose step by step from the top grade (Administrators, about half the average) to the bottom grade (Other, about twice the average): a four-fold gap. In Whitehall II, lower job control went with a higher likelihood of coronary heart disease. The slides also note that societies with high conflict and instability have increased mortality and morbidity.","ex":"A 40% increase in death rate in Russian men following the fall of communism.","src":"W5 Part 3, slides 13-15","ch":"W5-C5","added":"2026-10-26"},{"id":"W5-T-michael-marmot","term":"Sir Michael Marmot","def":"Led the classic Whitehall studies of the British Civil Service, which showed gradients of health by employment grade (25-year follow-up data: Marmot and Shipley, 1996).","src":"W5 Part 3, slides 13-14","ch":"W5-C5","added":"2026-10-26"},{"id":"W5-T-sources-of-stress","term":"Common sources of stress","def":"Major life changes, daily hassles, job-related stressors (burnout), postsecondary stressors (academic, interpersonal, time pressures, financial concerns, future worries), social stressors (real and virtual social networks; diverse populations, discrimination, racism), environmental stressors (natural disasters, acts of violence, industrial accidents), and internal stressors.","src":"W5 Part 4, slides 2-3","ch":"W5-C6","added":"2026-10-26"},{"id":"W5-T-rem-sleep","term":"REM sleep","def":"Rapid eye movement sleep, one of the two phases of sleep. Stress hormone levels increase during REM.","src":"W5 Part 4, slides 5-6, 9","ch":"W5-C6","added":"2026-10-26"},{"id":"W5-T-nrem-sleep","term":"NREM sleep","def":"Non-rapid eye movement sleep: 4 stages of successively deeper sleep. Blood pressure drops, breathing and heart rates slow, body temperature declines, growth hormone is released, and brain waves become slow and even. Stress hormones are low.","src":"W5 Part 4, slides 6, 9","ch":"W5-C6","added":"2026-10-26"},{"id":"W5-T-sleep-deprivation","term":"Sleep deprivation","def":"A lack of sleep over time. It is linked to increased stress hormones, stress, depression, and risk of suicide, and it slows the daytime decline in stress hormones. Most adults need 7 to 9 hours of sleep a night.","src":"W5 Part 4, slides 5, 8-9","ch":"W5-C6","added":"2026-10-26"},{"id":"W5-T-time-management","term":"Time management","def":"Strategies on the slides: set priorities, schedule tasks for peak efficiency, set realistic goals, budget enough time, break up long-term goals, visualize achievement, keep track of tasks you put off, do least favourite tasks first, consolidate tasks, identify quick transitional tasks, delegate, say no when necessary, give yourself a break, avoid time sinks, and just do it.","src":"W5 Part 4, slides 10-11","ch":"W5-C7","added":"2026-10-26"},{"id":"W5-T-journaling","term":"Confiding in yourself through writing","def":"Keeping a diary or journal. Helpful for people who are shy or introverted. It may lower short-term mood, but over the long term stress is reduced.","src":"W5 Part 4, slide 12","ch":"W5-C7","added":"2026-10-26"},{"id":"W5-T-relaxation-response","term":"Relaxation response","def":"The opposite of the fight-or-flight reaction. Relaxation techniques aim to trigger it: progressive muscle relaxation, visualization, meditation, deep breathing, yoga, tai chi, listening to music, and biofeedback.","src":"W5 Part 4, slide 14","ch":"W5-C7","added":"2026-10-26"},{"id":"W5-T-counterproductive-coping","term":"Counterproductive coping strategies","def":"Coping strategies that work against you: tobacco use, use of alcohol and other drugs, and unhealthy eating habits.","src":"W5 Part 4, slide 15","ch":"W5-C7","added":"2026-10-26"},{"id":"W5-T-tb-hormone","term":"Hormone","def":"A chemical messenger produced in the body and transported in the bloodstream to target cells or organs for specific regulation of their activities.","ex":"Cortisol and epinephrine are hormones released during the stress response.","src":"Textbook Ch 3, p. 66","ch":"W5-C8","added":"2026-10-26"},{"id":"W5-T-tb-norepinephrine","term":"Norepinephrine (noradrenaline)","def":"A neurotransmitter released by the sympathetic nervous system onto specific tissues to increase their function during increased activity. When released by the brain, it causes arousal: increased attention, awareness, and alertness. Sympathetic nerves use it to act on nearly every organ, sweat gland, blood vessel, and muscle.","src":"Textbook Ch 3, p. 66","ch":"W5-C8","added":"2026-10-26"},{"id":"W5-T-tb-endorphins","term":"Endorphins","def":"Brain secretions that have pain-inhibiting effects. During the fight-or-flight reaction the brain releases them in case you are injured.","ex":"Hearty laughter also triggers the release of endorphins.","src":"Textbook Ch 3, pp. 67, 84","ch":"W5-C8","added":"2026-10-26"},{"id":"W5-T-tb-behavioural-responses","term":"Behavioural responses to stressors","def":"Responses controlled by the somatic nervous system, which manages conscious actions, so they are entirely under our control. The textbook lists effective responses (talking, laughing, exercising, meditating, learning time management, becoming more assertive) and ineffective ones (overeating, expressing hostility, using tobacco, alcohol, or other drugs).","ex":"Amelia takes a deep breath and answers the questions she knows first; David lets his anxiety build until he stares into space.","src":"Textbook Ch 3, p. 69","ch":"W5-C8","added":"2026-10-26"},{"id":"W5-T-tb-type-a","term":"Type A personality","def":"Described as ultracompetitive, controlling, impatient, aggressive, and even hostile. Type A people have a higher perceived stress level, more problems coping, and react explosively to minor annoyances. Anger, cynicism, and hostility increase the risk of heart disease.","src":"Textbook Ch 3, p. 69","ch":"W5-C8","added":"2026-10-26"},{"id":"W5-T-tb-type-b","term":"Type B personality","def":"Relaxed and contemplative. Type B people are less frustrated by daily events and more tolerant of the behaviour of others.","src":"Textbook Ch 3, p. 69","ch":"W5-C8","added":"2026-10-26"},{"id":"W5-T-tb-type-c","term":"Type C personality","def":"Characterized by anger suppression, difficulty expressing emotions, feelings of hopelessness and despair, and an exaggerated response to minor stressors. This heightened response may impair immune functions.","src":"Textbook Ch 3, p. 69","ch":"W5-C8","added":"2026-10-26"},{"id":"W5-T-tb-type-d","term":"Type D (distressed) personality","def":"A newer personality construct: a joint tendency to feel (but not express) negative emotions and to avoid social contact. These people tend to be gloomy, socially inept, anxious worriers, a combination that puts them at risk for heart problems.","src":"Textbook Ch 3, p. 69","ch":"W5-C8","added":"2026-10-26"},{"id":"W5-T-tb-hardiness","term":"Hardiness","def":"A particular form of optimism. Hardy people view potential stressors as challenges and opportunities for growth and learning, not burdens. They are committed to their activities, have a sense of inner purpose and an inner locus of control, and feel at least partly in control of their lives.","src":"Textbook Ch 3, p. 70","ch":"W5-C8","added":"2026-10-26"},{"id":"W5-T-tb-resilience-types","term":"Three types of resilience","def":"Nonreactive resilience: the person does not react to a stressor. Homeostatic resilience: the person may react strongly but returns to baseline functioning quickly. Positive growth resilience: the person learns and grows from the stress experience.","src":"Textbook Ch 3, p. 70","ch":"W5-C8","added":"2026-10-26"},{"id":"W5-T-tb-gender-role","term":"Gender role","def":"A culturally expected pattern of behaviour and attitudes determined by a person's sex. Strict adherence to gender roles can limit a person's response to stress, can itself become a source of stress, and can affect how a stressor is perceived.","ex":"A man who gets most of his self-worth from work may find retirement more stressful than a woman whose self-image rests on several roles.","src":"Textbook Ch 3, p. 70","ch":"W5-C8","added":"2026-10-26"},{"id":"W5-T-tb-tend-and-befriend","term":"Tend and befriend","def":"The pattern of responding to stressors by seeking social support. Research suggests women are more likely than men to respond this way.","src":"Textbook Ch 3, p. 72","ch":"W5-C8","added":"2026-10-26"},{"id":"W5-T-tb-atherosclerosis","term":"Atherosclerosis","def":"A disease in which blood vessels become damaged and caked with fatty deposits that can block arteries and cause heart attacks and strokes. Chronic high blood pressure from the stress response is a major cause.","src":"Textbook Ch 3, p. 74","ch":"W5-C8","added":"2026-10-26"},{"id":"W5-T-tb-stress-cardiomyopathy","term":"Stress cardiomyopathy","def":"Also called broken heart syndrome: a condition caused by the stress response that mimics a heart attack but does not damage the heart.","src":"Textbook Ch 3, p. 74","ch":"W5-C8","added":"2026-10-26"},{"id":"W5-T-tb-major-life-changes","term":"Major life changes","def":"Any major change that requires adjustment and accommodation. Even positive changes such as graduation, a job promotion, or marriage can be stressful. A strong support network and a stress-resistant personality make illness less likely after life changes.","ex":"Moving out of the family home for university.","src":"Textbook Ch 3, p. 75","ch":"W5-C9","added":"2026-10-26"},{"id":"W5-T-tb-daily-hassles","term":"Daily hassles","def":"Minor problems such as losing your keys or wallet. Researchers propose they can be an even greater source of stress than major life changes because they occur much more often. People who perceive hassles negatively have a moderate stress response each time.","src":"Textbook Ch 3, p. 75","ch":"W5-C9","added":"2026-10-26"},{"id":"W5-T-tb-burnout","term":"Burnout","def":"A state of physical, mental, and emotional exhaustion that can result from severe or chronic job-related (or school-related) stress. It occurs most often in highly motivated, driven people who feel their work is not recognized or that they are not reaching their goals. People in the helping professions are prone to it.","ex":"Remedies include a vacation or leave, a reduced schedule, better communication with superiors, a change in job goals, or better time management.","src":"Textbook Ch 3, p. 77","ch":"W5-C9","added":"2026-10-26"},{"id":"W5-T-tb-acculturation","term":"Acculturation","def":"The process recent immigrants go through to live in a new society, balancing changing to be like the majority with keeping a connection to their own culture, language, and religion. It is generally stressful, especially when the person's background is very different.","src":"Textbook Ch 3, p. 78","ch":"W5-C9","added":"2026-10-26"},{"id":"W5-T-tb-environmental-stress","term":"Environmental stress","def":"A condition or event in the physical environment that causes stress. Mild examples are easy to avoid, such as a noisy restaurant; some are unavoidable daily stressors, such as pollen or construction noise. Severe examples include natural disasters, acts of violence, and industrial accidents.","src":"Textbook Ch 3, p. 78","ch":"W5-C9","added":"2026-10-26"},{"id":"W5-T-tb-internal-stressors","term":"Internal stressors","def":"Stressors found within ourselves. Reasonable goals can build self-esteem, but unrealistic expectations are a significant source of stress. Physical and emotional states such as illness and exhaustion are also internal stressors and can be both a cause and an effect of unmanaged stress.","ex":"Expecting to earn 100% on every test.","src":"Textbook Ch 3, pp. 78-79","ch":"W5-C9","added":"2026-10-26"},{"id":"W5-T-tb-assertive-communication","term":"Assertive communication","def":"Communicating your wants and needs in a way that respects the rights of others while protecting your own. People who suppress their feelings may benefit from assertiveness training; people who have trouble controlling anger may benefit from anger-management strategies.","src":"Textbook Ch 3, p. 80","ch":"W5-C9","added":"2026-10-26"},{"id":"W5-T-tb-overtraining","term":"Overtraining","def":"A risk for people who exercise compulsively, characterized by fatigue, irritability, depression, and diminished athletic performance. An overly strenuous program can compromise immune function.","src":"Textbook Ch 3, p. 81","ch":"W5-C9","added":"2026-10-26"},{"id":"W5-T-tb-insomnia","term":"Insomnia","def":"Trouble falling asleep or staying asleep. The most common causes are lifestyle factors, such as high caffeine or alcohol intake before bedtime. Many people with chronic insomnia report a stressful life event at its onset.","src":"Textbook Ch 3, p. 82","ch":"W5-C9","added":"2026-10-26"},{"id":"W5-T-tb-sleep-apnea","term":"Sleep apnea","def":"A chronic sleep problem in which a person stops breathing while asleep, usually because soft tissue at the back of the mouth collapses and blocks the airway. The sleeper wakes repeatedly to start breathing again, often without being aware of it.","src":"Textbook Ch 3, p. 82","ch":"W5-C9","added":"2026-10-26"},{"id":"W5-T-tb-problem-solving","term":"Problem solving (8 steps)","def":"A cognitive technique: 1 define the problem in one or two sentences; 2 identify its causes; 3 consider all solutions; 4 weigh positive and negative consequences of each; 5 make a decision; 6 list what you need to do; 7 begin to carry out the list; 8 evaluate the outcome and revise if needed.","src":"Textbook Ch 3, p. 84","ch":"W5-C9","added":"2026-10-26"},{"id":"W5-T-tb-progressive-relaxation","term":"Progressive relaxation","def":"Also called deep muscle relaxation. You tense and then relax the muscles of the body group by group, breathing in as you tense and out as you relax. Unlike most relaxation techniques, it needs no imagination, willpower, or self-suggestion.","src":"Textbook Ch 3, p. 85","ch":"W5-C9","added":"2026-10-26"},{"id":"W5-T-tb-mindfulness-meditation","term":"Mindfulness meditation","def":"A form of meditation that involves paying attention to physical sensations, perceptions, thoughts, and imagery. Instead of focusing on a word or object to quiet the mind, you observe the thoughts that occur without evaluating or judging them.","src":"Textbook Ch 3, p. 86","ch":"W5-C9","added":"2026-10-26"},{"id":"W5-T-tb-diaphragmatic-breathing","term":"Diaphragmatic breathing","def":"Slower, deeper stomach breathing with free expansion of the diaphragm and lower abdomen. It is the breathing pattern of children and sleeping adults. Many breathing exercises aim to shift people from chest breathing to this pattern.","src":"Textbook Ch 3, p. 86","ch":"W5-C9","added":"2026-10-26"},{"id":"W5-T-tb-biofeedback","term":"Biofeedback","def":"A technique in which monitoring devices help a person become conscious of unconscious body processes, such as body temperature or blood pressure, to exert some control over them. The goal is to learn how relaxation feels and transfer the skill to daily life without the equipment.","ex":"A tone gets louder as heart rate rises and softer as it falls.","src":"Textbook Ch 3, p. 87","ch":"W5-C9","added":"2026-10-26"},{"id":"W5-T-tb-systematic-desensitization","term":"Systematic desensitization","def":"A method for test anxiety based on the premise that you cannot feel anxiety and be relaxed at the same time. Phase I: build an anxiety hierarchy of ten or more situations. Phase II: learn muscle relaxation. Phase III: imagine each situation while relaxed, from least to most tense. Success rehearsal is a variation in which you imagine yourself dealing with each situation successfully.","src":"Textbook Ch 3, p. 90","ch":"W5-C9","added":"2026-10-26"}],"chapters":[{"id":"W5-C1","title":"What stress is and how the body reacts","src":"W5 Part 1, slides 2-13, 18; W5 Part 2, slide 2","blurb":"Stressor vs stress response vs stress, the PSS, nervous system divisions, fight or flight.","learn":"The slides separate three words. A <b>stressor</b> is the event that triggers reactions. The <b>stress response</b> is the reactions. <b>Stress</b> is the general physical and emotional state that goes with the response.<br>The <b>Perceived Stress Scale</b> scores 10 items from 0 (never) to 4 (very often) for the past week. Add items 1, 2, 3, 6, 9 and 10, then subtract the starred items 4, 5, 7 and 8. A total above 14 means you should build stress management skills.<br>The nervous system splits into the CNS (brain, spinal cord) and PNS. The PNS has a somatic part (mostly conscious) and an autonomic part (involuntary). The autonomic system has a <b>sympathetic</b> division (arousal, fight or flight, releases catecholamines) and a <b>parasympathetic</b> division (rest and digest). The endocrine system adds hormones. When the stressor ends, the parasympathetic division restores <b>homeostasis</b>.","steps":[{"id":"W5-C1-S1","type":"match","src":"W5 Part 1, slides 2, 9-10, 13","prompt":"Match each term to its slide definition.","pairs":[["Stressor","The situation or event that triggers physical and emotional reactions"],["Stress response","The physical and emotional reactions to the stressor"],["Stress","The general state that accompanies the stress response"],["Homeostasis","Stability and consistency in physiological functioning"],["Catecholamines","Norepinephrine and epinephrine"],["Endocrine system","Glands, tissues and cells that release hormones"]]},{"id":"W5-C1-S2","type":"table","src":"W5 Part 1, slide 4","prompt":"Use the Perceived Stress Scale scoring rule to answer.","caption":"Table 3.1 Perceived Stress Scale (adapted from Cohen, Kamarck and Mermelstein, 1983). Answer each item: never 0, almost never 1, sometimes 2, fairly often 3, very often 4. Starred items are subtracted. A total above 14: take time to develop effective stress management techniques.","head":["Item","In the past week, how often have you...","Scoring"],"rows":[["1","Been upset because of something that happened unexpectedly?","Add"],["2","Felt that you were unable to control the important things in your life?","Add"],["3","Felt nervous and stressed?","Add"],["4*","Felt confident about your ability to handle your personal problems?","Subtract"],["5*","Felt that things were going your way?","Subtract"],["6","Found that you could not cope with all the things you had to do?","Add"],["7*","Been able to control irritations in your life?","Subtract"],["8*","Felt that you were on top of things?","Subtract"],["9","Been angered because things happened that were outside your control?","Add"],["10","Felt difficulties were piling up so high that you could not overcome them?","Add"]],"qs":[{"id":"W5-C1-S2-Q1","type":"mcq","src":"W5 Part 1, slide 4","ch":"W5-C1","added":"2026-10-26","case":"Noor's answers: item 1 = 3, item 2 = 3, item 3 = 4, item 6 = 3, item 9 = 2, item 10 = 3. Starred items: item 4 = 1, item 5 = 1, item 7 = 1, item 8 = 0.","q":"What is Noor's PSS score, and what does the slide advise?","opts":[["15, which is above 14, so she should develop stress management techniques",true,"Added items: 3+3+4+3+2+3 = 18. Starred items: 1+1+1+0 = 3. 18 - 3 = 15, which is above the cutoff of 14."],["21, which is above 14, so she should develop stress management techniques",false,"21 comes from adding all ten items. The starred items must be subtracted."],["18, which is above 14, so she should develop stress management techniques",false,"18 is only the added items. The starred items 4, 5, 7 and 8 still need to be subtracted."],["15, which is not above 14, so no action is suggested",false,"The arithmetic is right, but 15 is above 14, so the slide advises building stress management techniques."]]},{"id":"W5-C1-S2-Q2","type":"mcq","src":"W5 Part 1, slide 4","ch":"W5-C1","added":"2026-10-26","q":"Which PSS item is subtracted from the total?","opts":[["Felt that things were going your way",true,"Item 5 is starred, so its answer is subtracted."],["Found that you could not cope with all the things you had to do",false,"Item 6 is not starred; it is added."],["Felt nervous and stressed",false,"Item 3 is added."],["Been angered because things happened that were outside your control",false,"Item 9 is added."]]}]},{"id":"W5-C1-S3","type":"compare","src":"W5 Part 1, slides 8-9, 13","prompt":"Which autonomic division is in charge in each scenario?","a":{"name":"Sympathetic division","points":["Activated during arousal: exercise and emergencies such as severe pain, anger, or fear","Releases catecholamines: norepinephrine and epinephrine","Drives the fight-or-flight reaction"]},"b":{"name":"Parasympathetic division","points":["In control when you are relaxed: rest and digest","Aids digesting food, storing energy, and promoting growth","Takes command after the stressor ends and restores homeostasis"]},"scenarios":[["A cyclist sprinting up a steep hill",0,"Exercise is a time of arousal, which activates the sympathetic division."],["Lying on the couch digesting a big lunch",1,"Digesting food while relaxed is parasympathetic."],["A car swerves toward you and adrenaline surges",0,"Emergency plus epinephrine release: sympathetic."],["An hour after the exam ends, your heart rate settles back to normal",1,"After the stressor ends, the parasympathetic division stops the stress response and restores homeostasis."],["A sudden, severe pain makes your heart pound",0,"Severe pain is listed as an emergency that activates the sympathetic division."]]},{"id":"W5-C1-S4","type":"mcq","src":"W5 Part 1, slide 18","ch":"W5-C1","added":"2026-10-26","case":"When a professor calls on Maya without warning, she goes still and cannot speak. Maya has a history of trauma.","q":"Which statement from the slides best fits Maya's reaction?","opts":[["Freezing may occur as a result of previous trauma",true,"The slide on fight, flight or freeze in modern life says freezing may follow previous trauma."],["Freezing shows the parasympathetic division has taken control",false,"The parasympathetic division takes over after the stressor ends. Freezing is part of the stress response itself."],["Freezing is the most common response in modern life",false,"The slide says the common response is flight."],["People who show more aggression tend to freeze more",false,"The slide says aggression may go with fewer freezing reactions."]]}],"summary":"Stressor = trigger, stress response = reactions, stress = the overall state. The sympathetic division drives fight or flight; the parasympathetic division brings you back to homeostasis."},{"id":"W5-C2","title":"HPA axis and SAM axis","src":"W5 Part 1, slides 14-17","blurb":"The hormone chain from hypothalamus to cortisol, negative feedback, and the rapid SAM pathway.","learn":"Two pathways carry the stress response. In the <b>HPA axis</b> (hypothalamus-pituitary-adrenal), the hypothalamus receives sensory stressors. Its paraventricular nucleus (PVN) releases <b>CRH</b>, which flows through veins to the pituitary gland. The pituitary releases <b>ACTH</b> into the bloodstream. ACTH reaches the adrenal gland, which releases glucocorticoids: <b>cortisol</b> in humans.<br><b>Negative feedback</b> turns the response down. Glucocorticoids bind to receptors (GCRs) in the hypothalamus, pituitary, and hippocampus, and glucocorticoids in the blood fall.<br>The <b>SAM axis</b> (sympathetic-adrenal-medullary) is the rapid pathway. Sympathetic neurons release norepinephrine to organs and trigger the adrenal medulla to secrete epinephrine. So HPA ends at the adrenal cortex (cortisol) and SAM at the adrenal medulla (epinephrine).<br>McEwen calls the whole pattern <b>allostasis</b>: start the response, sustain it until the stress ends, then shut it off.","steps":[{"id":"W5-C2-S1","type":"order","src":"W5 Part 1, slides 14-15","prompt":"Put the HPA axis steps in order, from stressor to shut-off.","items":["Hypothalamus receives sensory stressors","PVN in the hypothalamus releases CRH","CRH flows through veins to the pituitary gland","Pituitary releases ACTH into the bloodstream","ACTH reaches the adrenal gland","Adrenal gland releases glucocorticoids (cortisol)","Glucocorticoids bind GCRs and turn the response down"],"why":"Hypothalamus (CRH) to pituitary (ACTH) to adrenal gland (cortisol). Cortisol then feeds back on the hypothalamus, pituitary, and hippocampus to lower the response."},{"id":"W5-C2-S2","type":"label","fig":"hpa","src":"W5 Part 1, slides 14-15","prompt":"Drag each structure and hormone onto the HPA axis chain."},{"id":"W5-C2-S3","type":"compare","src":"W5 Part 1, slide 16","prompt":"HPA axis or SAM axis?","a":{"name":"HPA axis","points":["Hypothalamus, pituitary gland, adrenal cortex","Hormone chain: CRH (and AVP), then ACTH, then cortisol","Cortisol gives negative feedback to the hypothalamus"]},"b":{"name":"SAM axis","points":["Sympathetic neurons and adrenal medulla","Rapid response through interconnected neurons","Releases epinephrine and norepinephrine"]},"scenarios":[["ACTH in the blood stimulates the adrenal gland",0,"ACTH is the pituitary hormone of the HPA axis."],["The adrenal medulla secretes circulating epinephrine",1,"The adrenal medulla is the 'M' in SAM."],["The pathway the figure describes as the rapid response to stress",1,"The SAM box says it mediates a rapid response through interconnected neurons."],["CRH from the paraventricular nucleus reaches the pituitary",0,"CRH is the first hormone of the HPA chain."],["Norepinephrine is released to peripheral organs, glands and vessels",1,"Sympathetic neurons release norepinephrine in the SAM axis."]]},{"id":"W5-C2-S4","type":"mcq","src":"W5 Part 1, slide 15","ch":"W5-C2","added":"2026-10-26","case":"In a lab study, glucocorticoid receptors (GCRs) in an animal's hypothalamus, pituitary, and hippocampus are blocked. The animal is then exposed to a stressor.","q":"What would you predict?","opts":[["Cortisol stays high longer, because negative feedback cannot turn the response down",true,"Glucocorticoids binding GCRs is what lowers glucocorticoids in the blood. Block the receptors and the shut-off fails."],["CRH release stops, because the hypothalamus can no longer receive stressors",false,"The hypothalamus receives sensory stressors through other routes. GCRs are for feedback, not for detecting stressors."],["ACTH falls, because the pituitary responds only to epinephrine",false,"The pituitary releases ACTH in response to CRH, not epinephrine."],["The adrenal medulla takes over cortisol release",false,"Cortisol comes from the adrenal cortex. The adrenal medulla secretes epinephrine."]]}],"summary":"HPA: hypothalamus (CRH) to pituitary (ACTH) to adrenal cortex (cortisol), with negative feedback at the hypothalamus, pituitary and hippocampus. SAM: sympathetic neurons and adrenal medulla, fast, epinephrine and norepinephrine."},{"id":"W5-C3","title":"Emotional and behavioural responses","src":"W5 Part 2, slides 3-12","blurb":"Cognitive appraisal, effective vs ineffective responses, the stress curve, personality, and symptoms.","learn":"How you react depends on <b>cognitive appraisal</b>: whether you can predict a stressor and whether you feel in control. Appraisal is highly individual and strongly tied to emotion.<br><b>Effective responses</b> (talking, laughing, exercise, time management) lessen stress. <b>Ineffective responses</b> (overeating, procrastination, frustration, self-medicating) can make it worse.<br>The <b>stress curve</b> (Fig 3.2) shows performance rising from too little stress (underload) to an optimum, then falling with too much stress (overload) and burnout.<br>Personality is the sum of cognitive, behavioural and emotional tendencies. The <b>Big Five</b> are conscientiousness, agreeableness, neuroticism, openness to experience, and extraversion. Higher <b>trait anxiety</b> means more vulnerability to stress. <b>Resilience</b> helps people handle stress more positively, and you can change some elements of personality. Gender and gender roles, cultural background, and experiences also matter.<br>Symptoms of excess stress can be physical, emotional, or behavioural.","steps":[{"id":"W5-C3-S1","type":"sort","src":"W5 Part 2, slide 3","prompt":"Sort each response as effective or ineffective.","bins":["Effective response","Ineffective response"],"items":[["Talking it through with a friend",0,"Talking is listed as an effective response."],["Laughing at a comedy show after a long day",0,"Laughing is listed as effective."],["Going for a run before studying",0,"Exercise is listed as effective."],["Building a weekly study schedule",0,"Time management is listed as effective."],["Eating a whole bag of chips while stressed",1,"Overeating is listed as ineffective."],["Putting off the assignment until the night before",1,"Procrastination is listed as ineffective."],["Drinking to calm down before a presentation",1,"Self-medicating is listed as ineffective."],["Staying angry and frustrated about a group project",1,"Frustration is listed as ineffective."]]},{"id":"W5-C3-S2","type":"label","fig":"yerkes","src":"W5 Part 2, slide 4","prompt":"Place each zone of the stress curve (Fig 3.2), from too little stress to burnout."},{"id":"W5-C3-S3","type":"sort","src":"W5 Part 2, slide 9","prompt":"Sort each symptom of excess stress using the slide 9 table.","bins":["Physical","Emotional","Behavioural"],"items":[["Dry mouth",0,"Listed under physical symptoms."],["Grinding of teeth",0,"Listed under physical symptoms."],["High blood pressure",0,"Listed under physical symptoms."],["Stiff neck or aching lower back",0,"Listed under physical symptoms."],["Hypervigilance",1,"Listed under emotional symptoms."],["Edginess",1,"Listed under emotional symptoms."],["Impulsiveness",1,"Listed under emotional symptoms."],["Harsh treatment of others",2,"Listed under behavioural symptoms."],["Social isolation",2,"Listed under behavioural symptoms."]]},{"id":"W5-C3-S4","type":"mcq","src":"W5 Part 2, slide 6","ch":"W5-C3","added":"2026-10-26","case":"Jordan and Priya write the same midterm. On a personality test, Jordan scored high on trait anxiety and Priya scored low.","q":"Based on the slides, which outcome is most likely?","opts":[["Jordan is more vulnerable to stress from the midterm than Priya",true,"People with higher trait anxiety are more vulnerable to stress than those who score low on it."],["Priya is more vulnerable, because low trait anxiety makes stressors feel stronger",false,"The slide says the opposite: higher trait anxiety means more vulnerability."],["Their stress will be the same, because personality does not affect stress",false,"The slides say personality clearly affects how people perceive and react to stressors."],["Jordan will perform better, because more stress always raises performance",false,"The stress curve shows performance falls once stress goes past the optimum."]]}],"summary":"Appraisal (prediction and control), personality (Big Five, trait anxiety, resilience), gender and culture shape the response. Moderate stress is best; too little or too much hurts performance."},{"id":"W5-C4","title":"General adaptation syndrome and allostatic load","src":"W5 Part 3, slides 2-8","blurb":"Selye's three stages, eustress vs distress, why GAS is outdated, and the four causes of high allostatic load.","learn":"Canadian endocrinologist Hans Selye, the father of stress research, proposed the <b>general adaptation syndrome (GAS)</b>: three stages. In <b>alarm</b>, the body is more susceptible to disease or injury, with possible headaches, indigestion, anxiety, and disrupted eating or sleep. In <b>resistance</b>, homeostasis develops and the body becomes more resistant to disease and injury. <b>Exhaustion</b> is a life-threatening physiological state. A stressor can be pleasant (<b>eustress</b>) or unpleasant (<b>distress</b>).<br>Parts of GAS are outdated. Disease susceptibility is now traced to the stress response itself, not to depleted resources. GAS was replaced by <b>allostatic load</b>: the long-term wear and tear of the stress response. High allostatic load may come from:<ul><li>frequent stressors (repeated hits)</li><li>poor adaptation to common stressors</li><li>inability to shut down the response (prolonged response)</li><li>an inadequate response that leads to hyperactivity in other systems</li></ul>","steps":[{"id":"W5-C4-S1","type":"label","fig":"gas","src":"W5 Part 3, slides 3-4","prompt":"Place the three GAS stages on the resistance-to-injury curve."},{"id":"W5-C4-S2","type":"match","src":"W5 Part 3, slides 7-8","prompt":"Match each cause of high allostatic load to its pattern on McEwen's figure.","pairs":[["Frequent stressors","Repeated hits: a normal response repeated many times"],["Poor adaptation to common stressors","The response stays full height instead of shrinking with repetition"],["Inability to shut down the stress response","Prolonged response with no recovery"],["Inadequate response","A small response that leads to hyperactivity in other systems"]]},{"id":"W5-C4-S3","type":"mcq","src":"W5 Part 3, slide 2","ch":"W5-C4","added":"2026-10-26","case":"Sam has just been offered his dream job in a new city. He is excited, but his heart races as he plans the move.","q":"Which term best describes this stressor?","opts":[["Eustress",true,"Eustress is a pleasant stressor, such as a welcome job offer."],["Distress",false,"Distress is an unpleasant stressor. Sam is excited about the change."],["Allostatic load",false,"Allostatic load is long-term wear and tear, not a single pleasant event."],["Exhaustion stage",false,"Exhaustion is a life-threatening state after prolonged stress, not an exciting new event."]]},{"id":"W5-C4-S4","type":"mcq","src":"W5 Part 3, slides 3-4","ch":"W5-C4","added":"2026-10-26","case":"Two weeks into exam season, Lee's early headaches and poor sleep have stopped. Her body seems to have settled and she has not been sick, even though exams continue.","q":"Which GAS stage is Lee most likely in?","opts":[["Resistance",true,"In resistance, homeostasis develops and the body becomes more resistant to disease and injury."],["Alarm",false,"Alarm brings headaches, indigestion and disrupted sleep. Lee is past those."],["Exhaustion",false,"Exhaustion is a life-threatening state with low resistance. Lee is coping and not getting sick."],["Burnout zone of the stress curve",false,"Burnout is on Fig 3.2, the performance curve, and comes with breakdown. Lee is coping well."]]}],"summary":"GAS: alarm, resistance, exhaustion. It is outdated because disease comes from the stress response itself; allostatic load (wear and tear) replaced it."},{"id":"W5-C5","title":"Chronic stress and long-term health","src":"W5 Part 3, slides 9-17","blurb":"Health risks of chronic stress, psychoneuroimmunology, the hippocampus, and the Whitehall gradient.","learn":"Unresolved chronic stress, or handling stressors poorly, raises the risk of many health problems: cardiovascular disease (chronic high blood pressure; inflammation damages blood vessels), psychological problems (depression, anxiety, panic attacks, eating disorders, PTSD), and altered immune function (more infections). Others include digestive problems, headaches, insomnia, injuries, menstrual irregularities, and pregnancy complications.<br><b>Psychoneuroimmunology</b> studies how the nervous, endocrine, and immune systems interact. Higher cortisol lowers lymphocyte numbers. Neuropeptides turn stressful emotions into biochemical events. Acute stress moves white blood cells into the periphery; chronic stress and prolonged cortisol increase inflammation.<br>The <b>hippocampus</b> (learning, memory, emotion) keeps making new neurons. Stress, anxiety and depression suppress this neurogenesis; exercise increases it.<br>Sir Michael Marmot's <b>Whitehall studies</b> found a gradient: the lower the employment grade, the higher the death rate. Low job control went with more coronary heart disease.","steps":[{"id":"W5-C5-S1","type":"table","src":"W5 Part 3, slide 14","prompt":"Read the Whitehall data and answer.","caption":"Whitehall Figure 1: death rate by employment grade over a 25-year period in men, relative to the civil service average (set at 1). Source data: Marmot and Shipley, 1996. Bar values are not printed; the descriptions below come from the figure caption and bar order.","head":["Employment grade","Death rate vs average, ages 40-64"],"rows":[["Administrators (top grade)","About half the average"],["Professional/Executive","Below the average"],["Clerical","Above the average"],["Other (office support, bottom grade)","About twice the average"]],"qs":[{"id":"W5-C5-S1-Q1","type":"mcq","src":"W5 Part 3, slide 14","ch":"W5-C5","added":"2026-10-26","q":"Which conclusion does Figure 1 support?","opts":[["Death rate rises step by step as employment grade falls",true,"In every age group the bars rise from Administrators to Professional/Executive to Clerical to Other."],["Only the bottom grade differs from the average",false,"Administrators are well below the average and Clerical is above it, so several grades differ."],["Administrators have about twice the average death rate",false,"Administrators have about half the average. The Other grade has about twice."],["Higher grades have higher death rates because of heavier responsibility",false,"The chart shows the reverse: the top grade has the lowest death rate."]]},{"id":"W5-C5-S1-Q2","type":"mcq","src":"W5 Part 3, slide 14","ch":"W5-C5","added":"2026-10-26","q":"At ages 40-64, about how many times higher is the bottom grade's death rate than the top grade's?","opts":[["About four times",true,"About 2 (twice average) divided by about 0.5 (half average) = 4. The caption calls it a four-fold difference."],["About two times",false,"Two times is the gap between the Other grade and the average, not between the top and bottom grades."],["About half",false,"Half is the Administrators' rate compared with the average."],["About 40 percent higher",false,"40% is the rise in death rate in Russian men after the fall of communism, a different statistic."]]}]},{"id":"W5-C5-S2","type":"sort","src":"W5 Part 3, slides 10, 16","prompt":"Sort each long-term effect of chronic stress into its category on the slides.","bins":["Cardiovascular","Psychological","Immune system"],"items":[["Chronic high blood pressure",0,"Listed as leading to cardiovascular disease."],["Inflammation damaging blood vessels",0,"Listed under cardiovascular disease."],["Panic attacks",1,"Listed under psychological problems."],["Eating disorders",1,"Listed under psychological problems."],["Post-traumatic stress disorder",1,"Listed under psychological problems."],["Depression",1,"Listed under psychological problems."],["Increased vulnerability to infections",2,"Listed under altered functioning of the immune system."],["Fewer lymphocytes as cortisol rises",2,"Psychoneuroimmunology slide: increased cortisol leads to decreased numbers of lymphocytes."]]},{"id":"W5-C5-S3","type":"mcq","src":"W5 Part 3, slide 12","ch":"W5-C5","added":"2026-10-26","case":"After months of chronic stress and low mood, Ethan finds it much harder to learn and remember new course material.","q":"Which explanation from the slides fits best?","opts":[["Stress and depression are associated with suppressed neurogenesis in the hippocampus, a region involved in learning and memory",true,"The slide links stress, anxiety and depression to suppressed neurogenesis in the hippocampus."],["Stress increases neurogenesis in the hippocampus, which overloads memory",false,"Stress suppresses neurogenesis. Exercise is what increases it."],["The hippocampus releases ACTH, which blocks learning",false,"ACTH comes from the pituitary. The hippocampus is a site of negative feedback."],["Exercise suppresses neurogenesis, so his gym habit is the cause",false,"Exercise has been shown to increase neurogenesis in the hippocampus."]]}],"summary":"Chronic stress raises cardiovascular, psychological and immune risks through cortisol and inflammation, suppresses hippocampal neurogenesis, and follows a social gradient (Whitehall)."},{"id":"W5-C6","title":"Sources of stress and sleep","src":"W5 Part 4, slides 2-9","blurb":"Where stress comes from, first steps for managing it, and how sleep and stress hormones connect.","learn":"Common sources of stress: major life changes, daily hassles, job-related stressors (burnout), and postsecondary stressors (academic, interpersonal, time pressures, financial concerns, future worries). There are also social stressors (real and virtual social networks; diverse populations, discrimination, racism), environmental stressors (natural disasters, acts of violence, industrial accidents), and internal stressors.<br>To manage stress: shore up your support system, improve communication skills, do acts of kindness, build healthy exercise, eating and sleeping habits, and learn to identify and moderate your stressors.<br>Most adults need 7 to 9 hours of sleep. Sleep has two phases. <b>NREM</b> has 4 stages of deeper sleep: blood pressure, breathing, heart rate and temperature drop, growth hormone is released, and brain waves slow. <b>REM</b> is rapid eye movement sleep. Lack of sleep has the greatest impact on stress. Stress hormones are low in NREM and rise in REM, and sleep deprivation slows their daytime decline.","steps":[{"id":"W5-C6-S1","type":"sort","src":"W5 Part 4, slides 2-3","prompt":"Sort each stressor into its category from the slides.","bins":["Postsecondary stressor","Social stressor","Environmental stressor"],"items":[["Worrying about finding work after graduation",0,"Future worries are a postsecondary stressor."],["Figuring out how to pay next term's tuition",0,"Financial concerns are a postsecondary stressor."],["Three assignments due in the same week",0,"Time pressures are a postsecondary stressor."],["Comparing yourself to friends' posts online",1,"Virtual social networks are a social stressor."],["Experiencing racism on the bus",1,"Discrimination and racism are social stressors."],["A flood in your hometown",2,"Natural disasters are environmental stressors."],["A chemical spill at a nearby plant",2,"Industrial accidents are environmental stressors."],["An act of violence near campus",2,"Acts of violence are listed as environmental stressors."]]},{"id":"W5-C6-S2","type":"compare","src":"W5 Part 4, slides 6-7, 9","prompt":"NREM sleep or REM sleep?","a":{"name":"NREM sleep","points":["4 stages of successively deeper sleep","Blood pressure, heart rate, breathing and temperature drop; growth hormone released","Stress hormones are low"]},"b":{"name":"REM sleep","points":["Rapid eye movement","Stress hormones increase","Shown in red on the hypnogram; REM periods get longer toward morning"]},"scenarios":[["Brain wave patterns become slow and even",0,"Listed as a physiological change of NREM sleep."],["Stress hormone levels rise",1,"Stress hormones increase during REM."],["Growth hormone is released",0,"Listed under NREM changes."],["Body temperature declines",0,"Listed under NREM changes."],["The red segments on the hypnogram, longer late in the night",1,"REM is drawn in red, and REM periods lengthen toward morning."]]},{"id":"W5-C6-S3","type":"mcq","src":"W5 Part 4, slides 8-9","ch":"W5-C6","added":"2026-10-26","case":"After three nights of only four hours of sleep, Ali notices he feels more stressed and on edge in the afternoons than usual.","q":"Which explanation from the slides fits best?","opts":[["Sleep deprivation slows the normal daytime decline in stress hormones",true,"The slide says sleep deprivation slows the daytime decline in stress hormones."],["Missing NREM sleep means he missed the phase when stress hormones are highest",false,"Stress hormones are low during NREM and increase during REM."],["Lack of sleep lowers stress hormones, so he feels flat rather than stressed",false,"The slides link sleep deprivation to an increase in stress hormones."],["Short sleep raises growth hormone during the day",false,"Growth hormone release is listed as part of NREM sleep, not a daytime effect of short sleep."]]}],"summary":"Stress comes from life changes, daily hassles, school, social and environmental sources. Sleep loss has the biggest effect on stress: stress hormones rise in REM, and deprivation keeps them up during the day."},{"id":"W5-C7","title":"Coping techniques","src":"W5 Part 4, slides 10-17","blurb":"Time management, journaling, cognitive and relaxation techniques, and what to avoid.","learn":"<b>Time management</b>: set priorities, schedule tasks for peak efficiency, set realistic goals, budget enough time, break up long-term goals, track tasks you put off, do least favourite tasks first, consolidate tasks, delegate, say no when needed, take breaks, avoid time sinks, and just do it.<br><b>Journaling</b> (confiding in yourself through writing) helps people who are shy or introverted. It may lower mood in the short term, but stress drops over the long term.<br><b>Cognitive techniques</b>: think and act constructively, take control, problem solve, stay positive, cultivate humour, focus on what matters, and modify expectations.<br><b>Relaxation techniques</b> trigger the relaxation response, the opposite of fight or flight: progressive muscle relaxation, visualization, meditation, deep breathing, yoga, tai chi, music, and biofeedback.<br><b>Counterproductive</b> strategies: tobacco, alcohol and other drugs, and unhealthy eating. A personal plan: identify stressors, design your plan, get help.","steps":[{"id":"W5-C7-S1","type":"sort","src":"W5 Part 4, slides 10-15","prompt":"Sort each strategy into its slide category.","bins":["Time management","Cognitive technique","Relaxation technique","Counterproductive"],"items":[["Delegate responsibility",0,"Listed under time management."],["Do least favourite tasks first",0,"Listed under time management."],["Modify expectations",1,"Listed under cognitive techniques."],["Cultivate your sense of humour",1,"Listed under cognitive techniques."],["Progressive muscle relaxation",2,"Listed under relaxation techniques."],["Biofeedback",2,"Listed under relaxation techniques."],["Yoga",2,"Listed under relaxation techniques."],["Smoking to calm down",3,"Tobacco use is a counterproductive coping strategy."],["Stress eating fast food",3,"Unhealthy eating habits are counterproductive."]]},{"id":"W5-C7-S2","type":"mcq","src":"W5 Part 4, slide 12","ch":"W5-C7","added":"2026-10-26","case":"Kim is introverted and starts a journal about her stress. After a week, she says writing about her worries made her feel worse on some evenings.","q":"What do the slides predict for Kim?","opts":[["Her short-term mood may dip, but over the long term her stress should drop",true,"Journaling may negatively affect short-term mood, but over the long term stress is reduced."],["Journaling does not work for introverts, so she should stop",false,"The slide says journaling is helpful for people who are shy or introverted."],["The low mood means journaling is a counterproductive coping strategy",false,"Counterproductive strategies on the slides are tobacco, alcohol and other drugs, and unhealthy eating."],["Writing triggers the relaxation response right away",false,"The slide expects a possible short-term dip in mood, not instant relaxation."]]},{"id":"W5-C7-S3","type":"mcq","src":"W5 Part 4, slide 16","ch":"W5-C7","added":"2026-10-26","case":"A student's stress journal has a column for time, stressor, and reaction. Entries include 'Late for class: slouched in back of room, chewed my nails' and 'Ed asked to borrow money: stayed calm, counted to 10, explained he already owes me $50.'","q":"What is the main purpose of this journal, according to Fig 3.5?","opts":[["Tracking stressful events and reactions helps you understand how you normally cope",true,"Fig 3.5's caption says tracking stressors and reactions helps you understand how you normally cope. It supports the first step of a personal plan: identify stressors."],["It replaces getting help, the last step of a personal plan",false,"The plan is identify stressors, design your plan, and get help. The journal does not replace getting help."],["It measures stress hormone levels across the day",false,"Stress hormone levels are shown in Fig 3.4, a cortisol graph, not a journal."],["It gives a PSS score to compare against the cutoff of 14",false,"The PSS is a separate 10-item scale. The journal records events and reactions."]]}],"summary":"Manage stress with time management, journaling, cognitive and relaxation techniques. Avoid tobacco, alcohol and drugs, and unhealthy eating. Plan: identify stressors, design a plan, get help."},{"id":"W5-C8","title":"Reading: The stress response and health","src":"Textbook Ch 3, pp. 65-75","added":"2026-10-26","blurb":"Textbook detail on the physical response, personality types, hardiness, resilience, PNI and stress-linked conditions.","learn":"During stress, the sympathetic nervous system triggers the endocrine system. Sympathetic nerves use <b>norepinephrine</b> on nearly every organ, and hormones such as cortisol and epinephrine drive the fight-or-flight changes. The same basic set of reactions occurs for any stressor: positive or negative, physical or psychological.<br><b>Behavioural responses</b> are controlled by the somatic nervous system, so they are under our control. Personality types: <b>Type A</b> (competitive, impatient, hostile; anger, cynicism and hostility raise heart disease risk), <b>Type B</b> (relaxed), <b>Type C</b> (suppressed anger, hopelessness; may impair immunity), <b>Type D</b> (feels but does not express negative emotions, avoids people; heart risk). <b>Hardiness</b> and three types of <b>resilience</b> (nonreactive, homeostatic, positive growth) help people cope.<br>In GAS, the response is the same for eustress and distress. <b>PNI</b> holds that stress impairs immunity through the nervous and endocrine systems. Chronic stressors such as unemployment harm almost all measures of immunity. Stress also raises inflammation, which damages blood vessels.","summary":"Personality shapes stress: hostility (Type A) and unexpressed negative emotion (Type D) raise heart risk, while hardiness and resilience protect. Chronic stress harms immunity and the heart.","steps":[{"id":"W5-C8-S1","type":"match","src":"Textbook Ch 3, pp. 69-70","prompt":"Match each personality pattern to its textbook description.","pairs":[["Type A","Ultracompetitive, impatient and hostile; reacts explosively"],["Type B","Relaxed and contemplative; tolerant of others"],["Type C","Suppresses anger, feels hopeless, overreacts to minor stressors"],["Type D","Feels but does not express negative emotions; avoids social contact"],["Hardiness","Sees stressors as challenges; inner locus of control"],["Positive growth resilience","Learns and grows from the stress experience"]]},{"id":"W5-C8-S2","type":"sort","src":"Textbook Ch 3, p. 74","prompt":"Sort each stress-linked problem into the textbook's category.","bins":["Cardiovascular disease","Psychological problems","Immune system changes","Other health problems"],"items":[["Chronic high blood pressure leading to atherosclerosis",0,"Chronic high blood pressure is a major cause of atherosclerosis, which can block arteries."],["Stress cardiomyopathy that mimics a heart attack",0,"Listed under cardiovascular disease: it mimics a heart attack but does not damage the heart."],["Raised C-reactive protein (CRP), a marker of CVD risk",0,"Stress-induced inflammation is linked to raised CRP and homocysteine, markers for CVD risk."],["Excess PKC hurting focus and judgment",1,"Stress activates the enzyme PKC, which acts on the prefrontal cortex. Listed under psychological problems."],["Post-traumatic stress disorder",1,"Listed under psychological problems, along with depression, panic attacks, anxiety and eating disorders."],["Asthma and allergy attacks",2,"Listed among problems linked to stress-related changes in immune function."],["Flare-ups of genital herpes",2,"Flare-ups of chronic diseases such as genital herpes and HIV infection are linked to immune changes."],["Irritable bowel syndrome and ulcers",3,"Digestive problems are listed under other health problems."],["Repetitive strain injuries at work",3,"Injuries, including on-the-job repetitive strain, are listed under other health problems."]]},{"id":"W5-C8-S3","type":"mcq","src":"Textbook Ch 3, p. 70","ch":"W5-C8","added":"2026-10-26","case":"Right after a minor car accident, Jae is shaken: he cries and cannot sleep that night. Two days later he is back to his usual mood and routine.","q":"Which type of resilience does Jae show?","opts":[["Homeostatic resilience",true,"He reacts strongly but returns to baseline functioning quickly."],["Nonreactive resilience",false,"Nonreactive means not reacting to the stressor. Jae reacted strongly."],["Positive growth resilience",false,"Positive growth means learning and growing from the experience. Nothing shows growth, only a quick return to normal."],["Hardiness",false,"Hardiness is a form of optimism that views stressors as challenges. It is not one of the three types of resilience."]]},{"id":"W5-C8-S4","type":"mcq","src":"Textbook Ch 3, p. 73","ch":"W5-C8","added":"2026-10-26","case":"Kai is generally pessimistic. When he gets sick he stays passive, skips follow-up appointments, and has stopped exercising.","q":"How does the textbook connect this pattern to health?","opts":[["Mood, personality, behaviour and immune function are intertwined: pessimists may neglect health care and health-promoting behaviour",true,"The textbook uses pessimism as its example of how mood and behaviour tie into immune functioning."],["Pessimism has no link to immunity; only cortisol levels matter",false,"The textbook says mood, personality and behaviour are intertwined with immune functioning."],["Pessimism makes lymphocytes more efficient, so he recovers faster",false,"Nothing in the textbook says this. Optimism and positive problem solving are what may help immunity."],["His pattern shows positive growth resilience",false,"Positive growth resilience means learning and growing from stress. Kai is withdrawing, not growing."]]}]},{"id":"W5-C9","title":"Reading: Sources of stress and managing it","src":"Textbook Ch 3, pp. 75-90","added":"2026-10-26","blurb":"Life changes, hassles, job and internal stressors, and the textbook's coping, relaxation and planning tools.","learn":"<b>Major life changes</b>, even positive ones like graduation, need adjustment. <b>Daily hassles</b> may stress you more because they happen often. Job stress is high when workers are left out of decisions, and severe or chronic job stress can lead to <b>burnout</b>. <b>Internal stressors</b> include unrealistic expectations and states such as illness.<br>To manage stress: build social support, communicate <b>assertively</b>, exercise (it completes the energy cycle, but watch for <b>overtraining</b>), limit caffeine, protect sleep, and manage time. Cognitive techniques include an 8-step <b>problem-solving</b> approach. Relaxation techniques bring on the relaxation response: heart rate, breathing and metabolism slow, and brain waves shift from beta to alpha. Options include progressive relaxation, visualization, meditation (including <b>mindfulness</b>), diaphragmatic breathing, yoga, tai chi, music and <b>biofeedback</b>.<br>Counterproductive: tobacco, alcohol, stimulants, marijuana, opioids, and eating to cope. A personal plan starts with learning to listen to your body. Keep a stress journal, design a plan with rewards, and get help if needed: peer counselling, support groups, psychotherapy.","summary":"Know the stressor types (life changes, hassles, job, internal, environmental) and the textbook toolkit: support, assertiveness, exercise, sleep, problem solving, relaxation, and a written plan.","steps":[{"id":"W5-C9-S1","type":"sort","src":"Textbook Ch 3, pp. 75, 78-79","prompt":"Sort each stressor into its textbook category.","bins":["Major life change","Daily hassle","Internal stressor","Environmental stressor"],"items":[["Moving out of the family home for university",0,"The textbook names moving out of the family home as a major change of early adulthood."],["Getting married",0,"Even positive changes such as marriage can be stressful major life changes."],["Losing your keys on the way to class",1,"Losing your keys or wallet is the textbook's example of a daily hassle."],["Misplacing your wallet",1,"A minor, frequent problem: a daily hassle."],["Expecting to earn 100% on every test",2,"Unrealistic expectations are an internal stressor."],["Fighting the flu during midterms",2,"Physical states such as illness are internal stressors."],["A restaurant so noisy it puts you on edge",3,"The textbook's example of a mild environmental stressor."],["Construction noise outside your window every morning",3,"An unavoidable daily environmental stressor."]]},{"id":"W5-C9-S2","type":"order","src":"Textbook Ch 3, p. 84","prompt":"Put the textbook's problem-solving steps in order.","items":["Define the problem in one or two sentences","Identify the causes of the problem","Consider all solutions, not just the most obvious one","Weigh positive and negative consequences of each solution","Make a decision: choose a solution","List what you will need to do to act on your decision","Carry out your list, then evaluate the outcome and revise if needed"],"why":"Define, find causes, list all solutions, weigh them, decide, plan the actions, then act and evaluate. Students with better problem-solving skills report easier adjustment, lower stress and higher grades."},{"id":"W5-C9-S3","type":"mcq","src":"Textbook Ch 3, p. 77","ch":"W5-C9","added":"2026-10-26","case":"Dana is a highly driven social worker. For a year she has felt that her work is never recognized and that she is not meeting her goals. She now feels physically, mentally and emotionally drained.","q":"Which textbook term best fits Dana?","opts":[["Burnout",true,"Burnout is physical, mental and emotional exhaustion from severe or chronic job stress, most common in driven people who feel unrecognized. Helping professions are prone to it."],["Overtraining",false,"Overtraining comes from compulsive exercise, not job stress."],["Daily hassles",false,"Daily hassles are minor, frequent problems such as losing keys, not a year of exhausting work stress."],["Type B personality",false,"Type B people are relaxed and less frustrated by daily events."]]},{"id":"W5-C9-S4","type":"mcq","src":"Textbook Ch 3, p. 83","ch":"W5-C9","added":"2026-10-26","case":"It is 1 a.m. Tomas has been lying in bed for 25 minutes and cannot fall asleep before his 8 a.m. class.","q":"Which step follows the textbook's advice on insomnia?","opts":[["Get out of bed, leave the room if possible, and do something monotonous until he feels sleepy",true,"If you do not fall asleep in 15 to 20 minutes, get up and do something monotonous until sleepy."],["Take a sleeping pill every night from now on",false,"Sleeping pills are not recommended for chronic insomnia. They can be habit forming and lose effectiveness."],["Study in bed until he gets tired",false,"The textbook says to use your bed only for sleep: no eating, reading, studying or TV."],["Have a drink to relax",false,"Alcohol before bedtime causes disturbed, fragmented sleep."]]}]}],"questions":[{"id":"W5-Q01","type":"mcq","ch":"W5-C1","src":"W5 Part 1, slide 2","added":"2026-10-26","q":"In the textbook's terms, what is a stressor?","opts":[["A situation or event that triggers physical and emotional reactions",true,"This is the slide definition of a stressor."],["The physical and emotional reactions to a triggering event",false,"That is the stress response."],["The general physical and emotional state that accompanies the reactions",false,"That is stress."],["The long-term wear and tear of repeated reactions",false,"That is allostatic load."]]},{"id":"W5-Q02","type":"mcq","ch":"W5-C1","src":"W5 Part 1, slide 2","added":"2026-10-26","case":"Kai has four deadlines this week. When he opens his calendar, his heart races and his hands sweat. By Friday he describes himself as tense and worn out overall.","q":"Which matching of terms is correct?","opts":[["Deadlines = stressor; racing heart = stress response; overall tense state = stress",true,"Stressor is the trigger, stress response is the reaction, and stress is the general state that goes with the response."],["Deadlines = stress; racing heart = stressor; overall tense state = stress response",false,"The deadlines trigger the reaction, so they are the stressor."],["Deadlines = stressor; racing heart = stress; overall tense state = stress response",false,"The racing heart is a reaction (stress response). The overall state is stress."],["Deadlines = stress response; racing heart = stress; overall tense state = stressor",false,"This reverses trigger and reaction."]]},{"id":"W5-Q03","type":"mcq","ch":"W5-C1","src":"W5 Part 1, slide 4","added":"2026-10-26","case":"Rina's PSS answers to items 1, 2, 3, 6, 9 and 10 add up to 16. Her answers to the starred items are: item 4 = 2, item 5 = 1, item 7 = 1, item 8 = 0.","q":"What is Rina's total score, and how does it compare with the cutoff?","opts":[["12, which is not above 14",true,"16 - (2+1+1+0) = 16 - 4 = 12. The slide's action point is a total above 14."],["20, which is above 14",false,"20 comes from adding the starred items instead of subtracting them."],["16, which is above 14",false,"16 ignores the starred items, which must be subtracted."],["12, which is above 14",false,"The arithmetic is right, but 12 is below the cutoff of 14."]]},{"id":"W5-Q04","type":"mcq","ch":"W5-C1","src":"W5 Part 1, slide 4","added":"2026-10-26","q":"On the Perceived Stress Scale, which item is ADDED to the score (not subtracted)?","opts":[["Found that you could not cope with all the things you had to do",true,"Item 6 is not starred, so it is added."],["Felt confident about your ability to handle your personal problems",false,"Item 4 is starred and subtracted."],["Been able to control irritations in your life",false,"Item 7 is starred and subtracted."],["Felt that you were on top of things",false,"Item 8 is starred and subtracted."]]},{"id":"W5-Q05","type":"mcq","ch":"W5-C1","src":"W5 Part 2, slide 2","added":"2026-10-26","q":"Which statement about the divisions of the nervous system is correct?","opts":[["The autonomic nervous system is part of the PNS and works under involuntary control",true,"The slide diagram places the autonomic nervous system under the PNS, with involuntary control."],["The somatic nervous system contains the sympathetic and parasympathetic divisions",false,"Those two divisions belong to the autonomic nervous system."],["The CNS is made up of the brain, spinal cord, and autonomic nervous system",false,"The CNS is the brain and spinal cord. The autonomic system is in the PNS."],["The somatic nervous system controls basic body processes such as digestion",false,"The autonomic system controls basic body processes. The somatic system handles motor and sensory functions under mostly conscious control."]]},{"id":"W5-Q06","type":"mcq","ch":"W5-C1","src":"W5 Part 1, slide 9","added":"2026-10-26","q":"Activation of the sympathetic division causes release of which catecholamines?","opts":[["Norepinephrine and epinephrine",true,"The slide lists norepinephrine (noradrenaline) and epinephrine (adrenaline)."],["CRH and ACTH",false,"These are HPA axis hormones from the hypothalamus and pituitary, not catecholamines."],["Cortisol and other glucocorticoids",false,"Glucocorticoids come from the adrenal cortex through the HPA axis."],["Endorphins and oxytocin",false,"Endorphins block pain in fight or flight and oxytocin is mentioned under gender differences. Neither is listed as a catecholamine."]]},{"id":"W5-Q07","type":"mcq","ch":"W5-C1","src":"W5 Part 1, slides 11-12","added":"2026-10-26","case":"A cyclist swerves to avoid a car door that opens suddenly in front of her.","q":"Which body change would you expect during her fight-or-flight reaction?","opts":[["Her liver releases extra sugar into the blood to boost energy",true,"The slides list the liver releasing extra sugar as part of fight or flight."],["Digestion speeds up to supply fuel to the muscles",false,"Digestion halts during an emergency."],["Her pupils constrict to sharpen focus",false,"Fig 3.1 says pupils dilate to let in more light."],["Her heart rate slows to save oxygen",false,"Heart rate accelerates during fight or flight."]]},{"id":"W5-Q08","type":"mcq","ch":"W5-C1","src":"W5 Part 1, slides 13, 18","added":"2026-10-26","q":"Which statement about the stress response in modern life matches the slides?","opts":[["Many modern stressors, such as an exam, do not require a physical response",true,"The slide says fight, flight or freeze is part of our biological heritage, but many stressors do not need a physical response."],["Once a stressor ends, the sympathetic division stops the stress response",false,"The parasympathetic division takes command and stops the stress response."],["Everyone responds the same way to the same stressor",false,"The slide says people respond differently to various stressors."],["Freezing is the most common modern response",false,"The slide says the common response is flight."]]},{"id":"W5-Q09","type":"mcq","ch":"W5-C2","src":"W5 Part 1, slide 14","added":"2026-10-26","q":"In the HPA axis, which hormone does the pituitary gland release into the bloodstream?","opts":[["ACTH (adrenocorticotropic hormone)",true,"CRH stimulates the pituitary to release ACTH into the blood."],["CRH (corticotropin-releasing hormone)",false,"CRH is released by the hypothalamus."],["Cortisol",false,"Cortisol is released by the adrenal gland."],["Epinephrine",false,"Epinephrine comes from the adrenal medulla in the SAM axis."]]},{"id":"W5-Q10","type":"mcq","ch":"W5-C2","src":"W5 Part 1, slide 14","added":"2026-10-26","q":"Where is CRH released?","opts":[["The paraventricular nucleus (PVN) of the hypothalamus",true,"The PVN in the hypothalamus releases CRH."],["The adrenal cortex",false,"The adrenal cortex releases glucocorticoids."],["The adrenal medulla",false,"The adrenal medulla secretes epinephrine."],["The hippocampus",false,"The hippocampus is a site of negative feedback, not CRH release."]]},{"id":"W5-Q11","type":"mcq","ch":"W5-C2","src":"W5 Part 1, slides 14-15","added":"2026-10-26","case":"A patient has a pituitary condition that makes the gland release far more ACTH than normal, even with no stressor.","q":"What would you expect next in the HPA chain?","opts":[["The adrenal gland releases more glucocorticoids",true,"ACTH travels to the adrenal gland and stimulates glucocorticoid release, so more ACTH means more cortisol."],["The adrenal gland releases less cortisol",false,"ACTH stimulates the adrenal gland. More ACTH raises cortisol."],["The hypothalamus releases more CRH because ACTH stimulates it",false,"ACTH acts on the adrenal gland. Rising glucocorticoids feed back to turn the hypothalamus down, not up."],["The adrenal medulla releases cortisol in place of epinephrine",false,"Cortisol comes from the adrenal cortex. The adrenal medulla secretes epinephrine."]]},{"id":"W5-Q12","type":"mcq","ch":"W5-C2","src":"W5 Part 1, slide 15","added":"2026-10-26","q":"Besides the hypothalamus and pituitary, where else do glucocorticoids turn down the stress response?","opts":[["The hippocampus",true,"The slide says negative feedback also turns down the response in the hippocampus."],["The adrenal medulla",false,"The adrenal medulla is part of the SAM axis. It is not named as a feedback site."],["The locus coeruleus",false,"On the Bucci figure, norepinephrine (not glucocorticoids) feeds back to the locus coeruleus."],["The spleen",false,"The spleen releases red blood cells in fight or flight. It is not a feedback site."]]},{"id":"W5-Q13","type":"mcq","ch":"W5-C2","src":"W5 Part 1, slide 16","added":"2026-10-26","q":"Which pairing of stress pathway and output is correct?","opts":[["SAM axis: adrenal medulla secretes epinephrine. HPA axis: adrenal cortex secretes cortisol.",true,"This matches the Bucci et al. (2016) figure."],["SAM axis: adrenal cortex secretes cortisol. HPA axis: adrenal medulla secretes epinephrine.",false,"The glands are swapped."],["SAM axis: pituitary secretes ACTH. HPA axis: sympathetic neurons release norepinephrine.",false,"ACTH belongs to the HPA axis and sympathetic neurons to the SAM axis."],["Both axes end with the adrenal cortex secreting epinephrine",false,"The adrenal cortex secretes cortisol. Epinephrine comes from the adrenal medulla."]]},{"id":"W5-Q14","type":"mcq","ch":"W5-C2","src":"W5 Part 1, slide 17","added":"2026-10-26","q":"According to McEwen's (1998) figure, how do allostatic systems respond to stress?","opts":[["They start the adaptive response, sustain it until the stress ends, then shut it off",true,"The caption describes initiation, sustaining the response until the stress ceases, then shut-off (recovery)."],["They keep the response at full strength permanently once it starts",false,"That would be a prolonged response, one cause of allostatic load, not normal allostasis."],["They respond only through catecholamines, never glucocorticoids",false,"Responses are started by both catecholamines and glucocorticoids, and cross-talk can occur."],["They prevent any physiological change so the body stays at baseline",false,"Allostasis involves an adaptive response that alters cell and tissue function before recovery."]]},{"id":"W5-Q15","type":"mcq","ch":"W5-C3","src":"W5 Part 2, slide 3","added":"2026-10-26","case":"Tom and Ana get the same surprise quiz. Tom had guessed a quiz was coming and feels he can control how he prepares. Ana did not see it coming and feels helpless.","q":"Which concept best explains why Ana feels more stressed?","opts":[["Cognitive appraisal: successful prediction and perception of control",true,"Appraisal depends on whether you can predict the stressor and whether you feel in control. Tom had both; Ana had neither."],["Eustress: the quiz is a pleasant stressor for Tom",false,"Nothing suggests either student finds the quiz pleasant. The difference is in prediction and control."],["The exhaustion stage of the general adaptation syndrome",false,"Exhaustion follows prolonged stress. This is a single quiz."],["Repeated hits causing allostatic load",false,"Repeated hits are frequent stressors over time, not a difference in how one event is appraised."]]},{"id":"W5-Q16","type":"mcq","ch":"W5-C3","src":"W5 Part 2, slide 3","added":"2026-10-26","q":"Which is listed on the slides as an INEFFECTIVE response to stress?","opts":[["Procrastination",true,"Procrastination is listed with overeating, frustration, and self-medicating as ineffective."],["Laughing",false,"Laughing is listed as effective."],["Time management",false,"Time management is listed as effective."],["Talking",false,"Talking is listed as effective."]]},{"id":"W5-Q17","type":"mcq","ch":"W5-C3","src":"W5 Part 2, slide 4","added":"2026-10-26","case":"Deshawn has no deadlines, no job, and no goals this term. He describes himself as inactive and says nothing pushes him to improve.","q":"Where is Deshawn on the stress curve (Fig 3.2)?","opts":[["Too little stress (underload)",true,"Too little stress means people are not challenged enough to improve; the curve marks this zone 'inactive' and 'laid back'."],["Optimum stress",false,"Optimum stress challenges people in a way that promotes their best performance."],["Too much stress (overload)",false,"Overload comes with fatigue and exhaustion from too many demands."],["Burnout",false,"Burnout comes after overload, with anxiety, panic, anger, and breakdown."]]},{"id":"W5-Q18","type":"mcq","ch":"W5-C3","src":"W5 Part 2, slide 6","added":"2026-10-26","q":"Which of these is NOT one of the Big Five personality factors?","opts":[["Trait anxiety",true,"Trait anxiety is listed separately on the slide. The Big Five are conscientiousness, agreeableness, neuroticism, openness to experience, and extraversion."],["Conscientiousness",false,"Conscientiousness is one of the Big Five."],["Neuroticism",false,"Neuroticism is one of the Big Five."],["Openness to experience",false,"Openness to experience is one of the Big Five."]]},{"id":"W5-Q19","type":"mcq","ch":"W5-C3","src":"W5 Part 2, slide 7","added":"2026-10-26","q":"Which statement about resilience matches the slides?","opts":[["It is linked to social and academic success in at-risk populations and helps people handle stress more positively",true,"This is how the slide describes resilience."],["It is fixed at birth, since basic elements of personality cannot change",false,"The slide says research suggests you can change some basic elements of your personality."],["It is one of the five factors in the Big Five model",false,"Resilience is discussed separately from the Big Five."],["It makes people more vulnerable to stress",false,"That describes higher trait anxiety, not resilience."]]},{"id":"W5-Q20","type":"mcq","ch":"W5-C3","src":"W5 Part 2, slide 8","added":"2026-10-26","q":"Which physiological gender difference is described on the slides?","opts":[["Women have higher levels of oxytocin, linked to social interaction and mood regulation",true,"The slide lists higher oxytocin in women, linked to social interaction and mood regulation."],["Testosterone lowers blood pressure and protects against CVD",false,"The slide says testosterone affects blood pressure and could increase risk for CVD."],["Men have higher oxytocin, which affects the amygdala",false,"Higher oxytocin is listed for women. Testosterone is linked to the amygdala."],["Gender affects only expectations, not physiology",false,"The slide lists both expectations about behaviour and physiological differences."]]},{"id":"W5-Q21","type":"mcq","ch":"W5-C3","src":"W5 Part 2, slide 9","added":"2026-10-26","q":"In the slide 9 table of symptoms of excess stress, which is classed as a behavioural symptom?","opts":[["Problems communicating",true,"Problems communicating is in the behavioural column."],["Hypervigilance",false,"Hypervigilance is in the emotional column."],["Grinding of teeth",false,"Grinding of teeth is in the physical column."],["Pounding heart",false,"Pounding heart is in the physical column."]]},{"id":"W5-Q22","type":"mcq","ch":"W5-C4","src":"W5 Part 3, slide 2","added":"2026-10-26","q":"Who first proposed the general adaptation syndrome?","opts":[["Hans Selye, a Canadian endocrinologist",true,"The slide credits Selye, the father of the field of stress research."],["Sir Michael Marmot",false,"Marmot led the Whitehall studies of health gradients."],["Bruce McEwen",false,"McEwen's 1998 figures are used for allostasis and allostatic load."],["Sheldon Cohen",false,"Cohen is first author of the Perceived Stress Scale (1983)."]]},{"id":"W5-Q23","type":"mcq","ch":"W5-C4","src":"W5 Part 3, slide 3","added":"2026-10-26","case":"The day after learning his parent is seriously ill, Ravi has headaches and indigestion and cannot sleep.","q":"Which GAS stage best fits Ravi?","opts":[["Alarm",true,"In alarm the body is more susceptible to disease or injury, with headaches, indigestion, anxiety, and disrupted eating or sleep."],["Resistance",false,"In resistance, homeostasis develops and the body becomes more resistant. Ravi's symptoms are just starting."],["Exhaustion",false,"Exhaustion is a life-threatening state after prolonged exposure. This is one day in."],["Optimum stress",false,"Optimum stress is a zone on the stress curve, not a GAS stage."]]},{"id":"W5-Q24","type":"mcq","ch":"W5-C4","src":"W5 Part 3, slide 4","added":"2026-10-26","q":"Why is the general adaptation syndrome considered partly outdated?","opts":[["Increased disease susceptibility is now traced to the stress response itself rather than depletion of resources",true,"This is the reason given on the slide; GAS was replaced with the idea of allostatic load."],["It left out the resistance stage",false,"Resistance is one of the three GAS stages."],["It was replaced by the Perceived Stress Scale",false,"GAS was replaced by allostatic load. The PSS is a self-test."],["It assumed all stressors are pleasant",false,"GAS already separated eustress (pleasant) from distress (unpleasant)."]]},{"id":"W5-Q25","type":"mcq","ch":"W5-C4","src":"W5 Part 3, slides 7-8","added":"2026-10-26","case":"Mia gives a class presentation. Her heart rate and stress hormones are still high hours after it ended, with no recovery period.","q":"Which cause of high allostatic load does this show?","opts":[["Inability to shut down the stress response",true,"McEwen's figure shows this as a prolonged response with no recovery."],["Frequent stressors",false,"Frequent stressors are repeated hits: many separate normal responses."],["Poor adaptation to common stressors",false,"Poor adaptation is a response that does not shrink with repetition. This is one event that does not end."],["Inadequate response",false,"An inadequate response is too small, leading to hyperactivity in other systems."]]},{"id":"W5-Q26","type":"mcq","ch":"W5-C4","src":"W5 Part 3, slides 7-8","added":"2026-10-26","case":"Ben gives a talk every week. By his tenth talk, his stress response is just as large as it was the first time.","q":"Which cause of high allostatic load does this show?","opts":[["Poor adaptation to common stressors",true,"Normally the response shrinks with repetition. Ben's stays at full height: lack of adaptation."],["Inability to shut down the stress response",false,"Nothing suggests his response fails to recover after each talk."],["Inadequate response",false,"His response is large, not too small."],["Eustress",false,"Eustress is a pleasant stressor, not a cause of allostatic load."]]},{"id":"W5-Q27","type":"mcq","ch":"W5-C4","src":"W5 Part 3, slides 5, 7","added":"2026-10-26","q":"Which of these is NOT listed as a reason for high allostatic load?","opts":[["A quick return to baseline after each stressor",true,"A response that rises then recovers is the normal pattern on McEwen's figure, not a cause of load."],["Frequent stressors",false,"Listed as a cause."],["Inability to shut down the stress response",false,"Listed as a cause."],["An inadequate response that leads to hyperactivity in other systems",false,"Listed as a cause."]]},{"id":"W5-Q28","type":"mcq","ch":"W5-C5","src":"W5 Part 3, slide 5","added":"2026-10-26","q":"Psychoneuroimmunology is the study of interactions among which systems?","opts":[["Nervous, endocrine, and immune",true,"This is the slide definition."],["Nervous, cardiovascular, and digestive",false,"Cardiovascular and digestive problems are health outcomes of stress, not the systems in the definition."],["Endocrine, respiratory, and immune",false,"The nervous system, not the respiratory system, is part of the definition."],["Somatic, autonomic, and central nervous",false,"These are nervous system divisions only."]]},{"id":"W5-Q29","type":"mcq","ch":"W5-C5","src":"W5 Part 3, slide 16","added":"2026-10-26","case":"A nurse has worked night shifts under heavy pressure for two years, and her cortisol has stayed high for long periods.","q":"According to the psychoneuroimmunology slide, what would you expect?","opts":[["Increased inflammation",true,"Chronic stress and prolonged secretion of cortisol increase inflammation."],["More lymphocytes",false,"Increased cortisol leads to decreased numbers of lymphocytes."],["A boosted immune response as white blood cells move to the periphery",false,"That describes acute stress, not chronic stress."],["Increased neurogenesis in the hippocampus",false,"Stress is associated with suppressed neurogenesis. Exercise increases it."]]},{"id":"W5-Q30","type":"mcq","ch":"W5-C5","src":"W5 Part 3, slide 15","added":"2026-10-26","case":"Two civil servants in the same employment grade have the same coronary risk factors. One reports high control over her job; the other reports low control.","q":"Based on Whitehall II Figure 2, which is more likely?","opts":[["The low-control worker has a higher likelihood of coronary heart disease",true,"Low job control had the highest likelihood of CHD, even after adjusting for grade and coronary risk factors."],["The high-control worker has a higher likelihood of CHD from extra responsibility",false,"High job control had the lowest likelihood on the chart."],["They have equal risk because they are in the same grade",false,"The chart was adjusted for grade and still showed a difference by job control."],["Job control affects mortality but not CHD",false,"Figure 2 is specifically about CHD incidence and job control."]]},{"id":"W5-Q31","type":"mcq","ch":"W5-C5","src":"W5 Part 3, slide 13","added":"2026-10-26","q":"Which example on the slides shows that societies with high conflict and instability have higher mortality?","opts":[["A 40% increase in death rate in Russian men following the fall of communism",true,"This is the example given on the slide."],["A four-fold gap in mortality between top and bottom British civil service grades",false,"That is the Whitehall employment-grade gradient, not a society in conflict."],["A 40% decrease in death rate in Russian men following the fall of communism",false,"The slide reports an increase."],["Low job control doubling the likelihood of coronary heart disease",false,"That is the Whitehall II job control finding."]]},{"id":"W5-Q32","type":"mcq","ch":"W5-C5","src":"W5 Part 3, slide 17","added":"2026-10-26","q":"In the Neuropsychopharmacology Reviews (2012) figure, which is shown as an OUTCOME of chronic inflammation?","opts":[["Depression",true,"Arrows point out from chronic inflammation to diabetes, cancer, depression, and cardiovascular disease."],["Psychosocial stress",false,"Psychosocial stress is an input that feeds into chronic inflammation."],["Obesity",false,"Obesity is an input on the figure."],["Early life stress",false,"Early life stress is an input on the figure."]]},{"id":"W5-Q33","type":"mcq","ch":"W5-C6","src":"W5 Part 4, slide 2","added":"2026-10-26","case":"A second-year student is juggling rent, a part-time job that barely covers groceries, and a growing student loan.","q":"Which postsecondary stressor is this?","opts":[["Financial concerns",true,"Money worries fall under financial concerns."],["Time pressures",false,"Time pressures are about too little time, not money."],["Interpersonal",false,"Interpersonal stressors involve relationships with other people."],["Future worries",false,"Future worries are about what comes later, such as careers. Rent and loans are present financial concerns."]]},{"id":"W5-Q34","type":"mcq","ch":"W5-C6","src":"W5 Part 4, slide 5","added":"2026-10-26","q":"How much sleep do most adults need each night to stay healthy and perform their best?","opts":[["7 to 9 hours",true,"This is the range on the slide."],["5 to 6 hours",false,"Below the slide's range."],["10 to 12 hours",false,"Above the slide's range."],["4 hours of NREM plus 1 hour of REM",false,"The slide gives a total of 7 to 9 hours, not a split by phase."]]},{"id":"W5-Q35","type":"mcq","ch":"W5-C6","src":"W5 Part 4, slide 6","added":"2026-10-26","q":"Which change happens during NREM sleep?","opts":[["Growth hormone is released",true,"Listed among NREM changes."],["Blood pressure rises",false,"Blood pressure drops during NREM."],["Stress hormones increase",false,"Stress hormones are low during NREM and increase during REM."],["Brain waves become fast and uneven",false,"Brain wave patterns become slow and even."]]},{"id":"W5-Q36","type":"mcq","ch":"W5-C6","src":"W5 Part 4, slide 9","added":"2026-10-26","q":"According to Fig 3.4, when do stress hormones such as cortisol reach a high level?","opts":[["During the last stages of sleep, toward morning",true,"The caption says cortisol reaches a high level during the last stages of sleep. The graph peaks around 08h00."],["Around midnight, at the start of sleep",false,"The graph is near its lowest around midnight to 02h00."],["In the mid-afternoon",false,"Afternoon levels are lower than the morning peak."],["At a constant level all day and night",false,"The caption says levels fluctuate through the day and night."]]},{"id":"W5-Q37","type":"mcq","ch":"W5-C7","src":"W5 Part 4, slide 14","added":"2026-10-26","q":"Relaxation techniques aim to trigger the relaxation response. What is it?","opts":[["The opposite of the fight-or-flight reaction",true,"The slide defines the relaxation response this way."],["The alarm stage of the general adaptation syndrome",false,"Alarm is a stress stage, not relaxation."],["Activation of the SAM axis",false,"The SAM axis drives fight or flight."],["A rise in stress hormones during REM sleep",false,"That is a sleep pattern, not the relaxation response."]]},{"id":"W5-Q38","type":"mcq","ch":"W5-C7","src":"W5 Part 4, slides 10-11","added":"2026-10-26","case":"Lena plans to study from 7 to 10 p.m. but loses almost two hours to scrolling videos between chapters.","q":"Which time management tip targets her problem most directly?","opts":[["Avoid time sinks",true,"Scrolling that swallows study time is a time sink."],["Consolidate tasks",false,"Consolidating groups similar tasks. It does not address the lost time."],["Delegate responsibility",false,"Studying for her own course cannot be handed off."],["Visualize achievement",false,"Visualizing does not stop the scrolling."]]},{"id":"W5-Q39","type":"mcq","ch":"W5-C7","src":"W5 Part 4, slides 13-15","added":"2026-10-26","q":"Which is a counterproductive coping strategy on the slides?","opts":[["Using alcohol to unwind after a stressful day",true,"Use of alcohol and other drugs is listed as counterproductive."],["Deep breathing",false,"Deep breathing is a relaxation technique."],["Tai chi",false,"Tai chi is a relaxation technique."],["Problem solving",false,"Problem solving is a cognitive technique."]]},{"id":"W5-Q40","type":"mcq","ch":"W5-C7","src":"W5 Part 4, slide 13","added":"2026-10-26","case":"After a poor quiz mark, Omar reminds himself that one quiz does not decide his term grade and changes his target from a perfect score to a strong one.","q":"Which type of stress management is Omar using?","opts":[["A cognitive technique: modify expectations",true,"Modify expectations is listed under cognitive techniques."],["A relaxation technique: visualization",false,"He is changing how he thinks about the result, not using visualization to relax."],["Time management: set priorities",false,"He is not ordering tasks; he is changing his expectations."],["Confiding in yourself through writing",false,"He is not keeping a journal."]]},{"id":"W5-TQ01","type":"mcq","ch":"W5-C8","src":"Textbook Ch 3, p. 67","added":"2026-10-26","q":"According to the textbook, for which stressors does the same basic set of physical reactions occur?","opts":[["Any type: positive or negative, physical or psychological",true,"The changes vary in intensity, but the same basic set occurs for any type of stressor."],["Only negative events, such as failing a test",false,"Pleasant stressors trigger the same set of reactions."],["Only physical threats, such as a swerving car",false,"Psychological stressors trigger the same reactions."],["Only stressors that truly need a physical response",false,"Fight or flight prepares the body for action whether or not action is needed. That is why it is often inappropriate in modern life."]]},{"id":"W5-TQ02","type":"mcq","ch":"W5-C8","src":"Textbook Ch 3, p. 66","added":"2026-10-26","q":"According to the textbook, what triggers the endocrine system during stress?","opts":[["The sympathetic nervous system",true,"During stress, the sympathetic nervous system triggers the endocrine system."],["The parasympathetic division",false,"The parasympathetic division calms the body after the stressor ends."],["The somatic nervous system",false,"The somatic system manages conscious actions, such as behavioural responses."],["The immune system",false,"PNI describes the nervous and endocrine systems acting on the immune system, not the reverse."]]},{"id":"W5-TQ03","type":"mcq","ch":"W5-C8","src":"Textbook Ch 3, p. 68","added":"2026-10-26","case":"As a car swerves toward you, your body goes through the fight-or-flight changes shown in Fig 3.1.","q":"Which change does NOT happen?","opts":[["Secretion of saliva and mucus increases",true,"Saliva and mucus secretion decreases, since digestion has low priority in an emergency."],["The spleen releases more red blood cells",false,"This happens, to meet the demand for oxygen and replace blood lost from injuries."],["The bronchi dilate to let more air into the lungs",false,"This happens."],["Blood vessels in skeletal muscles dilate while those in skin and viscera contract",false,"This happens, raising blood pressure and sending blood where it is most needed."]]},{"id":"W5-TQ04","type":"mcq","ch":"W5-C8","src":"Textbook Ch 3, p. 68","added":"2026-10-26","case":"Two classmates get the same email: the midterm has moved up a week. They agree on the facts (what changed, when and where). One panics; the other shrugs.","q":"According to the textbook, which part of cognitive appraisal most likely differs between them?","opts":[["Their evaluation of personal outcome: what this means for me and whether I can do anything about it",true,"Facts are evaluated fairly consistently from person to person; evaluation of personal outcome varies."],["Their evaluation of the facts: who, what, where and when",false,"The textbook says facts are typically evaluated fairly consistently. They agree on them here."],["Their GAS stage, since one of them is in exhaustion",false,"Nothing suggests prolonged stress. The difference is in how each appraises the same event."],["The type of stressor, since one received eustress",false,"They received the same stressor. The difference is in appraisal."]]},{"id":"W5-TQ05","type":"mcq","ch":"W5-C8","src":"Textbook Ch 3, p. 69","added":"2026-10-26","case":"Before reading her exam, Amelia takes a deep breath, focuses on the answers she knows, and then goes back to the questions she is unsure of.","q":"Which part of the nervous system controls these behavioural responses?","opts":[["The somatic nervous system",true,"Behavioural responses are controlled by the somatic nervous system, which manages conscious actions."],["The sympathetic division",false,"The sympathetic division drives the automatic fight-or-flight reaction, not chosen behaviour."],["The parasympathetic division",false,"The parasympathetic division controls involuntary functions when relaxed."],["The autonomic nervous system as a whole",false,"The autonomic system controls involuntary processes such as digestion and heart rate."]]},{"id":"W5-TQ06","type":"mcq","ch":"W5-C8","src":"Textbook Ch 3, p. 69","added":"2026-10-26","case":"Kevin is ultracompetitive and impatient. He honks the moment a light turns green and often reacts to small annoyances with cynicism and open hostility.","q":"Which personality type does Kevin show, and which features of it raise heart disease risk?","opts":[["Type A; anger, cynicism and hostility",true,"Studies indicate anger, cynicism and hostility in the type A pattern increase the risk of heart disease."],["Type A; patience and trust",false,"Kevin is impatient and cynical. Patience and trust are not type A traits."],["Type C; anger suppression",false,"Kevin expresses anger openly. Type C suppresses it."],["Type D; avoiding social contact",false,"Nothing in the case shows social avoidance. Kevin's pattern is type A."]]},{"id":"W5-TQ07","type":"mcq","ch":"W5-C8","src":"Textbook Ch 3, p. 69","added":"2026-10-26","case":"Mei rarely shows anger and finds it hard to express emotions. She often feels hopeless and has an exaggerated reaction to small annoyances.","q":"Which personality type fits, and what health effect does the textbook link to it?","opts":[["Type C; the heightened response may impair immune functions",true,"Type C: anger suppression, difficulty expressing emotions, hopelessness and an exaggerated response to minor stressors, which may impair immunity."],["Type B; lower perceived stress",false,"Type B is relaxed and tolerant, not hopeless and overreactive."],["Type A; explosive anger raises heart disease risk",false,"Mei suppresses anger rather than expressing it explosively."],["Hardiness; she sees stressors as chances to grow",false,"Hopelessness is the opposite of hardiness."]]},{"id":"W5-TQ08","type":"mcq","ch":"W5-C8","src":"Textbook Ch 3, p. 69","added":"2026-10-26","case":"Owen feels gloomy and worried much of the time but keeps it to himself. He avoids parties, group work and social contact in general.","q":"Which pattern does Owen show?","opts":[["Type D, which puts him at risk for heart problems",true,"Type D: a joint tendency to feel but not express negative emotions and to avoid social contact."],["Type B, since he seems calm on the outside",false,"Type B is truly relaxed and contemplative, not hiding gloom and worry."],["Type A, since he is hostile toward others",false,"Nothing shows hostility or competitiveness."],["Hardiness, since he handles stress on his own",false,"Hardy people view stressors as challenges. Owen is an anxious worrier."]]},{"id":"W5-TQ09","type":"mcq","ch":"W5-C8","src":"Textbook Ch 3, p. 70","added":"2026-10-26","case":"When her co-op placement falls through, Leila calls it a chance to learn something new. She stays committed to her courses and believes her own choices shape what happens next.","q":"Which trait does Leila show?","opts":[["Hardiness",true,"Hardy people see stressors as challenges and chances to grow, stay committed, and have an inner locus of control."],["Trait anxiety",false,"High trait anxiety makes people more vulnerable to stress. Leila is coping well."],["Type C personality",false,"Type C involves hopelessness and overreaction. Leila is optimistic."],["Tend and befriend",false,"Tend and befriend means seeking social support. Leila is reframing the setback herself."]]},{"id":"W5-TQ10","type":"mcq","ch":"W5-C8","src":"Textbook Ch 3, p. 70","added":"2026-10-26","case":"Daniel is upset for a week after failing his first chemistry midterm. He then changes how he studies, joins a study group, and says the failure made him a stronger student.","q":"Which type of resilience does Daniel show?","opts":[["Positive growth resilience",true,"He learns and grows from the stress experience."],["Nonreactive resilience",false,"He did react: he was upset for a week."],["Homeostatic resilience",false,"Homeostatic resilience is a quick return to baseline. Daniel goes beyond baseline and grows."],["Type B personality",false,"Type B is a personality type, not a type of resilience."]]},{"id":"W5-TQ11","type":"mcq","ch":"W5-C8","src":"Textbook Ch 3, p. 70","added":"2026-10-26","case":"Frank built almost all of his self-worth around his engineering career. His wife sees herself as a parent, volunteer and teacher.","q":"Why might retirement be more stressful for Frank, according to the textbook?","opts":[["Gender roles shape how a stressor is perceived; his self-worth rests mostly on work",true,"The textbook uses this exact example: a man whose self-worth comes from work may find retirement more stressful than a woman with several roles."],["Retirement is a daily hassle, and hassles are always worse than life changes",false,"Retirement is a major life change, not a daily hassle."],["Retirement is pleasant, so it cannot cause stress",false,"Pleasant changes can still be stressful."],["Men cannot seek social support",false,"The textbook says traditional male roles may limit building a support network, not that men cannot seek it."]]},{"id":"W5-TQ12","type":"mcq","ch":"W5-C8","src":"Textbook Ch 3, p. 72","added":"2026-10-26","q":"In general adaptation syndrome theory, how do eustress and distress compare?","opts":[["They follow the same sequence of physical responses",true,"The sequence of physical responses in GAS is the same for eustress and distress."],["Eustress skips the alarm stage",false,"Both go through the same three stages."],["Eustress activates the parasympathetic division instead of the sympathetic",false,"A pleasant stressor still triggers the stress response."],["Distress is the stress from a pleasant stressor",false,"Distress comes from an unpleasant stressor; eustress from a pleasant one."]]},{"id":"W5-TQ13","type":"mcq","ch":"W5-C8","src":"Textbook Ch 3, p. 74","added":"2026-10-26","case":"After hearing that her husband died suddenly, a woman has chest pain and symptoms that look like a heart attack. Tests later show no damage to her heart.","q":"Which condition does the textbook describe that fits this case?","opts":[["Stress cardiomyopathy (broken heart syndrome)",true,"The stress response can cause a condition that mimics a heart attack but does not damage the heart."],["Atherosclerosis",false,"Atherosclerosis is damaged vessels caked with fatty deposits, which develops over time."],["High allostatic load",false,"Allostatic load is long-term wear and tear, not a sudden event without heart damage."],["Exhaustion stage of GAS",false,"Exhaustion follows prolonged or repeated stressors, not a single sudden shock."]]},{"id":"W5-TQ14","type":"mcq","ch":"W5-C8","src":"Textbook Ch 3, p. 75","added":"2026-10-26","case":"Sam remembers tiny details of a minor fender bender last year, but he cannot recall much about a serious crash he was in later.","q":"Which textbook explanation fits best?","opts":[["Moderate stress enhances the ability to remember, while high levels of acute stress can impair learning",true,"The textbook uses this example: people recall minute details of a fender bender but not of a major crash."],["Higher stress always improves memory",false,"High levels of acute stress impair learning."],["Stress affects memory only after years of chronic stress",false,"High acute stress can impair learning right away."],["The adult hippocampus cannot grow new neurons",false,"The textbook says the hippocampus does grow new neurons in adulthood; stress reduces new cell birth."]]},{"id":"W5-TQ15","type":"mcq","ch":"W5-C9","src":"Textbook Ch 3, p. 75","added":"2026-10-26","case":"Aisha and Kiara both graduated, got married and moved to a new city in the same year.","q":"According to the textbook, what would make one of them less likely to become ill from these changes?","opts":[["A strong support network and a stress-resistant personality",true,"These are named as moderating influences on the health effects of life changes."],["Seeing the changes as positive, since positive changes are never stressful",false,"Even positive changes such as graduation and marriage can be stressful."],["Adding more daily hassles to stay busy",false,"Hassles add stress, especially when perceived negatively."],["Avoiding social contact to save energy",false,"Social support buffers stress. Avoiding people removes that buffer."]]},{"id":"W5-TQ16","type":"mcq","ch":"W5-C9","src":"Textbook Ch 3, p. 75","added":"2026-10-26","q":"Why do researchers propose that daily hassles can be an even greater source of stress than major life changes?","opts":[["They occur much more often",true,"Major changes seldom occur regularly; hassles happen often, and each one can trigger a stress response if perceived negatively."],["They always involve physical danger",false,"Hassles are minor problems such as losing your keys."],["They always require moving or changing jobs",false,"Those are major life changes."],["They cannot be perceived negatively",false,"The textbook says people who perceive hassles negatively have a moderate stress response each time."]]},{"id":"W5-TQ17","type":"mcq","ch":"W5-C9","src":"Textbook Ch 3, p. 77","added":"2026-10-26","case":"At a call centre, managers set every script and schedule with no input from staff. Stress among workers is high.","q":"Which change does the textbook suggest would most likely raise job satisfaction and lower stress?","opts":[["Let workers help shape how their jobs are performed",true,"When workers can shape how their jobs are done, job satisfaction goes up and stress goes down."],["Add overtime so work gets done faster",false,"Tight schedules and overtime leave less time for exercise and other stress-proofing activities."],["Require staff to be reachable by text at all times",false,"Being 'always on' is described as a source of stress."],["Cut breaks so shifts end sooner",false,"The textbook advises giving yourself breaks; play renews you."]]},{"id":"W5-TQ18","type":"mcq","ch":"W5-C9","src":"Textbook Ch 3, pp. 78-79","added":"2026-10-26","case":"Jun expects to earn 100% on every test and feels like a failure after getting 91%.","q":"What kind of stressor is this?","opts":[["An internal stressor: unrealistic expectations",true,"The textbook gives expecting 100% on every test as an example of an internal stressor."],["An environmental stressor",false,"Environmental stressors come from the physical environment, such as noise or disasters."],["A daily hassle",false,"Hassles are minor outside problems such as losing keys."],["A social stressor from discrimination",false,"Nothing in the case involves prejudice or discrimination."]]},{"id":"W5-TQ19","type":"mcq","ch":"W5-C9","src":"Textbook Ch 3, p. 80","added":"2026-10-26","case":"Leah agrees to every favour her friends ask, says nothing when she is upset, and now feels resentful and taken advantage of.","q":"Which textbook suggestion fits Leah best?","opts":[["An assertiveness training course to change her patterns of communication",true,"People who suppress their feelings may benefit from assertiveness training."],["Anger-management strategies for verbal aggression",false,"Anger management is for people who express anger aggressively. Leah suppresses hers."],["Cutting off her social support so no one can ask favours",false,"Social support buffers stress. The fix is communicating her needs."],["More caffeine to keep up with the extra favours",false,"Caffeine can raise blood pressure and cortisol and disrupt sleep."]]},{"id":"W5-TQ20","type":"mcq","ch":"W5-C9","src":"Textbook Ch 3, p. 80","added":"2026-10-26","q":"How does the textbook explain why exercise reduces the effects of stress?","opts":[["The stress response readies the body for physical action; activity completes the energy cycle and trains the body to return to homeostasis",true,"If you are stressed and do not exert yourself, you are not completing the energy cycle."],["Exercise stops the release of all hormones",false,"The textbook does not claim this."],["Exercise helps only if done at the moment the stressor occurs",false,"You can be active at other times of the day and still get the benefit."],["Exercise raises cortisol, and higher cortisol lowers stress",false,"Higher cortisol is part of the stress response, not a cure for it."]]},{"id":"W5-TQ21","type":"mcq","ch":"W5-C9","src":"Textbook Ch 3, p. 81","added":"2026-10-26","case":"Bea copes with stress by running twice a day, every day. She now feels tired, irritable and low, and her race times are getting worse.","q":"Which condition does this most likely describe?","opts":[["Overtraining",true,"Compulsive exercise risks overtraining: fatigue, irritability, depression and diminished athletic performance."],["Burnout",false,"Burnout is exhaustion from severe or chronic job or school stress, not from compulsive exercise."],["The relaxation response",false,"The relaxation response is a calm state, not fatigue and irritability."],["Positive growth resilience",false,"Her performance and mood are getting worse, not growing."]]},{"id":"W5-TQ22","type":"mcq","ch":"W5-C9","src":"Textbook Ch 3, p. 82","added":"2026-10-26","case":"Gil's roommate notices that Gil stops breathing for a few seconds and then gasps, many times a night. Gil does not remember waking up but is exhausted every day.","q":"Which sleep problem is most likely?","opts":[["Sleep apnea",true,"In apnea, breathing stops during sleep and the sleeper wakes repeatedly, often without being aware of it."],["Insomnia",false,"Insomnia is trouble falling or staying asleep that the person notices. Gil does not know he is waking."],["Normal REM sleep",false,"REM brings dreams and limb paralysis, not repeated pauses in breathing."],["Overtraining",false,"Overtraining comes from compulsive exercise."]]},{"id":"W5-TQ23","type":"mcq","ch":"W5-C9","src":"Textbook Ch 3, p. 84","added":"2026-10-26","q":"In the textbook's problem-solving approach, what comes right after defining the problem in one or two sentences?","opts":[["Identify the causes of the problem",true,"Step 2 is to identify the causes."],["Choose the most obvious solution",false,"Step 3 says to consider all solutions, not just the most obvious one."],["Evaluate the outcome",false,"Evaluating the outcome is the last step."],["List what you will need to do",false,"Listing actions comes after making a decision."]]},{"id":"W5-TQ24","type":"mcq","ch":"W5-C9","src":"Textbook Ch 3, p. 86","added":"2026-10-26","case":"Instead of repeating a word to quiet her mind, Tess sits and observes whatever thoughts and sensations come up, without judging them.","q":"Which technique is Tess using?","opts":[["Mindfulness meditation",true,"Mindfulness means observing thoughts, sensations and imagery without evaluating or judging them."],["Progressive relaxation",false,"Progressive relaxation tenses and relaxes muscle groups."],["Visualization",false,"Visualization means imagining a scene, such as floating on a cloud."],["Biofeedback",false,"Biofeedback uses monitoring devices to show body processes."]]},{"id":"W5-TQ25","type":"mcq","ch":"W5-C9","src":"Textbook Ch 3, p. 87","added":"2026-10-26","case":"At a clinic, a sensor tracks Ben's heart rate. A tone gets louder as his heart speeds up and softer as it slows. Over several sessions he learns to make the tone softer.","q":"Which technique is this, and what is its goal?","opts":[["Biofeedback; to learn how relaxation feels and use the skill in daily life without the equipment",true,"Biofeedback training aims to transfer relaxation to daily life without electronic equipment."],["Biofeedback; to keep using the monitor every time he feels stressed",false,"The point is to no longer need the equipment."],["Systematic desensitization; to build an anxiety hierarchy",false,"Desensitization uses ranked anxiety situations, not a heart rate monitor."],["Diaphragmatic breathing; to shift from chest to stomach breathing",false,"No breathing technique is described."]]},{"id":"W5-TQ26","type":"mcq","ch":"W5-C9","src":"Textbook Ch 3, p. 88","added":"2026-10-26","q":"What does the textbook say about using marijuana to cope with stress?","opts":[["Some of its neurochemicals enhance the stress response, and getting high regularly can bring on panic attacks",true,"Physiological effects show marijuana does not cause relaxation."],["It reliably causes physical relaxation",false,"The textbook says physiological effects clearly show it does not."],["Withdrawal lowers stress hormones",false,"Withdrawal may be linked to an increase in circulating stress hormones."],["It improves short-term memory and attention",false,"It decreases short-term memory and attention."]]},{"id":"W5-TQ27","type":"mcq","ch":"W5-C9","src":"Textbook Ch 3, p. 90","added":"2026-10-26","case":"To beat test anxiety, Noah writes ten test-related situations on cards and ranks them from least to most tense. He learns muscle relaxation, then imagines each card while staying relaxed, moving on only when his anxiety is low.","q":"Which technique is this, and what is its premise?","opts":[["Systematic desensitization: you cannot feel anxiety and be relaxed at the same time",true,"This is the three-phase program in the textbook's test anxiety box."],["Success rehearsal: imagine failing so you are ready for the worst",false,"Success rehearsal means imagining yourself dealing with each situation successfully."],["Biofeedback: electronic monitoring of arousal",false,"No monitoring equipment is used."],["Mindfulness meditation: observe thoughts without judging",false,"Noah works through a ranked hierarchy while relaxed."]]},{"id":"W5-TQ28","type":"mcq","ch":"W5-C9","src":"Textbook Ch 3, p. 88","added":"2026-10-26","q":"According to the textbook, what is the most important starting point for a successful stress-management plan?","opts":[["Learning to listen to your body",true,"Recognizing the stress response and the emotions and thoughts that go with it lets you handle the moment in a healthy way."],["Starting psychotherapy",false,"Psychotherapy is an option under getting help, not the starting point."],["Removing every stressor from your life",false,"The textbook focuses on managing stressors, not removing all of them."],["Taking dietary supplements marketed for stress",false,"Supplements do not have to meet the same standards as medications."]]},{"id":"W5-TQ29","type":"mcq","ch":"W5-C9","src":"Textbook Ch 3, p. 80","added":"2026-10-26","case":"Two students live in cramped, overcrowded apartments. One has close friends and family she talks to often. The other handles everything alone.","q":"What does research in the textbook predict?","opts":[["The student with strong social support will be less distressed by the cramped space",true,"In the study, students with a strong support system were less distressed than loners."],["Both will feel the same, since the stressor is the same",false,"Social support changed how distressed the students were."],["The loner will cope better because she has fewer demands",false,"The loners were more distressed."],["Social support helps only married people",false,"The overcrowding study was of university students."]]},{"id":"W5-TQ30","type":"mcq","ch":"W5-C9","src":"Textbook Ch 3, p. 85","added":"2026-10-26","q":"When a relaxation technique triggers the relaxation response, which change does the textbook describe?","opts":[["Brain waves shift from an alert beta rhythm to a relaxed alpha rhythm",true,"Heart rate, breathing and metabolism also slow, and blood pressure and oxygen use fall."],["Heart rate and breathing speed up",false,"They slow down."],["Blood flow to the brain and skin decreases",false,"Blood flow to the brain and skin increases."],["Oxygen consumption rises",false,"Oxygen consumption decreases."]]}],"review":[{"id":"W5-R01","ch":"W5-C1","src":"W5 Part 1, slides 2-4","added":"2026-10-26","q":"Define stressor, stress response, and stress using one example. Then explain how the Perceived Stress Scale is scored and what score calls for action.","answer":"A stressor is the situation or event that triggers physical and emotional reactions, such as an upcoming exam. The stress response is the reactions themselves, such as a racing heart and sweaty palms. Stress is the general physical and emotional state that accompanies the stress response. The PSS has 10 items about the past week, each answered from 0 (never) to 4 (very often). You add items 1, 2, 3, 6, 9 and 10 and subtract the starred items 4, 5, 7 and 8. A total above 14 means you should take time to develop effective stress management techniques.","points":["Stressor = triggering situation or event","Stress response = the reactions; stress = the general state","PSS: 10 items scored 0 to 4 for the past week","Add 1, 2, 3, 6, 9, 10; subtract starred 4, 5, 7, 8","Above 14 = develop stress management techniques"]},{"id":"W5-R02","ch":"W5-C2","src":"W5 Part 1, slides 14-16","added":"2026-10-26","q":"Describe the HPA axis from stressor to cortisol, explain how negative feedback shuts it down, and contrast it with the SAM axis.","answer":"The hypothalamus receives sensory stressors, and its paraventricular nucleus releases CRH. CRH flows through veins to the pituitary, which releases ACTH into the bloodstream. ACTH travels to the adrenal gland, which releases glucocorticoids, cortisol in humans. Glucocorticoids then bind to glucocorticoid receptors in the hypothalamus, pituitary, and hippocampus, turning the response down and lowering glucocorticoids in the blood. The SAM axis is the rapid pathway: sympathetic neurons release norepinephrine and trigger the adrenal medulla to secrete epinephrine, activating fight or flight.","points":["Hypothalamus (PVN) releases CRH","Pituitary releases ACTH; adrenal gland releases cortisol","Negative feedback via GCRs in hypothalamus, pituitary, and hippocampus","SAM: sympathetic neurons and adrenal medulla, epinephrine and norepinephrine, rapid"]},{"id":"W5-R03","ch":"W5-C3","src":"W5 Part 2, slides 3-8","added":"2026-10-26","q":"Two students face the same exam but react very differently. Use cognitive appraisal, personality, and the stress curve to explain why.","answer":"Cognitive appraisal is highly individual: a student who can predict the exam and feels in control will appraise it as less threatening. Personality, the sum of cognitive, behavioural and emotional tendencies, affects how people perceive and react to stressors. A student high in trait anxiety is more vulnerable to stress, while resilience helps people handle stress more positively. Gender, cultural background, and past experiences also shape the response. On the stress curve, a moderate level of stress gives optimal performance, while too little stress (underload) or too much (overload, burnout) lowers performance and can harm health.","points":["Appraisal: prediction and perception of control","Trait anxiety raises vulnerability; resilience helps","Other factors: gender, culture, experiences","Stress curve: moderate stress is optimal; underload and overload or burnout lower performance"]},{"id":"W5-R04","ch":"W5-C4","src":"W5 Part 3, slides 2-8","added":"2026-10-26","q":"Outline Selye's general adaptation syndrome, explain why it is considered outdated, and describe what replaced it.","answer":"Hans Selye proposed GAS as a pattern of three stages. In alarm, the body is more susceptible to disease or injury and may show headaches, indigestion, anxiety, or disrupted eating and sleep. In resistance, homeostasis develops and the body becomes more resistant. Exhaustion is a life-threatening physiological state. GAS is partly outdated because increased disease susceptibility is now traced to the stress response itself rather than to depleted resources. It was replaced by allostatic load, the long-term wear and tear of the stress response, which may come from frequent stressors, poor adaptation, inability to shut down the response, or an inadequate response.","points":["Three stages: alarm, resistance, exhaustion, with one feature of each","Outdated: disease comes from the stress response itself, not depleted resources","Replaced by allostatic load (long-term wear and tear)","Names at least two of the four causes of high allostatic load"]},{"id":"W5-R05","ch":"W5-C5","src":"W5 Part 3, slides 10-16","added":"2026-10-26","q":"Explain how chronic stress can damage long-term health. Include psychoneuroimmunology, the hippocampus, and the Whitehall findings.","answer":"Chronic stress raises the risk of cardiovascular disease through chronic high blood pressure and inflammation that damages blood vessels, and of psychological problems such as depression and anxiety. Psychoneuroimmunology studies the links among the nervous, endocrine, and immune systems: higher cortisol lowers lymphocyte numbers, and chronic stress with prolonged cortisol increases inflammation, raising vulnerability to infection. In the hippocampus, which handles learning, memory and emotion, stress is associated with suppressed neurogenesis, while exercise increases it. The Whitehall studies of British civil servants found that death rate rose as employment grade fell, a four-fold gap from top to bottom, and that low job control was linked to more coronary heart disease.","points":["Cardiovascular and psychological risks","PNI: cortisol lowers lymphocytes; chronic stress increases inflammation","Hippocampus: stress suppresses neurogenesis; exercise increases it","Whitehall: lower grade and lower job control, worse health"]},{"id":"W5-R06","ch":"W5-C7","src":"W5 Part 4, slides 4-16","added":"2026-10-26","q":"A first-year student asks how to manage exam-season stress. Give a plan using at least four strategies from the slides, and name what to avoid.","answer":"Start by identifying stressors, for example with a stress journal, then design a plan and get help if needed. Protect sleep: most adults need 7 to 9 hours, and sleep deprivation keeps stress hormones high during the day. Use time management, such as setting priorities, breaking up long-term goals, and avoiding time sinks. Use cognitive techniques like problem solving and modifying expectations, and relaxation techniques such as deep breathing or yoga to trigger the relaxation response. Avoid counterproductive strategies: tobacco, alcohol and other drugs, and unhealthy eating.","points":["Personal plan: identify stressors, design plan, get help","Sleep 7 to 9 hours; deprivation keeps stress hormones up","At least two of: time management, journaling, cognitive, relaxation techniques","Avoid tobacco, alcohol and drugs, unhealthy eating"]},{"id":"W5-TR01","ch":"W5-C8","src":"Textbook Ch 3, pp. 69-70","added":"2026-10-26","q":"Compare Type A, B, C and D personalities and their health links. Then explain how hardiness and resilience help people deal with stress.","answer":"Type A people are ultracompetitive, impatient and hostile, and their anger, cynicism and hostility raise heart disease risk. Type B people are relaxed and tolerant. Type C people suppress anger, feel hopeless and overreact to minor stressors, which may impair immune function. Type D people feel but do not express negative emotions and avoid social contact, which puts them at risk for heart problems. Hardy people see stressors as challenges with an inner locus of control, and resilience (nonreactive, homeostatic or positive growth) shapes how a person responds to and recovers from stress.","points":["Type A: hostility, anger, cynicism; heart disease","Type B: relaxed; Type C: suppressed anger, hopelessness; immune effects","Type D: unexpressed negative emotions plus social avoidance; heart problems","Hardiness: stressors as challenges, commitment, inner locus of control","Three resilience types: nonreactive, homeostatic, positive growth"]},{"id":"W5-TR02","ch":"W5-C8","src":"Textbook Ch 3, pp. 73-74","added":"2026-10-26","q":"Explain the premise of psychoneuroimmunology and how different kinds of stress affect immunity. Give two stress-linked health problems from the textbook.","answer":"PNI holds that stress, acting through the nervous and endocrine systems, impairs the immune system and so affects health. Higher cortisol is linked to fewer lymphocytes, and epinephrine promotes lymphocyte release but reduces their efficiency. Acute stress enhances the immune response, a stressful event sequence usually brings no overall significant change, and chronic stressors such as unemployment harm almost all measures of immunity. Even large immune changes can have small clinical effects because they are short-term or the immune system compensates. Stress-linked problems include colds and other infections, asthma and allergy attacks, and cardiovascular disease through high blood pressure and inflammation.","points":["Premise: stress acts through nervous and endocrine systems to impair immunity","Cortisol lowers lymphocytes; epinephrine releases them but reduces efficiency","Acute enhances; event sequence little change; chronic harms almost all measures","Names two conditions (e.g. infections, asthma or allergies, CVD, herpes flare-ups)"]},{"id":"W5-TR03","ch":"W5-C9","src":"Textbook Ch 3, pp. 88-89","added":"2026-10-26","q":"Describe how to build a personal stress-management plan using the textbook's steps.","answer":"Start by learning to listen to your body so you recognize the stress response and the thoughts that go with it. Identify stressors by keeping a stress journal for a week or two, recording the time, circumstances, your thoughts and the outcome, and look for patterns. Then design a plan: choose the techniques that suit you, find a friend to work with, consider a contract with yourself, build in rewards, and evaluate and redesign the plan as needs change. If that is not enough, get help from self-help books, peer counselling, support groups or short-term psychotherapy.","points":["Start by learning to listen to your body","Identify stressors with a stress journal and spot patterns","Design: pick techniques, friend, contract, rewards, regular evaluation","Get help: self-help guides, peer counselling, support groups, psychotherapy"]}],"explore":[{"fig":"hpa","title":"The HPA axis","caption":"From stressor to cortisol, and how negative feedback turns it off (Englert, 2004, as shown in W5 Part 1, slides 14-15).","items":{"hyp":{"label":"Hypothalamus","text":"Receives sensory stressors. Its paraventricular nucleus (PVN) releases CRH. Glucocorticoids feed back here to turn the response down.","src":"W5 Part 1, slides 14-15"},"crh":{"label":"CRH","text":"Corticotropin-releasing hormone. It flows through veins to the nearby pituitary gland and stimulates release of ACTH. The figure also shows vasopressin taking the same route.","src":"W5 Part 1, slide 14"},"pit":{"label":"Pituitary gland","text":"Releases ACTH into the bloodstream when stimulated by CRH. It is also a site of negative feedback.","src":"W5 Part 1, slides 14-15"},"acth":{"label":"ACTH","text":"Adrenocorticotropic hormone. It flows through blood vessels to the adrenal gland and stimulates release of glucocorticoids.","src":"W5 Part 1, slide 14"},"adr":{"label":"Adrenal gland","text":"Sits on top of the kidney. Its cortex releases glucocorticoids when stimulated by ACTH. In the SAM axis, its medulla secretes epinephrine.","src":"W5 Part 1, slides 14, 16"},"cort":{"label":"Cortisol","text":"The glucocorticoid in humans. It binds glucocorticoid receptors (GCRs) in the hypothalamus, pituitary, and hippocampus, which turns the response down and lowers glucocorticoids in the blood.","src":"W5 Part 1, slides 14-15"}}},{"fig":"gas","title":"General adaptation syndrome","caption":"Selye's three stages of resistance to injury over time (Fig 3.3, W5 Part 3, slide 4).","items":{"alarm":{"label":"Alarm","text":"Resistance to injury dips below normal. The body is more susceptible to disease or injury; headaches, indigestion, anxiety, and disrupted eating or sleep may occur.","src":"W5 Part 3, slides 3-4"},"resist":{"label":"Resistance","text":"With continued stress, resistance rises above normal. Homeostasis develops and the body becomes more resistant to disease and injury.","src":"W5 Part 3, slides 3-4"},"exhaust":{"label":"Exhaustion","text":"With prolonged exposure to repeated stressors, resistance falls back to low levels. A life-threatening physiological state.","src":"W5 Part 3, slides 3-4"}}}]}]};
